def _alf_edge():
    for p in (os.environ.get('PROGRAMFILES(X86)',''),os.environ.get('PROGRAMFILES',''),os.environ.get('LOCALAPPDATA','')):
        if p:
            c=Path(p)/'Microsoft/Edge/Application/msedge.exe'
            if c.exists():return str(c)
    for p in (os.environ.get('PROGRAMFILES',''),os.environ.get('PROGRAMFILES(X86)',''),os.environ.get('LOCALAPPDATA','')):
        if p:
            c=Path(p)/'Google/Chrome/Application/chrome.exe'
            if c.exists():return str(c)
    return None

def _alf_yazicilar():
    """(yazıcı adları, varsayılan yazıcı) - Windows'a kurulu tüm yazıcılar."""
    names=[];default=''
    if os.name=='nt':
        try:
            import ctypes
            from ctypes import wintypes
            sp=ctypes.WinDLL('winspool.drv',use_last_error=True)
            class _PI4(ctypes.Structure):
                _fields_=[('pPrinterName',wintypes.LPWSTR),('pServerName',wintypes.LPWSTR),('Attributes',wintypes.DWORD)]
            need=wintypes.DWORD(0);ret=wintypes.DWORD(0);fl=2|4
            sp.EnumPrintersW(fl,None,4,None,0,ctypes.byref(need),ctypes.byref(ret))
            if need.value:
                buf=ctypes.create_string_buffer(need.value)
                if sp.EnumPrintersW(fl,None,4,buf,need.value,ctypes.byref(need),ctypes.byref(ret)):
                    arr=ctypes.cast(buf,ctypes.POINTER(_PI4))
                    names=[arr[i].pPrinterName for i in range(ret.value) if arr[i].pPrinterName]
            n=wintypes.DWORD(0)
            sp.GetDefaultPrinterW(None,ctypes.byref(n))
            if n.value:
                b=ctypes.create_unicode_buffer(n.value)
                if sp.GetDefaultPrinterW(b,ctypes.byref(n)):default=b.value
        except Exception as e:
            try:log_error('Yazıcı listesi (winspool)',e)
            except Exception as _se:_silent(_se)
    if not names:
        try:names=list(windows_printers(force=True))
        except Exception:names=[]
    names=sorted({x for x in names if x},key=str.lower)
    return names,default

def _alf_sayfa_olcu(doc):
    """HTML içindeki @page kuralından kâğıt boyutu / kenar boşluğu / yön okur (mm)."""
    pw,ph,mg=210.0,297.0,10.0
    m=re.search(r'@page\s*\{([^}]*)\}',doc,re.I)
    if m:
        body=m.group(1)
        sz=re.search(r'size\s*:\s*([^;}]+)',body,re.I)
        if sz:
            t=sz.group(1).strip().lower();land='landscape' in t
            toks=t.replace('portrait',' ').replace('landscape',' ').split()
            named={'a3':(297.0,420.0),'a4':(210.0,297.0),'a5':(148.0,210.0),'letter':(215.9,279.4)}
            mms=[x for x in toks if x.endswith('mm')]
            try:
                if mms:
                    pw=float(mms[0][:-2]);ph=float(mms[1][:-2]) if len(mms)>1 else pw*1.41421356
                elif toks and toks[0] in named:
                    pw,ph=named[toks[0]]
                    if land:pw,ph=ph,pw
            except Exception as _se:_silent(_se)
        mg_m=re.search(r'margin\s*:\s*([\d.]+)',body,re.I)
        if mg_m:
            try:mg=float(mg_m.group(1))
            except Exception as _se:_silent(_se)
    mg=max(0.0,min(mg,40.0))
    return pw,ph,mg

def _alf_html_hazirla(doc,win_w,page_h,offset=0,olcum=False):
    doc=doc.replace('window.print()','void 0').replace('window.print ()','void 0')
    css=('<style id="__alf">html,body{background:#fff!important;height:auto!important;min-height:0!important}.sheet,.report-page{margin:0!important;box-shadow:none!important;'
         f'width:{win_w:.2f}px!important;height:{page_h:.2f}px!important;break-after:auto!important;page-break-after:auto!important}}'
         +(f'html{{overflow:hidden!important;transform:translateY(-{offset:.2f}px)}}' if offset else '')+'</style>')
    if olcum:
        css+=("<script>window.addEventListener('load',function(){var h=Math.max(document.documentElement.scrollHeight,"
              "document.body?document.body.scrollHeight:0);var d=document.createElement('div');d.id='__ph';d.textContent=String(h);"
              "document.documentElement.appendChild(d);});</script>")
    low=doc.lower();i=low.rfind('</head>')
    return doc[:i]+css+doc[i:] if i>=0 else css+doc

def _alf_onizleme_kes(doc,ilk=6,esik=12):
    """Çok sayfalı rapor (ör. stok listesi, yüzlerce sayfa) için ön izleme yalnız ilk sayfalarla hızlı açılır.
    Dönüş: (ön izleme belgesi, toplam sayfa, kesildi_mi). Yazdırırken belgenin TAMAMI basılır."""
    ms=[m.start() for m in re.finditer(r'<section class="report-page">',doc)]
    if len(ms)<=esik:return doc,len(ms),False
    b=doc.rfind('</body>')
    if b<0 or ms[ilk]>b:return doc,len(ms),False
    return doc[:ms[ilk]]+doc[b:],len(ms),True

def _alf_png_boy(p):
    import struct
    with open(p,'rb') as fh:h=fh.read(24)
    return struct.unpack('>II',h[16:24])[1]

