# ===== v1.2.291.249: TEK TIKLA ÜRÜN EKLE + ENTER İLE ALANLAR ARASI GEÇİŞ (program geneli) =====
import time as _alf_time

def _alf_ayar_evet(k,varsayilan='Evet'):
    """Ayarlar Merkezi'ndeki Evet/Hayır ayarını (kapsamlara bakarak) okur; hata olursa varsayılanı döndürür."""
    try:
        if AYR.spec(k) is not None:return AYR.ayar_evet(k)
        return str(DX.get(k,varsayilan)).strip()!='Hayır'
    except Exception:return varsayilan!='Hayır'

def _alf_arama_gecikmesi(varsayilan=120):
    try:return AYR.ayar_tam('search_delay')
    except Exception:return varsayilan


def alf_tek_tik(tree,action):
    """Listedeki bir satıra TEK tıklayınca satırı seçip action'ı çalıştırır (başlık / boş alan tıklaması yok sayılır)."""
    def on_click(e):
        if not _alf_ayar_evet('click_add'):return
        try:
            if tree.identify_region(e.x,e.y) not in ('cell','tree'):return
            row=tree.identify_row(e.y)
            if not row:return
            tree.selection_set(row);tree.focus(row)
        except tk.TclError:return
        return action(e)
    tree.bind('<ButtonRelease-1>',on_click,add='+')

def alf_enter_zinciri(order,end_fn=None,auto=None):
    """Alanlar arasında Enter ile ilerleme. order: [(widget, sekme_seç_fonksiyonu|None)]. auto: {widget: fn(widget)->bool}
    fn True dönerse (örn. barkod tamamlandı) Enter beklemeden sonraki alana geçilir."""
    auto=auto or {}
    def uygun(wd):
        try:
            if not wd.winfo_exists():return False
            cls=wd.winfo_class();st=str(wd.cget('state'))
            if st=='disabled':return False
            if st=='readonly' and cls!='TCombobox':return False
            return True
        except tk.TclError:return False
    def git(i):
        for j in range(i+1,len(order)):
            wd,sec=order[j]
            if not uygun(wd):continue
            try:
                if sec:sec()
                wd.focus_set()
                if wd.winfo_class() in ('Entry','TEntry','Spinbox','TSpinbox'):
                    wd.selection_range(0,'end');wd.icursor('end')
            except tk.TclError:continue
            wd._alf_skip_until=_alf_time.time()+0.35   # okuyucunun gönderdiği Enter'ı yut
            return
        if end_fn:
            try:end_fn()
            except Exception as _se:_silent(_se)
    for i,(wd,_sec) in enumerate(order):
        try:
            tag='AlfEnter'+str(id(wd))
            def press(e,wd=wd):
                wd._alf_ret=_alf_ayar_evet('enter_nav') and _alf_time.time()>getattr(wd,'_alf_skip_until',0)
            def release(e,i=i,wd=wd):
                if getattr(wd,'_alf_ret',False):
                    wd._alf_ret=False;git(i)
            def anahtar(e,i=i,wd=wd):
                fn=auto.get(wd)
                if not fn or not _alf_ayar_evet('barcode_auto_advance'):return
                try:
                    onceki=getattr(wd,'_alf_len',0);simdi=len(wd.get())
                    wd._alf_len=simdi
                    if e.keysym in ('Return','KP_Enter','Tab','BackSpace','Delete','Left','Right','Home','End','Up','Down'):return
                    if simdi>onceki and fn(wd):git(i)
                except Exception as _se:_silent(_se)
            for seq in ('<KeyPress-Return>','<KeyPress-KP_Enter>'):wd.bind_class(tag,seq,press)
            for seq in ('<KeyRelease-Return>','<KeyRelease-KP_Enter>'):wd.bind_class(tag,seq,release)
            wd.bind_class(tag,'<KeyRelease>',anahtar)
            wd.bind_class(tag,'<FocusIn>',lambda e,wd=wd:setattr(wd,'_alf_len',len(wd.get())))
            bt=list(wd.bindtags());bt.insert(1,tag);wd.bindtags(tuple(bt))
            wd._alf_nav=True
        except Exception as _se:_silent(_se)

def alf_otomatik_enter(win):
    """Kart/form pencerelerinde (3+ giriş alanı) Enter ile sıradaki alana geçiş. Kendi Enter davranışı olan
    pencere/alanlara dokunmaz."""
    try:
        if not win.winfo_exists() or getattr(win,'_alf_nav',False):return
        if win.bind('<Return>') or win.bind('<KP_Enter>'):return
        adaylar=[]
        def tara(p):
            for ch in p.winfo_children():
                try:cls=ch.winfo_class()
                except tk.TclError:continue
                if cls=='Toplevel':continue
                if cls in ('Entry','TEntry','TCombobox','Spinbox','TSpinbox'):
                    try:
                        if ch.winfo_viewable() and not ch.bind('<Return>') and not ch.bind('<KP_Enter>') and not getattr(ch,'_alf_nav',False):adaylar.append(ch)
                    except tk.TclError:pass
                tara(ch)
        tara(win)
        if len(adaylar)<3:return
        adaylar.sort(key=lambda x:(round(x.winfo_rooty()/12),x.winfo_rootx()))
        alf_enter_zinciri([(x,None) for x in adaylar])
        win._alf_nav=True
    except Exception as _se:_silent(_se)
