# ===== v1.2.291.255: ONDALIK GÜRÜLTÜSÜNÜ (33.333333333333336 gibi) PROGRAM GENELİNDE TEMİZLE =====
# Hesaplanmış maliyet/fiyatlar veritabanında 33.333333333333336 gibi uzun kesirlerle durabilir. Kutulara, değişkenlere ve
# tablolara yazılırken bu değerler programın ondalık ayarına (varsayılan 2 hane) göre düzgün gösterilir. Gerçek
# (temiz) küsuratlar - ör. 0.0375 - korunur; veritabanındaki değer değişmez.
_ALF_NOISY=re.compile(r'^-?\d+\.\d{5,}$')

def _alf_float_text(v):
    try:
        v=float(v)
        if v!=v or v in (float('inf'),float('-inf')):return str(v)
        dec=decimal_places()
        if abs(round(v,4)-v)<1e-9:
            t=f'{v:.4f}'.rstrip('0').rstrip('.')
            if dec>0:
                whole,_,frac=t.partition('.')
                if len(frac)<dec:t=whole+'.'+frac.ljust(dec,'0')
            return '0' if t in ('-0','') else t
        return f'{v:.{dec}f}'
    except Exception:return str(v)

def _alf_clean_display(value):
    if isinstance(value,float):return _alf_float_text(value)
    if isinstance(value,str) and _ALF_NOISY.match(value):
        try:return _alf_float_text(float(value))
        except Exception:return value
    return value

def _alf_clean_cell(v):
    # tablo hücresi: yalnız gürültülü sayıları temizle (nokta ondalık korunur; sonradan float() ile okunabilir kalır)
    try:
        if isinstance(v,float):
            if abs(round(v,4)-v)<1e-9:return v
            return f'{v:.{decimal_places()}f}'
        if isinstance(v,str) and _ALF_NOISY.match(v):return f'{float(v):.{decimal_places()}f}'
    except Exception as _se:_silent(_se)
    return v

def _alf_clean_values(vals):
    if isinstance(vals,(tuple,list)):
        return type(vals)(_alf_clean_cell(x) for x in vals)
    return vals

_alf_o_entry_insert=tk.Entry.insert
tk.Entry.insert=lambda self,index,string:_alf_o_entry_insert(self,index,_alf_clean_display(string))
_alf_o_ttk_entry_insert=ttk.Entry.insert
ttk.Entry.insert=lambda self,index,string:_alf_o_ttk_entry_insert(self,index,_alf_clean_display(string))
_alf_o_spin_insert=tk.Spinbox.insert
tk.Spinbox.insert=lambda self,index,s:_alf_o_spin_insert(self,index,_alf_clean_display(s))
_alf_o_sv_set=tk.StringVar.set
tk.StringVar.set=lambda self,value:_alf_o_sv_set(self,_alf_clean_display(value))
_alf_o_tv_insert=ttk.Treeview.insert
def _alf_tv_insert(self,parent,index,iid=None,**kw):
    if 'values' in kw:kw['values']=_alf_clean_values(kw['values'])
    return _alf_o_tv_insert(self,parent,index,iid,**kw)
ttk.Treeview.insert=_alf_tv_insert
_alf_o_tv_item=ttk.Treeview.item
def _alf_tv_item(self,item,option=None,**kw):
    if 'values' in kw:kw['values']=_alf_clean_values(kw['values'])
    return _alf_o_tv_item(self,item,option,**kw)
ttk.Treeview.item=_alf_tv_item
