def _restart_application_no_console(root=None):
    """Başarılı BCK yüklemesinden sonra uygulamayı temiz süreçte yeniden başlat.
    Windows'ta python.exe kullanılsa bile yeni siyah konsol penceresi oluşturma.
    """
    exe=sys.executable
    kwargs={}
    if os.name=='nt':
        kwargs['creationflags']=getattr(subprocess,'CREATE_NO_WINDOW',0)
    if getattr(sys,'frozen',False):
        # Kurulu (PyInstaller) sürümde sys.executable programın kendisidir; betik yolu eklenmez.
        cmd=[exe];cwd=str(Path(exe).resolve().parent)
    else:
        script=str(Path(__file__).resolve());cmd=[exe,script];cwd=str(Path(script).parent)
    env=dict(os.environ);env['ALFABE_RESTART']='1'  # yeni süreç, eskisinin kapanmasını bekler
    subprocess.Popen(cmd,cwd=cwd,env=env,close_fds=(os.name!='nt'),**kwargs)
    try:
        if root is not None: root.destroy()
    except Exception:
        pass

