def _alfabe_is_network_path(p):
    try:
        s=str(p)
        if s.startswith('\\\\'):return True
        if os.name=='nt' and len(s)>1 and s[1]==':':
            import ctypes
            return ctypes.windll.kernel32.GetDriveTypeW(s[:2]+'\\')==4
    except Exception as _se:_silent(_se)
    return False

