_ALFABE_QTY_TOKENS=('adedi','adet','miktar','mevcut','sayım','sayim','stok miktarı','stok miktari','fişteki ürün','fisteki urun','ürün sayısı','urun sayisi','giren','çıkan','cikan','kalan adet','toplam adet','satılan adet','satilan adet','stok adedi')
_ALFABE_MONEY_TOKENS=('fiyat','tutar','toplam','maliyet','kâr','kar','iskonto','bakiye','borç','borc','alacak','ödeme','odeme','ciro','değer','deger','net','brüt','brut','kdv','vergi','₺','tl','sermaye')
def _alfabe_qty_zero_values(tree,values):
 """Bütün Treeview hücreleri için ortak gösterim; yalnızca görüntü metnini değiştirir."""
 try:
  # v1.2.291.454: sütun başlıkları ve türleri ağaç başına bir kez çözülür (heading() çağrılınca yenilenir); sayısal olmayan sütunlar hiç işlenmez.
  ck=str(tree.cget('columns'));hc=getattr(tree,'_alf_hcache',None)
  if hc is not None and getattr(tree,'_alf_hkey',None)!=ck:hc=None   # sütunlar yeniden tanımlandıysa
  if hc is None:
   cols=list(tree.cget('columns'));hc=[];tree._alf_hkey=ck
   for c in cols:
    h=_TREEVIEW_HEADING_ORIGINAL_23183(tree,c,'text') or c
    hc.append((h,_alfabe_report_field_type(h) in ('quantity','money','ratio')))
   tree._alf_hcache=hc
  result=list(values)
  for i,v in enumerate(result[:len(hc)]):
   if hc[i][1]:
    formatted=_alfabe_report_number_text(hc[i][0],v)
    if formatted is not None:result[i]=formatted
  return tuple(result)
 except Exception:return values

