def _alfabe_insert_23184(self,parent,index,iid=None,**kw):
 if 'values' in kw:kw['values']=_alfabe_qty_zero_values(self,kw['values'])
 result=_ALFABE_INSERT_ORIGINAL_23184(self,parent,index,iid=iid,**kw)
 try:
  if not getattr(self,'_alfabe_realign_pending',False):
   self._alfabe_realign_pending=True
   def _apply():
    self._alfabe_realign_pending=False
    _alfabe_realign_existing_columns(self)
   self.after_idle(_apply)
 except (tk.TclError,AttributeError):pass
 return result
