# v1.2.154 / v1.2.291.110 - Program geneli tablo yerlesim hafizasi.
# Kullanici bir tablonun sutun genisligini/sirasini degistirdiginde ekran kapanirken
# ve fare ile sutun ayari bittiginde otomatik kaydedilir. Sonraki acilista geri yuklenir.
_TABLE_LAYOUT_FILE=_DATA_BASE/'tablo_yerlesimleri.json'
_TREEVIEW_INIT_ORIGINAL=ttk.Treeview.__init__
_TABLE_LAYOUT_CACHE=None

def _load_table_layouts():
 global _TABLE_LAYOUT_CACHE
 if isinstance(_TABLE_LAYOUT_CACHE,dict):return _TABLE_LAYOUT_CACHE
 try:
  if _TABLE_LAYOUT_FILE.exists():
   d=json.loads(_TABLE_LAYOUT_FILE.read_text(encoding='utf-8'))
   _TABLE_LAYOUT_CACHE=d if isinstance(d,dict) else {}
   return _TABLE_LAYOUT_CACHE
 except Exception as e:log_error('Tablo yerlesimleri okunamadi',e)
 _TABLE_LAYOUT_CACHE={}
 return _TABLE_LAYOUT_CACHE

def _write_table_layouts(data):
 global _TABLE_LAYOUT_CACHE
 try:
  if isinstance(_TABLE_LAYOUT_CACHE,dict) and data==_TABLE_LAYOUT_CACHE:return
  tmp=_TABLE_LAYOUT_FILE.with_suffix('.tmp')
  tmp.write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
  os.replace(tmp,_TABLE_LAYOUT_FILE);_TABLE_LAYOUT_CACHE=dict(data)
 except Exception as e:log_error('Tablo yerlesimleri kaydedilemedi',e)

def _tree_layout_identity(tree):
 try:
  top=tree.winfo_toplevel(); title=str(top.title() or top.winfo_class())
  cols=[str(x) for x in tree.cget('columns')]
  return title,cols
 except Exception:return '',[]

def _tree_title_norm(title):
 # v1.2.291.459: "Toplu Stok Sayımı - SY-U1" gibi belge no / kişi adı içeren başlıklar her açılışta farklı anahtar üretmesin.
 t=str(title or '')
 if ' - ' in t:
  head,tail=t.split(' - ',1)
  if any(ch.isdigit() for ch in tail) and head.strip():return head.strip()
 return t

def _tree_layout_keys(tree):
 # v3: modül (ana pencerede) ve rapor kimliği anahtara dahildir -> farklı ekranların aynı sütun adları birbirini ezmez.
 title,cols=_tree_layout_identity(tree)
 if not title or not cols:return []
 body='|'.join(cols);ks=[]
 try:
  top=tree.winfo_toplevel();mod=str(getattr(top,'current_module','') or '')
 except Exception:mod=''
 rk=str(getattr(tree,'_alfabe_report_key','') or '')
 ks.append('v3||'+mod+'||'+rk+'||'+_tree_title_norm(title)+'||'+body)
 if not rk:ks.append('v2||'+title+'||'+body)
 return ks

def _tree_layout_key(tree):
 ks=_tree_layout_keys(tree)
 return ks[0] if ks else ''

def _tree_legacy_layout_prefix(tree):
 title,cols=_tree_layout_identity(tree)
 return title+'||'+'|'.join(cols)+'||' if title and cols else ''

def _find_saved_tree_layout(tree,data=None):
 try:
  data=_load_table_layouts() if data is None else data
  for key in _tree_layout_keys(tree):
   layout=data.get(key)
   if isinstance(layout,dict):return key,layout
  pref=_tree_legacy_layout_prefix(tree)
  if pref:
   for k,v in data.items():
    if str(k).startswith(pref) and isinstance(v,dict):return k,v
 except Exception as _se:_silent(_se)
 return '',None

def _alfabe_tree_font_size(tree):
 try:
  return int(getattr(tree,'_alfabe_font_size'))
 except Exception:
  return max(8,min(20,int(_table_setting('table_font_size','10'))))

def _alfabe_apply_tree_font(tree,size,save=True):
 """Yalniz secilen Treeview icin ayri ttk stili; genel stil degismez."""
 try:
  size=max(8,min(20,int(size)))
  style=ttk.Style(tree)
  # Widget yolundan benzersiz stil: diger tablolar etkilenmez.
  import hashlib
  token=hashlib.sha1(str(tree).encode('utf-8')).hexdigest()[:12]
  name='AlfabeFont'+token+'.Treeview'
  style.configure(name,font=('Segoe UI',size),rowheight=max(22,size+14))
  style.configure(name+'.Heading',font=('Segoe UI',max(8,size+int(getattr(tree,'_alf_baslik_fark',0))),'bold'))
  if getattr(tree,'_alf_secim_rengi',None):style.map(name,background=[('selected',tree._alf_secim_rengi)],foreground=[('selected',getattr(tree,'_alf_secim_yazi','#ffffff'))])
  tree.configure(style=name)
  tree._alfabe_font_size=size
  if save:_save_tree_layout(tree,force=True)
 except Exception as e:log_error('Tablo yazi boyutu',e)

class AlfMenu:
 """Program geneli şık açılır menü (tk.Menu yerine): yuvarlak köşe yok ama temiz kart görünümü, simge sütunu, üzerine gelince vurgu,
 kırmızı 'kaldır' ve mavi vurgulu ana işlem satırları, alt menüler (üzerine gelince/Sağ ok), klavye (↑ ↓ Enter Esc ← →),
 dışarı tıklayınca/odak gidince kapanır. tk.Menu ile aynı kullanım: add_command / add_separator / add_cascade / tk_popup."""
 BG='#ffffff';BORDER='#b9c7d8';HOVER='#e3effc';FG='#1b2a3a';MUTED='#7a8898';DIS='#a9b4c0';ACC='#0b5cad';RED='#c0392b';SEP='#e4eaf1';HEAD='#f1f6fb'
 FONT=('Segoe UI',10);FONTB=('Segoe UI',10,'bold');FONTS=('Segoe UI',8,'bold')
 _stack=[];_bound=False;focus_close=True      # odak başka uygulamaya geçince kapan (testte sanal ekran odağı fareyi izlediği için kapatılır)
 ICONS=[('kaldır','✕'),('göster','👁'),('gizle','🚫'),('alan seçici','☰'),('yeni alan','＋'),('hizalama','≡'),('sola','⇤'),('sağa','⇥'),('ortala','↔'),
        ('yazı','Aa'),('punto','Aa'),('boyut','Aa'),('en iyi','⇔'),('akıllı','⚡'),('yerleşimini kaydet','💾'),('varsayılan','↺'),('ön izleme','🖨'),
        ('düzenle','🎨'),('tasarımı kaydet','💾'),('tüm mevcut','☑')]
 def __init__(self,master=None,tearoff=0,**kw):
  self.master=master;self.items=[];self.win=None;self.sub=None;self.parent=None;self.rows=[];self.cur=None;self._job=None
 # --- tk.Menu uyumlu API
 def add_command(self,label='',command=None,state='normal',**kw):self.items.append(dict(t='c',label=str(label),cmd=command,state=state))
 def add_separator(self,**kw):self.items.append(dict(t='s'))
 def add_cascade(self,label='',menu=None,state='normal',**kw):
  if menu is not None:menu.parent=self
  self.items.append(dict(t='m',label=str(label),menu=menu,state=state))
 def add_header(self,text):self.items.append(dict(t='h',label=str(text)))
 def entrycget(self,i,opt):return self.items[i].get({'label':'label','state':'state'}.get(opt,opt))
 def index(self,i):return len(self.items)-1 if i=='end' else int(i)
 def grab_release(self):pass
 def tk_popup(self,x,y,entry=0):self.post(x,y)
 def unpost(self):AlfMenu.close_all()
 # --- görünüm
 @classmethod
 def close_all(cls):
  st=list(cls._stack);cls._stack.clear()
  for m in st:
   try:
    if m.win is not None:m.win.destroy()
   except Exception:pass
   m.win=None;m.rows=[];m.sub=None;m.cur=None
 def _icon(self,it):
  lab=it['label']
  if lab.startswith('✓ '):return '✔'
  if lab.startswith('   '):return ''
  lw=lab.lower()
  for k,v in self.ICONS:
   if k in lw:return v
  return ''
 def _text(self,it):
  lab=it['label']
  for pre in ('✓ ','   ','＋ '):
   if lab.startswith(pre):return lab[len(pre):]
  return lab
 def post(self,x,y):
  AlfMenu.close_all();AlfMenu._t0=_acilis_time.time();self._show(int(x),int(y),None)
 def _show(self,x,y,anchor):
  root=self.master.winfo_toplevel() if self.master is not None else tk._default_root
  w=tk.Toplevel(root);self.win=w;w.withdraw();w.overrideredirect(True)
  try:w.attributes('-topmost',True)
  except Exception:pass
  w.configure(bg=self.BORDER)
  box=tk.Frame(w,bg=self.BG);box.pack(padx=1,pady=1,fill='both',expand=True)
  inner=tk.Frame(box,bg=self.BG);inner.pack(padx=0,pady=4,fill='both',expand=True)
  self.rows=[]
  for k,it in enumerate(self.items):
   if it['t']=='s':
    tk.Frame(inner,bg=self.SEP,height=1).pack(fill='x',padx=10,pady=4);continue
   if it['t']=='h':
    tk.Label(inner,text=it['label'].upper(),bg=self.HEAD,fg=self.MUTED,font=self.FONTS,anchor='w',padx=14,pady=5).pack(fill='x',pady=(0,3));continue
   dis=(it.get('state')=='disabled');lab=self._text(it);lw=lab.lower()
   fg=self.DIS if dis else (self.RED if ('kaldır' in lw or 'gizle' in lw) else (self.ACC if lab.startswith('TASARIMI DÜZENLE') else self.FG))
   fnt=self.FONTB if (not dis and lab.startswith('TASARIMI DÜZENLE')) else self.FONT
   row=tk.Frame(inner,bg=self.BG,cursor='arrow' if dis else 'hand2');row.pack(fill='x',padx=4)
   ic=tk.Label(row,text=self._icon(it),bg=self.BG,fg=(self.ACC if it['label'].startswith('✓ ') else (self.DIS if dis else self.MUTED)),font=('Segoe UI Symbol',10),width=3,anchor='center')
   ic.pack(side='left',pady=5)
   tx=tk.Label(row,text=lab,bg=self.BG,fg=fg,font=fnt,anchor='w');tx.pack(side='left',fill='x',expand=True,pady=5,padx=(2,18))
   ar=None
   if it['t']=='m':
    ar=tk.Label(row,text='›',bg=self.BG,fg=self.DIS if dis else self.MUTED,font=('Segoe UI',12,'bold'));ar.pack(side='right',padx=(0,10))
   rec=dict(it=it,row=row,parts=[x for x in (row,ic,tx,ar) if x is not None],fg=fg,ic=ic,tx=tx,dis=dis)
   self.rows.append(rec)
   for wd in rec['parts']:
    wd.bind('<Enter>',lambda e=None,r=rec:self._hover(r))
    wd.bind('<ButtonPress-1>',lambda e=None,r=rec:setattr(self,'_down',r))
    wd.bind('<ButtonRelease-1>',lambda e=None,r=rec:(self._activate(r) if getattr(self,'_down',None) is r else None))     # basış+bırakış aynı satırda olmalı (yanlışlıkla tetiklenmez)
  w.update_idletasks()
  ww,wh=w.winfo_reqwidth(),w.winfo_reqheight()
  ww=max(ww,238 if anchor is None else 220)
  sw,sh=w.winfo_screenwidth(),w.winfo_screenheight()
  if anchor is not None:
   px,py,pw=anchor
   x=px+pw-3
   if x+ww>sw:x=px-ww+3
  x=max(0,min(x,sw-ww-2));y=max(0,min(y,sh-wh-40)) if y+wh>sh-40 else max(0,y)
  w.geometry('%dx%d+%d+%d'%(ww,wh,x,y));w.deiconify();w.lift()
  AlfMenu._stack.append(self)
  if not AlfMenu._bound:
   AlfMenu._bound=True
   try:w.bind_all('<ButtonPress>',AlfMenu._outside,add='+')
   except Exception:pass
  for ev,fn in (('<Escape>',lambda e=None:(AlfMenu.close_all(),'break')[1]),('<Down>',lambda e=None:self._move(1)),('<Up>',lambda e=None:self._move(-1)),
                ('<Return>',lambda e=None:self._key_enter()),('<Right>',lambda e=None:self._key_right()),('<Left>',lambda e=None:self._key_left())):
   w.bind(ev,fn)
  w.bind('<FocusOut>',lambda e=None:self._focus_out())
  try:w.focus_force()
  except Exception:pass
 @staticmethod
 def _outside(e):
  if not AlfMenu._stack or _acilis_time.time()-getattr(AlfMenu,'_t0',0)<0.3:return          # menüyü açan sağ tıkın kendisi (genel bağ aynı olayda sonra çalışır) kapatmasın
  try:top=e.widget.winfo_toplevel()
  except Exception:return
  if any(m.win is not None and m.win==top for m in AlfMenu._stack):return
  AlfMenu.close_all()
 def _focus_out(self):
  def chk():
   if not AlfMenu._stack or not AlfMenu.focus_close:return
   try:
    f=self.win.focus_get() if self.win is not None else None
    ok=f is not None and any(m.win is not None and f.winfo_toplevel()==m.win for m in AlfMenu._stack)
   except Exception:ok=False
   if not ok:AlfMenu.close_all()
  try:self.win.after(150,chk)
  except Exception:pass
 def _paint(self,rec,on):
  bg=self.HOVER if on and not rec['dis'] else self.BG
  for wd in rec['parts']:
   try:wd.configure(bg=bg)
   except Exception:pass
 def _hover(self,rec):
  if self.cur is not None and self.cur is not rec:self._paint(self.cur,False)
  self.cur=rec;self._paint(rec,True)
  it=rec['it']
  if self._job:
   try:self.win.after_cancel(self._job)
   except Exception:pass
   self._job=None
  if it['t']=='m' and not rec['dis']:
   self._job=self.win.after(140,lambda:(self._open_sub(rec) if self.cur is rec else None))
  elif self.sub is not None:
   self._close_sub()
 def _close_sub(self):
  s=self.sub
  if s is None:return
  self.sub=None
  try:s._close_sub()
  except Exception:pass
  try:
   if s.win is not None:s.win.destroy()
  except Exception:pass
  s.win=None
  if s in AlfMenu._stack:AlfMenu._stack.remove(s)
 def _open_sub(self,rec):
  try:
   if self.win is None:return
   m=rec['it']['menu']
   if self.sub is m and m.win is not None:return
   self._close_sub()
   if m is None or not m.items:return
   r=rec['row'];m.master=self.master
   self.sub=m;m._show(self.win.winfo_rootx(),r.winfo_rooty()-5,(self.win.winfo_rootx(),r.winfo_rooty(),self.win.winfo_width()))
  except Exception as e:
   try:log_error('Menü alt menü',e)
   except Exception:pass
 def _activate(self,rec):
  it=rec['it']
  if rec['dis']:return
  if it['t']=='m':self._open_sub(rec);return
  cmd=it.get('cmd');root=self.master.winfo_toplevel() if self.master is not None else None
  AlfMenu.close_all()
  if cmd is None:return
  def run():
   try:cmd()
   except Exception as e:
    try:log_error('Menü komutu',e)
    except Exception:pass
  try:root.after(20,run)
  except Exception:run()
 def _enabled(self):return [r for r in self.rows if not r['dis']]
 def _move(self,d):
  m=AlfMenu._stack[-1] if AlfMenu._stack else self
  en=m._enabled()
  if not en:return 'break'
  i=en.index(m.cur) if m.cur in en else (-1 if d>0 else 0)
  m._hover(en[(i+d)%len(en)]);return 'break'
 def _key_enter(self):
  m=AlfMenu._stack[-1] if AlfMenu._stack else self
  if m.cur is not None:m._activate(m.cur)
  return 'break'
 def _key_right(self):
  m=AlfMenu._stack[-1] if AlfMenu._stack else self
  if m.cur is not None and m.cur['it']['t']=='m':m._open_sub(m.cur)
  return 'break'
 def _key_left(self):
  m=AlfMenu._stack[-1] if AlfMenu._stack else self
  if m.parent is not None and m.parent in AlfMenu._stack:m.parent._close_sub()
  return 'break'

def _alfabe_tree_font_menu(menu,tree):
 sub=AlfMenu(menu,tearoff=0)
 for label,delta in [('2 punto artır',2),('1 punto artır',1),('2 punto azalt',-2),('1 punto azalt',-1)]:
  sub.add_command(label=label,command=lambda d=delta:_alfabe_apply_tree_font(tree,_alfabe_tree_font_size(tree)+d))
 sub.add_separator()
