def _save_tree_layout(tree,force=False):
 try:
  if not tree.winfo_exists():return False
  if not force and not ayar_evet('table_layout_memory'):return False
  key=_tree_layout_key(tree)
  if not key:return False
  cols=[str(x) for x in tree.cget('columns')]
  layout={'widths':{},'displaycolumns':list(tree.cget('displaycolumns')),'align':{},'manual_align':dict(getattr(tree,'_alfabe_manual_anchors',{})),'font_size':getattr(tree,'_alfabe_font_size',None),'image_hidden':bool(getattr(tree,'_alfabe_img_hidden',False))}
  for c in cols:
   try:
    layout['widths'][c]=int(_TREEVIEW_COLUMN_ORIGINAL(tree,c,'width'));layout['align'][c]=str(_TREEVIEW_COLUMN_ORIGINAL(tree,c,'anchor'))
   except Exception as _se:_silent(_se)
  data=dict(_load_table_layouts());pref=_tree_legacy_layout_prefix(tree)
  # Baslik/sutun kaydi font yuklenmeden tetiklenirse eski font boyutu silinmesin.
  if layout['font_size'] is None:
   _old_font_key,_old_font_layout=_find_saved_tree_layout(tree,data)
   if isinstance(_old_font_layout,dict):
    layout['font_size']=_old_font_layout.get('font_size')
  if force:layout['explicit']=True
  else:
   _ok,_ol=_find_saved_tree_layout(tree,data)
   if isinstance(_ol,dict) and _ol.get('explicit'):layout['explicit']=True
  if data.get(key)==layout:return True
  for k in list(data):
   if k!=key and ((pref and str(k).startswith(pref)) or k in _tree_layout_keys(tree)):data.pop(k,None)
  data[key]=layout;_write_table_layouts(data)
  return True
 except Exception as e:
  log_error('Tablo yerlesimi otomatik kayit',e);return False

def _save_tree_layout_explicit(tree):
 # Menüden 'Tablo Yerleşimini Kaydet': ayardan bağımsız kaydeder, sonucu kullanıcıya bildirir.
 try:
  ok=_save_tree_layout(tree,force=True)
  chk=_find_saved_tree_layout(tree,_load_table_layouts())[1] if ok else None
  if ok and isinstance(chk,dict):
   messagebox.showinfo(APP,'Tablo yerleşimi kaydedildi.\n\nSütun genişlikleri, sırası, gizli alanlar ve yazı boyutu bu tablo bir sonraki açılışta aynı şekilde gelecek.',parent=tree.winfo_toplevel())
  else:
   messagebox.showerror(APP,'Tablo yerleşimi kaydedilemedi.\n\nVeri klasörüne yazma izni olduğundan emin olun:\n'+str(_TABLE_LAYOUT_FILE),parent=tree.winfo_toplevel())
 except Exception as e:log_error('Tablo yerleşimi açık kayıt',e)

def _restore_tree_layout(tree):
 try:
  if not tree.winfo_exists():return
  _oldkey,layout=_find_saved_tree_layout(tree)
  if not isinstance(layout,dict):return
  if not ayar_evet('table_layout_memory') and not layout.get('explicit'):return
  cols=[str(x) for x in tree.cget('columns')]
  widths=layout.get('widths',{})
  for c in cols:
   if c in widths:
    try:_TREEVIEW_COLUMN_ORIGINAL(tree,c,width=max(35,int(widths[c])),stretch=False)
    except Exception as _se:_silent(_se)
  align=layout.get('align',{})
  # Eski kayitli otomatik hizalamalar elle secilmis gibi uygulanmasin.
  manual=layout.get('manual_align',{})
  tree._alfabe_manual_anchors={str(c):a for c,a in manual.items() if str(c) in cols and a in ('w','e','center')} if isinstance(manual,dict) else {}
  for c,a in align.items():
   if c in cols and a in ('w','e','center'):
    try:_TREEVIEW_COLUMN_ORIGINAL(tree,c,anchor=_alfabe_global_column_anchor(tree,c));tree.heading(c,anchor='center')
    except Exception as _se:_silent(_se)
  disp=layout.get('displaycolumns')
  if isinstance(disp,list) and disp:
   valid=[str(x) for x in disp if str(x) in cols]
   if valid:tree.configure(displaycolumns=valid)
  if layout.get('image_hidden'):
   try:_tree_toggle_image_col(tree,False,save=False)
   except Exception as _se:_silent(_se)
  _alfabe_realign_existing_columns(tree)
  if layout.get('font_size') is not None:_alfabe_apply_tree_font(tree,layout['font_size'],save=False)
  tree._alfabe_layout_loaded=True
 except Exception as e:log_error('Tablo yerlesimi geri yukleme',e)

def _persistent_treeview_init(self,*args,**kwargs):
 _TREEVIEW_INIT_ORIGINAL(self,*args,**kwargs)
 # heading/column tanimlari constructor'dan sonra yapildigi icin idle'da geri yukle.
 self.after_idle(lambda t=self:_restore_tree_layout(t))
 self.bind('<Destroy>',lambda e=None,t=self:_save_tree_layout(t) if (e is not None and e.widget is t) else None,add='+')

ttk.Treeview.__init__=_persistent_treeview_init
_TREEVIEW_CONFIGURE_ORIGINAL=ttk.Treeview.configure
def _persistent_treeview_configure(self,cnf=None,**kw):
 r=_TREEVIEW_CONFIGURE_ORIGINAL(self,cnf,**kw)
 try:
  if (isinstance(cnf,dict) and 'columns' in cnf) or 'columns' in kw:
   self._alfabe_layout_loaded=False
   if not getattr(self,'_alf_rl_pending',False):
    self._alf_rl_pending=True
    def _go(t=self):
     t._alf_rl_pending=False
     _restore_tree_layout(t)
    self.after_idle(_go)
 except Exception as _se:_silent(_se)
 return r
ttk.Treeview.configure=_persistent_treeview_configure
ttk.Treeview.config=_persistent_treeview_configure

# v1.2.291.95 - Program geneli guvenli sutun surukle/birak.
# Eski/varsayilan kolon sirasi degismez. Kullanici yalniz basligi yatay suruklerse
# displaycolumns sirasi degisir; veri, rapor hesabi ve satir sirasi etkilenmez.
def _global_column_drag_start(tree,event):
 tree._alfabe_drag_col=None;return  # v282: yeni sürükleme (_tree_drag_*) devraldı
 try:
  if tree.identify_region(event.x,event.y)!='heading':
   tree._alfabe_drag_col=None; return
  token=tree.identify_column(event.x)
  if not token or token=='#0':tree._alfabe_drag_col=None;return
  visible=_tree_visible_columns(tree)
  idx=int(token[1:])-1
  tree._alfabe_drag_col=visible[idx] if 0<=idx<len(visible) else None
  tree._alfabe_drag_start_x=int(event.x);tree._alfabe_drag_moved=False
 except Exception:tree._alfabe_drag_col=None

def _global_column_drag_motion(tree,event):
 return  # v282: yeni sürükleme devraldı
 try:
  col=getattr(tree,'_alfabe_drag_col',None)
  if not col:return
  # Normal baslik tiklamalarini/siralama davranisini bozmamak icin 8 px esik.
  if abs(int(event.x)-int(getattr(tree,'_alfabe_drag_start_x',event.x)))<8:return
  if tree.identify_region(event.x,event.y)!='heading':return
  token=tree.identify_column(event.x)
  if not token or token=='#0':return
  visible=_tree_visible_columns(tree)
  if col not in visible:return
  target=int(token[1:])-1
  if not (0<=target<len(visible)):return
  old=visible.index(col)
  if old!=target:
   visible.pop(old);visible.insert(target,col)
   tree.configure(displaycolumns=visible)
   tree._alfabe_drag_moved=True
 except Exception as e:log_error('Genel sutun surukleme',e)

def _global_column_drag_end(tree,event):
 try:
  if getattr(tree,'_alfabe_drag_col',None) and getattr(tree,'_alfabe_drag_moved',False):
   _save_tree_layout(tree,force=True)
 finally:
  tree._alfabe_drag_col=None;tree._alfabe_drag_moved=False

# Mevcut Treeview kurucusuna ikinci kez wrapper yapmadan, bundan sonra olusan tum
# tablolara davranisi eklemek icin onceki wrapper'a baglari ekle.
_PERSISTENT_TREEVIEW_INIT_29194=_persistent_treeview_init
