# v1.2.177 - Program genelinde guvenli Alan Secici.
# Bir tablonun kodda tanimli tum sutunlarini listeler; gizle/goster yalniz gorunumu degistirir.
def _tree_set_display_global(tree,cols):
 try:
  allcols=[str(c) for c in tree.cget('columns')]
  valid=[str(c) for c in cols if str(c) in allcols]
  if not valid:return
  tree.configure(displaycolumns=valid)
  _save_tree_layout(tree,force=True)
 except Exception as e:log_error('Genel tablo alan secimi',e)

def _tree_toggle_field_global(tree,col):
 try:
  visible=_tree_visible_columns(tree)
  if col in visible:
   if len(visible)<=1:return
   visible=[c for c in visible if c!=col]
  else:
   visible.append(col)
  _tree_set_display_global(tree,visible)
 except Exception as e:log_error('Genel tablo alan gizle/goster',e)

def _tree_add_extra_field(tree,col):
 try:
  if col not in set(getattr(tree,'_alfabe_extra_columns',())):return
  active=set(getattr(tree,'_alfabe_active_extra_columns',()));active.add(col);tree._alfabe_active_extra_columns=active
  visible=_tree_visible_columns(tree)
  if col not in visible:visible.append(col)
  _tree_set_display_global(tree,visible)
  cb=getattr(tree,'_alfabe_extra_changed',None)
  if cb:cb()
 except Exception as e:log_error('Yeni alan ekleme',e)

def _add_global_field_selector(menu,tree,col):
 # v1.2.291.94 - Gercek sutun ekle/cikar: sadece Treeview'da veri karsiligi olan
 # kolonlar sunulur. Islem veriyi silmez; yalniz displaycolumns gorunumunu degistirir.
 menu.add_separator()
 # v461.93: Görsel (#0) başlığına sağ tıklanınca 'Bu alanı kaldır' ilk gerçek sütunu değil Görsel sütununu gizler.
 if col=='#0':menu.add_command(label='Bu alanı kaldır (Görsel)',command=lambda:_tree_toggle_image_col(tree,False))
 else:menu.add_command(label='Bu alanı kaldır',command=lambda:_tree_toggle_field_global(tree,col))
 if getattr(tree,'_alfabe_img_hidden',False):menu.add_command(label='Görsel sütununu göster',command=lambda:_tree_toggle_image_col(tree,True))
 elif 'tree' in str(tree.cget('show')):menu.add_command(label='Görsel sütununu gizle',command=lambda:_tree_toggle_image_col(tree,False))
 fields=AlfMenu(menu,tearoff=0);allcols=[str(c) for c in tree.cget('columns')];visible=_tree_visible_columns(tree)
 extras=set(getattr(tree,'_alfabe_extra_columns',()));active=set(getattr(tree,'_alfabe_active_extra_columns',()))
 shown=[]
 for c in allcols:
  # Pasif ekstra alanlar once Yeni Alan Ekle menusunden etkinlestirilir.
  if c in extras and c not in active and c not in visible:continue
  shown.append(c)
  fields.add_command(label=('✓ ' if c in visible else '   ')+str(tree.heading(c,'text') or c),command=lambda cc=c:_tree_toggle_field_global(tree,cc))
 if shown:
  fields.add_separator();fields.add_command(label='Tüm mevcut alanları göster',command=lambda:_tree_set_display_global(tree,shown))
 menu.add_cascade(label='Alan Seçici',menu=fields)
 available=[c for c in allcols if c in extras and c not in active and c not in visible]
 addm=AlfMenu(menu,tearoff=0)
 if available:
  groups=getattr(tree,'_alfabe_extra_groups',None);done=set()
  for gname,gcols in (groups or ()):
   gl=[c for c in gcols if c in available]
   if not gl:continue
   addm.add_header(gname)
   for c in gl:done.add(c);addm.add_command(label=str(tree.heading(c,'text') or c),command=lambda cc=c:_tree_add_extra_field(tree,cc))
  rest=[c for c in available if c not in done]
  if rest and done:addm.add_header('Diğer')
  for c in rest:addm.add_command(label=str(tree.heading(c,'text') or c),command=lambda cc=c:_tree_add_extra_field(tree,cc))
 else:addm.add_command(label='Bu ekranda başka kullanılabilir alan yok',state='disabled')
 menu.add_cascade(label='＋ Yeni Alan Ekle...',menu=addm)


def _ensure_extra_tree_headings(tree):
 try:
  labels={'source':'Kaynak','source_id':'Kaynak ID','op_key':'İşlem Anahtarı','note':'Not','kind':'Tür',
          'scope_type':'Kapsam Türü','scope_value':'Kapsam Değeri','buy_qty':'Al Adet','pay_qty':'Öde Adet',
          'min_cart':'Min. Sepet','discount_pct':'İndirim %','fixed_price':'Sabit Fiyat','supplier_id':'Tedarikçi ID'}
  for c in set(getattr(tree,'_alfabe_extra_columns',())):
   if not str(tree.heading(c,'text') or '').strip():tree.heading(c,text=labels.get(c,c))
 except Exception as _se:_silent(_se)

# v1.2.176 - Program genelinde Treeview sutunlarinda canli hizalama.
# Stok tablolarinda mevcut kapsamli sag-tik menusu korunur.

# Var olan Treeview kurucusunu tekrar sarmalamadan, class binding ile tum stok alt ekranlarina uygula.
# Fonksiyon kendi icinde stok ekrani kontrolu yaptigi icin diger modullerde sag tik davranisi degismez.
def _tree_context_menu_29170(tree,event,force=False,top_items=None):
 # 291.70 - Program genelinde Treeview sag tik menusu.
 # Baslikta veya veri satirinda sag tiklandiginda ayni gorunum/yazdirma menusu acilir.
 try:
  if not isinstance(tree,ttk.Treeview):return None
  # Genel Alan Seçici yalnız sütun başlığında çalışır; satır sağ tık menülerini bozmaz.
  if not force and tree.identify_region(event.x,event.y)!='heading':return None
  visible=_tree_visible_columns(tree)
  if not visible:return 'break'
  coltag=tree.identify_column(event.x)
  try:idx=int(str(coltag)[1:])-1
  except Exception:idx=0
  if idx<0 or idx>=len(visible):idx=0
  col=visible[idx]
  is_img=(str(coltag)=='#0' and 'tree' in str(tree.cget('show')))
  menu=AlfMenu(tree,tearoff=0)
  try:menu.add_header('Sütun: '+('Görsel' if is_img else str(tree.heading(col,'text') or col))) if tree.identify_region(event.x,event.y)=='heading' else None
  except Exception as _se:_silent(_se)
  for _lab,_cmd in (top_items or []):
   if _lab is None:menu.add_separator()
   else:menu.add_command(label=_lab,command=_cmd)
  _ensure_extra_tree_headings(tree)
  _add_global_field_selector(menu,tree,'#0' if is_img else col)
  align=AlfMenu(menu,tearoff=0)
  align.add_command(label='Sola Yasla',command=lambda:_stock_tree_align(tree,col,'w'))
  align.add_command(label='Sağa Yasla',command=lambda:_stock_tree_align(tree,col,'e'))
  align.add_command(label='Ortala',command=lambda:_stock_tree_align(tree,col,'center'))
  menu.add_cascade(label='Hizalama',menu=align)
  _alfabe_tree_font_menu(menu,tree)
  menu.add_separator()
  menu.add_command(label='En iyi yerleşim',command=lambda:_stock_tree_best_fit(tree,col))
  menu.add_command(label='Akıllı Hizala (Tüm Sütunlar)',command=lambda:_stock_tree_best_fit(tree))
  menu.add_separator()
  menu.add_command(label='Tablo Yerleşimini Kaydet',command=lambda:_save_tree_layout_explicit(tree))
  menu.add_command(label='Varsayılan Yerleşimi Kullan',command=lambda:_stock_tree_default(tree))
  menu.add_separator()
  menu.add_command(label='Baskı Ön İzleme',command=lambda:_open_tree_print_center(tree))
  menu.add_command(label='TASARIMI DÜZENLE (Görsel PRO)',command=lambda:_tree_visual_designer(tree))
  menu.add_command(label='TASARIMI KAYDET',command=lambda:_tree_visual_design_save(tree))
  menu.tk_popup(event.x_root,event.y_root)
  tree._alfabe_context_menu=menu
 except Exception as e:
  log_error('291.70 tablo sag tik menusu',e)
 finally:
  try:menu.grab_release()
  except Exception as _se:_silent(_se)
 return 'break'

def _tree_hover_x_hide(tree):
 try:
  d=getattr(tree,'_alfabe_hx',None)
  if d and d.get('lbl'):d['lbl'].place_forget()
 except Exception as _se:_silent(_se)

def _tree_toggle_image_col(tree,show=None,save=True):
 # Görsel (#0) sütununu gizler/gösterir; ürün resimleri silinmez.
 try:
  cur=str(tree.cget('show'))
  hidden=bool(getattr(tree,'_alfabe_img_hidden',False))
  want_show=(hidden if show is None else bool(show))
  if want_show and 'tree' not in cur:
   tree.configure(show='tree headings');tree._alfabe_img_hidden=False
  elif not want_show and 'tree' in cur:
   tree.configure(show='headings');tree._alfabe_img_hidden=True
  if save:_save_tree_layout(tree,force=True)
 except Exception as e:log_error('Gorsel sutunu gizle/goster',e)

def _tree_hover_x_get(tree):
 d=getattr(tree,'_alfabe_hx',None)
 if d is None:
  lbl=tk.Label(tree,text='\u2715',bg='#C8102E',fg='white',font=('Segoe UI',8,'bold'),cursor='hand2')
  d=tree._alfabe_hx={'lbl':lbl,'col':None}
  def _click(_e=None,t=tree):
   c=t._alfabe_hx.get('col');_tree_hover_x_hide(t)
   if c=='#0':_tree_toggle_image_col(t,False)
   elif c:_tree_toggle_field_global(t,c)
  lbl.bind('<Button-1>',_click)
  lbl.bind('<Leave>',lambda _e,t=tree:_tree_hover_x_hide(t))
 return d



def _tree_col_edges(tree):
 # Görünür sütunların (ad,sol,sağ) kenarları; yatay kaydırma dahil, widget koordinatında.
 visible=_tree_visible_columns(tree)
 w0=int(tree.column('#0','width')) if 'tree' in str(tree.cget('show')) else 0
 widths=[int(tree.column(c,'width')) for c in visible]
 total=w0+sum(widths)
 off=int(round(tree.xview()[0]*total)) if total else 0
 out=[];x=w0-off
 for c,w in zip(visible,widths):
  out.append((c,x,x+w));x+=w
 return out,w0-off

def _tree_drag_cleanup(tree):
 st=getattr(tree,'_alfabe_drag',None)
 if st:
  for k in ('ghost','ind'):
   try:
    if st.get(k):st[k].place_forget()
   except Exception as _se:_silent(_se)
 tree._alfabe_drag=None

def _tree_drag_target(tree,x):
 # Bırakma konumu: kaçıncı sütunun önüne eklenecek (0..n) ve çizgi x'i.
 edges,_=_tree_col_edges(tree)
 if not edges:return 0,0
 for i,(c,l,r) in enumerate(edges):
  if x<(l+r)/2:return i,l
 return len(edges),edges[-1][2]

def _tree_drag_start(event):
 tree=event.widget
 try:
  _tree_drag_cleanup(tree)
  if not isinstance(tree,ttk.Treeview):return
  if tree.identify_region(event.x,event.y)!='heading':return
  tag=str(tree.identify_column(event.x))
  if tag=='#0':return
  visible=_tree_visible_columns(tree);idx=int(tag[1:])-1
  if idx<0 or idx>=len(visible) or len(visible)<2:return
  tree._alfabe_drag={'col':visible[idx],'x0':event.x,'moved':False,'ghost':None,'ind':None}
 except Exception:tree._alfabe_drag=None

def _tree_drag_autoscroll(tree):
 st=getattr(tree,'_alfabe_drag',None)
 if not st or not st.get('moved'):return
 try:
  px=tree.winfo_pointerx()-tree.winfo_rootx();w=tree.winfo_width()
  if px<40:tree.xview_scroll(-1,'units')
  elif px>w-40:tree.xview_scroll(1,'units')
  else:
   st['auto']=None;return
  _tree_drag_draw(tree,px)
  st['auto']=tree.after(60,lambda:_tree_drag_autoscroll(tree))
 except Exception as _se:_silent(_se)

def _tree_drag_draw(tree,x):
 st=getattr(tree,'_alfabe_drag',None)
 if not st:return
 if st['ghost'] is None:
  txt=str(tree.heading(st['col'],'text') or st['col'])
  st['ghost']=tk.Label(tree,text=' '+txt+' ',bg='#FFE08A',fg='#222',relief='solid',bd=1,font=('Segoe UI',9,'bold'))
  st['ind']=tk.Frame(tree,bg='#C8102E',width=3)
 pos,lx=_tree_drag_target(tree,x)
 st['ghost'].place(x=max(0,min(x-30,tree.winfo_width()-80)),y=2);st['ghost'].lift()
 st['ind'].place(x=max(0,lx-1),y=0,width=3,height=max(40,tree.winfo_height()));st['ind'].lift()
 st['pos']=pos

def _tree_drag_motion(event):
 tree=event.widget
 st=getattr(tree,'_alfabe_drag',None)
 if not st:return
 try:
  if not st['moved']:
   if abs(event.x-st['x0'])<8:return
   st['moved']=True;_tree_hover_x_hide(tree)
  _tree_drag_draw(tree,event.x)
  if not st.get('auto'):_tree_drag_autoscroll(tree)
 except Exception as e:log_error('Sutun surukleme',e)

def _tree_drag_end(event):
 tree=event.widget
 st=getattr(tree,'_alfabe_drag',None)
 if not st:return
 try:
  if st['moved']:
   visible=_tree_visible_columns(tree);col=st['col']
   pos=_tree_drag_target(tree,event.x)[0]
   if col in visible:
    old=visible.index(col)
    visible.remove(col)
    if pos>old:pos-=1
    visible.insert(max(0,min(pos,len(visible))),col)
    tree.configure(displaycolumns=visible)
    try:_save_tree_layout(tree,force=True)
    except Exception as _se:_silent(_se)
 except Exception as e:log_error('Sutun surukleme birak',e)
 finally:_tree_drag_cleanup(tree)

_NUM_RE=re.compile(r'^\s*[-+]?[\d.,\s]*\d[\d.,\s]*\s*(?:₺|TL|%)?\s*$')

def _num_entry_select_all(e):
    """Sayı kutusuna tıklayınca / girince içeriği SEÇİLİ yap: yeni değer doğrudan yazılsın (yazı kutularına dokunmaz)."""
    try:
        w=e.widget
        if str(w.cget('show')):return                      # parola kutusu
        if str(w.cget('state')) in ('disabled','readonly'):return
        txt=w.get()
        if not txt or not _NUM_RE.match(txt):return          # yalnız sayı görünümlü içerik
        if w.selection_present():return                       # kullanıcı zaten fare ile seçim yaptı
        w.after_idle(lambda:(w.select_range(0,'end'),w.icursor('end')))
    except Exception:pass

_ALF_CLICK={'w':None,'t':0.0}
def _alf_click_press(e):
    _ALF_CLICK['w']=e.widget;_ALF_CLICK['t']=_alf_time.time()
def _alf_click_focusin(e):
    # Fare tıklamasıyla ODAK KAZANAN yazı kutusu: bırakınca içeriği tümüyle seçilecek (arama kutusuna yeni yazı eskisinin üstüne yazılır).
    try:
        w=e.widget
        if _ALF_CLICK['w'] is w and _alf_time.time()-_ALF_CLICK['t']<0.5:w._alf_sel_pending=True
    except Exception:pass
def _alf_click_release(e):
    try:
        w=e.widget
        if not getattr(w,'_alf_sel_pending',False):return
        w._alf_sel_pending=False
        if str(w.cget('show')):return                       # parola
        if str(w.cget('state')) in ('disabled','readonly'):return
        if getattr(w,'_alf_no_click_select',False):return
        if not w.get():return
        if w.selection_present():return                      # sürükleyerek kendisi seçti
        w.after_idle(lambda:(w.select_range(0,'end'),w.icursor('end')))
    except Exception:pass

def _alf_tree_bos_tik(e):
    # Programın geneli: tabloda BOŞ bir yere (satır olmayan alana) tıklanınca seçili satırın mavisi kalkar.
    try:
        t=e.widget
        if getattr(t,'_alf_keep_sel',False):return                 # giriş ekranındaki firma listesi gibi seçili kalması gerekenler
        if t.identify_region(e.x,e.y)=='nothing':
            sel=t.selection()
            if sel:t.selection_remove(*sel)
    except Exception:pass

def _alf_fis_sigdir(h,w=80.0,m=3.0):
 """80 mm fiş/etiket çıktısı: sayfa genişliği = kâğıt - kenar boşlukları, yükseklik ise açılışta ve yazdırmadan hemen önce
 gerçek içerik yüksekliğinden ölçülüp @page'e yazılır (sabit tahmini yükseklik uzun listeyi kesiyor, kısa listede boş uzuyordu)."""
 if 'id="alf_pg"' in h or 'getElementById("alf_pg")' in h:return h
 cw=max(20.0,w-2*m)
 css=('<style>@media screen{body{padding:0!important;background:#fff!important}.report-page{box-sizing:content-box!important;max-width:none!important;width:%gmm!important;padding:%gmm!important;box-shadow:none!important;margin:0 auto!important}}'
  '.report-page{min-height:0!important;margin:0!important;padding-bottom:0!important;break-after:auto!important;page-break-after:auto!important}.footer{position:static!important;margin-top:4px}'
  'html,body{margin:0}table{width:100%%!important;table-layout:auto!important}col{width:auto!important}td,th{white-space:normal!important;overflow:visible!important;text-overflow:clip!important;word-break:break-word;padding:2px 2px!important}'
  'td[style*="text-align:right"],th{white-space:nowrap!important}.foot,.footer{font-size:7pt}</style>')%(cw,m)
 js=('<script>(function(){var W=%g,M=%g;function fit(){try{var st=document.getElementById("alf_pg");if(!st){st=document.createElement("style");st.id="alf_pg";document.head.appendChild(st);}'
  'var b=document.body,px=Math.max(b.scrollHeight,b.getBoundingClientRect().height);var hh=Math.ceil(px*25.4/96)+2;st.textContent="@page{size:"+W+"mm "+(hh+4)+"mm;margin:"+M+"mm}";}catch(e){}}'
  'window.addEventListener("load",fit);window.addEventListener("beforeprint",fit);if(document.readyState==="complete")fit();})();</script>')%(w,m)
 return h.replace('</head>',css+'</head>',1).replace('</body>',js+'</body>',1) if '</body>' in h else h.replace('</head>',css+js+'</head>',1)

