def decimal_places(value=None):
 global NUMBER_DECIMALS
 if value is not None:
  try:NUMBER_DECIMALS=max(0,min(4,int(str(value).strip())))
  except Exception:NUMBER_DECIMALS=2
 return NUMBER_DECIMALS

def number(v,places=None):
 try:
  p=decimal_places() if places is None else max(0,min(6,int(places)))
  return f'{float(v):,.{p}f}'.replace(',','X').replace('.',',').replace('X','.')
 except:return ('0' if (decimal_places() if places is None else int(places or 0))==0 else '0,'+'0'*(decimal_places() if places is None else int(places or 0)))

def money(v):
    return number(v)+' ₺'

def qty_display(v):
    """Miktar/adet gösterimi: tam sayıda ondalık gösterme (1), gerçek küsuratı Türkçe virgülle koru (1,5)."""
    try:return _ui_qty_text(float(v or 0))
    except Exception:return '0'

def fnum(s):
    try:return float(str(s).replace('.','').replace(',','.')) if ',' in str(s) else float(s or 0)
    except:return 0.0

def fnum_tutar(s):
    """Kullanıcının elle yazdığı TUTAR: '1.500' = 1500 (Türkçe binlik), nan/inf geçersiz (0)."""
    try:
        t=str(s if s is not None else '').replace('₺','').replace(' ','').strip()
        if ',' not in t and re.fullmatch(r'-?[1-9]\d{0,2}(\.\d{3})+',t):t=t.replace('.','')
        v=fnum(t)
        return v if v==v and v not in (float('inf'),float('-inf')) else 0.0
    except Exception:return 0.0

def _export_numeric(value):
 """Rapor değerini metne çevirmeden gerçek Excel sayısı olarak yakala."""
 if isinstance(value,(int,float)) and not isinstance(value,bool):return float(value)
 s=str(value or '').strip().replace(' ₺','').replace('%','').strip()
 if not s:return None
 # Belge/barkod/tarih gibi kimlikleri yanlışlıkla sayıya dönüştürme.
 if re.search(r'[A-Za-zÇĞİÖŞÜçğıöşü:/-]',s):return None
 try:return float(s.replace('.','').replace(',','.')) if ',' in s else float(s)
 except Exception:return None

def _xlsx_col(n):
 out=''
 while n:
  n,r=divmod(n-1,26);out=chr(65+r)+out
 return out

def write_report_export(path,title,heads,rows,total_row=None,report_key=''):
 """CSV veya bağımlılıksız gerçek XLSX üretir; sayılar Excel'de hesaplanabilir kalır."""
 path=str(path);design=report_design_get(report_key or title,heads);cols=report_visible_columns(design,heads)
 out_heads=[c[3] for c in cols];out_rows=[[tuple(r)[c[1]] if c[1]<len(tuple(r)) else '' for c in cols] for r in rows]
 out_total=[tuple(total_row)[c[1]] if c[1]<len(tuple(total_row)) else '' for c in cols] if total_row else None
 if path.lower().endswith('.csv'):
  with open(path,'w',newline='',encoding='utf-8-sig') as f:
   w=csv.writer(f,delimiter=';',lineterminator='\n');w.writerow(out_heads)
   for row in out_rows:w.writerow([number(v) if isinstance(v,(int,float)) and not isinstance(v,bool) else v for v in row])
   if out_total:w.writerow([]);w.writerow([number(v) if isinstance(v,(int,float)) and not isinstance(v,bool) else v for v in out_total])
  return path
 def esc(v):return html.escape(str(v if v is not None else ''),quote=False)
 def cell(v,ref,style=0):
  num=_export_numeric(v)
  if num is not None:return f'<c r="{ref}" s="{style or 2}"><v>{num:.12g}</v></c>'
  return f'<c r="{ref}" s="{style}" t="inlineStr"><is><t xml:space="preserve">{esc(v)}</t></is></c>'
 all_rows=[out_heads]+out_rows+(([out_total]) if out_total else [])
 xmlrows=[]
 for ri,row in enumerate(all_rows,1):
  style=1 if ri==1 or (out_total and ri==len(all_rows)) else 0
  xmlrows.append(f'<row r="{ri}">'+''.join(cell(v,f'{_xlsx_col(ci)}{ri}',style) for ci,v in enumerate(row,1))+'</row>')
 widths=''.join(f'<col min="{i}" max="{i}" width="{max(10,min(55,w/8)):.1f}" customWidth="1"/>' for i,w in enumerate((c[2] for c in cols),1))
 dim=f'A1:{_xlsx_col(max(1,len(out_heads)))}{max(1,len(all_rows))}'
 sheet='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><dimension ref="'+dim+'"/><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>'+widths+'</cols><sheetData>'+''.join(xmlrows)+'</sheetData><autoFilter ref="A1:'+_xlsx_col(max(1,len(out_heads)))+str(max(1,len(all_rows)-(1 if out_total else 0)))+'"/></worksheet>'
 styles=('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts count="1"><numFmt numFmtId="164" formatCode="#,##0'+('' if decimal_places()==0 else '.'+'0'*decimal_places())+'"/></numFmts>'
  '<fonts count="2"><font><sz val="10"/><name val="Calibri"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="10"/><name val="Calibri"/></font></fonts>'
  '<fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF0B376D"/><bgColor indexed="64"/></patternFill></fill></fills>'
  '<borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>'
  '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>'
  '<cellXfs count="3"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1"/><xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs>'
  '<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>')
 files={'[Content_Types].xml':'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>','_rels/.rels':'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml':'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Rapor" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/_rels/workbook.xml.rels':'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>','xl/worksheets/sheet1.xml':sheet,'xl/styles.xml':styles}
 with zipfile.ZipFile(path,'w',zipfile.ZIP_DEFLATED) as z:
  for name,data in files.items():z.writestr(name,data.encode('utf-8'))
 return path

def choose_report_export(parent,title,heads,rows,total_row=None,report_key=''):
 safe=re.sub(r'[^0-9A-Za-zÇĞİÖŞÜçğıöşü _-]+','_',title).strip() or 'Rapor'
 p=filedialog.asksaveasfilename(parent=parent,title='Excel / CSV olarak kaydet',defaultextension='.xlsx',initialfile=safe+'.xlsx',filetypes=[('Excel Çalışma Kitabı','*.xlsx'),('Excel uyumlu CSV','*.csv')])
 if not p:return ''
 write_report_export(p,title,heads,rows,total_row,report_key or title);return p

