def _alf_tv(tv,defs,groups=None):
 # Yeni Alan Ekle desteği: taze oluşturulmuş Treeview'a gizli ek sütunlar ekler (tv'yi döndürür).
 # defs=[(kolon,başlık,genişlik,hizalama)]; değerleri çağıran satır eklerken base değerlerin ARKASINA ekler.
 try:
  base=[str(c) for c in tv.cget('columns')];ex=[d[0] for d in defs]
  tv.configure(columns=tuple(base+ex),displaycolumns=tuple(base))
  for c,h,w,a in defs:tv.heading(c,text=h);tv.column(c,width=w,minwidth=50,anchor=a)
  tv._alfabe_extra_columns=set(ex);tv._alfabe_active_extra_columns=set()
  if groups:tv._alfabe_extra_groups=groups
 except Exception as e:log_error('Ek alan tanimi',e)
 return tv
def _src_doc_no(src,sid,cache):
 # Kaynak koduna göre satış/alış belge numarasını bulur ('-' yoksa).
 try:
  src=str(src or '').upper()
  tab='sales' if src.startswith('SALE') or src=='CARI_SALE' else ('purchases' if src.startswith('PURCHASE') else '')
  if not tab or not sid:return ('-','-')
  k=(tab,int(sid))
  if k not in cache:
   x=DX.one('SELECT doc_no'+(',user' if tab=='sales' else '')+' FROM '+tab+' WHERE id=?',(int(sid),));cache[k]=(x['doc_no'] if x else '-',(x['user'] if x and tab=='sales' else '-'))
  return cache[k]
 except Exception:return ('-','-')
_MOVE_EXTRA=(('prev_qty','Önceki Stok',90,'e'),('next_qty','Sonraki Stok',90,'e'),('value','Hareket Değeri',110,'e'),('doc','Belge No',120,'w'),('user','Kullanıcı',90,'w'),('weekday','Gün',90,'w'))
_MOVE_GROUPS=(('Stok',('prev_qty','next_qty','value')),('Kaynak',('doc','user')),('Zaman',('weekday',)))
def _stock_move_ext(rows,now_qty):
 # stock_moves satırları (yeniden eskiye) için ek alan değerleri; önceki/sonraki stok güncel stoktan geriye doğru hesaplanır.
 out=[];cache={};after=float(now_qty or 0)
 for x in rows:
  q=float(x['qty'] or 0);doc,usr=_src_doc_no(x['source'],x['source_id'],cache)
  try:gun=_GUN_TR[datetime.date.fromisoformat(str(x['dt'] or '')[:10]).weekday()]
  except Exception:gun='-'
  out.append(('%g'%(after-q),'%g'%after,money(q*float(x['unit_cost'] or 0)),doc,usr,gun));after-=q
 return out
