def now(): return datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')

def _date_parse(v):
 x=str(v or '').strip()
 if not x:return None
 for fmt in ('%Y-%m-%d','%d-%m-%Y','%d.%m.%Y','%d/%m/%Y'):
  try:return datetime.datetime.strptime(x[:10],fmt).date()
  except Exception as _se:_silent(_se)
 return None

def _date_display(v):
 d=_date_parse(v);return d.strftime('%d.%m.%Y') if d else str(v or '')

def _datetime_display(v):
 x=str(v or '').strip()
 d=_date_parse(x)
 if not d:return x
 tm=x[10:].strip() if len(x)>10 else ''
 return d.strftime('%d.%m.%Y') + ((' '+tm) if tm else '')

def _date_iso(v):
 d=_date_parse(v);return d.isoformat() if d else str(v or '').strip()

def _calendar_pick(parent,iso_var,on_change=None):
 base=_date_parse(iso_var.get()) or datetime.date.today();state={'y':base.year,'m':base.month}
 w=new_toplevel(parent);w.title('Tarih Seç');w.resizable(False,False);w.grab_set()
 try:w.transient(parent.winfo_toplevel())
 except Exception as _se:_silent(_se)
 head=tk.Frame(w,bg='white');head.pack(fill='x',padx=8,pady=(8,2));title=tk.Label(head,bg='white',font=('Segoe UI',11,'bold'));title.pack(side='left',expand=True)
 body=tk.Frame(w,bg='white');body.pack(padx=8,pady=(2,8))
 def draw():
  for z in body.winfo_children():z.destroy()
  import calendar
  months=('','Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık')
  title.config(text=f"{months[state['m']]} {state['y']}")
  for c,n in enumerate(('Pt','Sa','Ça','Pe','Cu','Ct','Pa')):tk.Label(body,text=n,width=4,bg='white',font=('Segoe UI',9,'bold')).grid(row=0,column=c,pady=2)
  weeks=calendar.Calendar(firstweekday=0).monthdayscalendar(state['y'],state['m'])
  for r,wk in enumerate(weeks,1):
   for c,day in enumerate(wk):
    if not day:continue
    def choose(d=day):
     iso_var.set(datetime.date(state['y'],state['m'],d).isoformat());w.destroy()
     if on_change:
      try:on_change()
      except Exception as _se:_silent(_se)
    tk.Button(body,text=str(day),width=4,command=choose,relief='flat').grid(row=r,column=c,padx=1,pady=1)
 def move(delta):
  m=state['m']+delta;y=state['y']
  if m<1:m=12;y-=1
  if m>12:m=1;y+=1
  state.update(y=y,m=m);draw()
 tk.Button(head,text='◀',width=4,command=lambda:move(-1)).pack(side='left');tk.Button(head,text='▶',width=4,command=lambda:move(1)).pack(side='right');draw()
 try:
  w.update_idletasks();x=parent.winfo_rootx();y=parent.winfo_rooty()+parent.winfo_height()+2;w.geometry(f'+{x}+{y}')
 except Exception as _se:_silent(_se)
 return w

def date_entry(parent,iso_var,width=11,on_change=None,**kw):
 """Ekranda GG.AA.YYYY, uygulama/veritabanında YYYY-AA-GG tutan takvimli tarih alanı."""
 f=tk.Frame(parent,bg=kw.pop('frame_bg','white'));disp=tk.StringVar(value=_date_display(iso_var.get()))
 e=tk.Entry(f,textvariable=disp,width=width,**kw);e.pack(side='left',fill='x',expand=True)
 b=tk.Button(f,text='▾',width=2,command=lambda:_calendar_pick(e,iso_var,lambda:sync_from_iso(True)),takefocus=False);b.pack(side='left')
 busy={'v':False}
 def sync_from_iso(call=False,*_):
  if busy['v']:return
  busy['v']=True
  try:disp.set(_date_display(iso_var.get()))
  finally:busy['v']=False
  if call and on_change:
   try:on_change()
   except Exception as _se:_silent(_se)
 def commit(*_):
  if busy['v']:return
  d=_date_parse(disp.get())
  if d:
   iso_var.set(d.isoformat());disp.set(d.strftime('%d.%m.%Y'))
   if on_change:
    try:on_change()
    except Exception as _se:_silent(_se)
  else:
   disp.set(_date_display(iso_var.get()))
 # Performans: takvim yalnız sağdaki ok düğmesine basıldığında oluşturulur.
 # Elle GG.AA.YYYY yazılırken geçerli tarih tamamlandığı anda arka plandaki ISO değerini güncelle.
 # Böylece Listele/Yenile tıklaması FocusOut olayından önce çalışsa bile sorguya eski tarih gitmez.
 def key_sync(_event=None):
  if busy['v']:return
  d=_date_parse(disp.get())
  if d:
   iso_var.set(d.isoformat())
 e.bind('<KeyRelease>',key_sync);e.bind('<Return>',commit);e.bind('<FocusOut>',commit)
 # StringVar trace kullanılmaz; yalnız gerçek klavye olayı işlendiği için genel performans korunur.
 f.entry=e;f.button=b;f.commit=commit;f.get_iso=lambda:(_date_iso(disp.get()) if _date_parse(disp.get()) else _date_iso(iso_var.get()));return f

