def _report_date_parse(value):
 # Ekranda GG.AA.YYYY görünür; değişken okunurken program ISO (YYYY-AA-GG) alabilir. İkisi de kabul edilir.
 s=str(value).strip()
 try:return datetime.datetime.strptime(s,'%d.%m.%Y').date()
 except ValueError:
  if len(s)>=10 and s[4:5]=='-' and s[7:8]=='-':return datetime.datetime.strptime(s[:10],'%Y-%m-%d').date()
  raise


def _report_date_field(parent, variable, *, background=None):
 """Kullanicinin gordugu tarih GG.AA.YYYY; veritabani ISO kalir."""
 holder=tk.Frame(parent,bg=background or parent.cget('bg'))
 entry=tk.Entry(holder,textvariable=variable,width=12)
 entry.pack(side='left')
 def open_calendar():
  try: selected=_report_date_parse(variable.get())
  except ValueError:selected=datetime.date.today()
  popup=tk.Toplevel(holder);popup.title('Takvimden Tarih Seç');popup.resizable(False,False)
  popup.transient(holder.winfo_toplevel());popup.grab_set()
  month=datetime.date(selected.year,selected.month,1)
  month_var=tk.StringVar()
  head=tk.Frame(popup);head.pack(fill='x',padx=8,pady=7)
  body=tk.Frame(popup);body.pack(padx=8,pady=(0,8))
  def change_month(delta):
   nonlocal month
   index=month.year*12+month.month-1+delta
   y,m=divmod(index,12)
   if not 1<=y<=9999:return
   month=datetime.date(y,m+1,1);draw()
  tk.Button(head,text='◀',width=3,command=lambda:change_month(-1)).pack(side='left')
  tk.Label(head,textvariable=month_var,width=19,font=('Segoe UI',10,'bold')).pack(side='left')
  tk.Button(head,text='▶',width=3,command=lambda:change_month(1)).pack(side='left')
  def choose(day):
   variable.set(day.strftime('%d.%m.%Y'));popup.destroy()
  def draw():
   import calendar
   month_var.set(month.strftime('%m.%Y'))
   for child in body.winfo_children():child.destroy()
   for j,name in enumerate(('Pt','Sa','Ça','Pe','Cu','Ct','Pa')):
    tk.Label(body,text=name,width=4,font=('Segoe UI',9,'bold')).grid(row=0,column=j,pady=3)
   for i,week in enumerate(calendar.monthcalendar(month.year,month.month),start=1):
    for j,day in enumerate(week):
     if day:
      date=datetime.date(month.year,month.month,day)
      tk.Button(body,text=str(day),width=3,command=lambda d=date:choose(d),
       relief='sunken' if date==selected else 'raised').grid(row=i,column=j,padx=1,pady=1)
  draw()
 tk.Button(holder,text='📅',command=open_calendar,width=3).pack(side='left',padx=(3,0))
 return holder

