def current_user():
 return CURRENT_USER or 'Yönetici'

def hash_password(password):
 """PBKDF2 parola özeti. Eski SHA-256 kayıtları girişte desteklenmeye devam eder."""
 if not password:return ''
 salt=os.urandom(16); rounds=240000
 digest=hashlib.pbkdf2_hmac('sha256',password.encode('utf-8'),salt,rounds)
 return f'pbkdf2_sha256${rounds}${salt.hex()}${digest.hex()}'

def verify_password(password,stored):
 # Güncel PBKDF2, eski SHA-256 ve çok eski düz-metin şifre kayıtlarıyla uyumludur.
 # Başarılı şifre değişiminden sonra kayıt zaten PBKDF2 biçimine yükseltilir.
 if not stored:return True
 try:
  stored=str(stored)
  if stored.startswith('pbkdf2_sha256$'):
   _,rounds,salt,digest=stored.split('$',3)
   calc=hashlib.pbkdf2_hmac('sha256',password.encode('utf-8'),bytes.fromhex(salt),int(rounds)).hex()
   return hmac.compare_digest(calc,digest)
  # Eski sürümlerde 64 karakterlik SHA-256 özeti kullanılmış olabilir.
  if re.fullmatch(r'[0-9a-fA-F]{64}',stored):
   return hmac.compare_digest(hashlib.sha256(password.encode('utf-8')).hexdigest().lower(),stored.lower())
  # Daha eski KTS/ALFABE kayıtlarında şifre düz metin tutulmuş olabilir.
  return hmac.compare_digest(str(password),stored)
 except Exception:return False

