def new_toplevel(parent=None):
    """Alt pencereler: normal Windows başlık çubuğu — Küçült / Büyüt / X."""
    w=tk.Toplevel(parent)
    try:
        w.overrideredirect(False)
        w.resizable(True, True)
        # transient kullanılmaz: Windows'ta küçült/büyüt düğmelerini gizleyebilir.
        w.protocol('WM_DELETE_WINDOW', w.destroy)
    except Exception:
        pass
    try:w.after(800,lambda w=w:alf_otomatik_enter(w))
    except Exception as _se:_silent(_se)
    return w

_ALF_NO_ZOOM_TITLES={'Günlük Özet'}      # kullanıcı istedi: bu pencere eskisi gibi normal boyutta açılır (isterse kendisi büyütür)
def _alf_install_big_window_zoom():
    """v1.2.291.470: Boyutu 1000x650 ve üstü olarak tasarlanmış alt pencereler (Yeni Alış, listeler, raporlar...) tam ekran (büyütülmüş) açılır.
    Küçük giriş/onay pencerelerine dokunmaz. Pencere ilk büyük geometry() çağrısında bir kez büyütülür; kullanıcı sonra küçültebilir."""
    if getattr(tk.Toplevel,'_alf_zoom',False):return
    orig=tk.Toplevel.wm_geometry
    def _zoom(w):
        try:
            if w.winfo_exists() and not w.overrideredirect() and str(w.title()) not in _ALF_NO_ZOOM_TITLES:w.state('zoomed')
        except Exception as _se:_silent(_se)
    def geo(self,newGeometry=None):
        r=orig(self,newGeometry)
        try:
            if newGeometry and not self.__dict__.get('_alf_zoom_done'):
                m=re.match(r'^\s*(\d+)x(\d+)',str(newGeometry))
                if m and int(m.group(1))>=1000 and int(m.group(2))>=650:
                    self._alf_zoom_done=True
                    self.after_idle(lambda w=self:_zoom(w))
        except Exception as _se:_silent(_se)
        return r
    tk.Toplevel.wm_geometry=geo;tk.Toplevel.geometry=geo;tk.Toplevel._alf_zoom=True
_alf_install_big_window_zoom()

def _alf_install_button_autofit():
    """v1.2.291.470: Sabit karakter genişliği (width=N) verilmiş düğme/etikette yazı sığmıyorsa, pencere açıldığında gerçek yazı tipi ölçüsüyle
    genişlik yazıya göre otomatik (width=0) yapılır; böylece yazının harfleri kesilmez. Yazısı zaten sığan düğmelere dokunulmaz."""
    import tkinter.font as _tkf
    if getattr(tk.Button,'_alf_fit',False):return
    def _fit(w):
        try:
            if not w.winfo_exists() or str(w.cget('image')):return
            t=str(w.cget('text'))
            if not t.strip() or w.winfo_pixels(str(w.cget('wraplength')))>0:return      # satır kıran (wraplength) yazılar kesilmez
            f=_tkf.Font(root=w,font=w.cget('font'))
            pad=2*sum(w.winfo_pixels(str(w.cget(o))) for o in ('padx','bd','highlightthickness'))      # '3m' gibi mm/piksel değerleri piksele çevrilir
            need=max(f.measure(x) for x in t.split('\n'))+pad+4
            if need>w.winfo_reqwidth():w.configure(width=0)
        except Exception as _se:_silent(_se)
    for cls in (tk.Button,tk.Label):
        orig=cls.__init__
        def init(self,*a,_o=orig,**k):
            _o(self,*a,**k)
            try:
                if int(float(str(self.cget('width')) or 0))>0 and str(self.cget('text')).strip():self.after_idle(lambda w=self:_fit(w))
            except Exception as _se:_silent(_se)
        cls.__init__=init;cls._alf_fit=True
_alf_install_button_autofit()

def refresh_main_dashboard(widget):
    """Ana sayfa verisini yenileme isteği. Aktif modülü ASLA değiştirme.

    Eski sürüm burada app.show('Ana Sayfa') çağırdığı için satış/alt pencere
    işlemlerinden sonra kullanıcı istemeden ana sayfaya gönderiliyordu. Ana
    sayfa bir sonraki gerçek açılışında zaten veriyi DB'den yeniden okur; bu
    nedenle güvenli davranış navigasyon yapmadan isteği kabul etmektir.
    """
    current=widget
    while current is not None:
        if hasattr(current,'show') and hasattr(current,'main'):
            return True
        current=getattr(current,'master',None)
    return False

def _clean_text(v):
    return '' if v is None or str(v).strip().lower()=='none' else str(v)

def search_norm(value):
    """Liste aramalarında Türkçe karakter ve büyük/küçük harf farkını kaldırır."""
    value=str(value or '').replace('ı','i').replace('İ','I')
    return ''.join(ch for ch in unicodedata.normalize('NFKD',value).casefold() if not unicodedata.combining(ch))

def _legacy_first(row, names, default=None, prefer_nonzero=False):
    """Eski BCK alan adları sürümler arasında değişebildiği için güvenli alan eşleme."""
    found=default
    for name in names:
        if name in row and row.get(name) is not None and str(row.get(name)).strip()!='':
            val=row.get(name)
            if found is default: found=val
            if not prefer_nonzero:
                return val
            try:
                if float(val)!=0: return val
            except Exception:
                return val
    return found


