def copy_to_second_backup(source):
 """Ana yedeği seçilen 2. yedek konumuna kopyalar ve doğrular."""
 np=_second_backup_path()
 if not np:return None,'İkinci yedek konumu tanımlı değil.'
 source=Path(source);nd=Path(np);nd.mkdir(parents=True,exist_ok=True)
 # Ana yedek klasörünün aynısının seçilmesini engelle.
 try:
  if nd.resolve()==BACK.resolve():raise RuntimeError('İkinci yedek konumu ana yedek klasörü ile aynı olamaz.')
 except FileNotFoundError:pass
 import ALFABE_YEDEK_BAKIM as _YB
 ok_free,free,need=_YB.free_space_check(nd,source,1.05,10)
 if not ok_free:raise RuntimeError(f'İkinci kopya konumunda yeterli boş alan yok (boş {_YB.fmt_size(free)}, gereken {_YB.fmt_size(need)}).')
 second=_YB.copy_atomic(source,nd)      # .part ile kopyala, SHA256 doğrula, sonra adlandır
 c=sqlite3.connect(str(DB))
 c.execute("INSERT OR REPLACE INTO settings(k,v) VALUES('last_nas_backup_ok',?)",(now()+' | '+str(second),))
 c.execute("DELETE FROM settings WHERE k='last_nas_backup_error'")
 c.commit();c.close()
 return second,'OK'

def create_verified_full_backup(kind='MANUEL', single_close=False):
 """SQLite online-backup + ZIP test + SHA256 manifest. Returns Path or raises."""
 BACK.mkdir(parents=True,exist_ok=True)
 if not DB.exists(): raise RuntimeError('Canlı veritabanı bulunamadı; yeni yedek alınmadı.')
 # v1.2.291.140: Kapanışta canlı DB'yi ayrıca tam integrity_check ile baştan sona tarama.
 # SQLite online backup sonrasında oluşan kopya zaten aşağıda tam bütünlük kontrolünden geçiyor.
 # Manuel/devir yedeklerinde eski çift-kontrol güvenliği aynen korunur.
 if kind!='KAPANIS' and not _db_integrity(DB): raise RuntimeError('Canlı veritabanı sağlam değil; sağlam yedek korunarak yeni yedek alınmadı.')
 if not _has_real_company_period(): raise RuntimeError('Firma/dönem tanımlı değil; boş sistem yedeği alınmadı.')
 try:
  import ALFABE_YEDEK_BAKIM as _YB
  _ok,_free,_need=_YB.free_space_check(BACK,DB,2.5,50)
  if not _ok:raise RuntimeError(f'Diskte yeterli boş alan yok: boş {_YB.fmt_size(_free)}, yedek için en az {_YB.fmt_size(_need)} gerekir. Disk alanı açıp yeniden deneyin.')
 except RuntimeError:raise
 except Exception as _se:_silent(_se)
 stamp=f'{datetime.datetime.now():%Y%m%d_%H%M%S}'
 prefix='ALFABE' if kind=='KAPANIS' else 'ALFABE_TAM_YEDEK'
 ext='.bck' if kind=='KAPANIS' else '.zip'
 dest=BACK/f'{prefix}_{stamp}{ext}'; tmp=BACK/f'_safe_{stamp}'
 try:
  tmp.mkdir(parents=True,exist_ok=True); dbcopy=tmp/'alfabe_veritabani.db'
  src=sqlite3.connect(str(DB)); dst=sqlite3.connect(str(dbcopy)); src.backup(dst); dst.close(); src.close()
  if not _db_integrity(dbcopy): raise RuntimeError('Yedek veritabanı bütünlük kontrolünden geçemedi.')
  c=sqlite3.connect(str(dbcopy)); c.row_factory=sqlite3.Row
  settings=[dict(x) for x in c.execute('SELECT k,v FROM settings ORDER BY k').fetchall()]
  designs=[dict(x) for x in c.execute('SELECT * FROM designs ORDER BY id').fetchall()]
  c.close()
  (tmp/'ayarlar.json').write_text(json.dumps(settings,ensure_ascii=False,indent=2),encoding='utf-8')
  (tmp/'tasarimlar.json').write_text(json.dumps(designs,ensure_ascii=False,indent=2),encoding='utf-8')
  # Firma logosu dosya olarak seçilmişse yedeğe de al.
  logo=''
  try:
   det=next((x.get('v','') for x in settings if x.get('k')=='company_details'),'')
   d=json.loads(det) if det else {}; logo=d.get('logo') or d.get('logo_path') or ''
   lp=Path(logo) if logo else None
   if lp and lp.exists() and lp.is_file(): shutil.copy2(lp,tmp/('firma_logo'+lp.suffix.lower()))
  except Exception as _e:log_error('Yedek: firma logosu yedeğe eklenemedi',_e)
  hashes={f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in tmp.iterdir() if f.is_file()}
  identity={x.get('k'):x.get('v','') for x in settings if x.get('k') in ('company','period')}
  manifest={'format':'ALFABE_TAM_YEDEK','version':4,'kind':kind,'created':now(),'database':'alfabe_veritabani.db','company':identity.get('company',''),'period':identity.get('period',''),'sha256':hashes}
  (tmp/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
  # Kapanış yedeğinde hız öncelikli: SQLite güvenli backup ve ZIP doğrulaması korunur;
  # tekrar CPU harcayan DEFLATE sıkıştırması yerine dosyalar ZIP içinde sıkıştırmasız saklanır.
  _zip_mode = zipfile.ZIP_STORED if kind=='KAPANIS' else zipfile.ZIP_DEFLATED
  with zipfile.ZipFile(dest,'w',_zip_mode,compresslevel=(None if _zip_mode==zipfile.ZIP_STORED else 3)) as z:
   for f in tmp.iterdir(): z.write(f,f.name)
  with zipfile.ZipFile(dest,'r') as z:
   bad=z.testzip()
   if bad: raise RuntimeError('ZIP doğrulaması başarısız: '+bad)
   if 'manifest.json' not in z.namelist() or 'alfabe_veritabani.db' not in z.namelist(): raise RuntimeError('Yedek paketi eksik oluştu.')
  # Kapanış yedeğinde yalnızca son sağlam kapanış kopyasını tut; manuel yedeklere dokunma.
  if single_close:
   for old in list(BACK.glob('ALFABE_*.bck'))+list(BACK.glob('ALFABE_KAPANIS_YEDEGI_*.zip')):
    if old!=dest:
     try: old.unlink()
     except Exception as _e:log_error('Yedek: eski yedek silinemedi: '+str(old),_e)
  # 2. YEDEK: Ana yedek tamamlandıktan sonra seçilen farklı disk/NAS klasörüne otomatik kopyala ve doğrula.
  try:
   if _second_backup_path(): copy_to_second_backup(dest)
  except Exception as e:
   try:
    c=sqlite3.connect(str(DB));c.execute("INSERT OR REPLACE INTO settings(k,v) VALUES('last_nas_backup_error',?)",(str(e),));c.commit();c.close()
   except Exception as _se:_silent(_se)
  # Saklama: gün sınırı + her zaman en yeni 5 yedek korunur; ikinci kopya ve güvenlik kopyaları da budanır; günlük tabloları sınırlanır.
  try:
   import ALFABE_YEDEK_BAKIM as _YB
   c=sqlite3.connect(str(DB));row=c.execute("SELECT v FROM settings WHERE k='backup_keep_days'").fetchone();single=c.execute("SELECT v FROM settings WHERE k='backup_single'").fetchone()
   days=max(1,int((row[0] if row else '30') or 30));is_single=str((single[0] if single else 'Evet') or 'Evet').strip().lower() not in ('hayır','hayir','no','0','false','kapalı','kapali')
   _YB.prune_tables(c);c.close()
   _YB.prune_all(BACK,days,_second_backup_path(),(dest,),is_single)
  except Exception as _se:_silent(_se)
  return dest
 finally:
  shutil.rmtree(tmp,ignore_errors=True)


def _period_registry_load():
 try:
  d=json.loads(PERIOD_REGISTRY.read_text(encoding='utf-8')) if PERIOD_REGISTRY.exists() else {}
  if isinstance(d,dict):
   for _v in d.values():
    if isinstance(_v,dict) and _v.get('path'):_v['path']=_alfabe_remap(_v['path'],'donemler',PERIOD_REGISTRY.parent/'donemler')
   return d
  return {}
 except Exception:return {}
def _period_registry_save(d):
 tmp=PERIOD_REGISTRY.with_suffix('.tmp');tmp.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8');os.replace(tmp,PERIOD_REGISTRY)
PENDING_PERIOD_DELETES=_DATA_BASE/'donem_silme_bekleyen.json'
def _pending_period_deletes_load():
 try:
  d=json.loads(PENDING_PERIOD_DELETES.read_text(encoding='utf-8')) if PENDING_PERIOD_DELETES.exists() else []
  return d if isinstance(d,list) else []
 except Exception:return []
def _pending_period_deletes_save(items):
 tmp=PENDING_PERIOD_DELETES.with_suffix('.tmp');tmp.write_text(json.dumps(items,ensure_ascii=False,indent=2),encoding='utf-8');os.replace(tmp,PENDING_PERIOD_DELETES)
def _queue_period_delete(path):
 path=Path(path);items=_pending_period_deletes_load();q=str(path)
 if q not in items:items.append(q);_pending_period_deletes_save(items)
def _cleanup_pending_period_deletes():
 """Önceki oturumdan kilitli kalmış dönem dosyalarını, artık kilit yoksa temizler."""
 items=_pending_period_deletes_load();left=[]
 import gc,time
 gc.collect()
 for q in items:
  p=Path(q)
  if not p.exists():continue
  ok=False
  for _ in range(3):
   try:p.unlink();ok=True;break
   except (PermissionError,OSError):time.sleep(.10);gc.collect()
  if not ok:left.append(q)
 if left:_pending_period_deletes_save(left)
 elif PENDING_PERIOD_DELETES.exists():
  try:PENDING_PERIOD_DELETES.unlink()
  except Exception as _se:_silent(_se)
 return left
def _period_target_path(period):
 """Aynı yılın eski/kilitli fiziksel dosyası kalmışsa yeni dönem için çakışmayan dosya adı üretir."""
 base=PERIOD_DIR/f'ALFABE_{period}.db'
 if not base.exists():return base
 stamp=datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
 i=0
 while True:
  suffix=f'_{stamp}' if i==0 else f'_{stamp}_{i}'
  q=PERIOD_DIR/f'ALFABE_{period}{suffix}.db'
  if not q.exists():return q
  i+=1

def _switch_period_db(period):
 global DB
 reg=_period_registry_load(); rec=reg.get(str(period))
 if not rec:return False
 q=Path(rec.get('path',''))
 if not q.exists():return False
 DB=q
 # Dönem dosyası eski bir şemadan gelmiş olabilir. Kullanıcı girişi sorgusundan önce
 # users tablosunun güncel kolonlarını garanti et.
 try:DX.init()
 except NameError:pass
 return True
def _period_snapshot(path):
 c=sqlite3.connect(str(path));c.row_factory=sqlite3.Row
 def one(sql):return c.execute(sql).fetchone()[0]
 out={'stock_count':one('SELECT COUNT(*) FROM stock'),'stock_qty':one('SELECT COALESCE(SUM(qty),0) FROM stock'),'cari_count':one('SELECT COUNT(*) FROM caris'),'cari_balance':one('SELECT COALESCE(SUM(debit-credit),0) FROM cari_moves'),'cari_moves':one('SELECT COUNT(*) FROM cari_moves'),'open_installments':one("SELECT COUNT(*) FROM installments WHERE COALESCE(status,'')!='Ödendi' AND amount-paid>0.0001"),'open_installment_amount':one("SELECT COALESCE(SUM(amount-paid),0) FROM installments WHERE COALESCE(status,'')!='Ödendi' AND amount-paid>0.0001"),'open_checks':one("SELECT COUNT(*) FROM checks_notes WHERE status NOT IN ('Tahsil','İptal','Ödendi')"),'sales':one('SELECT COUNT(*) FROM sales'),'service_sales':one('SELECT COUNT(*) FROM service_sales'),'finance_count':one('SELECT COUNT(*) FROM finance'),'finance_balance':one('SELECT COALESCE(SUM(amount),0) FROM finance')}
 c.close();return out

def _safe_unlink_period_file(path, switch_to=None):
 """Windows'ta aktif DB hedef dosyayı kilitliyorsa önce DB'yi güvenli döneme geçirip kontrollü siler."""
 global DB
 path=Path(path)
 if not path.exists():return
 if switch_to is not None:
  try:
   if Path(DB).resolve()==path.resolve():DB=Path(switch_to)
  except Exception as _se:_silent(_se)
 import gc,time
 gc.collect()
 last=None
 for _ in range(5):
  try:path.unlink();return
  except PermissionError as e:last=e;time.sleep(.25);gc.collect()
  except FileNotFoundError:return
 if last:raise RuntimeError('Hedef dönem dosyası başka bir ALFABE oturumu veya işlem tarafından kullanılıyor. Diğer ALFABE pencerelerini kapatıp tekrar deneyin.\n\n'+str(path)) from last

def create_standard_period_rollover(source_period,target_period):
 """Kaynak DB'yi değiştirmeden yeni dönem DB'si üretir. Hata halinde hedef silinir."""
 global DB
 sp=str(source_period).strip();tp=str(target_period).strip();reg=_period_registry_load();srec=reg.get(sp,{});source=Path(srec.get('path','')) if srec.get('path') else Path(DB)
 if not source.exists():raise RuntimeError('Kaynak dönem dosyası bulunamadı: '+str(source))
 DB=source;source_hash=hashlib.sha256(source.read_bytes()).hexdigest()
 if not sp or not tp or sp==tp:raise RuntimeError('Kaynak ve hedef dönem geçerli ve farklı olmalıdır.')
 reg=_period_registry_load()
 if tp in reg and Path(reg[tp].get('path','')).exists():
  if str(reg[tp].get('status',''))=='Boş Dönem':
   # Yeni Dönem ile önceden açılmış boş hedef, devir sırasında güvenle yeniden üretilebilir.
   _safe_unlink_period_file(Path(reg[tp].get('path','')),source)
   reg.pop(tp,None);_period_registry_save(reg)
  else:raise RuntimeError(tp+' dönemi zaten mevcut. Çift devir engellendi.')
 if not _db_integrity(source):raise RuntimeError('Kaynak dönem veritabanı bütünlük kontrolünden geçemedi.')
 # Zorunlu doğrulanmış tam yedek.
 backup=create_verified_full_backup('DONEM_DEVRI',single_close=False)
 if not backup.exists():raise RuntimeError('Devir öncesi doğrulanmış yedek oluşturulamadı.')
 srcsnap=_period_snapshot(source)
 archive=PERIOD_DIR/f'ALFABE_{sp}.db'; target=_period_target_path(tp)
 if archive.resolve()!=source.resolve():
  shutil.copy2(source,archive)
  if not _db_integrity(archive):raise RuntimeError('Kaynak dönem arşivi doğrulanamadı.')
 else: archive=source
 try:
  shutil.copy2(source,target)
  c=sqlite3.connect(str(target));c.row_factory=sqlite3.Row;c.execute('PRAGMA foreign_keys=OFF')
  # Devirden önce açılış değerlerini belleğe al.
  cari_bal={int(r['cari_id']):(float(r['d'] or 0),float(r['cr'] or 0)) for r in c.execute('SELECT cari_id,SUM(debit) d,SUM(credit) cr FROM cari_moves GROUP BY cari_id')}
  fin_bal={str(r['account'] or 'Ana Kasa'):float(r['bal'] or 0) for r in c.execute('SELECT account,SUM(amount) bal FROM finance GROUP BY account')}
  open_inst=[dict(r) for r in c.execute("SELECT * FROM installments WHERE COALESCE(status,'')!='Ödendi' AND amount-paid>0.0001")]
  open_checks=[dict(r) for r in c.execute("SELECT * FROM checks_notes WHERE status NOT IN ('Tahsil','İptal','Ödendi')")]
  # Geçmiş hareketler yeni döneme satış/alış/hareket olarak taşınmaz.
  clear=['installment_payments','sale_collections','transaction_reversals','installment_adjustments','cari_reconciliations','stock_count_lines','stock_counts','stock_corrections','sale_payments','sale_lines','sales','purchase_lines','purchases','supplier_price_history','goods_receipt_lines','goods_receipts','finance','cari_moves','stock_moves','service_sales','installments','checks_notes','day_closings','pos_settlements','bank_operations','bank_operation_keys','business_card_payments','business_card_installments','business_card_purchases']
  existing={r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
  for t in clear:
   if t in existing:c.execute('DELETE FROM '+t)
  opening_dt=f'{tp}-01-01 00:00:00'
  for r in c.execute('SELECT id,qty,avg_cost FROM stock').fetchall():
   if abs(float(r['qty'] or 0))>0.0000001:c.execute("INSERT INTO stock_moves(stock_id,dt,kind,qty,unit_cost,source,source_id,note) VALUES(?,?,?,?,?,'PERIOD_OPEN',NULL,?)",(r['id'],opening_dt,'Dönem Açılış',r['qty'],r['avg_cost'],sp+' → '+tp+' açılış'))
  for cid,(d,cr) in cari_bal.items():
   bal=d-cr
   if abs(bal)>0.0000001:c.execute("INSERT INTO cari_moves(cari_id,dt,kind,debit,credit,source,source_id,note) VALUES(?,?,?,?,?,'PERIOD_OPEN',NULL,?)",(cid,opening_dt,'Dönem Açılış',max(bal,0),max(-bal,0),sp+' → '+tp+' açılış'))
  for account,bal in fin_bal.items():
   if abs(bal)>0.0000001:c.execute("INSERT INTO finance(dt,account,kind,amount,source,source_id,note) VALUES(?,?,?,?, 'PERIOD_OPEN',NULL,?)",(opening_dt,account,'Dönem Açılış',bal,sp+' → '+tp+' açılış'))
  for r in open_inst:c.execute("INSERT INTO installments(id,cari_id,sale_id,due_date,amount,paid,status) VALUES(?,?,NULL,?,?,?,?)",(r['id'],r['cari_id'],r['due_date'],r['amount'],r['paid'],r['status']))
  for r in open_checks:c.execute("INSERT INTO checks_notes(id,kind,number,customer,due_date,amount,status,note) VALUES(?,?,?,?,?,?,?,?)",(r['id'],r['kind'],r['number'],r['customer'],r['due_date'],r['amount'],r['status'],r['note']))
  c.execute("INSERT INTO settings(k,v) VALUES('period',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(tp,))
  c.execute("INSERT INTO settings(k,v) VALUES('period_source',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(sp,))
  c.execute("INSERT INTO settings(k,v) VALUES('period_rollover_at',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(now(),))
  c.execute('DELETE FROM counters WHERE period=?',(tp,));c.commit();c.execute('PRAGMA foreign_keys=ON');c.close()
  if not _db_integrity(target):raise RuntimeError('Yeni dönem bütünlük kontrolünden geçemedi.')
  tgtsnap=_period_snapshot(target)
  srcsnap['source_unchanged']=(hashlib.sha256(source.read_bytes()).hexdigest()==source_hash)
  if not srcsnap['source_unchanged']:raise RuntimeError('Kaynak dönem dosyası değişti. Devir güvenlik nedeniyle iptal edildi.')
  checks=[srcsnap['stock_count']==tgtsnap['stock_count'],abs(srcsnap['stock_qty']-tgtsnap['stock_qty'])<0.001,srcsnap['cari_count']==tgtsnap['cari_count'],abs(srcsnap['cari_balance']-tgtsnap['cari_balance'])<0.01,srcsnap['open_installments']==tgtsnap['open_installments'],srcsnap['open_checks']==tgtsnap['open_checks'],tgtsnap['sales']==0,tgtsnap['service_sales']==0]
  if not all(checks):raise RuntimeError('Devir sonrası kaynak/hedef doğrulaması başarısız oldu. Hedef dönem iptal edildi.')
  reg[sp]={'path':str(archive),'created':now(),'status':'Arşiv'};reg[tp]={'path':str(target),'created':now(),'source':sp,'status':'Aktif'};_period_registry_save(reg)
  DB=target
  return backup,srcsnap,tgtsnap
 except Exception:
  try:
   if target.exists():_safe_unlink_period_file(target,source)
  except Exception as _se:_silent(_se)
  raise



def _prepare_rollover_target(source_period,target_period):
 global DB
 sp,tp=str(source_period).strip(),str(target_period).strip();reg=_period_registry_load();srec=reg.get(sp,{});source=Path(srec.get('path','')) if srec.get('path') else Path(DB)
 if not source.exists():raise RuntimeError('Kaynak dönem dosyası bulunamadı: '+str(source))
 DB=source
 if not sp or not tp or sp==tp:raise RuntimeError('Kaynak ve hedef dönem geçerli ve farklı olmalıdır.')
 reg=_period_registry_load()
 if tp in reg and Path(reg[tp].get('path','')).exists():
  if str(reg[tp].get('status',''))=='Boş Dönem':
   _safe_unlink_period_file(Path(reg[tp].get('path','')),source);reg.pop(tp,None);_period_registry_save(reg)
  else:raise RuntimeError(tp+' dönemi zaten mevcut. Çift devir engellendi.')
 if not _db_integrity(source):raise RuntimeError('Kaynak dönem veritabanı bütünlük kontrolünden geçemedi.')
 backup=create_verified_full_backup('DONEM_DEVRI',single_close=False)
 if not backup.exists():raise RuntimeError('Devir öncesi doğrulanmış yedek oluşturulamadı.')
 archive=PERIOD_DIR/f'ALFABE_{sp}.db';target=_period_target_path(tp)
 if archive.resolve()!=source.resolve():
  shutil.copy2(source,archive)
  if not _db_integrity(archive):raise RuntimeError('Kaynak dönem arşivi doğrulanamadı.')
 else:archive=source
 return source,archive,target,backup,_period_registry_load()

def create_period_rollover_by_method(source_period,target_period,method):
 method=str(method or 'B').upper()
 if method=='B':return create_standard_period_rollover(source_period,target_period)
 global DB
 sp,tp=str(source_period).strip(),str(target_period).strip();reg0=_period_registry_load();srec=reg0.get(sp,{});source=Path(srec.get('path','')) if srec.get('path') else Path(DB)
 if not source.exists():raise RuntimeError('Kaynak dönem dosyası bulunamadı: '+str(source))
 DB=source;source_hash=hashlib.sha256(source.read_bytes()).hexdigest();srcsnap=_period_snapshot(source)
 source,archive,target,backup,reg=_prepare_rollover_target(sp,tp)
 try:
  shutil.copy2(source,target)
  c=sqlite3.connect(str(target));c.execute('PRAGMA foreign_keys=OFF')
  existing={r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
  if method=='C':
   clear=['installment_payments','sale_collections','transaction_reversals','installment_adjustments','cari_reconciliations','stock_count_lines','stock_counts','stock_corrections','sale_payments','sale_lines','sales','purchase_lines','purchases','supplier_price_history','goods_receipt_lines','goods_receipts','finance','cari_moves','stock_moves','service_sales','installments','checks_notes','day_closings','pos_settlements','bank_operations','bank_operation_keys','business_card_payments','business_card_installments','business_card_purchases']
   for t in clear:
    if t in existing:c.execute('DELETE FROM '+t)
   if 'stock' in existing:c.execute('UPDATE stock SET qty=0')
  elif method=='D':
   # Yalnız eski perakende/hizmet satışları ile kasa/POS geçmişini temizler; diğer tam devir kayıtları korunur.
   clear=['sale_collections','sale_payments','sale_lines','sales','service_sales','day_closings','pos_settlements','bank_operations','bank_operation_keys','finance']
   for t in clear:
    if t in existing:c.execute('DELETE FROM '+t)
  elif method!='A':raise RuntimeError('Bilinmeyen devir yöntemi: '+method)
  c.execute("INSERT INTO settings(k,v) VALUES('period',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(tp,))
  c.execute("INSERT INTO settings(k,v) VALUES('period_source',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(sp,))
  c.execute("INSERT INTO settings(k,v) VALUES('period_rollover_method',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(method,))
  c.execute("INSERT INTO settings(k,v) VALUES('period_rollover_at',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(now(),))
  c.commit();c.close()
  if not _db_integrity(target):raise RuntimeError('Yeni dönem bütünlük kontrolünden geçemedi.')
  tgtsnap=_period_snapshot(target)
  srcsnap['source_unchanged']=(hashlib.sha256(source.read_bytes()).hexdigest()==source_hash)
  if not srcsnap['source_unchanged']:raise RuntimeError('Kaynak dönem dosyası değişti. Devir güvenlik nedeniyle iptal edildi.')
  if method=='A':
   checks=[srcsnap['stock_count']==tgtsnap['stock_count'],abs(srcsnap['stock_qty']-tgtsnap['stock_qty'])<.001,srcsnap['cari_count']==tgtsnap['cari_count'],abs(srcsnap['cari_balance']-tgtsnap['cari_balance'])<.01,srcsnap['open_installments']==tgtsnap['open_installments'],srcsnap['open_checks']==tgtsnap['open_checks'],srcsnap['sales']==tgtsnap['sales'],srcsnap['service_sales']==tgtsnap['service_sales'],srcsnap['finance_count']==tgtsnap['finance_count'],abs(srcsnap['finance_balance']-tgtsnap['finance_balance'])<.01]
  elif method=='C':
   checks=[srcsnap['stock_count']==tgtsnap['stock_count'],abs(tgtsnap['stock_qty'])<.001,srcsnap['cari_count']==tgtsnap['cari_count'],abs(tgtsnap['cari_balance'])<.01,tgtsnap['cari_moves']==0,tgtsnap['open_installments']==0,tgtsnap['open_checks']==0,tgtsnap['sales']==0,tgtsnap['service_sales']==0,tgtsnap['finance_count']==0]
  else:
   checks=[srcsnap['stock_count']==tgtsnap['stock_count'],abs(srcsnap['stock_qty']-tgtsnap['stock_qty'])<.001,srcsnap['cari_count']==tgtsnap['cari_count'],abs(srcsnap['cari_balance']-tgtsnap['cari_balance'])<.01,srcsnap['open_installments']==tgtsnap['open_installments'],srcsnap['open_checks']==tgtsnap['open_checks'],tgtsnap['sales']==0,tgtsnap['service_sales']==0,tgtsnap['finance_count']==0]
  if not all(checks):raise RuntimeError('Devir sonrası yöntem doğrulaması başarısız oldu. Hedef dönem iptal edildi.')
  reg[sp]={'path':str(archive),'created':now(),'status':'Arşiv'};reg[tp]={'path':str(target),'created':now(),'source':sp,'status':'Aktif','method':method};_period_registry_save(reg);DB=target
  return backup,srcsnap,tgtsnap
 except Exception:
  try:
   if target.exists():_safe_unlink_period_file(target,source)
  except Exception as _se:_silent(_se)
  raise

def create_blank_period(source_period,target_period):
 """Yeni Dönem Oluştur: devir yapmadan ayrı, boş çalışma dönemi dosyası oluşturur."""
 global DB
 sp,tp=str(source_period).strip(),str(target_period).strip();source=Path(DB)
 if not (tp.isdigit() and len(tp)==4):raise RuntimeError('Yeni dönem 4 haneli yıl olmalıdır.')
 if sp.isdigit() and int(tp)<=int(sp):raise RuntimeError('Yeni dönem kaynak dönemden büyük olmalıdır.')
 reg=_period_registry_load();target=_period_target_path(tp)
 if tp in reg and Path(reg[tp].get('path','')).exists():raise RuntimeError(tp+' dönemi zaten mevcut.')
 if not _db_integrity(source):raise RuntimeError('Kaynak dönem veritabanı bütünlük kontrolünden geçemedi.')
 # Şema, kart/tanım ve ayarlar korunur; işlem hareketleri ve açılış bakiyeleri oluşturulmaz.
 shutil.copy2(source,target)
 try:
  c=sqlite3.connect(str(target));c.execute('PRAGMA foreign_keys=OFF')
  existing={r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
  clear=['installment_payments','sale_collections','transaction_reversals','installment_adjustments','cari_reconciliations','stock_count_lines','stock_counts','stock_corrections','sale_payments','sale_lines','sales','purchase_lines','purchases','supplier_price_history','goods_receipt_lines','goods_receipts','finance','cari_moves','stock_moves','service_sales','installments','checks_notes','day_closings','pos_settlements','bank_operations','bank_operation_keys','business_card_payments','business_card_installments','business_card_purchases']
  for t in clear:
   if t in existing:c.execute('DELETE FROM '+t)
  if 'stock' in existing:c.execute('UPDATE stock SET qty=0')
  c.execute("INSERT INTO settings(k,v) VALUES('period',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(tp,))
  c.execute("INSERT INTO settings(k,v) VALUES('period_source',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(sp,))
  c.execute("INSERT INTO settings(k,v) VALUES('period_created_blank_at',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(now(),))
  c.commit();c.close()
  if not _db_integrity(target):raise RuntimeError('Yeni dönem dosyası bütünlük kontrolünden geçemedi.')
  reg[tp]={'path':str(target),'created':now(),'source':sp,'status':'Boş Dönem'};_period_registry_save(reg)
  return target
 except Exception:
  try:
   if target.exists():_safe_unlink_period_file(target,source)
  except Exception as _se:_silent(_se)
  raise

