    r=tk.Frame(body,bg='white',highlightthickness=1,highlightbackground='#bfd0e2');r.pack(fill='x',pady=5);tk.Label(r,text=a,width=22,anchor='w',bg='white',font=('Segoe UI',10,'bold')).pack(side='left',padx=10,pady=9);tk.Label(r,text=b,anchor='w',bg='white',font=('Segoe UI',10)).pack(side='left',padx=8)
