def _alfabe_bg_bakim_run():
 try:
  c=sqlite3.connect(str(DB),timeout=60);c.execute('PRAGMA busy_timeout=60000');c.execute('PRAGMA analysis_limit=2000')
  made=0
  for q in _BAKIM_INDEXLER:
   try:
    n=q.split(' ON ')[0].split()[-1]
    if c.execute("SELECT 1 FROM sqlite_master WHERE type='index' AND name=?",(n,)).fetchone():continue
    c.execute(q);c.commit();made+=1
   except Exception as _se:_silent(_se)
  try:
   if made or not c.execute("SELECT 1 FROM sqlite_master WHERE name='sqlite_stat1'").fetchone():c.execute('ANALYZE');c.commit()
  except Exception as _se:_silent(_se)
  c.close()
 except Exception as _se:_silent(_se)
def _alfabe_bg_bakim():
 import threading as _th
 _th.Thread(target=_alfabe_bg_bakim_run,daemon=True,name='alfabe-bakim').start()

# v1.2.291.456: Satış ekranı ürün araması her tuşta tüm stoğu okuyup yeniden normalleştirmesin.
_FP={'con':None,'db':None,'ver':None,'rows':[],'hay':[],'memo':{}}
def _fp_snapshot():
 try:
  key=str(DB)
  if _FP['con'] is None or _FP['db']!=key:
   try:
    if _FP['con'] is not None:_FP['con'].close()
   except Exception as _se:_silent(_se)
   c=sqlite3.connect(key,timeout=15,check_same_thread=False);c.row_factory=sqlite3.Row;_FP.update(con=c,db=key,ver=None,memo={})
  c=_FP['con'];ver=c.execute('PRAGMA data_version').fetchone()[0]
  if _FP['ver']!=ver or not _FP['rows']:
   rows=c.execute('SELECT * FROM stock ORDER BY name').fetchall()
   alt={}
   try:
    for b in c.execute('SELECT stock_id,barcode FROM stock_barcodes WHERE active=1'):alt.setdefault(int(b[0]),[]).append(str(b[1] or ''))
   except Exception as _se:_silent(_se)
   memo=_FP['memo'];hay=[];new={}
   for r in rows:
    sid=int(r['id']);src=tuple(str(r[k] or '') for k in ('barcode','code','name','brand','model','special','shelf','grp'))+tuple(alt.get(sid,()))
    m=memo.get(sid)
    if m is None or m[0]!=src:m=(src,search_norm(' '.join(src)))
    new[sid]=m;hay.append(m[1])
   _FP.update(ver=ver,rows=rows,hay=hay,memo=new)
  return _FP['rows'],_FP['hay']
 except Exception as _se:
  _silent(_se);_FP['con']=None;_FP['rows']=[]
  rows=DX.rows('SELECT * FROM stock ORDER BY name')
  return rows,[search_norm(' '.join(str(r[k] or '') for k in ('barcode','code','name','brand','model','special','shelf','grp'))) for r in rows]
def _fp_nat(s):
 import re as _r
 return [(0,int(x),'') if x.isdigit() else (1,0,x) for x in _r.split(r'(\d+)',search_norm(s or '')) if x!='']
def _fp_sort_rows(rs,col,rev=False):
 num={'price':'retail','qty':'qty'}
 if col in num:k=lambda r:float(r[num[col]] or 0)
 else:
  fld={'barcode':'barcode','code':'code','name':'name','brand':'brand','grp':'grp'}.get(col,'name')
  if col=='grp':k=lambda r:(1 if not r['grp'] else 0,_fp_nat(r['grp']),_fp_nat(r['name']))
  else:k=lambda r:_fp_nat(r[fld])
 return sorted(rs,key=k,reverse=rev)

def _alf_cellhl(tree,col,font):
 """Seçili satırda yalnız bir hücre (örn. Ürün Adı) mavi görünsün; satırın kalanı açık renk."""
 lbl=tk.Label(tree,bg='#1f6fd6',fg='#ffffff',font=font,anchor='w',padx=6,bd=0)
 def fwd(seq,btn):
  def f(e):
   try:tree.focus_set();tree.event_generate(seq,x=e.x+lbl.winfo_x(),y=e.y+lbl.winfo_y(),button=btn)
   except tk.TclError:pass
   return 'break'
  return f
 for seq,b in (('<Button-1>',1),('<ButtonRelease-1>',1),('<Double-1>',1),('<Button-3>',3)):lbl.bind(seq,fwd(seq,b))
 def hl():
  try:
   sel=tree.selection()
   if not sel or not tree.exists(sel[0]):lbl.place_forget();return
   box=tree.bbox(sel[0],col)
   if not box:lbl.place_forget();return
   x,y,w,h=box;lbl.configure(text=str(tree.set(sel[0],col)));lbl.place(x=x,y=y,width=w,height=h);lbl.lift()
  except tk.TclError:pass
  except Exception as _se:_silent(_se)
 for seq in ('<<TreeviewSelect>>','<Configure>','<MouseWheel>','<ButtonRelease-1>','<KeyRelease>','<Map>'):tree.bind(seq,lambda e:tree.after_idle(hl),add='+')
 tree._alf_hl=hl
 return hl
