 for c,h,wid in [('date','Geçerlilik',100),('rates','Değişiklik',130),('mode','Satış fiyatı',230),('status','Durum',110),('count','Stok',70)]:t.heading(c,text=h);t.column(c,width=wid,anchor='center' if c!='mode' else 'w')
