 t.pack(fill='both',expand=True,padx=18,pady=4)
 def refresh():
  t.delete(*t.get_children())
  for i,p in enumerate(_vat_plans_load()):
   t.insert('','end',iid=str(i),values=(p.get('date',''),f"%{float(p['old']):g} → %{float(p['new']):g}",'KDV hariç sabit' if p.get('price_mode')=='net' else 'KDV dahil sabit',p.get('status',''),p.get('count','')))
 def do_apply():
  try:
   old=float(old_var.get().replace(',','.'));new=float(new_var.get().replace(',','.'))
   if not 0<=new<=100:raise ValueError('Yeni KDV oranı 0 ile 100 arasında olmalıdır.')
   if abs(old-new)<1e-6:raise ValueError('Eski ve yeni oran aynı olamaz.')
   d=_vat_parse_date(date_var.get())
  except ValueError as ex:
   return messagebox.showwarning(APP,str(ex) if str(ex) and 'could not convert' not in str(ex) else 'Yeni KDV oranını rakamla yazın (örnek: 25).',parent=w)
  mode=mode_var.get();n=_vat_count(old)
  plan={'id':now(),'old':old,'new':new,'date':d.isoformat(),'price_mode':mode,'set_default':int(def_var.get()),'deactivate_old':int(off_var.get()),'status':'Bekliyor'}
  now_apply=d<=datetime.date.today()
  fiyat='KDV HARİÇ fiyat sabit kalacak; KDV dahil satış fiyatları güncellenecek.' if mode=='net' else 'KDV DAHİL satış fiyatları aynı kalacak.'
  soru=(f"%{old:g} KDV'li {n} stok kartı %{new:g} olacak.\n{fiyat}\n\n" + ('Şimdi uygulansın mı?' if now_apply else f"Değişiklik {d.strftime('%d.%m.%Y')} tarihinde otomatik uygulanacak. Planlansın mı?"))
