 if not heads:
  return messagebox.showwarning(APP,'Önce raporu getiriniz.',parent=parent)
 try:
  design=report_design_get(report_key,heads)
  if not messagebox.askyesno(APP,'Bu raporun mevcut tasarımı kaydedilsin mi?\\n\\n'+report_key,parent=parent):return
  _report_design_save_atomic(report_key,design)
  messagebox.showinfo(APP,'Bu raporun tasarımı kaydedildi.',parent=parent)
 except Exception as e:
  messagebox.showerror(APP,'Tasarım kaydedilemedi:\\n'+str(e),parent=parent)

