   if i in selected['items']:canvas.create_rectangle(o['x'],o['y'],o['x']+o['w'],o['y']+o['h'],outline=RED,width=2,dash=(4,2),tags=('selection',))
   # Seçili veri sütununun sağ kenarında boyutlandırma tutamacı.
