  push_undo();n=sum(1 for x in objects if x.get('band')=='Detay')
  if h=='[Firma Logosu]':o={'type':'logo','text':'FİRMA LOGOSU','field':'','band':'Üstbilgi','x':65,'y':85,'w':95,'h':65,'size':9,'bold':0,'align':'center'}
  elif h.startswith('['):o={'type':'text','text':h,'field':'','band':'Üstbilgi','x':180,'y':120,'w':220,'h':24,'size':10,'bold':0,'align':'left'}
  else:o={'type':'field','text':h,'heading':h,'field':h,'band':'Detay','x':65+(n%6)*155,'y':225+(n//6)*48,'w':145,'h':42,'size':9,'bold':0,'align':'auto','format':'Otomatik'}
