 def align_objects(kind):
  ids=selected['items']
  if len(ids)<2:return
  push_undo();os=[objects[i] for i in ids]
  if kind=='left':v=min(o['x'] for o in os);[o.update(x=v) for o in os]
  elif kind=='right':v=max(o['x']+o['w'] for o in os);[o.update(x=v-o['w']) for o in os]
  elif kind=='hcenter':v=sum(o['x']+o['w']/2 for o in os)/len(os);[o.update(x=round(v-o['w']/2)) for o in os]
  elif kind=='top':v=min(o['y'] for o in os);[o.update(y=v) for o in os]
  elif kind=='bottom':v=max(o['y']+o['h'] for o in os);[o.update(y=v-o['h']) for o in os]
  elif kind=='vcenter':v=sum(o['y']+o['h']/2 for o in os)/len(os);[o.update(y=round(v-o['h']/2)) for o in os]
  elif kind=='samew':v=objects[ids[-1]]['w'];[o.update(w=v) for o in os]
  elif kind=='sameh':v=objects[ids[-1]]['h'];[o.update(h=v) for o in os]
  elif kind in ('spaceh','spacev') and len(os)>2:
   key=(lambda o:o['x']) if kind=='spaceh' else (lambda o:o['y']);ordered=sorted(os,key=key);first=key(ordered[0]);last=key(ordered[-1]);gap=(last-first)/(len(ordered)-1)
   for n,o in enumerate(ordered):o['x' if kind=='spaceh' else 'y']=round(first+n*gap)
  for o in os:o['band']=band_at(o['y'])
  render();load_props()
 def fit_detail_columns():
  # Kayıtlı şablon otomatik değiştirilmez; kullanıcı isteği ve kaydetme gerekir.
  ids=[i for i,o in enumerate(objects) if o.get('type')=='field' and o.get('field') in heads]
  if not ids:return messagebox.showinfo(APP,'Yerleştirilecek veri sütunu bulunamadı.',parent=w)
  if len(ids)>18:return messagebox.showwarning(APP,'18 sütundan fazla alanı tek sayfaya sıkıştırmak okunabilirliği bozar.',parent=w)
  push_undo()
  def weight(o):
   h=str(o.get('heading') or o.get('field') or '').casefold()
   if any(k in h for k in ('stok adı','ürün adı','açıklama','unvan','ünvan','adres')):return 3.5
   if any(k in h for k in ('tarih','vade','saat')):return 1.8
   if any(k in h for k in ('tutar','fiyat','miktar','bakiye','borç','alacak','ödenen','kalan')):return 1.6
   return 1.7
  weights=[weight(objects[i]) for i in ids];total=sum(weights)
  start=65;usable=max(250,page_right()-start);x=start
  for j,(i,wt) in enumerate(zip(ids,weights)):
   o=objects[i];ww=(start+usable-x) if j==len(ids)-1 else round(usable*wt/total)
   o.update(x=x,w=max(1,ww),y=208,h=42,band='Detay')
   x+=ww
  selected['items']=[];render();load_props()
  status.set('Sütunlar sayfaya dağıtıldı. Kalıcı olması için TASARIMI KAYDET kullanın.')
