 for txt,val in [('SOLA','left'),('ORTA','center'),('SAĞA','right')]:tk.Button(toolbar,text=txt,command=lambda v=val:set_text_align(v)).pack(side='left',padx=2)
 tk.Button(toolbar,text='ÜST',command=lambda:set_valign('top')).pack(side='left',padx=(8,2));tk.Button(toolbar,text='DİKEY ORTA',command=lambda:set_valign('middle')).pack(side='left',padx=2);tk.Button(toolbar,text='ALT',command=lambda:set_valign('bottom')).pack(side='left',padx=2);tk.Checkbutton(toolbar,text='Izgaraya Yapıştır',variable=snap,bg='#bad5f2').pack(side='left',padx=8)
