def generate_internal_ean13():
 """290 önekli, benzersiz işletme içi EAN-13 barkodu üretir.
 Terazi entegrasyonunda 290 öneki rezerve tutulmalıdır.
 """
 import random
 def check_digit(first12):
  total=sum((1 if i%2==0 else 3)*int(ch) for i,ch in enumerate(first12))
  return str((10-total%10)%10)
 for _ in range(5000):
  base='290'+''.join(str(random.randint(0,9)) for _ in range(9))
  code=base+check_digit(base)
  if not DX.one("SELECT 1 FROM stock WHERE barcode=? UNION ALL SELECT 1 FROM stock_barcodes WHERE barcode=? AND active=1 LIMIT 1",(code,code)):
   return code
 raise RuntimeError('Benzersiz otomatik barkod üretilemedi. Lütfen tekrar deneyin.')

def generate_internal_ean8():
 """Benzersiz EAN-8 barkodu oluşturur; son rakam kontrol basamağıdır."""
 import random
 for _ in range(5000):
  first7=''.join(str(random.randint(0,9)) for _ in range(7))
  total=sum(int(ch)*(3 if i%2==0 else 1) for i,ch in enumerate(first7))
  code=first7+str((10-total%10)%10)
  if not DX.one("SELECT 1 FROM stock WHERE barcode=? UNION ALL SELECT 1 FROM stock_barcodes WHERE barcode=? AND active=1 LIMIT 1",(code,code)):
   return code
 raise RuntimeError('Benzersiz EAN8 barkodu üretilemedi.')

