def check_cari_risk(cari_id,new_debt,parent=None):
 """Satış kaydından önce cari riskini hesaplar; işlem devam edebiliyorsa True döndürür."""
 new_debt=max(float(new_debt or 0),0)
 if new_debt<=0.005:return True
 c=DX.one('SELECT title,risk FROM caris WHERE id=? AND active=1',(cari_id,))
 if not c:return False
 limit=float(c['risk'] or 0)
 if limit<=0:return True
 b=DX.one('SELECT COALESCE(SUM(debit-credit),0) balance FROM cari_moves WHERE cari_id=?',(cari_id,));current=float(b['balance'] or 0);projected=current+new_debt;excess=projected-limit
 if excess<=0.005:return True
 detail=f"RİSK LİMİTİ AŞILIYOR\n\nCari: {c['title']}\nMevcut bakiye: {money(current)}\nYeni cari borç: {money(new_debt)}\nSatış sonrası bakiye: {money(projected)}\nRisk limiti: {money(limit)}\nLimit aşımı: {money(excess)}"
 action=effective_setting('cari_risk_action','Uyar').strip().lower()
 if 'engel' in action:
  messagebox.showerror(APP,detail+'\n\nAyar gereği satış kaydedilmedi.',parent=parent);DX.audit('Cari','Risk Aşımı Engellendi',cari_id,new=current,reason=detail);return False
 if 'yönet' in action or 'yonet' in action or 'onay' in action:return manager_approval(parent,detail)
 ok=messagebox.askyesno(APP,detail+'\n\nSatışa devam edilsin mi?',parent=parent)
 DX.audit('Cari','Risk Aşımı Uyarısı',cari_id,new='Devam' if ok else 'Vazgeçildi',reason=detail);return ok

