_CODE39={'0':'nnnwwnwnn','1':'wnnwnnnnw','2':'nnwwnnnnw','3':'wnwwnnnnn','4':'nnnwwnnnw','5':'wnnwwnnnn','6':'nnwwwnnnn','7':'nnnwnnwnw','8':'wnnwnnwnn','9':'nnwwnnwnn','A':'wnnnnwnnw','B':'nnwnnwnnw','C':'wnwnnwnnn','D':'nnnnwwnnw','E':'wnnnwwnnn','F':'nnwnwwnnn','G':'nnnnnwwnw','H':'wnnnnwwnn','I':'nnwnnwwnn','J':'nnnnwwwnn','K':'wnnnnnnww','L':'nnwnnnnww','M':'wnwnnnnwn','N':'nnnnwnnww','O':'wnnnwnnwn','P':'nnwnwnnwn','Q':'nnnnnnwww','R':'wnnnnnwwn','S':'nnwnnnwwn','T':'nnnnwnwwn','U':'wwnnnnnnw','V':'nwwnnnnnw','W':'wwwnnnnnn','X':'nwnnwnnnw','Y':'wwnnwnnnn','Z':'nwwnwnnnn','-':'nwnnnnwnw','.':'wwnnnnwnn',' ':'nwwnnnwnn','*':'nwnnwnwnn'}
def code39_svg(value,height=58):
 value=str(value or '').upper();value=''.join(ch for ch in value if ch in _CODE39 and ch!='*')
 encoded='*'+value+'*';narrow=2;wide=5;gap=2;x=8;bars=[]
 for char in encoded:
  for i,kind in enumerate(_CODE39[char]):
   width=wide if kind=='w' else narrow
   if i%2==0:bars.append(f'<rect x="{x}" y="2" width="{width}" height="{height}"/>')
   x+=width
  x+=gap
 total=x+8
 return f'<svg xmlns="http://www.w3.org/2000/svg" width="100%" viewBox="0 0 {total} {height+20}" role="img" aria-label="{html.escape(value)}"><g fill="#000">{"".join(bars)}</g><text x="{total/2}" y="{height+15}" text-anchor="middle" font-family="Arial" font-size="11">{html.escape(value)}</text></svg>'

# v1.2.289.2: Windows yazıcı taraması PowerShell başlattığı için özellikle Etiket
# Merkezi her açıldığında programı saniyelerce bekletebiliyordu. Sonuç kısa süreli
# önbelleğe alınır; kullanıcı YENİLE dediğinde zorla tekrar taranır.
_PRINTER_CACHE={'ts':0.0,'names':[]}
def windows_printers(force=False):
 if os.name!='nt':return []
 try:
  import time as _time
  t=_time.monotonic()
  if not force and _PRINTER_CACHE['names'] and t-_PRINTER_CACHE['ts']<300:
   return list(_PRINTER_CACHE['names'])
  cmd=['powershell','-NoProfile','-Command','Get-Printer | Select-Object -ExpandProperty Name']
  p=subprocess.run(cmd,capture_output=True,text=True,timeout=3,creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
  names=sorted({x.strip() for x in p.stdout.splitlines() if x.strip()},key=str.lower)
  _PRINTER_CACHE.update(ts=t,names=names)
  return list(names)
 except Exception:return list(_PRINTER_CACHE.get('names') or [])
def is_label_printer(name):
 n=str(name or '').lower();return any(x in n for x in ('argox','zebra','tsc','godex','cab ','barcode','barkod','etiket','label'))

LEGACY_TABLES = ['STOK','CARI','ISLEM','DETAY','TAKSIT','CEKSENET','PERSATIS','PERDETAY','SGURUP','BIRIM','CGURUP','BHESAP','SABLON','AYAR','KASA','GLGURUP','GDGURUP','KKART','IGURUP','SERINO']

def legacy_extract(src: Path, dest: Path):
    data=src.read_bytes()
    company=period=''
    try:
        header=data[32:96].decode('cp1254','ignore')
        m=re.search(r'Firma=(\d+)',header,re.I); company=m.group(1) if m else ''
        m=re.search(r'D.nem=(\d+)|Dönem=(\d+)',header,re.I); period=(m.group(1) or m.group(2)) if m else ''
    except Exception: pass
    dest.mkdir(parents=True, exist_ok=True)
    found=[]
    for m in re.finditer(rb'([A-Z]+)\.dat', data):
        name=m.group(1).decode('ascii','ignore')
        if name not in LEGACY_TABLES: continue
        pos=m.end()
        if pos+29>len(data): continue
        ver=struct.unpack_from('<I',data,pos)[0]; pos+=4
        usize=struct.unpack_from('<Q',data,pos)[0]; pos+=8
        guid=data[pos:pos+16]; pos+=16
        marker=data[pos]; pos+=1
        out=bytearray()
        try:
            while len(out)<usize:
                clen=struct.unpack_from('<I',data,pos)[0]; pos+=4
                comp=data[pos:pos+clen]; pos+=clen
                out += zlib.decompress(comp)
            (dest/f'{name}.dat').write_bytes(out[:usize])
            found.append({'name':name,'version':ver,'size':usize,'marker':marker})
        except Exception:
            continue
    meta={'source':src.name,'company':company,'period':period,'tables':found,'imported_at':datetime.datetime.now().isoformat(timespec='seconds')}
    (dest/'manifest.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2),encoding='utf-8')
    return meta



def _legacy_date(v):
    """DBISAM Date: ordinal day number. Returns ISO date text."""
    try:
        if v is None:
            return ''
        n=int(v)
        if n <= 0:
            return ''
        from datetime import date
        return date.fromordinal(n).isoformat()
    except Exception:
        return ''




def _legacy_time(v):
    """KTS/DBISAM saat veya timestamp değerinden HH:MM:SS üretir."""
    if v is None:return ''
    s=str(v).strip()
    if not s:return ''
    # Bazı KTS sürümleri saati doğrudan metin olarak saklar.
    m=re.search(r'(?<!\d)([01]?\d|2[0-3])[:.]([0-5]\d)(?:[:.]([0-5]\d))?',s)
    if m:return f'{int(m.group(1)):02d}:{int(m.group(2)):02d}:{int(m.group(3) or 0):02d}'
    try:
        # KTS KAYITTARIHI iki biçimde görülebilir:
        # 1) Delphi/DBISAM gün + gün kesri, 2) gün değerinin milisaniye ölçekli hali.
        # Gerçek F1D2026_26Eyl2026 yedeğinde örn. 63926132178439 / 86400000
        # = 739885.789... ve bu 2026-09-26 18:56:18 saatini verir.
        n=float(s)
        day_value=(n/86400000.0) if abs(n)>10000000 else n
        frac=abs(day_value)-int(abs(day_value));seconds=int(round(frac*86400))%86400
        # 00:00 gerçek bir saat olabilir; büyük timestamp değerlerinde bunu koru.
        if not seconds and abs(n)<=10000000:return ''
        return f'{seconds//3600:02d}:{(seconds%3600)//60:02d}:{seconds%60:02d}'
    except Exception:return ''


def _legacy_sale_datetime(row):
    """Satış tarihini, KTS'de bulunan gerçek işlem saatiyle birleştirir."""
    day=_legacy_date(row.get('TARIH'))
    raw=_legacy_first(row,['SAAT','ISLEMSAATI','KAYITSAATI','KAYITTARIHI','KAYITTARIH'],None)
    tm=_legacy_time(raw)
    return (day+' '+tm) if day and tm else (day or now())


def parse_dbisam_dat(path: Path, include_deleted=False):
    """Read the DBISAM v4-style .dat files extracted from the KTS .bck archive.

    This parser is intentionally read-only. It understands the fixed 512-byte
    header, 768-byte field definitions and fixed-size data rows used by the
    uploaded KTS backup. It supports the field types present in this dataset.
    """
    data=Path(path).read_bytes()
    if len(data) < 0x200:
        raise ValueError(f'{Path(path).name}: tablo dosyası çok kısa.')
    total_rows=struct.unpack_from('<I',data,0x29)[0]
    row_size=struct.unpack_from('<H',data,0x2D)[0]
    total_fields=struct.unpack_from('<H',data,0x2F)[0]
    if row_size <= 0 or total_fields <= 0 or total_fields > 500:
        raise ValueError(f'{Path(path).name}: DBISAM tablo yapısı tanınmadı.')
    data_start=0x200 + total_fields*768
    if data_start + total_rows*row_size > len(data):
        raise ValueError(f'{Path(path).name}: tablo uzunluğu beklenen yapı ile uyuşmuyor.')

    fields=[]
    for i in range(total_fields):
        o=0x200+i*768
        raw=data[o+2:o+164]
        n=raw[0] if raw else 0
        if 0 < n <= 160:
            name=raw[1:1+n].decode('cp1254','replace')
        else:
            name=raw.split(b'\x00',1)[0].decode('cp1254','replace').strip('\x00\x01\x02\x03\x04\x05\x06\x07\x08\x09')
        typ=struct.unpack_from('<H',data,o+0xA4)[0]
        length=struct.unpack_from('<H',data,o+0xA6)[0]
        roff=struct.unpack_from('<H',data,o+0xAC)[0]
        fields.append((name,typ,length,roff))

    def value(row,typ,length,off):
        if off >= len(row): return None
        # In this DBISAM layout every stored field starts with a present/null byte.
        if row[off] == 0: return None
        p=off+1
        try:
            if typ==1:  # string
                return row[p:p+length].split(b'\x00',1)[0].decode('cp1254','replace').strip()
            if typ==2:  # date
                return struct.unpack_from('<i',row,p)[0]
            if typ==4:  # boolean
                return bool(row[p])
            if typ==5:  # short int
                return struct.unpack_from('<h',row,p)[0]
            if typ in (6,7430):  # int / autoinc
                return struct.unpack_from('<i',row,p)[0]
            if typ in (7,5383,11):  # double / currency / timestamp
                return struct.unpack_from('<d',row,p)[0]
            if typ in (3,5635):  # BLOB/Memo pointer; .blb not present in this backup
                return None
        except Exception:
            return None
        return None

    rows=[]
    for i in range(total_rows):
        row=data[data_start+i*row_size:data_start+(i+1)*row_size]
        deleted = bool(row[0])
        if deleted and not include_deleted:
            continue
        rec={name:value(row,typ,length,off) for name,typ,length,off in fields}
        rec['_deleted']=deleted
        rows.append(rec)
    return {'total_rows':total_rows,'active_rows':len(rows),'row_size':row_size,'fields':[f[0] for f in fields],'rows':rows}


def _read_legacy_table(extract_dir: Path, name: str, include_deleted=False):
    p=Path(extract_dir)/f'{name}.dat'
    if not p.exists():
        return {'total_rows':0,'active_rows':0,'fields':[],'rows':[]}
    return parse_dbisam_dat(p,include_deleted=include_deleted)






def restore_legacy_master(extract_dir: Path, source_name=''):
    # v1.2.165: BCK yalnız stok olarak ele alınmaz. Desteklenen iş kayıtları MASTER
    # tablolarına aktarılır; ayrıca BCK içindeki TÜM tabloların TÜM satırları (silinmiş
    # kayıt işareti dahil) JSON olarak salt-okunur arşiv tablosunda korunur. Böylece
    # yeni şemada birebir karşılığı olmayan eski alanlar sessizce kaybolmaz.
    st=_read_legacy_table(extract_dir,'STOK'); cr=_read_legacy_table(extract_dir,'CARI')
    ps=_read_legacy_table(extract_dir,'PERSATIS'); pd=_read_legacy_table(extract_dir,'PERDETAY')
    tk=_read_legacy_table(extract_dir,'TAKSIT'); cs=_read_legacy_table(extract_dir,'CEKSENET'); ks=_read_legacy_table(extract_dir,'KASA')
    stats={'products':0,'customers':0,'sales':0,'sale_items':0,'installments':0,'checks':0,'cash':0,'raw_records':0,'raw_tables':0,'source_counts':{}}
    c=DX.con()
    try:
        c.execute('BEGIN'); c.execute('PRAGMA foreign_keys=OFF')
        c.execute('CREATE TABLE IF NOT EXISTS legacy_raw_records(id INTEGER PRIMARY KEY,source_file TEXT,table_name TEXT,row_no INTEGER,deleted INTEGER DEFAULT 0,data_json TEXT,UNIQUE(source_file,table_name,row_no))')
        for t in ['sale_lines','sale_payments','sales','stock_moves','cari_moves','installments','checks_notes','finance','caris','stock']:
            c.execute(f'DELETE FROM {t}')
        # Aynı kaynak yeniden yüklenirse ham arşivde çift kayıt oluşmasın.
        c.execute('DELETE FROM legacy_raw_records WHERE source_file=?',(source_name,))
        for legacy_name in LEGACY_TABLES:
            lp=Path(extract_dir)/f'{legacy_name}.dat'
            if not lp.exists(): continue
            raw=_read_legacy_table(extract_dir,legacy_name,include_deleted=True)
            stats['raw_tables']+=1; stats['source_counts'][legacy_name]={'total':raw.get('total_rows',0),'active':sum(1 for x in raw['rows'] if not x.get('_deleted'))}
            for row_no,row in enumerate(raw['rows'],1):
                deleted=1 if row.get('_deleted') else 0
                payload={k:v for k,v in row.items() if k!='_deleted'}
                c.execute('INSERT INTO legacy_raw_records(source_file,table_name,row_no,deleted,data_json) VALUES(?,?,?,?,?)',(source_name,legacy_name,row_no,deleted,json.dumps(payload,ensure_ascii=False,default=str)))
                stats['raw_records']+=1
        seen=set(); product_by_code={}
        for r in st['rows']:
            code=str(r.get('STKOD') or '').strip(); name=str(r.get('STADI') or '').strip()
            if not code and not name: continue
            barcode=str(r.get('STBARKOD') or '').strip() or None
            if barcode in seen: barcode=None
            if barcode: seen.add(barcode)
            # KTS/BCK sürümlerinde alan adları değişebildiği için olası alanları sırayla kontrol et.
            qty=float(_legacy_first(r,['STMEVCUT','STMIKTAR','MIKTAR','MEVCUT'],0,True) or 0)
            last_cost=float(_legacy_first(r,['STSONALIS','SONALIS','STFIYAT1'],0,True) or 0)
            avg_cost=float(_legacy_first(r,['STORTMALIYET','STORTMAL','ORTMALIYET','STFIYAT1'],last_cost,True) or 0)
            retail=float(_legacy_first(r,['STFIYAT3','STSATIS','SATISFIYAT','STFIYAT2','STFIYAT4'],0,True) or 0)
            wholesale=float(_legacy_first(r,['STFIYAT4','STTOPTAN','TOPTANFIYAT','STFIYAT2'],0,True) or 0)
            special_price=float(_legacy_first(r,['STFIYAT2','STOZELFIYAT','OZELFIYAT'],0,True) or 0)
            section=str(_legacy_first(r,['STBOLUM','BOLUM','STBOLGE','BOLGE','STYER','YER'],'') or '').strip()
            shelf=str(_legacy_first(r,['STRAF','RAF','STRAFKOD','RAFKOD'],'') or '').strip()
            warehouse=str(_legacy_first(r,['STDEPO','DEPO','DEPOKOD'],'') or '').strip()
            cur=c.execute('INSERT INTO stock(barcode,code,name,brand,model,grp,unit,vat,special,warehouse,section,shelf,min_qty,qty,last_cost,avg_cost,retail,wholesale,special_price,created,updated) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',
                (barcode,code or None,name or f'STOK {code}',str(r.get('STMARKA') or '').strip(),str(r.get('STMODEL') or '').strip(),str(r.get('STGURUP') or '').strip(),str(r.get('STBIRIM') or 'Adet').strip(),float(r.get('STKDV') or 0),str(r.get('STOZELKOD') or '').strip(),warehouse,section,shelf,float(r.get('STKRITIK') or 0),qty,last_cost,avg_cost,retail,wholesale,special_price,now(),now()))
            product_by_code[code]=cur.lastrowid; stats['products']+=1
            if qty: c.execute('INSERT INTO stock_moves(stock_id,dt,kind,qty,unit_cost,source,note) VALUES(?,?,?,?,?,?,?)',(cur.lastrowid,now(),'KTS Açılış',qty,(avg_cost if avg_cost else last_cost),'KTS',source_name))
        customer_by_old={}
        for r in cr['rows']:
            old=str(r.get('CRKOD') or '').strip(); title=str(r.get('CRUNVAN') or r.get('CRFATURAUNVANI') or '').strip()
            if not old and not title: continue
            cur=c.execute('INSERT INTO caris(title,role,phone,email,tax_no,tax_office,city,address,grp,special,risk,due_days,active,web,contact_name,contact_phone,contact_email) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,1,?,?,?,?)',(title or f'CARİ {old}','Müşteri',str(r.get('CRCEP') or r.get('CRTEL1') or r.get('CRTEL2') or '').strip(),str(r.get('CREMAIL') or '').strip(),str(r.get('CRVERGINO') or r.get('CRKIMLIKNO') or '').strip(),str(r.get('CRVERGID') or '').strip(),str(r.get('CRIL') or '').strip(),str(r.get('CRADRES') or '').strip(),str(r.get('CRGURUP') or '').strip(),str(r.get('CROZELKOD') or '').strip(),float(r.get('CRKREDILIMITI') or 0),int(float(r.get('CRVADE') or 0)),str(r.get('CRWWW') or '').strip(),str(r.get('CRYETKILI') or '').strip(),str(r.get('CRTEL1') or '').strip(),str(r.get('CREMAIL') or '').strip()))
            customer_by_old[old]=cur.lastrowid; stats['customers']+=1
            bal=float(r.get('CRBAKIYE0') or 0)
            if bal: c.execute('INSERT INTO cari_moves(cari_id,dt,kind,debit,credit,source,note) VALUES(?,?,?,?,?,?,?)',(cur.lastrowid,now(),'KTS Açılış',bal if bal>0 else 0,-bal if bal<0 else 0,'KTS',source_name))
        sale_by_isno={}
        for r in ps['rows']:
            isno=str(r.get('ISNO') or '').strip(); base_receipt=str(r.get('FISNO') or '').strip() or (f'KTS-PS-{isno}' if isno else '')
            if not base_receipt: continue
            # KTS yedeğinde aynı FISNO birden fazla işlemde bulunabiliyor (ör. PS15003).
            # MASTER doc_no benzersiz olduğundan çakışmada ISNO ekleyerek hiçbir satışı kaybetme.
            receipt=base_receipt
            if c.execute('SELECT 1 FROM sales WHERE doc_no=?',(receipt,)).fetchone():
                receipt=f'{base_receipt}-KTS-{isno or stats["sales"]+1}'
                n=2
                while c.execute('SELECT 1 FROM sales WHERE doc_no=?',(receipt,)).fetchone():
                    receipt=f'{base_receipt}-KTS-{isno or stats["sales"]+1}-{n}'; n+=1
            dt=_legacy_sale_datetime(r); subtotal=float(r.get('NETTUTAR') or r.get('TUTAR') or 0); disc=float(r.get('ISKONTOTUTARI') or 0); total=float(r.get('TOPLAMTUTAR') or subtotal); pay=str(r.get('ODEMETURUSTR') or '').strip() or 'Nakit'
            cur=c.execute('INSERT INTO sales(doc_no,dt,payment,gross,discount,total,status,user) VALUES(?,?,?,?,?,?,?,?)',(receipt,dt,pay,subtotal,disc,total,'FINAL','KTS Aktarım')); sale_by_isno[isno]=cur.lastrowid; stats['sales']+=1
            c.execute('INSERT INTO sale_payments(sale_id,kind,amount) VALUES(?,?,?)',(cur.lastrowid,pay,total))
        for r in pd['rows']:
            sid=sale_by_isno.get(str(r.get('ISNO') or '').strip())
            if not sid: continue
            code=str(r.get('STKOD') or '').strip(); pid=product_by_code.get(code); qty=float(r.get('DTMIKTAR') or 0); price=float(r.get('DTFIYAT') or r.get('DTBIRIMFIYATYTL') or 0); disc=float(r.get('DTISKONTOYTL') or 0); total=float(r.get('DTGENELTOPLAMYTL') or r.get('DTTOPLAMYTL') or (qty*price-disc))
            c.execute('INSERT INTO sale_lines(sale_id,stock_id,barcode,name,qty,price,discount,total,cost_snapshot,campaign) VALUES(?,?,?,?,?,?,?,?,?,?)',(sid,pid,str(r.get('STBARKOD') or '').strip(),str(r.get('STADI') or '').strip(),qty,price,disc,total,0,'KTS'))
            stats['sale_items']+=1
        for r in tk['rows']:
            cid=customer_by_old.get(str(r.get('CRKOD') or '').strip()); amt=float(r.get('TUTAR') or 0); paid=amt if r.get('ODENDI') else 0
            c.execute('INSERT INTO installments(cari_id,sale_id,due_date,amount,paid,status) VALUES(?,?,?,?,?,?)',(cid,None,_legacy_date(r.get('TARIH')),amt,paid,'Ödendi' if paid else 'Açık')); stats['installments']+=1
        for r in cs['rows']:
            c.execute('INSERT INTO checks_notes(kind,number,customer,due_date,amount,status,note) VALUES(?,?,?,?,?,?,?)',(str(r.get('TURSTR') or 'Çek/Senet'),str(r.get('CEKSENETNO') or ''),str(r.get('CRUNVAN') or r.get('KIME') or ''),_legacy_date(r.get('TARIHI')),float(r.get('TUTAR') or 0),'Portföyde',str(r.get('ACIKLAMA') or ''))); stats['checks']+=1
        for r in ks['rows']:
            amount=0.0
            for key in ('BORC0','ALACAK0','TUTAR','TOPLAM'):
                if r.get(key) is not None: amount=float(r.get(key) or 0); break
            c.execute('INSERT INTO finance(dt,account,kind,amount,source,note) VALUES(?,?,?,?,?,?)',(_legacy_date(r.get('TARIH')) or now(),'Kasa','KTS Kasa Hareketi',amount,'KTS',str(r.get('ISTURSTR') or r.get('GURUBU') or ''))); stats['cash']+=1
        # Kaynak/MASTER sayıları birebir uyuşmadan aktarımı başarılı sayma.
        # PERDETAY içinde ana PERSATIS kaydı bulunmayan eski/yetim detaylar olabilir.
        # Bunlar MASTER satış satırına bağlanamaz; fakat legacy_raw_records içinde eksiksiz korunur.
        # Doğrulamada yalnız gerçekten bağlanabilir aktif detaylar beklenir.
        linked_detail_count=sum(1 for r in pd['rows'] if str(r.get('ISNO') or '').strip() in sale_by_isno)
        expected={'products':st['active_rows'],'customers':cr['active_rows'],'sales':ps['active_rows'],'sale_items':linked_detail_count,'installments':tk['active_rows'],'checks':cs['active_rows'],'cash':ks['active_rows']}
        # Stokta yalnız sayı değil kimlikler de birebir doğrulanır.
        src_stock={(str(r.get('STKOD') or '').strip(),str(r.get('STBARKOD') or '').strip()) for r in st['rows']}
        dst_stock={(str(x[0] or '').strip(),str(x[1] or '').strip()) for x in c.execute('SELECT code,barcode FROM stock').fetchall()}
        if src_stock!=dst_stock:
            missing=sorted(src_stock-dst_stock)[:20]; extra=sorted(dst_stock-src_stock)[:20]
            raise RuntimeError('BCK stok kimlik doğrulaması başarısız; hiçbir değişiklik kaydedilmedi.\nEksik örnek: '+repr(missing)+'\nFazla örnek: '+repr(extra))
        # v1.2.167: Sayı/kimlik eşitliği tek başına yeterli değildir. Kaynak BCK'deki
        # stok adı, marka, grup, mevcut, KDV ve fiyat alanlarını hedef MASTER ile
        # STKOD bazında tek tek karşılaştır. Bir alan bile farklıysa COMMIT yapılmaz.
        field_errors=[]
        dst_by_code={str(x['code'] or '').strip():x for x in c.execute('SELECT code,barcode,name,brand,model,grp,unit,vat,special,warehouse,section,shelf,min_qty,qty,last_cost,avg_cost,retail,wholesale,special_price FROM stock').fetchall()}
        for r in st['rows']:
            code=str(r.get('STKOD') or '').strip(); d=dst_by_code.get(code)
            if d is None:
                field_errors.append(f'{code}: hedefte yok'); continue
            expected_barcode=str(r.get('STBARKOD') or '').strip()
            text_checks={
                'barcode':expected_barcode,'name':str(r.get('STADI') or '').strip(),
                'brand':str(r.get('STMARKA') or '').strip(),'model':str(r.get('STMODEL') or '').strip(),
                'grp':str(r.get('STGURUP') or '').strip(),'unit':str(r.get('STBIRIM') or 'Adet').strip(),
                'special':str(r.get('STOZELKOD') or '').strip(),
                'warehouse':str(_legacy_first(r,['STDEPO','DEPO','DEPOKOD'],'') or '').strip(),
                'section':str(_legacy_first(r,['STBOLUM','BOLUM','STBOLGE','BOLGE','STYER','YER'],'') or '').strip(),
                'shelf':str(_legacy_first(r,['STRAF','RAF','STRAFKOD','RAFKOD'],'') or '').strip()}
            num_checks={
                'vat':float(r.get('STKDV') or 0),'min_qty':float(r.get('STKRITIK') or 0),
                'qty':float(_legacy_first(r,['STMEVCUT','STMIKTAR','MIKTAR','MEVCUT'],0,True) or 0),
                'last_cost':float(_legacy_first(r,['STSONALIS','SONALIS','STFIYAT1'],0,True) or 0),
                'avg_cost':float(_legacy_first(r,['STORTMALIYET','STORTMAL','ORTMALIYET','STFIYAT1'],_legacy_first(r,['STSONALIS','SONALIS','STFIYAT1'],0,True),True) or 0),
                'retail':float(_legacy_first(r,['STFIYAT3','STSATIS','SATISFIYAT','STFIYAT2','STFIYAT4'],0,True) or 0),
                'wholesale':float(_legacy_first(r,['STFIYAT4','STTOPTAN','TOPTANFIYAT','STFIYAT2'],0,True) or 0),
                'special_price':float(_legacy_first(r,['STFIYAT2','STOZELFIYAT','OZELFIYAT'],0,True) or 0)}
            for k,v in text_checks.items():
                if str(d[k] or '').strip()!=v: field_errors.append(f'{code} {k}: kaynak={v!r} hedef={str(d[k] or "").strip()!r}')
            for k,v in num_checks.items():
                if abs(float(d[k] or 0)-v)>0.000001: field_errors.append(f'{code} {k}: kaynak={v} hedef={float(d[k] or 0)}')
            if len(field_errors)>=30:break
        if field_errors:
            raise RuntimeError('BCK stok alan doğrulaması başarısız; hiçbir değişiklik kaydedilmedi.\n'+'\n'.join(field_errors[:30]))
        # Kullanıcıya doğrulama özetinde kaynaktaki gerçek doluluk sayılarını da ver.
        stats['stock_nonzero_qty']=sum(1 for r in st['rows'] if abs(float(r.get('STMEVCUT') or 0))>0.000001)
        stats['stock_nonzero_retail']=sum(1 for r in st['rows'] if abs(float(r.get('STFIYAT3') or 0))>0.000001)
        stats['stock_nonzero_cost']=sum(1 for r in st['rows'] if abs(float(r.get('STFIYAT1') or 0))>0.000001)
        mismatches=[]
        for key,want in expected.items():
            if int(stats[key])!=int(want):mismatches.append(f'{key}: kaynak {want}, aktarılan {stats[key]}')
        raw_expected=sum(v['total'] for v in stats['source_counts'].values())
        if stats['raw_records']!=raw_expected:mismatches.append(f'ham arşiv: kaynak {raw_expected}, korunan {stats["raw_records"]}')
        if mismatches:raise RuntimeError('BCK doğrulaması başarısız; hiçbir değişiklik kaydedilmedi.\n'+'\n'.join(mismatches))
        c.execute('PRAGMA foreign_keys=ON'); c.commit(); return stats
    except Exception:
        c.rollback(); raise
    finally: c.close()

class Base(tk.Frame):
 def __init__(self,p,title,sub=''):
  super().__init__(p,bg=BG); self.pack(fill='both',expand=True); self.after(300,self._alf_gate_raw)
  # v1.2.291.17: Modül içinde ayrıca 'EKRANI KAPAT' düğmesi yok.
  # Kapatma için Windows'un standart — / □ / X başlık düğmeleri kullanılır.
  head=tk.Frame(self,bg=BG);head.pack(fill='x',padx=24,pady=(18,4))
  tk.Label(head,text=title,bg=BG,fg=TXT,font=('Segoe UI',22,'bold')).pack(side='left',anchor='w')
 def _alf_gate_raw(self):
  try:
   if self.winfo_exists():_gv().gate_widget_tree(self,_module_of(self))
  except Exception as _se:_silent(_se)
 def card(self): f=tk.Frame(self,bg='white',highlightthickness=1,highlightbackground=BORDER); f.pack(fill='x',padx=24,pady=8); return f
 def btn(self,p,text,cmd,red=False):
  # v1.2.150: Program geneli ortak buton görünüm standardı.
  # Yalnız görsel katmandır; command/iş mantığı/veritabanı akışı değiştirilmez.
  label=str(text or '').upper()
  primary_words=('ÖDEME','ÖDE','KAYDET','TAMAMLA','TAHSİLAT','SATIŞI TAMAMLA','FATURA OLUŞTUR')
  primary = bool(red) or any(word in label for word in primary_words)
  # v1.2.291.448: Ekle / Değiştir / Pasife Al / Yazdır düğmeleri rol yetkisine bağlıdır (Yönetici serbest; yetkisi olmayana yetkili onayı).
  try:cmd=_gv().gate_command(lambda:p.winfo_toplevel(),_module_of(self),text,cmd)
  except Exception as _se:_silent(_se)
  # Ana işlem: F9 ÖDEME örneği gibi kırmızı + beyaz.
  # Yardımcı işlem: F4/F5/F6/F7/F8 örneği gibi beyaz + siyah çerçeve/yazı.
  _b=tk.Button(p,text=text,command=cmd,
   bg='#c8102e' if primary else '#ffffff',fg='#ffffff' if primary else '#111111',
   activebackground='#a90d27' if primary else '#f2f2f2',activeforeground='#ffffff' if primary else '#111111',
   relief='solid',bd=1,highlightthickness=0,font=('Segoe UI',_ui_font_size('button'),'bold'),
   padx=12,pady=7,cursor='hand2',takefocus=True)
  _b._alf_gated=True;return _b

class Dashboard(Base):
 def __init__(self,p):
  # Yeni ana ekran kendi üst başlığını kullandığı için Base başlığı oluşturulmaz.
  tk.Frame.__init__(self,p,bg='#f3f5f9'); self.pack(fill='both',expand=True); self.after(300,self._alf_gate_raw)
  self._db_stamp=self._database_stamp(); self.refresh(); self.after(1200,self._watch_database)
 def _database_stamp(self):
  try: st=DB.stat(); return (st.st_mtime_ns,st.st_size)
  except Exception:return (0,0)
 def _watch_database(self):
  try:
   if not self.winfo_exists():return
   stamp=self._database_stamp()
   # v1.2.277: DB değiştiğinde Ana Sayfanın tamamını destroy/rebuild etmek
   # saniyelik beyazlama/titreme oluşturuyordu. Değişikliği yalnız işaretle;
   # Ana Sayfa yeniden açıldığında Dashboard zaten güncel veriyi DB'den kurar.
   # Böylece ekrandayken görüntü sabit kalır.
   if stamp!=self._db_stamp:self._db_stamp=stamp;self._data_dirty=True
   _rs=ayar_tam('refresh_seconds')   # Ayarlar > Açılış, Kapanış & Bakım > Ana sayfa yenileme (0 = kapalı)
   if _rs>0 and getattr(self,'_data_dirty',False):
    _t=_alf_time.time()
    if _t-getattr(self,'_rf_last',_t)>=_rs:
     self._data_dirty=False;self._rf_last=_t;self.refresh()
    self._rf_last=getattr(self,'_rf_last',_t)
   self.after(1200,self._watch_database)
  except tk.TclError:return
 def _goto(self,name):
  w=self
  while w is not None:
   if name=='__STOK_EKLE__' and hasattr(w,'open_new_stock'):
    try:w.open_new_stock();return
    except Exception as _se:_silent(_se)
   if hasattr(w,'show'):
    try:w.show(name);return
    except Exception as _se:_silent(_se)
   w=getattr(w,'master',None)
 def _pay_total(self,day,kind,until_time=None):
  total=0.0
  time_sql=" AND (length(s.dt)<=10 OR substr(s.dt,12,8)<=?)" if until_time else ""
  args=(day,until_time) if until_time else (day,)
  rows=DX.rows("SELECT s.id,s.payment,s.total,sp.kind,sp.amount FROM sales s LEFT JOIN sale_payments sp ON sp.sale_id=s.id WHERE substr(s.dt,1,10)=? AND s.status='FINAL'"+time_sql,args)
  by_sale={}
  for r in rows:
   sid=r['id']; rec=by_sale.setdefault(sid,{'payment':str(r['payment'] or ''),'total':float(r['total'] or 0),'pays':[]})
   if r['kind'] is not None:rec['pays'].append((str(r['kind'] or ''),float(r['amount'] or 0)))
  def pay_class(label):
   k=search_norm(label)
   if any(x in k for x in ('kart','pos','kredi')):return 'card'
   if any(x in k for x in ('nakit','cash','pesin','kasa')):return 'cash'
   return ''
  for rec in by_sale.values():
   if rec['pays']:
    for label,amount in rec['pays']:
     if pay_class(label)==kind:total+=amount
   elif pay_class(rec['payment'])==kind:
    total+=rec['total']
  return total
 def _pay_count(self,day,until_time=None):
  """Günün satışlarını ödeme türüne göre tekil işlem/kişi olarak sayar.
  Parçalı ödemede satış iki kez sayılmaz; yüksek tutarlı ödeme ana ödeme türü kabul edilir.
  """
  time_sql=" AND (length(s.dt)<=10 OR substr(s.dt,12,8)<=?)" if until_time else ""
  args=(day,until_time) if until_time else (day,)
  rows=DX.rows("SELECT s.id,s.payment,s.total,sp.kind,sp.amount FROM sales s LEFT JOIN sale_payments sp ON sp.sale_id=s.id WHERE substr(s.dt,1,10)=? AND s.status='FINAL'"+time_sql,args)
  by_sale={}
  for r in rows:
   sid=r['id'];rec=by_sale.setdefault(sid,{'payment':str(r['payment'] or ''),'cash':0.0,'card':0.0})
   label=search_norm(str(r['kind'] or ''));amount=float(r['amount'] or 0)
   if any(x in label for x in ('kart','pos','kredi')):rec['card']+=amount
   elif any(x in label for x in ('nakit','cash','pesin','kasa')):rec['cash']+=amount
  out={'cash':0,'card':0}
  for rec in by_sale.values():
   if rec['cash']>0 or rec['card']>0:
    # Parçalı ödemeyi iki kişiye/işleme dönüştürme: baskın ödeme türüne tek kez yaz.
    out['card' if rec['card']>rec['cash'] else 'cash']+=1
   else:
    k=search_norm(rec['payment'])
    if any(x in k for x in ('kart','pos','kredi')):out['card']+=1
    elif any(x in k for x in ('nakit','cash','pesin','kasa')):out['cash']+=1
