 def _where(self):
  term=self.q.get().strip(); parts=['active=0' if self.filter.get()=='Pasif Stoklar' else 'active=1']; args=[]
  if term:
   toks=[x for x in term.split() if x]
   for t in toks:
    like='%'+t+'%'; parts.append("(COALESCE(barcode,'') LIKE ? OR COALESCE(code,'') LIKE ? OR COALESCE(name,'') LIKE ? OR COALESCE(brand,'') LIKE ? OR COALESCE(model,'') LIKE ? OR COALESCE(special,'') LIKE ? OR COALESCE(shelf,'') LIKE ? OR id IN (SELECT stock_id FROM stock_barcodes WHERE barcode LIKE ? AND active=1))"); args += [like]*8
