  if f=='Pasif Stoklar':
   passive_where,passive_args=self._where()
   sql=("SELECT s.*, "
        "COALESCE((SELECT SUM(qty) FROM stock_moves WHERE stock_id=s.id AND kind LIKE '%Açılış%'),0) opening, "
        "COALESCE((SELECT SUM(qty) FROM stock_moves WHERE stock_id=s.id AND qty>0 AND kind NOT LIKE '%Açılış%'),0) inputs, "
        "COALESCE((SELECT SUM(-qty) FROM stock_moves WHERE stock_id=s.id AND qty<0 AND kind NOT LIKE '%Açılış%'),0) outputs "
        "FROM stock s WHERE "+passive_where+" ORDER BY s.id DESC")
   args=passive_args
  rows=DX.rows(sql,args); self.tree.delete(*self.tree.get_children())
  tot_qty=tot_cost=tot_sale=0.0;n_neg=n_crit=n_nocost=0
  try:_sold30={x['stock_id']:float(x['q'] or 0) for x in DX.rows("SELECT sl.stock_id,SUM(COALESCE(sl.qty,0)) q FROM sale_lines sl JOIN sales s ON s.id=sl.sale_id WHERE sl.stock_id IS NOT NULL AND s.status IN ('FINAL','PARTIAL_RETURN') AND substr(s.dt,1,10)>=date('now','-30 day') GROUP BY sl.stock_id")}
  except Exception:_sold30={}
  _lsale={}
