 def _stock_thumbs_apply(self):
  # v1.2.291.246: Listede her stoğun ilk görseli küçük resim olarak gösterilir (önbellekli, arka planda üretilir).
  try:
   if not hasattr(self,'tree'):return
   from ALFABE_STOK_EK_OZELLIKLER import primary_images,list_thumb_file,ensure_list_thumbs
   dbp=Path(DB); imgs=primary_images(DX.con)
   # v461.94: Hiç ürüne görsel eklenmemişse boş 'Görsel' sütunu otomatik gizlenir; görsel eklenince kendiliğinden geri gelir.
   try:
    if not imgs:
     if 'tree' in str(self.tree.cget('show')):_tree_toggle_image_col(self.tree,False,save=False);self.tree._alf_auto_hid=True
    elif getattr(self.tree,'_alf_auto_hid',False):
     self.tree._alf_auto_hid=False;_tree_toggle_image_col(self.tree,True,save=False)
   except Exception as _se:_silent(_se)
   if not imgs:return
   cache=self.__dict__.setdefault('_thumb_imgs',{}); failed=self.__dict__.setdefault('_thumb_failed',set()); missing=[]
   for iid in self.tree.get_children():
    try:sid=int(iid)
    except Exception:continue
    f=imgs.get(sid)
    if not f:continue
    th=list_thumb_file(dbp,f,28)
    if th.exists() and th.stat().st_size>100:
     key=(str(th),th.stat().st_mtime); ph=cache.get(key)
     if ph is None:
      try:ph=tk.PhotoImage(file=str(th)); cache[key]=ph
      except Exception:continue
     self.tree.item(iid,image=ph)
    elif str(th) not in failed:missing.append((dbp/'stok_gorselleri'/f,th))
   if missing and not getattr(self,'_thumb_busy',False):
    self._thumb_busy=True; self._thumb_done=False
    def work():
     try:ensure_list_thumbs(missing,28)
     except Exception as ex:
      try:log_error('Stok listesi küçük resim',ex)
      except Exception as _se:_silent(_se)
     finally:
      for _src,_th in missing:
       if not _th.exists():failed.add(str(_th))
      self._thumb_done=True
    _alf_th.Thread(target=work,daemon=True).start()
    self.after(400,self._stock_thumbs_poll)
  except Exception as ex:
   try:log_error('Stok listesi görselleri',ex)
   except Exception as _se:_silent(_se)
