  tk.Label(w,text='BOŞA ÇIKAN STOK KODLARI',font=('Segoe UI',16,'bold'),fg='#0b376d').pack(anchor='w',padx=16,pady=(14,4))
  tk.Label(w,text='Silinen stok kartlarının kodları burada tutulur. Bir kodu seçip yeni karta verebilirsiniz.',fg=MUT).pack(anchor='w',padx=16,pady=(0,10))
  t=ttk.Treeview(w,columns=('code','name','dt'),show='headings',selectmode='browse')
  for c,h,wd in [('code','Stok Kodu',130),('name','Eski Stok Adı',390),('dt','Silinme Tarihi',170)]:t.heading(c,text=h);t.column(c,width=wd,anchor='w')
  t.pack(fill='both',expand=True,padx=16,pady=4)
  rec={}
  for r in DX.rows("SELECT * FROM deleted_stock_codes WHERE reused_at IS NULL OR trim(reused_at)='' ORDER BY CASE WHEN trim(code) GLOB '[0-9]*' THEN CAST(code AS INTEGER) ELSE 999999999 END,code"):
   iid=str(r['id']);rec[iid]=r;t.insert('', 'end',iid=iid,values=(r['code'],r['old_name'] or '',r['deleted_at'] or ''))
  result={'value':None}
