  for row in c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"):
   table=row[0]
   if table in ('stock','stock_trash_log'):continue
   columns={x[1] for x in c.execute('PRAGMA table_info("'+table.replace('"','""')+'")')}
   if 'stock_id' not in columns:continue
   n=c.execute('SELECT COUNT(*) FROM "'+table.replace('"','""')+'" WHERE stock_id=?',(sid,)).fetchone()[0]
   if n:refs.append((table,n))
  return refs
