  def _name_suggest_setup():
   en=ents.get('name')
   if en is None:return
   try:_all=DX.rows('SELECT name,brand,model,grp,subgrp,origin FROM stock WHERE active=1 AND trim(COALESCE(name,\'\'))<>\'\' ORDER BY name COLLATE NOCASE')
   except Exception:return
   st={'win':None,'lb':None,'rows':[]}
   def close():
    sw=st['win']
    if sw is not None:
     try:sw.destroy()
     except Exception as _se:_silent(_se)
    st['win']=None;st['lb']=None;st['rows']=[]
   def pick(event=None):
    lb=st['lb']
    if lb is None:return 'break'
    sl=lb.curselection();k=sl[0] if sl else 0
    if k>=len(st['rows']):close();return 'break'
    row=st['rows'][k];close()
    en.delete(0,'end');en.insert(0,row['name']);en.icursor('end')
    if not sid:
     for key in ('brand','model','grp','subgrp','origin'):
      wd=ents.get(key)
      try:
       if wd is not None and not wd.get().strip() and str(row[key] or '').strip():wd.insert(0,str(row[key]).strip())
      except Exception as _se:_silent(_se)
    return 'break'
   def move(d):
    lb=st['lb']
    if lb is None or not lb.size():return None
    sl=lb.curselection();k=(sl[0]+d) if sl else (0 if d>0 else lb.size()-1);k=max(0,min(lb.size()-1,k))
    lb.selection_clear(0,'end');lb.selection_set(k);lb.see(k);return 'break'
   def show(matches):
    close()
    if not matches:return
    try:
     en.update_idletasks();sw=tk.Toplevel(en);sw.overrideredirect(True);sw.attributes('-topmost',True)
     x0=en.winfo_rootx();y0=en.winfo_rooty()+en.winfo_height();wd=max(en.winfo_width(),260);n=min(len(matches),8)
     sw.geometry(f'{wd}x{max(24,n*24+4)}+{x0}+{y0}');lb=tk.Listbox(sw,font=('Segoe UI',10),activestyle='dotbox',exportselection=False);lb.pack(fill='both',expand=True)
     for m_ in matches[:8]:lb.insert('end',m_['name'])
     lb.bind('<ButtonRelease-1>',pick);lb.bind('<Double-1>',pick);st['win']=sw;st['lb']=lb;st['rows']=matches[:8]
    except Exception:close()
   def on_key(event):
    if event.keysym in ('Up','Down','Left','Right','Return','Escape','Tab','Shift_L','Shift_R','Control_L','Control_R'):return
    q=_tr_fold(en.get().strip())
    if len(q)<2:close();return
    seen=set();res=[]
    for r_ in _all:
     nm=str(r_['name']);f_=_tr_fold(nm)
     if q in f_ and f_ not in seen and not (sid and f_==_tr_fold(str(r['name'] if r else ''))):seen.add(f_);res.append(r_)
    res.sort(key=lambda r_:(0 if _tr_fold(str(r_['name'])).startswith(q) else 1,_tr_fold(str(r_['name']))))
    show(res)
   def on_press(event):
    if event.keysym=='Escape' and st['lb'] is not None:close();return 'break'
    if event.keysym=='Down':return move(1)
    if event.keysym=='Up':return move(-1)
    if event.keysym=='Return' and st['lb'] is not None:
     if not st['lb'].curselection():st['lb'].selection_set(0)
     return pick()
   en.bind('<KeyRelease>',on_key,add='+');en.bind('<KeyPress>',on_press,add='+');en.bind('<FocusOut>',lambda ev:en.after(150,close),add='+')
