  def propose_price():
   margin=fnum(target_pct.get())
   if not 0<=margin<100:return messagebox.showwarning(APP,'Hedef kâr marjı 0 ile 100 arasında (100 hariç) olmalıdır.',parent=w)
   cost=fnum(ents['avg_cost'].get())
   if cost<=0:
    cost=fnum(ents['last_cost'].get())
