  def _u_stock_text(row):
   try:
    q=fnum(ents['qty'].get()) if 'qty' in ents else 0.0
   except Exception:q=0.0
   if row['main']:return f"{q:g} {str(ents['unit'].get() or 'adet').lower()}"
   f=fnum(row['factor'].get())
   if f<=0:return '-'
   whole=int(q//f) if q>=0 else 0;rem=round(q-whole*f,6)
   return f"{whole:g} {row['name'].get().strip().lower()}"+(f" + {rem:g} {str(ents['unit'].get() or 'adet').lower()}" if rem>1e-9 else '')
