  def _tax_values():
   """(değerler, hata) döndürür; hata varsa metin."""
   g=''.join(ch for ch in tax_vars['gtip'].get() if ch not in ' .-')
   if g and (not g.isdigit() or len(g)>12 or len(g)<4):return None,'GTİP yalnız rakamlardan oluşmalı ve 4-12 hane olmalıdır.'
   o=tax_vars['otv_rate'].get().strip().replace('%','').replace(',','.')
   try:ov=float(o) if o else 0.0
   except ValueError:return None,'ÖTV oranı sayı olmalıdır.'
   if ov<0 or ov>1000:return None,'ÖTV oranı 0 ile 1000 arasında olmalıdır.'
   u=tax_vars['einv_unit'].get().strip().split(' ')[0].upper()
   if u and (not u.isalnum() or len(u)>3):return None,'E-Fatura birim kodu en çok 3 karakterli olmalıdır (örn. C62).'
   return (g,ov,tax_vars['vat_exempt'].get().strip(),u),None
  def save(show_preview=False,new_after=False):
   d={k:e.get().strip() for k,e in ents.items()};d['origin']=_tr_upper(d.get('origin',''));
   _tax_vals,_tax_err=_tax_values()
   if _tax_err:
    nb.select(tabs['Vergi / E-Fatura']);return messagebox.showwarning(APP,_tax_err,parent=w)
