 def _stock_owner(self):
  try:
   if getattr(self,'stock_window',None) and self.stock_window.winfo_exists(): return self.stock_window
  except Exception: pass
  try:return self.master.winfo_toplevel()
  except Exception:return self
 def _restore_stock_focus(self):
  # Stok alt işlemi kapanınca Windows odağını kesin olarak Stok Merkezi'ne döndür.
  # Ana uygulama penceresinin öne geçmesini engeller.
  try:
   owner=self._stock_owner()
   if not owner.winfo_exists(): return
   owner.lift()
   owner.after(25, owner.lift)
   owner.after(50, owner.focus_force)
  except Exception as _se:_silent(_se)
 def _prepare_stock_child(self,w,allow_maximize=False):
  # Alt pencerenin sahibi daima Stok Merkezi'dir; ana pencere değildir.
  owner=self._stock_owner()
  try:
   if not allow_maximize: w.transient(owner)
   w.lift(owner)
   w.grab_set()
   w.focus_force()
  except Exception: pass
  def close_child():
   try: w.grab_release()
   except Exception: pass
   try: w.destroy()
   finally: self.after_idle(self._restore_stock_focus)
  w.protocol('WM_DELETE_WINDOW',close_child)
  return close_child
