 def counting(self):
  sid=self.selected_id()
  if not sid:return messagebox.showinfo(APP,'Sayım yapılacak ürünü stok listesinden seçin.',parent=self._stock_owner())
  owner=self._stock_owner(); owner.deiconify(); owner.lift(); owner.focus_force(); r=DX.one('SELECT * FROM stock WHERE id=?',(sid,))
  actual=simpledialog.askfloat('Stok Sayımı',f"{r['name']}\nSistem stoku: {float(r['qty'] or 0):g} {r['unit'] or 'Adet'}\n\nFiili sayım miktarı:",parent=owner)
  if actual is None:return
  oldq=float(r['qty'] or 0); diff=float(actual)-oldq
  if abs(diff)<0.000001:return messagebox.showinfo(APP,'Sayım farkı yok. Stok değiştirilmedi.',parent=owner); self.after_idle(self._restore_stock_focus)
  if not messagebox.askyesno('Sayım Farkı',f"Sistem: {oldq:g}\nFiili: {actual:g}\nFark: {diff:+g}\n\nFark stok hareketi olarak işlensin mi?",parent=owner):return
  c=DX.con()
  try:
   c.execute('BEGIN');c.execute('UPDATE stock SET qty=?,updated=? WHERE id=?',(actual,now(),sid));c.execute('INSERT INTO stock_moves(stock_id,dt,kind,qty,unit_cost,source,source_id,note) VALUES(?,?,?,?,?,?,?,?)',(sid,now(),'Sayım Farkı',diff,float(r['avg_cost'] or 0),'COUNT',sid,f'Sistem {oldq:g} / Fiili {actual:g}'));c.execute('INSERT INTO audit(dt,user,module,action,record_id,old_value,new_value,reason) VALUES(?,?,?,?,?,?,?,?)',(now(),'Yönetici','Stok','Sayım Kesinleştir',sid,str(oldq),str(actual),f'Fark {diff:+g}'));c.commit()
  except Exception as e:c.rollback();messagebox.showerror(APP,'Sayım kaydedilemedi:\n'+str(e),parent=owner); self.after_idle(self._restore_stock_focus);return
  finally:c.close()
  self.refresh();messagebox.showinfo(APP,'Sayım farkı stok hareketi olarak kaydedildi.',parent=owner); self.after_idle(self._restore_stock_focus)
