  def on_scan(*_):
   if not editable:return 'break'
   txt=scan.get();scan.set('')
   if not txt.strip():return 'break'
   try:dq=float(adet.get().strip().replace(',','.') or 1)
   except Exception:dq=1.0
   adet.set('1');q,code=SY.parse_scan(txt,dq);q=q*S.unit_factor(code)
   st,sid=S.resolve(code)
   if st=='multi':
    sid=choose(sid,'Bu barkod birden fazla üründe kayıtlı - seçin');st='ok' if sid else 'none'
    if not sid:entry.focus_set();return 'break'
   if st=='ok':
    if mode_v.get()=='Miktar sor':
     c=S.catalog[sid];l=S.lines.get(sid);v=ask_qty(c['name'],l['system_qty'] if l else c['qty'],l['actual_qty'] if l else q)
     if v is not None:do_count(sid,v,'set')
    else:do_count(sid,q)
   else:
    cands=S.search_name(code) if (re.search(r'[A-Za-zÇĞİÖŞÜçğıöşü]',code) and len(code)>=2) else []
    if cands:
     sid=choose(cands,'Ada göre bulundu - seçin')
     if sid:do_count(sid,q)
    else:unknown(code,q)
   entry.focus_set();return 'break'
