   def audit(con,action,rid,old,new,rs):con.execute('INSERT INTO audit(dt,user,module,action,record_id,old_value,new_value,reason) VALUES(?,?,?,?,?,?,?,?)',(now(),current_user(),'Stok',action,rid,old,new,rs))
