  _PRICE_PRESELECT=ids
  top=self.winfo_toplevel()
  if hasattr(top,'show'):top.show('Fiyat Yönetimi')
  else:messagebox.showinfo('Toplu Fiyat','Fiyat Yönetimi ekranını açın.')
