      old={'min_qty':float(live_s['min_qty'] or 0),'max_qty':float(live_s['max_qty'] or 0)};new={'min_qty':mn,'max_qty':mx};con.execute('UPDATE stock SET min_qty=?,max_qty=?,updated=? WHERE id=?',(mn,mx,now(),x['sid']));action='Min/Max Düzeltme'
