  tk.Label(w,text='STOK MALİYET VE TEDARİKÇİ ANALİZİ',font=('Segoe UI',18,'bold'),fg='#0b376d').pack(anchor='w',padx=18,pady=(14,2));tk.Label(w,text='Alış geçmişi, ağırlıklı maliyet, tedarikçi karşılaştırması, fiyat artışı ve hedef kâr önerisi',fg=MUT).pack(anchor='w',padx=18,pady=(0,8))
  target=tk.StringVar(value='30');flt=tk.StringVar(value='Tümü');q=tk.StringVar();controls=tk.Frame(w,bg='white',highlightbackground=BORDER,highlightthickness=1);controls.pack(fill='x',padx=18,pady=(0,8));tk.Label(controls,text='Hedef brüt kâr %:',bg='white',font=('Segoe UI',9,'bold')).pack(side='left',padx=(10,3),pady=8);tk.Entry(controls,textvariable=target,width=8,bg='#fff7a8').pack(side='left');tk.Label(controls,text='Göster:',bg='white',font=('Segoe UI',9,'bold')).pack(side='left',padx=(14,3));ttk.Combobox(controls,textvariable=flt,values=['Tümü','Fiyatı Yükselen','Maliyet Altı','Maliyeti Eksik','Birden Fazla Tedarikçi'],state='readonly',width=22).pack(side='left');tk.Label(controls,text='Ara:',bg='white',font=('Segoe UI',9,'bold')).pack(side='left',padx=(14,3));tk.Entry(controls,textvariable=q,bg='#fff7a8').pack(side='left',fill='x',expand=True,padx=(0,10))
  stocks=DX.rows('SELECT * FROM stock WHERE active=1 ORDER BY name');history=DX.rows("""SELECT sph.*,c.title supplier,p.status purchase_status FROM supplier_price_history sph LEFT JOIN caris c ON c.id=sph.supplier_id LEFT JOIN purchases p ON p.id=sph.purchase_id WHERE COALESCE(p.status,'Kesinleşti')!='İade' ORDER BY sph.stock_id,sph.dt,sph.id""");purchase_lines=DX.rows("""SELECT pl.*,p.dt,p.supplier_id,c.title supplier,p.status FROM purchase_lines pl JOIN purchases p ON p.id=pl.purchase_id LEFT JOIN caris c ON c.id=p.supplier_id WHERE p.status='Kesinleşti' ORDER BY p.dt,p.id""")
  hist_by={};lines_by={}
  for r in history:hist_by.setdefault(int(r['stock_id']),[]).append(r)
  for r in purchase_lines:lines_by.setdefault(int(r['stock_id']),[]).append(r)
  cards=tk.Frame(w,bg=BG);cards.pack(fill='x',padx=14,pady=5);stock_value=sum(float(s['qty'] or 0)*float(s['avg_cost'] or 0) for s in stocks);below=sum(1 for s in stocks if float(s['retail'] or 0)>0 and float(s['avg_cost'] or 0)>float(s['retail'] or 0));rising=sum(1 for sid,hs in hist_by.items() if len(hs)>1 and float(hs[-1]['cost'] or 0)>float(hs[-2]['cost'] or 0)+.0001)
  for title,value,color in [('STOK DEĞERİ',money(stock_value),'#0b376d'),('AKTİF ÜRÜN',len(stocks),TXT),('ALIŞ FİYAT KAYDI',len(history),'#166534'),('FİYATI YÜKSELEN',rising,'#b45309'),('MALİYET ALTI',below,RED)]:
   b=tk.Frame(cards,bg='white',highlightbackground=BORDER,highlightthickness=1);b.pack(side='left',fill='x',expand=True,padx=4);tk.Label(b,text=title,bg='white',fg=MUT,font=('Segoe UI',8,'bold')).pack(anchor='w',padx=12,pady=(8,1));tk.Label(b,text=str(value),bg='white',fg=color,font=('Segoe UI',14,'bold')).pack(anchor='w',padx=12,pady=(0,8))
  nb=ttk.Notebook(w);nb.pack(fill='both',expand=True,padx=18,pady=6);tab1=tk.Frame(nb);tab2=tk.Frame(nb);nb.add(tab1,text=' ÜRÜN MALİYETLERİ ');nb.add(tab2,text=' MARKA / GRUP / TEDARİKÇİ ÖZETİ ')
  t=ttk.Treeview(tab1,columns=('barcode','name','brand','group','qty','value','avg','last','purchase_avg','best','supplier','change','retail','margin','suggested'),show='headings',selectmode='browse')
