    tag='urgent' if float(s['qty'] or 0)<0 or (x['days'] is not None and x['days']<=3) else 'soon' if x['days'] is not None and x['days']<=7 else 'nosupplier' if x['suggest']>0 and x['supplier_id'] is None else 'slow' if x['daily']<=0 else ''
    t.insert('','end',iid=str(sid),values=(s['barcode'] or '',s['name'],s['brand'] or '',f"{float(s['qty'] or 0):g}",f"{x['q7']:g}",f"{x['q30']:g}",f"{x['q90']:g}",f"{x['daily']:.2f}",f"{x['days']:.1f}" if x['days'] is not None else '—',f"{float(s['min_qty'] or 0):g} / {float(s['max_qty'] or 0):g}",f"{x['suggest']:.0f}",f"{x['approved']:.0f}",x['supplier'],money(x['cost']),money(x['approved']*x['cost']),x['reason']),tags=(tag,) if tag else ());shown.append(x)
