  tk.Label(logo,text='K',bg='#eaf5ff',fg='#1767ad',font=('Segoe UI',26,'bold')).pack(side='left')
  tk.Label(brand,text='ALFABE KIRTASİYE',bg='#eaf5ff',fg='#e51d2a',font=('Segoe UI',11,'bold')).pack(anchor='w')
  title=tk.Frame(head,bg='#eaf5ff');title.pack(side='left',fill='both',expand=True,padx=8,pady=7)
  tk.Label(title,text='Hızlı / Perakende Satış',bg='#eaf5ff',fg=INK,font=('Segoe UI',20,'bold')).pack(anchor='w',pady=(3,0))
  tk.Label(title,text='Hızlı  •  Güvenilir  •  Kolay Kullanım',bg='#eaf5ff',fg='#55789c',font=('Segoe UI',10,'bold')).pack(anchor='w',pady=(3,0))
  actions=tk.Frame(head,bg='#eaf5ff');actions.pack(side='right',padx=8,pady=6)
  action_defs=[('▣\nF10\nKaydet',self.pay,'white',INK),('▣\nF11\nKaydet ve Yeni',lambda:self.pay('new'),'white',INK),('▣\nF3\nKaydet ve Yazdır',lambda:self.pay('print'),'white','#0759aa'),('✕\nESC\nİptal Et ve Kapat',self.cancel_and_close,'#fff0f4','#e21d2f'),('▣\nF12\nKaydet ve Kapat',lambda:self.pay('close'),'white',INK)]
  for text,cmd,bg,fg in action_defs:
   tk.Button(actions,text=text,command=cmd,bg=bg,fg=fg,activebackground='#e9f3fb',relief='solid',bd=1,font=('Segoe UI',9,'bold'),width=17,height=3,cursor='hand2').pack(side='left',padx=4)
  # Satış bilgisi + sarı barkod alanı + miktar/birim + toplam
  top=tk.Frame(self,bg=PALE,highlightthickness=1,highlightbackground=LINE);top.pack(fill='x',padx=10,pady=5)
  info=tk.Frame(top,bg=PALE,width=275,height=92);info.pack(side='left',fill='y',padx=(10,8),pady=8);info.pack_propagate(False)
  for lab,val in [('Satış No','—'),('Tarih',datetime.date.today().strftime('%d.%m.%Y')),('Kasiyer',current_user())]:
   r=tk.Frame(info,bg=PALE,height=30);r.pack(fill='x',pady=3);r.pack_propagate(False)
