  tk.Label(searchrow,text='▥',bg='white',fg=INK,font=('Segoe UI',25,'bold'),width=3).pack(side='left')
  self.search_entry=tk.Entry(searchrow,textvariable=self.search,font=('Segoe UI',18),bg='white',fg='#26384a',insertbackground='black',relief='flat',bd=0);self.search_entry.pack(side='left',fill='both',expand=True,ipady=9,padx=(3,8));self.search_entry.bind('<Return>',lambda e:self.add());self.search_entry.bind('<KP_Enter>',lambda e:self.add())
  self.quick_stock_status=tk.Label(searchcard,text='',bg='#fff0a8',fg='#d0182b',font=('Segoe UI',12,'bold'),anchor='w')
