  tk.Label(controls,text='Miktar',bg=PALE,fg=INK,font=('Segoe UI',10,'bold')).grid(row=0,column=0,sticky='w');tk.Label(controls,text='Birim',bg=PALE,fg=INK,font=('Segoe UI',10,'bold')).grid(row=0,column=1,sticky='w',padx=(10,0))
  # v1.2.291.194: Yalnizca Hizli Satis ust miktar alani - buyuk yazi ve kolay tuslar.
  qty_box=tk.Frame(controls,bg=PALE)
