  self.last_name=tk.Label(last,text='BARKOD OKUTUN / ÜRÜN EKLEYİN',bg='#0e2a52',fg='white',font=('Segoe UI',18,'bold'),anchor='w',padx=18);self.last_name.pack(side='left',fill='both',expand=True)
  self.last_price=tk.Label(last,text='0,00',bg='#0e2a52',fg='#fff200',font=('Segoe UI',24,'bold'),anchor='e',padx=22);self.last_price.pack(side='right',fill='y')
  # Sepet ve favoriler
  content=tk.Frame(self,bg='#f4f9fd');content.pack(fill='both',expand=True,padx=10)
