  _pw=(360 if self.winfo_screenwidth()>=1500 else 300) if self._fav_on else 200
  self.fav_side=tk.Frame(content,bg='white',width=_pw,highlightthickness=1,highlightbackground=LINE);self.fav_side.pack(side='right',fill='y',padx=(10,0));self.fav_side.pack_propagate(False)
  center.pack(side='left',fill='both',expand=True)
