 def liste_fiyat(self):
  import ALFABE_LISTE_FIYAT as _LF
  top=self.winfo_toplevel()
  def xl(title,heads,rows,total):
   return choose_report_export(top,title,heads,rows,total,'LISTE_FIYATLA')
  def pdf(html_text,name):
   t=filedialog.asksaveasfilename(parent=top,title='PDF olarak kaydet',defaultextension='.pdf',initialfile=name+'.pdf',filetypes=[('PDF','*.pdf')])
   if not t:return ''
   edge=_edge_path()
   if not edge:raise RuntimeError('Microsoft Edge PDF motoru bulunamadı. Bunun yerine YAZDIR düğmesini kullanıp "PDF olarak yazdır" seçebilirsiniz.')
   src=Path(tempfile.gettempdir())/('alfabe_liste_fiyat_%d.html'%os.getpid());src.write_text(alf_firma_baslik_ekle(html_text),encoding='utf-8')
   dest=Path(t).resolve()
   try:
    import ALFABE_EDGE_SERVIS as _ES
    _ES.servis(edge).pdf(src,dest)
    try:src.unlink()
    except Exception as _se:_silent(_se)
    if dest.exists() and dest.stat().st_size>100:return str(dest)
   except Exception as _e:
    try:log_error('Liste Fiyatla PDF hızlı servis (eski yöntem)',_e)
    except Exception as _se:_silent(_se)
   r=subprocess.run([str(edge),'--headless','--disable-gpu','--no-pdf-header-footer',f'--print-to-pdf={dest}',src.resolve().as_uri()],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=90,creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
   try:src.unlink()
   except Exception as _se:_silent(_se)
   if r.returncode!=0 or not dest.exists() or dest.stat().st_size<100:raise RuntimeError('PDF oluşturulamadı: '+r.stderr.decode(errors='ignore')[-200:])
   return str(dest)
  def sug(kind):
   try:_alf_oneri(CZ.printer_for(kind) or '')
   except Exception as _se:_silent(_se)
  def render(key,heads,rows,total,period,pap):
   # Rapor Motoru: kayıtlı Rapor Düzenleyici tasarımı varsa o, yoksa kâğıda uygun varsayılan tasarım kullanılır.
   import copy as _copy
   ov=False
   d=report_design_get(key,heads)
   if pap.get('kind')!='a4' and not d.get('_has_saved'):
    d=_copy.deepcopy(d);d.update({'paper':'80 mm','orientation':'Dikey','margin':3,'font_size':8,'signatures':'','show_page_no':0,'title':str(key).split(' / ')[-1].replace(' - Fiş','')})
    for c_ in d.get('columns',[]):c_['width']=190 if str(c_.get('name')) in ('Ürün','Liste satırı') else (62 if str(c_.get('name'))=='Adet' else 100)
    d['header_size']=12
    _REPORT_DESIGN_PREVIEW_OVERRIDE[key]=d;ov=True
   try:h=report_html_document(key,heads,rows,period,total)
   finally:
    if ov:_REPORT_DESIGN_PREVIEW_OVERRIDE.pop(key,None)
   if pap.get('kind')!='a4':
    sz='%gmm %gmm'%(pap['w'],pap['h'])
    h=re.sub(r'(@page\s*\{\s*size:)[^;}]*',lambda m:m.group(1)+sz,h,count=1)
    h=h.replace('</head>','<style>td,th{white-space:normal!important;text-overflow:clip!important;overflow:visible!important;word-break:break-word}</style></head>',1)
    if pap.get('kind') in ('fis','barkod'):h=_alf_fis_sigdir(h,float(pap.get('w') or 80))      # fiş/etiket yazıcıda kâğıt boyu içeriğe göre ölçülür: alt/yan kesilme olmaz
   return h
  def designer(key,heads,rows,on_close):
   win=open_report_designer(top,key,heads,None,rows)
   try:win.bind('<Destroy>',lambda e:on_close() if e.widget is win else None,add='+')
   except Exception as _se:_silent(_se)
   return win
