 def add_school_items(self,items):
  # items: [(stock_id, adet)] — her ürün favori ekleme yolundan geçer (stok uyarısı, birleştirme, fiyat tipi korunur).
  n=0
  for it in items:
   sid,q=it[0],it[1]; fix=it[2] if len(it)>2 else None
   before={id(x):x.get('qty',0) for x in self.cart}; cnt=len(self.cart)
   self.add_favorite_to_cart(sid)
   line=None
   for x in self.cart:
    if id(x) not in before or x.get('qty',0)!=before[id(x)]: line=x
   if line is not None and fix is not None: line['price']=float(fix)
   if line is not None and q>1:
    line['qty']=float(line.get('qty',0))+float(q)-1
    n+=1
   elif line is not None: n+=1
  self.render()
 def add_favorite_to_cart(self,stock_id):
  r=DX.one('SELECT * FROM stock WHERE id=? AND active=1',(stock_id,))
  if not r:return messagebox.showwarning(APP,'Favori ürün stokta bulunamadı.',parent=self)
  if not self._warn_out_of_stock(r,1.0):return
  _m=self._cart_merge(r,1.0)
  if _m is not None:
   self._set_last_scanned(_m); self.render(); return
  self.cart.append({'id':r['id'],'barcode':r['barcode'] or '','code':r['code'] or '','name':r['name'],'qty':1.0,'unit':r['unit'] or 'Adet','price':float(r['retail'] or 0),'disc':0.0,'camp':'','camp_disc':0.0,'cost':sale_cost(r),'vat':float(r['vat'] or 0),'vat_included':True,'note':''}); self._set_last_scanned(self.cart[-1]); self.render()
