  for c,h,wd in cols:t.heading(c,text=h);t.column(c,width=wd,anchor='w' if c=='name' else 'e')
  t.tag_configure('acil',foreground='#b00020');t.tag_configure('yakin',foreground='#b36b00')
  def load():
   t.delete(*t.get_children())
   try:
    rows=DX.rows("SELECT st.id sid,st.name nm,st.qty stk,st.retail pr,SUM(CASE WHEN substr(s.dt,1,10)>=date('now','localtime','-6 day') THEN sl.qty ELSE 0 END) q7,SUM(CASE WHEN substr(s.dt,1,10)=date('now','localtime') THEN sl.qty ELSE 0 END) q1,SUM(CASE WHEN substr(s.dt,1,10)<date('now','localtime','-6 day') THEN sl.qty ELSE 0 END) qp FROM sale_lines sl JOIN sales s ON s.id=sl.sale_id JOIN stock st ON st.id=sl.stock_id WHERE s.status IN ('FINAL','RETURN') AND substr(s.dt,1,10)>=date('now','localtime','-13 day') AND st.active=1 GROUP BY st.id")
   except Exception as e:
    _silent(e);rows=[]
   items=[]
   for r in rows:
    q7=float(r['q7'] or 0);qp=float(r['qp'] or 0);stk=float(r['stk'] or 0)
    if q7<=0:continue
    if mode.get()=='Yükselenler' and q7<=qp:continue
    gun=(stk/(q7/7.0)) if stk>0 else 0
    items.append((q7-qp if mode.get()=='Yükselenler' else q7,r,q7,qp,stk,gun))
   items.sort(key=lambda z:-z[0])
   for _k,r,q7,qp,stk,gun in items[:100]:
    tag=('acil',) if gun<3 else (('yakin',) if gun<7 else ())
    t.insert('','end',iid=str(r['sid']),values=(r['nm'],qty_display(r['q1']),qty_display(q7),qty_display(qp),qty_display(stk),('BİTTİ' if stk<=0 else f'{gun:.1f}'.replace('.',',')),money(r['pr'])),tags=tag)
   info.config(text=f'{min(len(items),100)} ürün  •  çift tık: sepete ekle')
