 def _camp_one(self,c,taken):
  """Tek kampanyayı sepete uygular (sepete yazmaz): {satır_no: (indirim, kampanya adı)}. taken: başka kampanyaya ait satırlar."""
  out={}
  targets=DX.rows('SELECT target_type,target_value,stock_id FROM campaign_targets WHERE campaign_id=?',(c['id'],))
  eligible=[]
  for i,x in enumerate(self.cart):
   if not x.get('id') or i in taken:continue
   st=DX.one('SELECT * FROM stock WHERE id=?',(x['id'],)); typ=c['scope_type'] or 'Tümü'; sv=str(c['scope_value'] or '').lower(); ok=(typ=='Tümü')
   if targets:
    ok=False
    for t in targets:
     tt=str(t['target_type'] or '')
     if t['stock_id'] and int(t['stock_id'])==int(x['id']):ok=True;break
     tv=str(t['target_value'] or '').lower()
     if tt=='Marka' and tv==str(st['brand'] or '').lower():ok=True;break
     if tt=='Grup' and tv==str(st['grp'] or '').lower():ok=True;break
   elif typ=='Barkod':ok=str(st['barcode'] or '')==str(c['scope_value'] or '')
   elif typ=='Stok Kodu':ok=str(st['code'] or '')==str(c['scope_value'] or '')
   elif typ=='Ürün':ok=sv in str(st['name'] or '').lower()
   elif typ=='Marka':ok=sv in str(st['brand'] or '').lower()
   elif typ=='Grup':ok=sv in str(st['grp'] or '').lower()
   if ok:eligible.append((i,x))
  if not eligible:return out
  kind=c['kind']
  if kind in ('2 Al 1 Öde','3 Al 2 Öde','X Al Y Öde') and float(c['buy_qty'] or 0)>0:
   buy=int(float(c['buy_qty'])); pay=int(float(c['pay_qty'] or 0)); free_per=max(0,buy-pay)
   units=[]
   for i,x in eligible:
    whole=int(float(x['qty'] or 0))
    units += [(float(x['price']),i)]*whole
   groups=len(units)//buy; free_count=groups*free_per
   # Fiyatlar farklıysa kampanya grubundaki en ucuz birimler ücretsiz olur.
   for price,i in sorted(units,key=lambda z:z[0])[:free_count]:
    out[i]=(out.get(i,(0.0,''))[0]+price,c['name'])
  else:
   for i,x in eligible:
    q=float(x['qty']);pr=float(x['price']);base=q*pr;disc=0
    if kind=='% İndirim':disc=max(0,base*float(c['value'] or 0)/100)
    elif kind=='TL İndirim':disc=min(base,float(c['value'] or 0))
    elif kind=='Sabit Fiyat' and float(c['fixed_price'] or 0)>0:disc=max(0,base-q*float(c['fixed_price']))
    if disc>0:out[i]=(disc,c['name'])
  return out
 def apply_campaigns(self):
  # v1.2.291.452: Çakışma yöntemi ve zararına kampanya kuralı Ayarlar > Kampanya'dan okunur.
  td=today(); camps=DX.rows("SELECT * FROM campaigns WHERE active=1 AND (start_date IS NULL OR start_date='' OR start_date<=?) AND (end_date IS NULL OR end_date='' OR end_date>=?) ORDER BY priority,id",(td,td))
  for x in self.cart:x['camp']='';x['camp_disc']=0.0;x['_camp_loss']=False
  mode=ayar('campaign_conflict')
  if mode=='Son Kampanya':camps=list(reversed(camps))
  if mode=='En Avantajlı':
   best={}
   for c in camps:
    for i,(d,nm) in self._camp_one(c,set()).items():
     if d>best.get(i,(0.0,''))[0]+1e-9:best[i]=(d,nm)
   for i,(d,nm) in best.items():self.cart[i]['camp']=nm;self.cart[i]['camp_disc']=d
  else:
   taken=set()
   for c in camps:
    for i,(d,nm) in self._camp_one(c,taken).items():
     self.cart[i]['camp']=nm;self.cart[i]['camp_disc']=d;taken.add(i)
  pol=ayar_izin('campaign_loss')
  if pol!='izin':
   for x in self.cart:
    if not x.get('id') or float(x.get('camp_disc',0) or 0)<=0:continue
    cost=float(x.get('cost') or 0);qty=float(x.get('qty') or 0)
    if cost<=0 or qty<=0:continue
    lt=qty*float(x.get('price') or 0)-float(x.get('disc',0) or 0)-float(x.get('camp_disc',0) or 0)
    if lt<=0:continue   # bedelsiz (X Al Y Öde) satırı zarar sayılmaz
    vp=float(x.get('vat',0) or 0)
    if lt/(1+vp/100.0)/qty<cost-0.005:
     if pol=='engelle':x['camp']='';x['camp_disc']=0.0
     else:x['_camp_loss']=True
 def totals(self):
  gross=sum(x['qty']*x['price'] for x in self.cart); disc=sum(x.get('disc',0) for x in self.cart); camp=sum(x.get('camp_disc',0) for x in self.cart); return gross,disc,camp,max(0,gross-disc-camp)
 @staticmethod
 def _tier_price(srow,tier):
  # Müşteri fiyat tipine göre birim fiyat; ilgili fiyat tanımsızsa perakendeye düşer.
  try:
   ret=float(srow['retail'] or 0)
   if tier=='Toptan': v=float(srow['wholesale'] or 0)
   elif tier=='Özel': v=float(srow['special_price'] or 0)
   else: v=ret
   return v if v>0 else ret
  except Exception: return 0.0
 def _customer_tier(self):
  try:
   if not self.customer_id: return 'Perakende'
   r=DX.one('SELECT price_tier FROM caris WHERE id=?',(self.customer_id,))
   t=str(r['price_tier'] or 'Perakende') if r else 'Perakende'
   if t=='Toptan' and not ayar_evet('use_wholesale'):return 'Perakende'
   if t=='Özel' and not ayar_evet('use_special_price'):return 'Perakende'
   return t if t in ('Toptan','Özel') else 'Perakende'
  except Exception: return 'Perakende'
 def _tier_sync(self):
  # Sepetteki elle fiyatlanmamış satırları müşterinin fiyat tipine göre günceller (tekrar çalışması zararsız).
  try:
   tier=self._customer_tier()
   for x in self.cart:
    if not x.get('id') or x.get('_alfabe_special_price') or x.get('service_id'): continue
    if x.get('_tier_applied','Perakende')==tier: continue
    st=DX.one('SELECT retail,wholesale,special_price FROM stock WHERE id=?',(x['id'],))
    if st:
     _z=unit_row(x['id'],x.get('_uname')) if abs(float(x.get('_ufac',1.0) or 1.0)-1.0)>1e-9 else None
     x['price']=unit_base_price(st,_z,tier) if _z is not None else self._tier_price(st,tier)
    x['_tier_applied']=tier
  except Exception as ex: log_error('Hızlı Satış fiyat tipi',ex)
 def render(self):
  self._tier_sync()
  self.after_idle(self._hl);self.after_idle(self._ubar_refresh)
  self.apply_campaigns()
  self.tree.delete(*self.tree.get_children())
  for i,x in enumerate(self.cart):
   net=max(0,x['price']-(x.get('disc',0)+x.get('camp_disc',0))/max(float(x['qty']),0.000001)); total=max(0,x['qty']*x['price']-x.get('disc',0)-x.get('camp_disc',0)); self.tree.insert('', 'end',iid=str(i),values=(x['barcode'],x.get('code',''),x['name'],f"{x['qty']:g}",x.get('unit','Adet'),money(x['price']),money(x.get('disc',0)),x.get('camp',''),money(net),f"%{float(x.get('vat',0)):g}",'☑' if x.get('vat_included',True) else '☐',x.get('note',''),money(total)))
  _as=getattr(self,'_auto_sel',None);self._auto_sel=None
  if _as is not None:
   try:
    for _i,_x in enumerate(self.cart):
     if _x is _as:
      self.tree.selection_set(str(_i));self.tree.focus(str(_i));self.tree.see(str(_i));break
   except Exception as _se:_silent(_se)
  g,d,c,t=self.totals()
  self._customer_display_update()
  try:
   kdv=0.0
   for _x in self.cart:
    _t=max(0,_x['qty']*_x['price']-_x.get('disc',0)-_x.get('camp_disc',0));_v=float(_x.get('vat',0) or 0)
    kdv+=(_t*_v/(100+_v)) if _x.get('vat_included',True) else (_t*_v/100)
   self.sum_labels['count'].config(text=f"{len(self.cart)} kalem / {sum(float(_x['qty']) for _x in self.cart):g} adet");self.sum_labels['vat'].config(text=money(kdv))
  except Exception as _se:_silent(_se)
  # Boş sepette bant sakin lacivert; ürün varsa yeşil (kırmızı yalnız uyarı için).
  try:
   if not self.cart:self._band('#0e2a52','BARKOD OKUTUN / ÜRÜN EKLEYİN','0,00')
  except Exception as _se:_silent(_se)
  self.sum_labels['gross'].config(text=money(g)); self.sum_labels['discount'].config(text=money(d)); self.sum_labels['campaign'].config(text=money(c)); self.top_total.config(text=money(t))
 # v1.2.291.456: Seçili satırda yalnızca Ürün Adı hücresi mavi; sağ tık = ürün bilgi penceresi.
 def _hl_setup(self):
  t=self.tree
  self._hl_lbl=tk.Label(t,bg='#1f6fd6',fg='#ffffff',font=('Segoe UI',14),anchor='w',padx=6,bd=0,cursor='arrow')
  def fwd(seq,btn):
   def f(e):
    l=self._hl_lbl
    try:
     t.focus_set();t.event_generate(seq,x=e.x+l.winfo_x(),y=e.y+l.winfo_y(),button=btn)
    except tk.TclError:pass
    return 'break'
   return f
  for seq,b in (('<Button-1>',1),('<ButtonRelease-1>',1),('<Double-1>',1),('<Button-3>',3)):self._hl_lbl.bind(seq,fwd(seq,b))
  for seq in ('<<TreeviewSelect>>','<Configure>','<MouseWheel>','<ButtonRelease-1>','<KeyRelease>','<Map>'):t.bind(seq,lambda e:self.after_idle(self._hl),add='+')
  t.bind('<Button-3>',self._row_info_click)
  t.bind('<Control-i>',lambda e:(self._item_info(),'break')[1]);t.bind('<Control-I>',lambda e:(self._item_info(),'break')[1])
 def _hl(self):
  try:
   t=self.tree;l=self._hl_lbl
   sel=t.selection()
   if not sel or not t.exists(sel[0]):l.place_forget();return
   disp=list(t.cget('displaycolumns'))
   if disp==['#all']:disp=list(t.cget('columns'))
   if 'name' not in disp:l.place_forget();return
   box=t.bbox(sel[0],'name')
   if not box:l.place_forget();return
   x,y,w,h=box
   l.configure(text=str(t.set(sel[0],'name')),font=ttk.Style(t).lookup(t.cget('style') or 'Treeview','font') or ('Segoe UI',14))
   l.place(x=x,y=y,width=w,height=h);l.lift()
  except tk.TclError:pass
  except Exception as _se:_silent(_se)
 def _row_info_click(self,e):
  t=self.tree
  if t.identify_region(e.x,e.y)=='heading':return None   # başlıkta genel tablo menüsü çalışsın
  row=t.identify_row(e.y)
  if not row:return 'break'
  t.selection_set(row);t.focus(row);self._hl()
  self._item_info();return 'break'
 def _item_info(self):
  try:self._hide_live_search()
  except Exception as _se:_silent(_se)
  i=self._selected_cart_index()
