 def discount(self):
  if not self.cart:return messagebox.showinfo(APP,'Sepet boş.',parent=self.winfo_toplevel())
  sel_idx=[]
  try:sel_idx=sorted(int(i) for i in self.tree.selection() if 0<=int(i)<len(self.cart))
  except Exception:sel_idx=[]
  w=new_toplevel(self); w.title('İskonto Uygulama Seçenekleri'); w.geometry('560x520'); w.resizable(False,False); w.transient(self.winfo_toplevel()); w.grab_set()
  body=tk.Frame(w,bg='#eaf2ff',padx=14,pady=12); body.pack(fill='both',expand=True)
  tk.Label(body,text='İSKONTO UYGULAMA SEÇENEKLERİ',bg='#eaf2ff',fg=TXT,font=('Segoe UI',14,'bold')).pack(anchor='w',pady=(0,10))
  scope=tk.StringVar(value='sel' if sel_idx else 'all')
  sf=tk.LabelFrame(body,text='İskonto nereye uygulansın?',bg='#eaf2ff',fg=TXT,font=('Segoe UI',10,'bold'),padx=10,pady=6); sf.pack(fill='x',pady=(0,8))
  _nm=(str(self.cart[sel_idx[0]].get('name',''))[:40] if len(sel_idx)==1 else '%d seçili satır'%len(sel_idx)) if sel_idx else 'önce sepette bir satır seçin'
  tk.Radiobutton(sf,text='Yalnız seçili ürüne: '+_nm,variable=scope,value='sel',bg='#eaf2ff',anchor='w',state=('normal' if sel_idx else 'disabled'),command=lambda:refresh_summary()).pack(fill='x')
  tk.Radiobutton(sf,text='Tüm sepete (bütün satırlara paylaştır)',variable=scope,value='all',bg='#eaf2ff',anchor='w',command=lambda:refresh_summary()).pack(fill='x')
  pct=tk.LabelFrame(body,text='% Olarak İskonto Uygula',bg='#eaf2ff',fg=TXT,font=('Segoe UI',10,'bold'),padx=10,pady=10); pct.pack(fill='x')
  row=tk.Frame(pct,bg='#eaf2ff'); row.pack(fill='x')
  pvars=[]
  for i in range(3):
   f=tk.Frame(row,bg='#eaf2ff'); f.pack(side='left',padx=(0,10)); tk.Label(f,text=f'İskonto {i+1} %',bg='#eaf2ff').pack(anchor='w'); v=tk.DoubleVar(value=0); pvars.append(v); tk.Spinbox(f,from_=0,to=100,increment=.5,textvariable=v,width=9,justify='right').pack()
  def scope_idx():
   return list(sel_idx) if (scope.get()=='sel' and sel_idx) else list(range(len(self.cart)))
  def available_total():
   return sum(max(0,float(self.cart[i]['qty'])*float(self.cart[i]['price'])-float(self.cart[i].get('camp_disc',0))) for i in scope_idx())
  def apply_total_discount(amount):
   base=available_total(); amount=max(0,min(float(amount),base))
   remaining=round(amount,2); ids=scope_idx()
   bases={i:max(0,float(self.cart[i]['qty'])*float(self.cart[i]['price'])-float(self.cart[i].get('camp_disc',0))) for i in ids}
   positive=[i for i in ids if bases[i]>0]
   for i in ids:self.cart[i]['disc']=0.0
   for pos,i in enumerate(positive):
    d=remaining if pos==len(positive)-1 else round(amount*bases[i]/base,2)
    d=max(0,min(d,bases[i])); self.cart[i]['disc']=d; remaining=round(remaining-d,2)
   self.render(); refresh_summary()
   try:
    for i in sel_idx:self.tree.selection_add(str(i))
   except Exception as _se:_silent(_se)
  def apply_pct():
   try:
    ps=[max(0,min(100,float(v.get() or 0))) for v in pvars]; factor=1.0
    for p in ps:factor*=1-p/100.0
    apply_total_discount(available_total()*(1-factor))
   except Exception:messagebox.showerror(APP,'İskonto yüzdelerini kontrol edin.',parent=self)
  btns=tk.Frame(pct,bg='#eaf2ff'); btns.pack(fill='x',pady=(10,0))
  tk.Button(btns,text='İskonto Yok',command=lambda:apply_total_discount(0),width=14).pack(side='left')
  tk.Button(btns,text='Girilen % Uygula',command=apply_pct,width=18).pack(side='right')
  amt=tk.LabelFrame(body,text='Girilen tutar kadar iskonto uygula',bg='#eaf2ff',fg=TXT,font=('Segoe UI',10,'bold'),padx=10,pady=10); amt.pack(fill='x',pady=10)
  av=tk.StringVar(value='0,00'); tk.Label(amt,text='İskonto tutarını giriniz',bg='#eaf2ff').pack(side='left'); tk.Entry(amt,textvariable=av,width=15,justify='right',font=('Segoe UI',11)).pack(side='left',padx=12); tk.Button(amt,text='Uygula',command=lambda:apply_amount(),width=12).pack(side='right')
  target=tk.LabelFrame(body,text='Girilen toplam tutara göre iskonto uygula',bg='#eaf2ff',fg=TXT,font=('Segoe UI',10,'bold'),padx=10,pady=10); target.pack(fill='x')
  cur=tk.StringVar(); tv=tk.StringVar(value='0,00'); tk.Label(target,text='Şu andaki tutar (seçime göre)',bg='#eaf2ff').grid(row=0,column=0,sticky='w',pady=3); tk.Label(target,textvariable=cur,bg='white',font=('Segoe UI',12,'bold'),width=15,anchor='e').grid(row=0,column=1,padx=12); tk.Label(target,text='İskontolu Toplam Tutar',bg='#eaf2ff').grid(row=1,column=0,sticky='w',pady=3); tk.Entry(target,textvariable=tv,width=15,justify='right',font=('Segoe UI',11)).grid(row=1,column=1,padx=12); tk.Button(target,text='Uygula',command=lambda:apply_target(),width=12).grid(row=1,column=2,padx=(8,0))
  def num(v):return float(str(v).strip().replace('.','').replace(',','.')) if ',' in str(v) else float(str(v).strip() or 0)
  def apply_amount():
   try:apply_total_discount(num(av.get()))
   except Exception:messagebox.showerror(APP,'İskonto tutarını kontrol edin.',parent=self)
  def apply_target():
   try:
    desired=num(tv.get()); base=available_total()
    if desired<0 or desired>base:raise ValueError
    apply_total_discount(base-desired)
   except Exception:messagebox.showerror(APP,'İskontolu toplam tutarı kontrol edin.',parent=self)
  def refresh_summary():
   ids=scope_idx(); cur.set(money(sum(max(0,float(self.cart[i]['qty'])*float(self.cart[i]['price'])-float(self.cart[i].get('disc',0))-float(self.cart[i].get('camp_disc',0))) for i in ids)))
  refresh_summary()
  tk.Button(body,text='KAPAT',command=w.destroy,width=14).pack(anchor='e',pady=(12,0))
