   if not chosen:return messagebox.showwarning(APP,'En az bir ürün için iade miktarı girin.',parent=self)
   ret_total=sum((float(x['total'] or 0)/float(x['qty'] or 1))*qty for x,qty in chosen)
   if ret_total<=0:return messagebox.showwarning(APP,'İade tutarı hesaplanamadı.',parent=self)
   _rd=ayar_tam('sale_return_days')
   if _rd>0:
    try:_age=(datetime.date.today()-datetime.datetime.strptime(str(r['dt'])[:10],'%Y-%m-%d').date()).days
    except Exception:_age=0
    if _age>_rd and not _gv().require(self,'Hızlı Satış',f'İade süresi ({_rd} gün) dolmuş satışın iadesi ({_age} günlük satış)',kind='critical',setting_key=None):return
   if not _gv().require(self,'Hızlı Satış','Satış iadesi',setting_key='return_approval'):return
   if not messagebox.askyesno(APP,f'{len(chosen)} satır iade edilecek.\nİade toplamı: {money(ret_total)}\nGeri ödeme: {refund.get()}\n\nDevam edilsin mi?',parent=self):return
   import ALFABE_IBAN as _IB
   iban_ret=None
