    yr=str(datetime.date.today().year);row=c.execute('SELECT last_no FROM counters WHERE prefix=? AND period=?',('IA',yr)).fetchone();n=(row['last_no'] if row else 0)+1;c.execute('INSERT INTO counters(prefix,period,last_no) VALUES(?,?,?) ON CONFLICT(prefix,period) DO UPDATE SET last_no=excluded.last_no',('IA',yr,n));ret_doc=f'IA-{yr}-{n:06d}'
    cur=c.execute("INSERT INTO sales(doc_no,dt,customer_id,payment,gross,discount,total,status,user,original_sale_id,return_note) VALUES(?,?,?,?,?,?,?,'RETURN',?,?,?)",(ret_doc,now(),r['customer_id'],r['payment'],-ret_total,0,-ret_total,current_user(),r['id'],reason.get().strip()));rid=cur.lastrowid
    for x,qty in chosen:
     unit_net=float(x['total'] or 0)/float(x['qty'] or 1);line_total=qty*unit_net
     # İade KDV'si güncel stok oranından değil, orijinal satış satırından alınır.
