     original_qty=float(x['qty'] or 0)
     original_vat_pct=float(x['vat_pct'] or 0)
     original_vat_amount=float(x['vat_amount'] or 0)
     return_vat_amount=-(original_vat_amount*qty/original_qty) if original_qty else 0.0
     c.execute('INSERT INTO sale_lines(sale_id,stock_id,barcode,name,qty,price,discount,total,cost_snapshot,campaign,original_line_id,vat_pct,vat_amount) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',(rid,x['stock_id'],x['barcode'],x['name'],-qty,x['price'],0,-line_total,x['cost_snapshot'],x['campaign'],x['id'],original_vat_pct,return_vat_amount))
