    open_before=max(float(initial or 0)-float(collected or 0)-float(prior_return or 0),0);cari_credit=round(min(ret_total,open_before),2) if r['customer_id'] else 0
    if cari_credit>0:
     c.execute('INSERT INTO cari_moves(cari_id,dt,kind,credit,source,source_id,note) VALUES(?,?,?,?,?,?,?)',(r['customer_id'],now(),'Cari Satış İadesi',cari_credit,'SALE_RETURN',rid,ret_doc+' / '+r['doc_no']));c.execute('INSERT INTO sale_payments(sale_id,kind,amount) VALUES(?,?,?)',(rid,'Cari',-cari_credit))
