 def receipt_designer(self,parent=None):
  parent=parent or self;w=new_toplevel(parent);w.title('Fiş Tasarımcısı');w.geometry('1180x760');w.minsize(980,650)
  selected={'id':None};name=tk.StringVar(value='Standart 80 mm');paper=tk.StringVar(value='80 mm Fiş');font_size=tk.IntVar(value=11);company=tk.StringVar(value='ALFABE KIRTASİYE');header=tk.StringVar(value='SATIŞ FİŞİ');footer=tk.StringVar(value='Teşekkür ederiz.')
  flags={k:tk.IntVar(value=int(RECEIPT_DESIGN_DEFAULT[k])) for k in ('show_company','show_customer','show_barcode','show_receipt_barcode','show_discount','show_cashier','show_payment','show_phone','bold_total')}
  left=tk.LabelFrame(w,text='KAYITLI ŞABLONLAR',padx=8,pady=8);left.pack(side='left',fill='y',padx=(12,5),pady=12);lst=tk.Listbox(left,width=25,font=('Segoe UI',10));lst.pack(fill='both',expand=True)
  center=tk.LabelFrame(w,text='CANLI ÖN İZLEME',padx=8,pady=8);center.pack(side='left',fill='both',expand=True,padx=5,pady=12);preview=tk.Text(center,font=('Consolas',11),bg='white',wrap='none',state='disabled');preview.pack(fill='both',expand=True)
  right=tk.LabelFrame(w,text='TASARIM AYARLARI',padx=12,pady=10);right.pack(side='right',fill='y',padx=(5,12),pady=12)
  templates=[]
  def config_data():return {'paper':paper.get(),'font_size':max(8,min(18,int(font_size.get() or 11))),'company':company.get().strip(),'header':header.get().strip(),'footer':footer.get().strip(),**{k:int(v.get()) for k,v in flags.items()}}
  def sample_text():
   d=config_data();width=32 if d['paper'].startswith('58') else (42 if d['paper'].startswith('80') else 70);out=[]
   if d['show_company']:out.append((d['company'] or 'ALFABE KIRTASİYE').center(width))
   out+=[(d['header'] or 'SATIŞ FİŞİ').center(width),'='*width,'Belge : PS-2026-000001','Tarih : 2026-09-24 10:30:00']
   if d['show_customer']:out.append('Müşteri: Perakende'+(' / 0258 000 00 00' if d['show_phone'] else ''))
   if d['show_cashier']:out.append('Kasiyer: Yönetici')
   out.append('-'*width);out.append(('8690000000001  ' if d['show_barcode'] else '')+'Örnek Kalem');out.append(' 2 x 25,00 ₺                  50,00 ₺')
   if d['show_discount']:out.append('   İskonto: 5,00 ₺')
   out+=['-'*width,'BRÜT   : 50,00 ₺','İSKONTO:  5,00 ₺','TOPLAM : 45,00 ₺']
   if d['show_payment']:out+=['-'*width,'Nakit: 45,00 ₺']
   if d['show_receipt_barcode']:out+=['','| ||| || |  ||| | ||  || |','PS-2026-000001'.center(width)]
   out+=['='*width,(d['footer'] or '').center(width)];return '\n'.join(out)
  def refresh(*_):
   preview.config(state='normal',font=('Consolas',max(8,min(18,int(font_size.get() or 11)))));preview.delete('1.0','end');preview.insert('1.0',sample_text());preview.config(state='disabled')
  def list_templates(select_id=None):
   nonlocal templates
   templates=DX.rows("SELECT * FROM designs WHERE kind='RECEIPT' ORDER BY active DESC,name,id");lst.delete(0,'end')
   for i,r in enumerate(templates):
    lst.insert('end',('★ ' if r['active'] else '   ')+(r['name'] or 'İsimsiz'))
    if select_id and r['id']==select_id:lst.selection_set(i);lst.see(i)
  def load_selected(e=None):
   s=lst.curselection()
   if not s:return
   r=templates[s[0]];selected['id']=r['id'];name.set(r['name'] or '')
   d=dict(RECEIPT_DESIGN_DEFAULT)
   try:d.update(json.loads(r['data'] or '{}'))
   except Exception as _se:_silent(_se)
   paper.set(d['paper']);font_size.set(int(d['font_size']));company.set(d['company']);header.set(d['header']);footer.set(d['footer'])
   for k,v in flags.items():v.set(int(d.get(k,1)));refresh()
  def new_design():
   selected['id']=None;name.set('Yeni Fiş Tasarımı');paper.set('80 mm Fiş');font_size.set(11);company.set('ALFABE KIRTASİYE');header.set('SATIŞ FİŞİ');footer.set('Teşekkür ederiz.')
   for k,v in flags.items():v.set(int(RECEIPT_DESIGN_DEFAULT[k]));lst.selection_clear(0,'end');refresh()
  def save(make_default=False,save_as=False):
   nm=name.get().strip()
   if not nm:return messagebox.showwarning(APP,'Şablon adı boş bırakılamaz.',parent=self)
   data=json.dumps(config_data(),ensure_ascii=False)
   sid=None if save_as else selected['id'];c=DX.con()
   try:
    c.execute('BEGIN IMMEDIATE')
    if make_default:c.execute("UPDATE designs SET active=0 WHERE kind='RECEIPT'")
    if sid:c.execute("UPDATE designs SET name=?,data=?,active=CASE WHEN ? THEN 1 ELSE active END WHERE id=? AND kind='RECEIPT'",(nm,data,1 if make_default else 0,sid))
    else:
     cur=c.execute("INSERT INTO designs(kind,name,data,active) VALUES('RECEIPT',?,?,?)",(nm,data,1 if make_default else 0));sid=cur.lastrowid
    c.commit();selected['id']=sid;DX.audit('Fiş Tasarımcısı','Kaydet',sid,new=nm,reason='Varsayılan' if make_default else 'Şablon');list_templates(sid);messagebox.showinfo(APP,'Fiş tasarımı kaydedildi.'+('\nVarsayılan şablon yapıldı.' if make_default else ''),parent=self)
   except Exception as e:c.rollback();messagebox.showerror(APP,'Tasarım kaydedilemedi:\n'+str(e),parent=self)
   finally:c.close()
  def set_default():
   if not selected['id']:return save(True)
   save(True)
  for label,var,kind in [('Şablon adı',name,'entry'),('Kâğıt',paper,'combo'),('Yazı boyutu',font_size,'spin'),('Firma adı',company,'entry'),('Başlık',header,'entry'),('Alt mesaj',footer,'entry')]:
   tk.Label(right,text=label+':',anchor='w').pack(fill='x',pady=(6,1))
   if kind=='combo':ttk.Combobox(right,textvariable=var,values=['58 mm Fiş','80 mm Fiş','A4'],state='readonly',width=24).pack(fill='x')
   elif kind=='spin':tk.Spinbox(right,from_=8,to=18,textvariable=var,width=8).pack(fill='x')
   else:tk.Entry(right,textvariable=var,width=28).pack(fill='x')
  options=[('Firma adını göster','show_company'),('Müşteriyi göster','show_customer'),('Telefonu göster','show_phone'),('Ürün barkodunu göster','show_barcode'),('Fiş arama barkodunu göster','show_receipt_barcode'),('İskontoyu göster','show_discount'),('Kasiyeri göster','show_cashier'),('Ödeme türünü göster','show_payment'),('Toplamı kalın göster','bold_total')]
  for text_,key in options:tk.Checkbutton(right,text=text_,variable=flags[key],anchor='w').pack(fill='x',pady=1)
  for v in [name,paper,font_size,company,header,footer,*flags.values()]:v.trace_add('write',refresh)
  lst.bind('<<ListboxSelect>>',load_selected);self.btn(left,'YENİ ŞABLON',new_design).pack(fill='x',pady=(8,3));self.btn(left,'KAPAT',w.destroy).pack(fill='x',pady=3)
  self.btn(right,'KAYDET',lambda:save(False),True).pack(fill='x',pady=(14,3));self.btn(right,'FARKLI KAYDET',lambda:save(False,True)).pack(fill='x',pady=3);self.btn(right,'VARSAYILAN YAP',set_default).pack(fill='x',pady=3)
  list_templates();
  if templates:lst.selection_set(0);load_selected()
  else:new_design()
 def sales_analysis(self,a=None,b=None):
  """Perakende satış analizi: en çok satan ürün/grup/marka ve günlük-haftalık-aylık-yıllık özetler (Cari Satış hariç, iadeler düşülür)."""
  w=new_toplevel(self);w.title('Perakende Satış Raporları');sw,sh=w.winfo_screenwidth(),w.winfo_screenheight();ww=min(1250,max(800,sw-100));hh=min(780,max(520,sh-130));w.geometry(f'{ww}x{hh}+{max(0,(sw-ww)//2)}+{max(0,(sh-hh-65)//2)}');w.minsize(min(900,ww),min(520,hh))
  tk.Label(w,text='PERAKENDE SATIŞ RAPORLARI',font=('Segoe UI',16,'bold'),fg=TXT).pack(anchor='w',padx=14,pady=(10,0))
  tk.Label(w,text='Yalnız perakende satışlar; Cari Satış (CS-) hariç. İadeler net rakamdan düşülür. Ürün/grup/marka sıralamalarında hizmetler (fotokopi vb.) yer almaz; "Hizmet / Ürün Ayrımı" raporunda görünür.',fg=MUT).pack(anchor='w',padx=14)
  today_=datetime.date.today()
  period=tk.StringVar(value='Özel Tarih' if a else 'Bu Ay');start=tk.StringVar(value=a or today_.replace(day=1).isoformat());end=tk.StringVar(value=b or today_.isoformat())
  rep=tk.StringVar(value='En Çok Satan Ürünler');sortv=tk.StringVar(value='Adet');topv=tk.StringVar(value='Tümü');q=tk.StringVar()
  REPS=['En Çok Satan Ürünler','En Çok Satan Gruplar','En Çok Satan Markalar','En Az Satan Ürünler','Düşük Kâr Marjlı Ürünler','Hiç Satılmayan Ürünler','Birlikte Satılan Ürünler','Günlük Satış','Haftalık Satış','Aylık Satış','Yıllık Satış','Haftanın Günü','Saat Dağılımı','Sepet Analizi (Saat)','Kasiyer / Kullanıcı','Hizmet / Ürün Ayrımı','Kampanyalı Satışlar','Ödeme Türü Dağılımı','Dönem Karşılaştırma']
  f1=tk.Frame(w,bg='white');f1.pack(fill='x',padx=12,pady=(8,2))
  tk.Label(f1,text='Rapor:',bg='white',font=('Segoe UI',9,'bold')).pack(side='left',padx=(8,2));rcb=ttk.Combobox(f1,textvariable=rep,state='readonly',width=28,values=REPS);rcb.pack(side='left')
  tk.Label(f1,text='Dönem:',bg='white').pack(side='left',padx=(12,2));pcb=ttk.Combobox(f1,textvariable=period,state='readonly',width=12,values=['Bugün','Dün','Bu Hafta','Geçen Hafta','Bu Ay','Geçen Ay','Bu Yıl','Geçen Yıl','Tümü','Özel Tarih']);pcb.pack(side='left')
  tk.Label(f1,text='Sırala:',bg='white').pack(side='left',padx=(12,2));scb=ttk.Combobox(f1,textvariable=sortv,state='readonly',width=8,values=['Adet','Ciro','Kâr']);scb.pack(side='left')
  tk.Label(f1,text='İlk:',bg='white').pack(side='left',padx=(12,2));tcb=ttk.Combobox(f1,textvariable=topv,state='readonly',width=6,values=['Tümü','10','20','50','100']);tcb.pack(side='left')
  f2=tk.Frame(w,bg='white');f2.pack(fill='x',padx=12,pady=(0,2))
  tk.Label(f2,text='Tarih aralığı:',bg='white').pack(side='left',padx=(8,3));d1=date_entry(f2,start,width=11,on_change=lambda:chg());d1.pack(side='left',padx=3);tk.Label(f2,text='—',bg='white').pack(side='left');d2=date_entry(f2,end,width=11,on_change=lambda:chg());d2.pack(side='left',padx=3)
  tk.Label(f2,text='   Ara:',bg='white').pack(side='left');qe=tk.Entry(f2,textvariable=q,width=26,bg='#fff59d');qe.pack(side='left',padx=3)
  cols=[];wrap=tk.Frame(w);wrap.pack(fill='both',expand=True,padx=12,pady=6);t=ttk.Treeview(wrap,show='headings',selectmode='browse');sy=ttk.Scrollbar(wrap,orient='vertical',command=t.yview);t.configure(yscrollcommand=sy.set);sy.pack(side='right',fill='y');t.pack(side='left',fill='both',expand=True)
  t.tag_configure('z_odd',background='#E6F2FA')
  info=tk.Label(w,text='',bg='#e8f1fb',fg='#0b376d',font=('Segoe UI',10,'bold'),anchor='w');info.pack(fill='x',padx=12,pady=(0,4),ipady=6)
  state={'heads':[],'rows':[],'shown':[]}
  def rng():
   p=period.get();d=today_
   if p=='Bugün':return d,d
   if p=='Dün':y=d-datetime.timedelta(days=1);return y,y
   if p=='Bu Hafta':return d-datetime.timedelta(days=d.weekday()),d
   if p=='Geçen Hafta':e=d-datetime.timedelta(days=d.weekday()+1);return e-datetime.timedelta(days=6),e
   if p=='Bu Ay':return d.replace(day=1),d
   if p=='Geçen Ay':e=d.replace(day=1)-datetime.timedelta(days=1);return e.replace(day=1),e
   if p=='Bu Yıl':return d.replace(month=1,day=1),d
   if p=='Geçen Yıl':return datetime.date(d.year-1,1,1),datetime.date(d.year-1,12,31)
   if p=='Özel Tarih':
    try:return datetime.date.fromisoformat(start.get()),datetime.date.fromisoformat(end.get())
    except Exception:return d.replace(day=1),d
   return datetime.date(1900,1,1),datetime.date(2999,12,31)
  def fnum(x):
   try:return float(x or 0)
   except Exception:return 0.0
  SUMH=('Adet','Ciro','Maliyet','Kâr','Tutar','Fiş Sayısı','İade Tutarı','Stok','Stok Değeri','Birlikte Fiş Sayısı')
  MONEYH=('Ciro','Maliyet','Kâr','Tutar','Ort. Sepet','Ort. Sepet Tutarı','İade Tutarı','Stok Değeri')
  PCTH=('Pay %','Marj %','İade Oranı %')
  QTYH=('Adet','Stok','Ort. Sepet Adedi')
  INTH=('Sıra','Fiş Sayısı','Birlikte Fiş Sayısı')
  def query_lines(a_,b_):
   return DX.rows("""SELECT s.id sid,s.doc_no,s.dt dt,substr(s.dt,1,10) day,substr(s.dt,12,2) hr,COALESCE(s.status,'FINAL') st,COALESCE(NULLIF(s.user,''),'(Belirsiz)') usr,sl.stock_id,
     COALESCE(NULLIF(sl.name,''),st.name,'') nm,COALESCE(st.code,'') code,COALESCE(st.brand,'') brand,COALESCE(NULLIF(st.grp,''),'(Grupsuz)') grp,
     COALESCE(sl.barcode,'') bc,COALESCE(sl.campaign,'') camp,
     sl.qty qty,sl.total total,sl.qty*COALESCE(sl.cost_snapshot,0) cost
     FROM sales s JOIN sale_lines sl ON sl.sale_id=s.id LEFT JOIN stock st ON st.id=sl.stock_id
     WHERE substr(s.dt,1,10) BETWEEN ? AND ? AND COALESCE(s.doc_no,'') NOT LIKE 'CS-%'
       AND NOT EXISTS(SELECT 1 FROM sales os WHERE os.id=s.original_sale_id AND COALESCE(os.doc_no,'') LIKE 'CS-%')
       AND COALESCE(s.status,'FINAL') IN ('FINAL','RETURN','PARTIAL_RETURN','RETURNED')""",(a_,b_))
  def totals(a_,b_):
   ln=query_lines(a_,b_);T={'ciro':0.0,'qty':0.0,'cost':0.0,'iade':0.0,'docs':set()}
   for x in ln:
    T['ciro']+=fnum(x['total']);T['qty']+=fnum(x['qty']);T['cost']+=fnum(x['cost'])
    if x['st']=='RETURN':T['iade']+=abs(fnum(x['total']))
    else:T['docs'].add(x['sid'])
   n=len(T['docs']);T['n']=n;T['kar']=T['ciro']-T['cost'];T['avg']=T['ciro']/n if n else 0;T['marj']=T['kar']/T['ciro']*100 if T['ciro'] else 0
   return T
  def wk(day):
   d=datetime.date.fromisoformat(day);m_=d-datetime.timedelta(days=d.weekday());iso=d.isocalendar()
   return (m_.isoformat(),f"{iso[0]}-H{iso[1]:02d} ({m_.strftime('%d.%m')} - {(m_+datetime.timedelta(days=6)).strftime('%d.%m.%Y')})")
  GUN=['Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi','Pazar']
  def run(*_):
   a_,b_=rng()
   if period.get()=='Tümü':start.set('');end.set('')
   elif period.get()!='Özel Tarih':start.set(a_.isoformat());end.set(b_.isoformat())
   for _de,_v in ((d1,start),(d2,end)):
    try:_de.entry.delete(0,'end');_de.entry.insert(0,_date_display(_v.get()) if _v.get() else '')
    except Exception as _se:_silent(_se)
   r=rep.get();A,B=a_.isoformat(),b_.isoformat();state['mode']='std';state['detail']=False
   if r=='Ödeme Türü Dağılımı':
    pr=DX.rows("""SELECT COALESCE(NULLIF(sp.kind,''),'Tanımsız') k,SUM(sp.amount) a,COUNT(DISTINCT s.id) n FROM sale_payments sp JOIN sales s ON s.id=sp.sale_id
      WHERE substr(s.dt,1,10) BETWEEN ? AND ? AND COALESCE(s.doc_no,'') NOT LIKE 'CS-%' AND COALESCE(s.status,'FINAL') IN ('FINAL','RETURN','PARTIAL_RETURN','RETURNED') GROUP BY 1""",(A,B))
    tot=sum(fnum(x['a']) for x in pr) or 1
    state['heads']=['Ödeme Türü','Fiş Sayısı','Tutar','Pay %'];state['rows']=[[x['k'],x['n'],fnum(x['a']),fnum(x['a'])/tot*100] for x in sorted(pr,key=lambda z:-fnum(z['a']))];draw();return
   if r=='Dönem Karşılaştırma':
    if period.get()=='Tümü':
     state['heads']=['Gösterge'];state['rows']=[['Karşılaştırma için bir tarih aralığı seçin (Tümü seçiliyken yapılamaz).']];state['mode']='text';draw();return
    days=(b_-a_).days+1;pb=a_-datetime.timedelta(days=1);pa=pb-datetime.timedelta(days=days-1)
    try:ly_a=a_.replace(year=a_.year-1);ly_b=b_.replace(year=b_.year-1)
    except Exception:ly_a=a_-datetime.timedelta(days=365);ly_b=b_-datetime.timedelta(days=365)
    C=totals(A,B);P=totals(pa.isoformat(),pb.isoformat());L=totals(ly_a.isoformat(),ly_b.isoformat())
    def pc(c,p):return 'Yeni' if (not p and c) else ('-' if not p else f"%{(c-p)/abs(p)*100:+.1f}".replace('.',','))
    items=[('Net Satış (Ciro)','ciro','m'),('Satılan Adet','qty','q'),('Fiş Sayısı','n','i'),('Ortalama Sepet','avg','m'),('Maliyet','cost','m'),('Brüt Kâr','kar','m'),('Kâr Marjı','marj','p'),('İade Tutarı','iade','m')]
    def fv(v,k):return money(v) if k=='m' else (f'{v:g}'.replace('.',',') if k=='q' else (f'%{v:.1f}'.replace('.',',') if k=='p' else str(int(v))))
    state['heads']=['Gösterge',f'Seçili ({_date_display(A)} - {_date_display(B)})',f'Önceki Dönem ({_date_display(pa.isoformat())} - {_date_display(pb.isoformat())})','Fark','Fark %',f'Geçen Yıl ({_date_display(ly_a.isoformat())} - {_date_display(ly_b.isoformat())})','Geçen Yıl Fark %']
    state['rows']=[[nm,fv(C[k],kd),fv(P[k],kd),(fv(C[k]-P[k],kd) if kd!='p' else f"{C[k]-P[k]:+.1f} puan".replace('.',',')),pc(C[k],P[k]) if kd!='p' else '',fv(L[k],kd),pc(C[k],L[k]) if kd!='p' else ''] for nm,k,kd in items]
    state['mode']='text';draw();return
   if r=='Hiç Satılmayan Ürünler':
    sold={x['stock_id'] for x in query_lines(A,B) if x['stock_id']};rows=[]
    for x in DX.rows("""SELECT st.id,st.code,st.name,COALESCE(st.brand,'') brand,COALESCE(NULLIF(st.grp,''),'(Grupsuz)') grp,COALESCE(st.qty,0) qty,
       COALESCE(NULLIF(st.avg_cost,0),st.last_cost,0) cost,(SELECT MAX(substr(s.dt,1,10)) FROM sale_lines sl JOIN sales s ON s.id=sl.sale_id WHERE sl.stock_id=st.id AND COALESCE(s.status,'FINAL') IN ('FINAL','PARTIAL_RETURN','RETURNED')) last_sale
       FROM stock st WHERE COALESCE(st.active,1)=1 AND COALESCE(st.qty,0)>0 ORDER BY st.name COLLATE NOCASE"""):
     if x['id'] in sold:continue
     rows.append([x['code'] or '',x['name'],x['brand'],x['grp'],fnum(x['qty']),_date_display(x['last_sale']) if x['last_sale'] else 'Hiç satılmadı',fnum(x['qty'])*fnum(x['cost'])])
    rows.sort(key=lambda z:-z[6]);state['heads']=['Sıra','Stok Kodu','Ürün','Marka','Grup','Stok','Son Satış','Stok Değeri'];state['rows']=[[i+1]+z for i,z in enumerate(rows)];draw();return
   lines=query_lines(A,B)
   if r=='Birlikte Satılan Ürünler':
    docs={}
    for ln in lines:
     if ln['st']!='RETURN' and ln['stock_id'] and fnum(ln['qty'])>0:docs.setdefault(ln['sid'],{})[ln['stock_id']]=ln['nm']
    pairs={};multi=0
    for sid,it in docs.items():
     ks=sorted(it)[:15]
     if len(ks)>=2:multi+=1
     for i_ in range(len(ks)):
      for j_ in range(i_+1,len(ks)):pairs[(ks[i_],ks[j_])]=pairs.get((ks[i_],ks[j_]),0)+1
    nmap={}
    for it in docs.values():nmap.update(it)
    lst=sorted(pairs.items(),key=lambda z:-z[1])
    state['heads']=['Sıra','Ürün 1','Ürün 2','Birlikte Fiş Sayısı','Pay %'];state['rows']=[[i+1,nmap[k[0]],nmap[k[1]],n,(n/multi*100 if multi else 0)] for i,(k,n) in enumerate(lst[:300])];draw();return
   agg={};ranked=False
   def add(key,ln,extra=None):
    x=agg.setdefault(key,{'qty':0.0,'ciro':0.0,'cost':0.0,'docs':set(),'iade':0.0,'extra':extra,'n':0})
    x['qty']+=fnum(ln['qty']);x['ciro']+=fnum(ln['total']);x['cost']+=fnum(ln['cost'])
    if ln['st']=='RETURN':x['iade']+=abs(fnum(ln['total']))
    else:x['docs'].add(ln['sid'])
   for ln in lines:
    if r in ('En Çok Satan Ürünler','En Az Satan Ürünler','Düşük Kâr Marjlı Ürünler','En Çok Satan Gruplar','En Çok Satan Markalar') and (ln['bc']=='HIZMET' or not ln['stock_id']):continue
    if r in ('En Çok Satan Ürünler','En Az Satan Ürünler','Düşük Kâr Marjlı Ürünler'):add(ln['stock_id'] if ln['stock_id'] else ('N:'+str(ln['nm'])),ln,(ln['code'],ln['nm'],ln['brand'],ln['grp']))
    elif r=='En Çok Satan Gruplar':add(ln['grp'],ln,(ln['grp'],))
    elif r=='En Çok Satan Markalar':add(ln['brand'] or '(Markasız)',ln,(ln['brand'] or '(Markasız)',))
    elif r=='Günlük Satış':add(ln['day'],ln,(_date_display(ln['day']),))
    elif r=='Haftalık Satış':k,l=wk(ln['day']);add(k,ln,(l,))
    elif r=='Aylık Satış':add(ln['day'][:7],ln,(ln['day'][5:7]+'.'+ln['day'][:4],))
    elif r=='Yıllık Satış':add(ln['day'][:4],ln,(ln['day'][:4],))
