  def render_page():
   t.delete(*t.get_children())
   total_pages=max(1,(len(last_rows)+page_size-1)//page_size)
   current_page[0]=min(current_page[0],total_pages-1)
   page_label.config(text=f'Sayfa {current_page[0]+1}/{total_pages} • {len(last_rows)} kayıt')
   page_target.set(str(current_page[0]+1))
   # Ek alanlar yalniz gorunen 100 kayit icin tek toplu sorguda hesaplanir.
