   out+=['-'*width,f"{'BRÜT':9}{money(s['gross']):>{max(1,width-9)}}",f"{'İSKONTO':9}{money(s['discount']):>{max(1,width-9)}}",f"{'TOPLAM':9}{money(s['total']):>{max(1,width-9)}}"]
