   for x in lines:lt.insert('','end',values=(x['barcode'] or '',x['name'],f"{float(x['qty'] or 0):g}",money(x['price']),money(x['discount']),money(float(x['qty'] or 0)*float(x['cost_snapshot'] or 0)),money(float(x['total'] or 0)-float(x['qty'] or 0)*float(x['cost_snapshot'] or 0)),x['campaign'] or '',money(x['total']))+_sale_line_ext(x,s))
