 def _cari_list_report_heads(self):
  # Sadece ekranda gorunen alanlar; cari veritabani degistirilmez.
  columns=[str(c) for c in self.t.cget('columns')]
  visible=self.t.cget('displaycolumns')
  if isinstance(visible,str):
   visible=columns if visible in ('#all','') else list(self.t.tk.splitlist(visible))
  else:visible=list(visible)
  if not visible or visible==['#all']:visible=columns
  return [str(self.t.heading(c,'text')) for c in visible if c in columns]
 def summary_data(self):
  """Cari yönetim özeti verisi. Taksit tanımı Cari listesindeki 'Vadesi Geçen' ile aynıdır: kalan > 0 ve durum Ödendi/İptal/İade değil."""
  td=today();limit=(datetime.date.today()+datetime.timedelta(days=7)).isoformat()
  bals=[dict(r) for r in DX.rows("SELECT c.id,c.title,c.role,c.phone,COALESCE(c.risk,0) risk,COALESCE(SUM(m.debit-m.credit),0) balance,MAX(m.dt) lastdt FROM caris c LEFT JOIN cari_moves m ON m.cari_id=c.id WHERE COALESCE(c.active,1)=1 GROUP BY c.id")]
  try:ins=[dict(r) for r in DX.rows("SELECT i.id,i.cari_id,i.due_date,COALESCE(i.amount,0) amount,COALESCE(i.paid,0) paid,c.title,COALESCE(s.doc_no,'') doc FROM installments i LEFT JOIN caris c ON c.id=i.cari_id LEFT JOIN sales s ON s.id=i.sale_id WHERE COALESCE(i.amount,0)-COALESCE(i.paid,0)>0.005 AND COALESCE(i.status,'') NOT IN ('Ödendi','İptal','İade') ORDER BY i.due_date,i.id")]
  except Exception:ins=[]
  for r in ins:r['remain']=max(float(r['amount'])-float(r['paid']),0.0);r['due']=str(r['due_date'] or '')[:10]
  over=[r for r in ins if r['due'] and r['due']<td];soon=[r for r in ins if r['due'] and td<=r['due']<=limit]
  cust=sum(1 for r in bals if 'Müşteri' in str(r['role'] or ''));supp=sum(1 for r in bals if 'Tedarik' in str(r['role'] or ''))
  return {'bals':bals,'ins':ins,'over':over,'soon':soon,'cust':cust,'supp':supp,
   'recv':sum(max(float(r['balance']),0.0) for r in bals),'pay':sum(max(-float(r['balance']),0.0) for r in bals),
   'risk':[r for r in bals if float(r['risk'])>0 and float(r['balance'])>float(r['risk'])],'td':td}
