   t.tag_configure('z_even',background='#FFFFFF');t.tag_configure('z_odd',background='#E6F2FA');t.tag_configure('late',background='#FDE3E3',foreground='#000000');t.tag_configure('soon',background='#FFF1CC',foreground='#7A4B00')
   t._alfabe_report_title=title;t._alfabe_report_key='Cari Merkezi / Yönetim Özeti / '+title;t.bind('<Double-1>',lambda e,tt=t:open_cari(tt));trees.append(t);return t
