  sections=[('GENEL BİLGİLER',[('Cari Kodu','cari_code'),('Unvan / Ad Soyad *','title'),('Cari Türü','role'),('Vergi / TCKN','tax_no'),('Vergi Dairesi','tax_office')]),('İLETİŞİM',[('Telefon','phone'),('E-posta','email'),('Web Sitesi','web'),('İl','city'),('İlçe','district'),('Adres','address'),('Yetkili Kişi','contact_name'),('Yetkili Telefon','contact_phone'),('Yetkili E-posta','contact_email')]),('FİNANS',[('Risk Limiti','risk'),('Vade Günü','due_days')]),('İSKONTO',[('Alış İskonto %','buy_discount_rate'),('Satış İskonto %','sell_discount_rate')])]
  # Cari turleri secili firma/donem veritabaninda saklanir.
  DX.exec('CREATE TABLE IF NOT EXISTS cari_types (name TEXT PRIMARY KEY COLLATE NOCASE)')
  # Turkish-aware identity for display labels; do not alter historical cari role values.
  def type_key(name):
   return str(name or '').strip().translate(str.maketrans({'I':'ı','İ':'i'})).casefold()
  base_types=('Müşteri','Tedarikçi','Ortak')
  def upper_tr(value):
   return str(value or '').strip().replace('i','İ').replace('ı','I').upper()
  def type_names():
   existing=[r['role'] for r in DX.rows("SELECT DISTINCT role FROM caris WHERE role IS NOT NULL AND TRIM(role)<>''")]
   custom=[r['name'] for r in DX.rows('SELECT name FROM cari_types ORDER BY name')]
   result=[];seen=set()
   for name in list(base_types)+existing+custom:
    key=type_key(name)
    if key and key not in seen:result.append(upper_tr(name));seen.add(key)
   return result
  # Otomatik kod: mevcut en yuksek sayisal kod + 1; elle bosalan kod kullanilabilir.
  used_codes={str(r['cari_code']).strip() for r in DX.rows("SELECT cari_code FROM caris WHERE cari_code IS NOT NULL")}
  def next_code():
   numeric=[int(x) for x in used_codes if x.isdecimal()]
   return str(max(numeric,default=0)+1)
  vars={}
  for title,fields in sections:
   tab=tk.Frame(nb,bg='white');nb.add(tab,text='  '+title+'  ')
