    tk.Label(cell,text=label,font=('Segoe UI',10,'bold'),fg=muted,bg='white').pack(anchor='w',pady=(0,5))
    val='' if not old else str(old[key] if old[key] is not None else '')
    if key=='cari_code' and not cid:val=next_code()
    if not old and val=='':   # v1.2.291.452: yeni cari kartı varsayılanları (Ayarlar > Cari & Risk)
     if key=='risk':
      _dl=ayar_sayi('cari_default_limit');val=(('%.2f'%_dl).rstrip('0').rstrip('.') if _dl>0 else '')
     elif key=='due_days':val=str(ayar_tam('cari_due_days'))
    v=tk.StringVar(value=val);vars[key]=v
