 def _reconciliation_issues(self,cid,balance,inst_total):
  """Gerçek hesap kontrolleri: tutarsızlık varsa kısa uyarı metinleri döner."""
  out=[]
  try:
   n=DX.one("""SELECT COUNT(*) n FROM cari_moves m WHERE m.cari_id=? AND m.source='MANUAL' AND m.kind IN ('Tahsilat','Ödeme')
    AND (SELECT COUNT(*) FROM finance f WHERE f.source='CARI' AND f.source_id=m.id)<>1""",(cid,))['n']
   if n:out.append(f'{n} tahsilat/ödeme kasa-banka kaydıyla eşleşmiyor')
   n=DX.one("SELECT COUNT(*) n FROM installments WHERE cari_id=? AND COALESCE(paid,0)>COALESCE(amount,0)+0.005",(cid,))['n']
   if n:out.append(f'{n} taksitte ödenen tutar taksit tutarını aşıyor')
   n=DX.one("SELECT COUNT(*) n FROM installments WHERE cari_id=? AND COALESCE(paid,0)<-0.005",(cid,))['n']
   if n:out.append(f'{n} taksitte negatif ödenen tutar var')
   if inst_total>max(balance,0)+0.01:out.append(f'açık taksit toplamı ({money(inst_total)}) cari bakiyeyi ({money(balance)}) aşıyor')
   n=DX.one("""SELECT COUNT(*) n FROM transaction_reversals tr JOIN cari_moves o ON o.id=tr.original_cari_move_id
    LEFT JOIN cari_moves r ON r.id=tr.reversal_cari_move_id WHERE o.cari_id=? AND (r.id IS NULL OR ABS((r.debit-r.credit)+(o.debit-o.credit))>0.005)""",(cid,))['n']
   if n:out.append(f'{n} iptal kaydının ters hareketi orijinalle uyuşmuyor')
  except Exception as e:
   log_error('Mutabakat kontrolleri',e);out.append('kontroller çalıştırılamadı: '+str(e)[:60])
  return out
