 def _return_candidates(self,cid):
  """İade edilebilir satış belgeleri: [(sale_row, returned, available)]."""
  out=[]
  for s in DX.rows("SELECT * FROM sales WHERE customer_id=? AND status IN ('FINAL','PARTIAL_RETURN') ORDER BY id DESC",(cid,)):
   returned=float(DX.one("SELECT COALESCE(SUM(ABS(total)),0) v FROM sales WHERE original_sale_id=? AND status='RETURN'",(s['id'],))['v'] or 0);available=max(float(s['total'] or 0)-returned,0)
   if available>0.005:out.append((dict(s),returned,available))
  return out
