 def _open_document_rows(self,cid):
  c=DX.one('SELECT due_days FROM caris WHERE id=?',(cid,));due_days=max(int((c['due_days'] if c else 0) or ayar_tam('cari_due_days')),0);result=[]
  rows=DX.rows('''SELECT s.*,
   COALESCE((SELECT SUM(cm.debit-cm.credit) FROM cari_moves cm WHERE cm.cari_id=s.customer_id AND cm.source_id=s.id AND cm.source IN ('CARI_SALE','SALE','ORDER_SALE')),0) initial_debt,
   COALESCE((SELECT SUM(sc.amount) FROM sale_collections sc WHERE sc.sale_id=s.id),0) collected,
   COALESCE((SELECT SUM(ABS(rs.total)) FROM sales rs WHERE rs.original_sale_id=s.id AND rs.status='RETURN'),0) returned,
   (SELECT MIN(i.due_date) FROM installments i WHERE i.sale_id=s.id) first_installment
   FROM sales s WHERE s.customer_id=? AND s.status IN ('FINAL','PARTIAL_RETURN') ORDER BY s.dt,s.id''',(cid,))
  for r in rows:
   initial=max(float(r['initial_debt'] or 0),0);collected=float(r['collected'] or 0);returned=float(r['returned'] or 0);remaining=max(round(initial-collected-returned,2),0)
   if initial<=0.005:continue
   sale_day=str(r['dt'] or today())[:10]
   try:fallback=(datetime.date.fromisoformat(sale_day)+datetime.timedelta(days=due_days)).isoformat()
   except:fallback=today()
   due=str(r['due_date'] or r['first_installment'] or fallback)[:10]
   try:late=max((datetime.date.today()-datetime.date.fromisoformat(due)).days,0) if remaining>0.005 else 0
   except:late=0
   if remaining<=0.005:status='Ödendi'
   elif late>0:status='Gecikmiş'
   elif collected>0.005 or initial<float(r['total'] or 0)-0.005:status='Kısmi'
   else:status='Açık'
   result.append({'id':int(r['id']),'doc':r['doc_no'],'dt':r['dt'],'due':due,'payment':r['payment'],'total':float(r['total'] or 0),'initial':initial,'advance':max(float(r['total'] or 0)-initial,0),'collected':collected,'returned':returned,'remaining':remaining,'late':late,'status':status})
  return result
