 def _debt_aging_rows(self):
  result=[]
  for c in DX.rows('SELECT id,title,phone,risk FROM caris WHERE COALESCE(active,1)=1 ORDER BY title'):
   docs=[d for d in self._open_document_rows(c['id']) if d['remaining']>0.005]
   if not docs:continue
   b={'not_due':0.0,'d1_7':0.0,'d8_30':0.0,'d31_60':0.0,'d61_90':0.0,'d90p':0.0}
   for d in docs:
    a=float(d['remaining']);late=int(d['late'] or 0)
    if late<=0:b['not_due']+=a
    elif late<=7:b['d1_7']+=a
    elif late<=30:b['d8_30']+=a
    elif late<=60:b['d31_60']+=a
    elif late<=90:b['d61_90']+=a
    else:b['d90p']+=a
   total=sum(b.values());overdue=total-b['not_due'];oldest=min(d['due'] for d in docs);max_late=max(int(d['late'] or 0) for d in docs);risk=float(c['risk'] or 0)
   last=DX.one("""SELECT MAX(m.dt) dt FROM cari_moves m LEFT JOIN transaction_reversals tr ON tr.original_cari_move_id=m.id
    WHERE m.cari_id=? AND m.kind='Tahsilat' AND m.source='MANUAL' AND tr.id IS NULL""",(c['id'],))
   result.append({'id':int(c['id']),'title':c['title'],'phone':c['phone'] or '','total':total,'overdue':overdue,**b,'oldest':oldest,'max_late':max_late,'last_collection':(last['dt'] if last else '') or '','risk':risk,'excess':max(total-risk,0) if risk>0 else 0})
  return result
