   if DX.one('SELECT id FROM transaction_reversals WHERE original_cari_move_id=?',(original_id,)):return messagebox.showwarning(APP,'Bu işlem daha önce iptal edilmiş. İkinci kez iptal edilemez.',parent=w)
   amount=float(orig['credit'] or 0) if orig['kind']=='Tahsilat' else float(orig['debit'] or 0)
