     paid_amount=round(float(ip['amount'] or 0),2)
     if paid_amount<=0:raise ValueError('Taksit tahsilat bağlantısında geçersiz tutar var; iptal durduruldu.')
     if ip['installment_id'] in seen_installments:raise ValueError('Aynı taksite birden fazla bağlantı bulundu; iptal durduruldu.')
     seen_installments.add(ip['installment_id'])
     ins=con.execute('SELECT * FROM installments WHERE id=?',(ip['installment_id'],)).fetchone()
     if not ins:raise ValueError(f"Bağlı taksit bulunamadı (ID: {ip['installment_id']}); iptal durduruldu.")
     if int(ins['cari_id'])!=int(cid):raise ValueError('Bağlı taksit başka cari hesaba ait; iptal durduruldu.')
     current_paid=round(float(ins['paid'] or 0),2)
     if current_paid+0.005<paid_amount:raise ValueError('Taksitin ödenmiş tutarı iptal edilecek tahsilattan az; iptal durduruldu.')
     new_paid=round(current_paid-paid_amount,2)
     if new_paid<0:raise ValueError('Taksit bakiyesi negatif olamaz; iptal durduruldu.')
     total=float(ins['amount'] or 0)
     new_status='Ödendi' if new_paid>=total-0.005 else ('Kısmi' if new_paid>0.005 else 'Bekliyor')
     installment_updates.append((ins['id'],new_paid,new_status,paid_amount))
