   doc=next_doc('TM' if kind=='Tahsilat' else 'OM');stamp=chosen_date.isoformat()+' '+datetime.datetime.now().strftime('%H:%M:%S');desc=f"Belge: {doc} | Ödeme: {paytype.get()} | Hesap: {account.get()} | {note.get().strip()}";con=DX.con();allocated=0.0;allocated_count=0;sale_allocated=0.0;sale_doc=''
