  def show(*_):
   t.delete(*t.get_children());qq=search_norm(q.get().strip());kv=kind_v.get();n=0;td=tc=0.0
   for r in state['rows']:
    if kv!='Tümü' and str(r['kind'] or '')!=kv:continue
    if state['flt'] and not state['flt'][1](r):continue
    doc=r.get('doc') or '';hay=search_norm(' '.join(str(x or '') for x in (r['title'],r['kind'],doc,r['note'],_kaynak_tr(r['source']))))
    if qq and qq not in hay:continue
    tags=[]
