  def _k(r):return _tr_fold(r['kind'] or '')
  def _src(r):return str(r['source'] or '').upper()
  def is_return(r):return 'iade' in _k(r) or _src(r) in ('SALE_RETURN','PURCHASE_RETURN','ALIS_IADE')
  def is_cancel(r):return 'iptal' in _k(r) or 'ters' in _k(r) or 'REVERSAL' in _src(r) or 'CANCEL' in _src(r)
  def is_sale(r):return ('satis' in _k(r) or _src(r) in ('CARI_SALE','SALE','ORDER_SALE')) and not is_return(r) and not is_cancel(r) and 'pesinat' not in _k(r) and 'tahsilat' not in _k(r)
  def is_purchase(r):return (_src(r) in ('PURCHASE','GOODS_RECEIPT','SUPPLIER_INVOICE') or _k(r).startswith('alis') or 'mal kabul' in _k(r) or 'fatura' in _k(r)) and not is_return(r) and not is_cancel(r) and 'odeme' not in _k(r)
  def is_pay(r):return any(x in _k(r) for x in ('tahsilat','odeme','pesinat')) and not is_cancel(r)
  def is_invoiced_purchase(r):return _src(r).startswith('SUPPLIER_INVOICE') and not is_cancel(r) and 'odeme' not in _k(r)
  def is_installment(r):return 'taksit' in _k(r) or 'senet' in _k(r) or 'vade' in _k(r)
  def is_credit_today(r):
   return (is_sale(r) or is_purchase(r)) and str(r['dt'] or '')[:10]==datetime.date.today().isoformat() and any(x in _k(r) for x in ('acik hesap','vadeli','senet','taksit','alis','mal kabul','fatura'))
