   if aa:
    marks=','.join('?'*len(aa));rr=DX.rows(f"SELECT f.*,COALESCE(c.title,'') cari FROM finance f LEFT JOIN caris c ON f.source='BANK_CARI' AND c.id=f.source_id WHERE f.account IN ({marks}) ORDER BY f.id DESC LIMIT 3000",aa);total=sum(float(r['amount'] or 0) for r in rr)
