 def cari_output_center(self,cid=None,initial_report=None):
  cid=cid or self.selected()
  if not cid:return
  c=DX.one('SELECT * FROM caris WHERE id=?',(cid,))
  if not c:return
  w=new_toplevel(self);w.title('Cari Çıktı Merkezi - '+c['title']);w.geometry('1080x760');w.minsize(850,620)
  head=tk.Frame(w,bg='#dcecff');head.pack(fill='x');tk.Label(head,text='CARİ ÇIKTI MERKEZİ',bg='#dcecff',fg='#0b376d',font=('Segoe UI',18,'bold')).pack(side='left',padx=18,pady=14);tk.Label(head,text=c['title'],bg='#dcecff',fg=TXT,font=('Segoe UI',12,'bold')).pack(side='right',padx=18)
  opts=tk.Frame(w,bg='white');opts.pack(fill='x',padx=14,pady=10)
  report=tk.StringVar(value=initial_report or 'Cari Hesap Ekstresi');start=tk.StringVar(value=('1900-01-01' if initial_report in ('Taksit Ödeme Planı','Senet Ödeme Planı') else datetime.date.today().replace(day=1).isoformat()));end=tk.StringVar(value=('2999-12-31' if initial_report in ('Taksit Ödeme Planı','Senet Ödeme Planı') else today()));orientation=tk.StringVar(value='Dikey')
  for lab,var,vals,wd in [('Belge',report,['Cari Hesap Ekstresi','Cari Hareket Dökümü','Taksit Ödeme Planı','Senet Ödeme Planı'],24),('Başlangıç',start,None,12),('Bitiş',end,None,12),('Yön',orientation,['Dikey','Yatay'],9)]:
   tk.Label(opts,text=lab+':',bg='white').pack(side='left',padx=(8,2))
   (ttk.Combobox(opts,textvariable=var,values=vals,state='readonly',width=wd) if vals else (date_entry(opts,var,width=wd) if lab in ('Başlangıç','Bitiş') else tk.Entry(opts,textvariable=var,width=wd))).pack(side='left',padx=3)
  quick=tk.Frame(w,bg=BG);quick.pack(fill='x',padx=14,pady=(0,6))
  tk.Label(quick,text='Hızlı dönem:',bg=BG,fg=MUT,font=('Segoe UI',9,'bold')).pack(side='left',padx=(2,6))
  def set_period(kind):
   t0=datetime.date.today()
   if kind=='Bu Ay':s0,e0=t0.replace(day=1),t0
   elif kind=='Son 3 Ay':s0,e0=(t0.replace(day=1)-datetime.timedelta(days=62)).replace(day=1),t0
   elif kind=='Bu Yıl':s0,e0=t0.replace(month=1,day=1),t0
   elif kind=='Geçen Yıl':s0,e0=datetime.date(t0.year-1,1,1),datetime.date(t0.year-1,12,31)
   else:s0,e0=datetime.date(1900,1,1),t0
   start.set(s0.isoformat());end.set(e0.isoformat())
  for _k in ('Bu Ay','Son 3 Ay','Bu Yıl','Geçen Yıl','Tümü'):
   tk.Button(quick,text=_k,command=lambda k=_k:set_period(k),font=('Segoe UI',9,'bold'),bg='#E8F1FB',relief='flat',padx=10,pady=3,cursor='hand2').pack(side='left',padx=2)
  tx=tk.Text(w,font=('Consolas',10),wrap='none',bg='white');tx.pack(fill='both',expand=True,padx=14,pady=(0,8));current={'text':''}
  # Cari Ekstre icin metin yerine okunakli, gercek sutunlu tablo.
  statement_area=tk.Frame(w,bg='white')
  statement_summary=tk.StringVar(value='')
  tk.Label(statement_area,textvariable=statement_summary,bg='#e8f2ff',fg='#123c6a',
           font=('Segoe UI',11,'bold'),anchor='w',padx=12,pady=10).pack(fill='x')
  statement_columns=('Tarih / Saat','İşlem','Borç','Alacak','Bakiye','Kaynak','Açıklama')
  statement_tree=ttk.Treeview(statement_area,columns=statement_columns,show='headings',style='CariListe.Treeview')
  for col in statement_columns:
   statement_tree.heading(col,text=col)
   statement_tree.column(col,width=145 if col in ('Tarih / Saat','Açıklama') else 110,
       anchor='e' if col in ('Borç','Alacak','Bakiye') else 'w',minwidth=65)
  statement_scroll=ttk.Scrollbar(statement_area,orient='vertical',command=statement_tree.yview)
  statement_tree.configure(yscrollcommand=statement_scroll.set)
  statement_scroll.pack(side='right',fill='y')
  statement_tree.pack(fill='both',expand=True)
  statement_total=tk.StringVar(value='')
  tk.Label(statement_area,textvariable=statement_total,bg='#dcecff',fg='#0b376d',
           font=('Segoe UI',10,'bold'),anchor='w',padx=12,pady=9).pack(fill='x')
  def build_text():
   title=report.get();a=start.get().strip() or '1900-01-01';b=end.get().strip() or '2999-12-31';width=112 if orientation.get()=='Yatay' else 88
   out=[('ALFABE KIRTASİYE').center(width),title.upper().center(width),'='*width,f"Cari: {c['title']}",f"Telefon: {c['phone'] or '-'}    Vergi/TCKN: {c['tax_no'] or '-'}",f"Tarih Aralığı: {a} - {b}",'-'*width]
   if title in ('Taksit Ödeme Planı','Senet Ödeme Planı'):
    rows=DX.rows("SELECT i.id,i.sale_id,i.due_date,i.amount,i.paid,i.status,COALESCE(s.doc_no,'') doc,COALESCE(s.payment,'') payment FROM installments i LEFT JOIN sales s ON s.id=i.sale_id WHERE i.cari_id=? AND i.due_date BETWEEN ? AND ? AND (?='Taksit Ödeme Planı' OR LOWER(COALESCE(s.payment,'')) LIKE '%senet%' OR LOWER(COALESCE(s.payment,'')) LIKE '%taksit%') ORDER BY i.due_date,i.id",(cid,a,b,title));out.append(f"{'NO':4} {'SENET NO':16} {'BELGE':12} {'VADE':12} {'TUTAR':>13} {'ÖDENEN':>13} {'KALAN':>13}  DURUM");ta=tp=0
    seen_installments=set()
    for no,r in enumerate(rows,1):
     seen_installments.add(int(r['id']));amt=float(r['amount'] or 0);paid=float(r['paid'] or 0);ta+=amt;tp+=paid;senet=('SNT-'+str(r['sale_id'])+'-'+str(no).zfill(2)) if title=='Senet Ödeme Planı' else '-'
     durum=('ÖDENDİ' if paid>=amt-0.005 else ('KISMİ ÖDENDİ' if paid>0.005 else ('GECİKMİŞ' if str(r['due_date'])<today() else 'BEKLİYOR')))
     out.append(f"{no:<4} {senet[:16]:16} {str(r['doc'])[:12]:12} {r['due_date']:12} {money(amt):>13} {money(paid):>13} {money(max(amt-paid,0)):>13}  {durum}")
    if title=='Senet Ödeme Planı':
     manual=DX.rows("SELECT id,number,due_date,amount,status,note FROM checks_notes WHERE cari_id=? AND due_date BETWEEN ? AND ? AND kind='Alınan Senet' AND (installment_id IS NULL OR installment_id=0) ORDER BY due_date,id",(cid,a,b))
     base=len(rows)
     for ix,r in enumerate(manual,base+1):
      amt=float(r['amount'] or 0);cancelled='iptal' in str(r['status'] or '').lower();paid=0.0;remain=0.0 if cancelled else amt;ta+=0 if cancelled else amt
      durum='İPTAL EDİLDİ' if cancelled else ('GECİKMİŞ' if str(r['due_date'] or '')<today() else str(r['status'] or 'PORTFÖYDE').upper())
      out.append(f"{ix:<4} {str(r['number'] or '')[:16]:16} {'MANUEL':12} {str(r['due_date'] or '')[:12]:12} {money(amt):>13} {money(paid):>13} {money(remain):>13}  {durum}")
    out+=['-'*width,f"GENEL TOPLAM   Tutar: {money(ta)}   Ödenen: {money(tp)}   Kalan: {money(ta-tp)}"]
   else:
    rows=DX.rows('SELECT dt,kind,debit,credit,source,note FROM cari_moves WHERE cari_id=? AND substr(dt,1,10) BETWEEN ? AND ? ORDER BY dt,id',(cid,a,b));opening=DX.one('SELECT COALESCE(SUM(debit-credit),0) b FROM cari_moves WHERE cari_id=? AND substr(dt,1,10)<?',(cid,a));run=float(opening['b'] or 0);td=tc=0
    out.append(f"Önceki Bakiye: {money(run)}");out.append(f"{'TARİH':19} {'İŞLEM':18} {'BORÇ':>13} {'ALACAK':>13} {'BAKİYE':>13}  AÇIKLAMA")
    for r in rows:d=float(r['debit'] or 0);cr=float(r['credit'] or 0);td+=d;tc+=cr;run+=d-cr;out.append(f"{str(r['dt'])[:19]:19} {str(r['kind'] or '')[:18]:18} {money(d):>13} {money(cr):>13} {money(run):>13}  {str(r['note'] or '')[:28]}")
    out+=['-'*width,f"TOPLAM BORÇ: {money(td)}    TOPLAM ALACAK: {money(tc)}    KALAN BAKİYE: {money(run)}"]
   current['text']='\n'.join(out);tx.config(state='normal');tx.delete('1.0','end');tx.insert('1.0',current['text']);tx.config(state='disabled')
   if title in ('Cari Hesap Ekstresi','Cari Hareket Dökümü'):
    tx.pack_forget()
    statement_area.pack(fill='both',expand=True,padx=14,pady=(0,8))
    for item in statement_tree.get_children():statement_tree.delete(item)
    statement_summary.set('CARİ: '+str(c['title'])+'    |    DÖNEM: '+a+' — '+b+'    |    ÖNCEKİ BAKİYE: '+money(float(opening['b'] or 0)))
    running=float(opening['b'] or 0)
    for index,r in enumerate(rows):
     debit=float(r['debit'] or 0);credit=float(r['credit'] or 0)
     running+=debit-credit
     statement_tree.insert('','end',values=(report_display_datetime(r['dt']),
      str(r['kind'] or ''),money(debit),money(credit),money(running),
      _kaynak_tr(r['source']),str(r['note'] or '')),
      tags=('alternate',) if index%2 else ())
    statement_tree.tag_configure('alternate',background='#f1f6fd')
    statement_total.set('TOPLAM KAYIT: '+str(len(rows))+'     BORÇ: '+money(td)+'     ALACAK: '+money(tc)+'     KAPANIŞ BAKİYESİ: '+money(run))
   else:
    statement_area.pack_forget()
    tx.pack(fill='both',expand=True,padx=14,pady=(0,8))
  def central_print():
    # Finansal raporlarda metin satiri degil, gercek tablo kolonlari tasarimciya aktarilir.
    try:
     build_text()
     title=report.get()
     a=_date_iso(start.get().strip()) if start.get().strip() else '1900-01-01'
     b=_date_iso(end.get().strip()) if end.get().strip() else '2999-12-31'
     if title in ('Taksit Ödeme Planı','Senet Ödeme Planı'):
      heads=('No','Senet No','Belge No','Vade Tarihi','Taksit Tutarı','Ödenen','Kalan','Durum')
      records=DX.rows("SELECT i.id,i.sale_id,i.due_date,i.amount,i.paid,i.status,COALESCE(s.doc_no,'') doc,COALESCE(s.payment,'') payment FROM installments i LEFT JOIN sales s ON s.id=i.sale_id WHERE i.cari_id=? AND i.due_date BETWEEN ? AND ? AND (?='Taksit Ödeme Planı' OR LOWER(COALESCE(s.payment,'')) LIKE '%senet%' OR LOWER(COALESCE(s.payment,'')) LIKE '%taksit%') ORDER BY i.due_date,i.id",(cid,a,b,title))
      data=[]
      for no,r in enumerate(records,1):
       amt=float(r['amount'] or 0);paid=float(r['paid'] or 0)
       senet=('SNT-'+str(r['sale_id'])+'-'+str(no).zfill(2)) if title=='Senet Ödeme Planı' else '-'
       durum=('ÖDENDİ' if paid>=amt-0.005 else ('KISMİ ÖDENDİ' if paid>0.005 else ('GECİKMİŞ' if str(r['due_date'])<today() else 'BEKLİYOR')))
       data.append((no,senet,str(r['doc'] or ''),report_display_datetime(r['due_date'],True),money(amt),money(paid),money(max(amt-paid,0)),durum))
      if title=='Senet Ödeme Planı':
       manual=DX.rows("SELECT id,number,due_date,amount,status,note FROM checks_notes WHERE cari_id=? AND due_date BETWEEN ? AND ? AND kind='Alınan Senet' AND (installment_id IS NULL OR installment_id=0) ORDER BY due_date,id",(cid,a,b))
       for r in manual:
        amt=float(r['amount'] or 0);cancelled='iptal' in str(r['status'] or '').lower()
        durum='İPTAL EDİLDİ' if cancelled else ('GECİKMİŞ' if str(r['due_date'] or '')<today() else str(r['status'] or 'PORTFÖYDE').upper())
        data.append((len(data)+1,str(r['number'] or ''),'MANUEL',report_display_datetime(r['due_date'],True),money(amt),money(0),money(0 if cancelled else amt),durum))
     else:
      heads=('Tarih / Saat','İşlem','Borç','Alacak','Bakiye','Kaynak','Açıklama',
             'Cari Unvanı','İşlem No','İşlem Tarihi','İşlem Saati','Önceki Bakiye')
      records=DX.rows('SELECT id,dt,kind,debit,credit,source,note FROM cari_moves WHERE cari_id=? AND substr(dt,1,10) BETWEEN ? AND ? ORDER BY dt,id',(cid,a,b))
      opening=DX.one('SELECT COALESCE(SUM(debit-credit),0) b FROM cari_moves WHERE cari_id=? AND substr(dt,1,10)<?',(cid,a))
      running=float(opening['b'] or 0);data=[]
      for r in records:
       debit=float(r['debit'] or 0);credit=float(r['credit'] or 0)
       previous=running
       running+=debit-credit
       dt=str(r['dt'] or '')
       data.append((report_display_datetime(r['dt']),str(r['kind'] or ''),money(debit),money(credit),money(running),_kaynak_tr(r['source']),str(r['note'] or ''),
        str(c['title'] or ''),str(r['id']),report_display_datetime(dt,True),
        dt[11:19] if len(dt)>=16 else '',money(previous)))
     tree=ttk.Treeview(w,columns=tuple(str(i) for i in range(len(heads))),show='headings')
     for i,h in enumerate(heads):
      tree.heading(str(i),text=h);tree.column(str(i),width=125,anchor='e' if h in ('Borç','Alacak','Bakiye','Taksit Tutarı','Ödenen','Kalan') else 'w')
     for row in data:tree.insert('','end',values=row)
     tree._alfabe_report_title=title+' - '+str(c['title'])
     tree._alfabe_report_key='Cari Çıktı / '+title+(' / '+str(c['title']) if title=='Cari Hesap Ekstresi' else '')
     _open_tree_print_center(tree)
    except Exception as exc:
     log_error('Cari cikti merkezi profesyonel yazdirma',exc)
     messagebox.showerror(APP,'Merkezi Yazdırma açılamadı:\n'+str(exc),parent=w)
  def print_preview():
   if report.get() in ('Cari Hesap Ekstresi','Cari Hareket Dökümü'):
    return central_print()
   build_text();safe=html.escape(current['text']);page='A4 landscape' if orientation.get()=='Yatay' else 'A4 portrait';doc=f'''<!doctype html><html lang="tr"><head><meta charset="utf-8"><title>{html.escape(report.get())}</title><style>@page{{size:{page};margin:12mm}}body{{font-family:Consolas,"Courier New",monospace;font-size:10px;color:#000}}pre{{white-space:pre-wrap}}@media print{{button{{display:none}}}}</style></head><body>{_a4_structured_body(safe, 'CARİ ÇIKTI')}<script>window.onload=()=>setTimeout(()=>window.print(),350)</script></body></html>''';p=_DATA_BASE/'cari_cikti_onizleme.html';p.write_text(doc,encoding='utf-8');webbrowser.open(p.as_uri(),new=1)
  def save_csv():
   p=filedialog.asksaveasfilename(parent=w,title='Cari çıktısını kaydet',defaultextension='.txt',filetypes=[('Metin belgesi','*.txt'),('Tüm dosyalar','*.*')],initialfile='cari_'+str(cid)+'_'+report.get().lower().replace(' ','_')+'.txt')
   if p:Path(p).write_text(current['text'],encoding='utf-8');messagebox.showinfo(APP,'Dosya kaydedildi:\n'+p,parent=self)
