def next_doc(prefix):
 # Ortak belge numarası: sayaç güncellemesi aynı veritabanında güvenli yapılır.
 yr=str(datetime.date.today().year)
 con=DX.con()
 try:
  con.execute('BEGIN IMMEDIATE')
  row=con.execute('SELECT last_no FROM counters WHERE prefix=? AND period=?',(prefix,yr)).fetchone()
  n=(int(row['last_no']) if row else 0)+1
  con.execute('INSERT INTO counters(prefix,period,last_no) VALUES(?,?,?) ON CONFLICT(prefix,period) DO UPDATE SET last_no=excluded.last_no',(prefix,yr,n))
  con.commit()
  return f'{prefix}-{yr}-{n:06d}'
 except:
  con.rollback(); raise
 finally:
  con.close()


def _alfabe_cursor_end(ed):
 """Düzenleme kutusunda imleci değerin sonuna koyar (tüm değer seçili kalır).
 Pencere yerleştirme/odak olayları imleci başa alırsa diye birkaç kez tekrarlanır."""
 def put():
  try:
   if not ed.winfo_exists():return
   ed.selection_range(0,'end');ed.icursor('end')
  except tk.TclError:pass
 put()
 for ms in (1,50,150):
  try:ed.after(ms,put)
  except tk.TclError:pass
 try:ed.bind('<FocusIn>',lambda e:put(),add='+')
 except tk.TclError:pass

def _alfabe_click_column(tree,event):
 """Tıklanan hücrenin (satır iid, sütun adı) bilgisini verir; başlık/boş alanda (None,None)."""
 try:
  if tree.identify_region(event.x,event.y)!='cell':return None,None
  row=tree.identify_row(event.y);col=tree.identify_column(event.x)
  if not row or not col:return None,None
  names=list(tree['columns']);dc=tree['displaycolumns']
  if isinstance(dc,str):dc=(dc,)
  vis=names if (not dc or tuple(dc)==('#all',)) else [names[int(d)] if str(d).isdigit() else str(d) for d in dc]
  i=int(col[1:])-1
  return (row,vis[i]) if 0<=i<len(vis) else (None,None)
 except Exception:return None,None

def _alfabe_inline_cell_editor(tree,row,col,initial,commit,values=None,after=None):
 """Tablo hücresini tıklanan yerde düzenler. Enter/başka yere tıklama kaydeder, Esc vazgeçer.
 commit(metin) yalnız değer değiştiyse çağrılır. after() yalnız Enter sonrası çalışır."""
 try:
  old=getattr(tree,'_alfabe_inline_ed',None)
  if old is not None and old.winfo_exists():old.destroy()
 except tk.TclError:pass
 tree._alfabe_inline_ed=None
 try:box=tree.bbox(row,col)
 except tk.TclError:return None
 if not box:return None
 bx,by,bw,bh=box;var=tk.StringVar(value=str(initial));state={'done':False}
 if values is not None:ed=ttk.Combobox(tree,textvariable=var,values=list(values),state='readonly',font=('Segoe UI',11))
 else:ed=tk.Entry(tree,textvariable=var,justify='right',font=('Segoe UI',11))
 def finish(apply=True,refocus=False):
  if state['done']:return 'break'
  state['done']=True;text=var.get()
  try:ed.destroy()
  except tk.TclError:pass
  tree._alfabe_inline_ed=None
  if apply and str(text).strip()!=str(initial).strip():commit(text)
  if refocus and after is not None:
   try:after()
   except Exception as _se:_silent(_se)
  return 'break'
 ed.bind('<Return>',lambda e:finish(True,True));ed.bind('<KP_Enter>',lambda e:finish(True,True))
 ed.bind('<Escape>',lambda e:finish(False))
 if values is not None:ed.bind('<<ComboboxSelected>>',lambda e:finish(True,True))
 else:ed.bind('<FocusOut>',lambda e:finish(True))
 if not getattr(tree,'_alfabe_inline_bound',False):
  tree._alfabe_inline_bound=True
  def _cancel_combo(e):
   o=getattr(tree,'_alfabe_inline_ed',None)
   if o is not None and isinstance(o,ttk.Combobox):
    try:o.destroy()
    except tk.TclError:pass
    tree._alfabe_inline_ed=None
  tree.bind('<Button-1>',_cancel_combo,add='+')
 tree._alfabe_inline_ed=ed
 ed.place(x=bx,y=by,width=bw,height=bh);ed.focus_set()
 try:
  if values is None:_alfabe_cursor_end(ed)
  else:ed.event_generate('<Button-1>')
 except Exception as _se:_silent(_se)
 return ed

def _alfabe_attach_live_stock_suggestions(parent,entry,query_var,on_choose,on_enter=None):
 """Independent popup above sibling widgets; never changes document or stock logic."""
 popup=tk.Toplevel(entry)
 popup.withdraw()
 popup.overrideredirect(True)
 popup.transient(entry.winfo_toplevel())
 frame=tk.Frame(popup,bg='white',bd=1,relief='solid')
 frame.pack(fill='both',expand=True)
 tree=ttk.Treeview(frame,columns=('name','qty','price'),show='headings',height=6,selectmode='browse')
 for col,label,width in [('name','Ürün adı',330),('qty','Stok',75),('price','Fiyat',95)]:
  tree.heading(col,text=label);tree.column(col,width=width,anchor='w')
 tree.pack(side='left',fill='both',expand=True)
 sb=ttk.Scrollbar(frame,orient='vertical',command=tree.yview)
 sb.pack(side='right',fill='y');tree.configure(yscrollcommand=sb.set)
 pending=[None]; quiet=[0.0]
 def exact_find(term):
  # Barkod / stok kodu / ek barkod ile TAM eşleşen ürün (varsa aktif olan öncelikli).
  try:
   return DX.one('SELECT * FROM stock WHERE barcode=? OR code=? OR id IN (SELECT stock_id FROM stock_barcodes WHERE active=1 AND barcode=?) ORDER BY active DESC LIMIT 1',(term,term,term))
  except Exception:return None
 def hide():
  try:popup.withdraw()
  except tk.TclError:pass
 def show():
  pending[0]=None
  try:
   if not entry.winfo_exists() or not entry.winfo_viewable():hide();return
   term=query_var.get().strip()
   if not term or _alf_time.time()<quiet[0]:hide();return
   # Tam barkod yazıldı/okutuldu: ürün zaten bulundu, liste açmaya gerek yok; Enter doğrudan ekler.
   if len(term)>=8 and term.isdigit() and exact_find(term):hide();return
   pat='%'+term+'%'
   rows=DX.rows('SELECT * FROM stock WHERE name LIKE ? OR brand LIKE ? OR barcode LIKE ? OR code LIKE ? OR id IN (SELECT stock_id FROM stock_barcodes WHERE active=1 AND barcode LIKE ?) ORDER BY name LIMIT 50',(pat,pat,pat,pat,pat))
   tree.delete(*tree.get_children())
   for r in rows:
    title=('[PASİF] ' if not r['active'] else '')+str(r['name'])
    tree.insert('','end',iid=str(r['id']),values=(title,qty_display(r['qty']),money(r['retail'])))
   if not rows:hide();return
   entry.update_idletasks()
   screen_w=entry.winfo_screenwidth();screen_h=entry.winfo_screenheight()
   x=entry.winfo_rootx();below=entry.winfo_rooty()+entry.winfo_height()
   width=min(680,max(400,entry.winfo_width()),screen_w-20)
   height=min(210,screen_h-70)
   x=max(0,min(x,screen_w-width-8))
   y=below if below+height+10<=screen_h else max(0,entry.winfo_rooty()-height)
   popup.geometry(f'{width}x{height}+{x}+{y}')
   popup.deiconify();popup.lift()
  except tk.TclError:hide()
 def changed(*_):
  if pending[0] is not None:
   try:entry.after_cancel(pending[0])
   except tk.TclError:pass
  pending[0]=entry.after(120,show)
 def choose(event=None):
  selected=tree.selection()
  if not selected and tree.get_children():
   selected=(tree.get_children()[0],)
  if not selected:return 'break'
  r=DX.one('SELECT * FROM stock WHERE id=?',(int(selected[0]),))
  hide()
  if r:
   quiet[0]=_alf_time.time()+0.7   # seçimden sonra metin değişince liste yeniden açılmasın
   on_choose(r)
   try:entry.icursor('end')
   except tk.TclError:pass
   if event is not None and getattr(event,'keysym','') in ('Return','KP_Enter') and on_enter is not None:
    entry.after_idle(on_enter)
  entry.focus_set()
  return 'break'
 def arrows(event):
  if event.keysym=='Down' and popup.state()=='normal' and tree.get_children():
   first=tree.get_children()[0];tree.selection_set(first);tree.focus(first);tree.focus_set();return 'break'
 def tree_keys(event):
  if event.keysym in ('Return','KP_Enter'):return choose(event)
  if event.keysym=='Escape':hide();entry.focus_set();return 'break'
 def entry_return(event=None):
  try:
   visible=popup.state()=='normal' and bool(tree.get_children())
  except tk.TclError:
   visible=False
  _term=query_var.get().strip()
  if _term and not tree.selection():
   _x=exact_find(_term)
   if _x is not None:
    hide();quiet[0]=_alf_time.time()+0.7
    on_choose(_x)
    if on_enter is not None:entry.after_idle(on_enter)
    return 'break'
  if visible:
   selected=tree.selection()
   if not selected and tree.get_children():
    first=tree.get_children()[0]
    tree.selection_set(first);tree.focus(first)
   return choose(event)
  if on_enter is not None:
   on_enter()
  return 'break'
 # Replace prior Return handlers: the suggestion picker must get first chance.
 entry.bind('<Return>',entry_return)
 entry.bind('<KP_Enter>',entry_return)
 entry.bind('<Down>',arrows,add='+')
 entry.bind('<Escape>',lambda event:hide(),add='+')
 def _click_pick(e):
  choose(e)
  if on_enter is not None:entry.after_idle(on_enter)
  return 'break'
 alf_tek_tik(tree,_click_pick)
 tree.bind('<Return>',tree_keys)
 tree.bind('<KP_Enter>',tree_keys)
 tree.bind('<Escape>',tree_keys)
 query_var.trace_add('write',changed)
 return hide

