  self.saved_lbl=tk.Label(totals,text='',bg='white',fg='#15803d',font=('Segoe UI',12,'bold'),anchor='e',justify='right');self.saved_lbl.pack(fill='x',padx=15,pady=(0,10));self._kaydedildi=False
  # Taksit/senet alanı
