  row(f2,'Taksit Sayısı',cnt);row(f2,'İlk Taksit Tarihi',first);combo_row('Vade Aralığı',interval,['Aylık','15 Gün','30 Gün','45 Gün','60 Gün','90 Gün']);combo_row('Vade Farkı Uygulaması',mode,['Vade Farkı Yok','Toplam Tutara Vade Farkı Uygula','Peşinat Hariç Kalan Tutara Vade Farkı Uygula','Aylık Vade Farkı Uygula']);row(f2,'Vade Farkı Oranı (%)',rate)
