 def change_document_price(self):
  if self._kayitli_kilidi():return
  selection=self.t.selection()
  if not selection:return messagebox.showwarning(APP,'Önce bir ürün satırı seçiniz.',parent=self.winfo_toplevel())
  try:i=int(selection[0]);x=self.lines[i]
  except (ValueError,IndexError,KeyError):return
  def check(p):
   cost=float(x.get('cost') or 0);vat=float(x.get('vat') or 0);disc=float(x.get('disc') or 0)
   if cost>0 and p*(1-disc/100)/(1+vat/100)<cost:
    return messagebox.askyesno(APP,'İskonto sonrası satış fiyatı maliyetin altında. Devam edilsin mi?',parent=self.winfo_toplevel())
   return True
  price=_alfabe_document_unit_price(self,x['name'],x['price'],'Cari Satış',check,line=x)
  if price is None:return
  _o=float(x.get('_alf_orig_price') or x.get('price') or 0);x.setdefault('_alf_orig_price',_o);_q=abs(float(x.get('qty') or 1)) or 1
  if price<_o-0.004 and not _gv().check_discount(self.winfo_toplevel(),_o*_q,(_o-price)*_q):return
  x['price']=price;x['total']=round(float(x['qty'])*price*(1-float(x.get('disc',0))/100),2)
  x['_alfabe_special_price']=True
  self._installment_plan=None
  self.refresh_lines()
  if self.t.exists(str(i)):self.t.selection_set(str(i))

 # 461.59: Cari Satış'ta seçili satırın birimini ADET/KUTU/KOLİ arasında değiştirme (alt şerit + Ctrl+1/2/3).
 def _ubar_units(self,x):
  if not x or not x.get('stock_id'):return []
  zs=DX.rows('SELECT unit_name,base_quantity,retail,barcode FROM stock_unit_conversions WHERE stock_id=? AND base_quantity>0 ORDER BY base_quantity,unit_name',(x['stock_id'],))
  if not zs:return []
  out=[(str(x.get('unit') or 'Adet').upper() if abs(float(x.get('_ufac',1.0) or 1.0)-1)<1e-9 else 'ADET',1.0,0.0,'')]
  for z in zs[:2]:out.append((str(z['unit_name'] or '').strip().upper(),float(z['base_quantity']),float(z['retail'] or 0),str(z['barcode'] or '').strip()))
  return out
 def _ubar_cur(self):
  try:
   s=self.t.selection()
   if not s:return None
   i=int(s[0]);return i if 0<=i<len(self.lines) else None
  except Exception:return None
 def _ubar_refresh(self):
  try:
   bar=self._ubar
   if not bar.winfo_exists():return
   i=self._ubar_cur();us=self._ubar_units(self.lines[i]) if i is not None else []
   for w in bar.winfo_children():w.destroy()
   if len(us)<2 or getattr(self,'_kaydedildi',False):bar.pack_forget();return
   x=self.lines[i];cur=float(x.get('_ufac',1.0) or 1.0)
   tk.Label(bar,text=f"Seçili satır: {str(x.get('name',''))[:40]}   Birim:",bg='#eaf2fb',fg='#0b2c55',font=('Segoe UI',11)).pack(side='left',padx=(8,6),pady=4)
   for n,(nm,f,_p,_b) in enumerate(us):
    on=abs(f-cur)<1e-9
    lab=nm if n==0 else f'{nm} ({f:g})'
    tk.Button(bar,text=f'{lab}  Ctrl+{n+1}',command=(lambda k=n:self._set_line_unit(k)),bg=('#0b5cad' if on else 'white'),fg=('white' if on else '#0b5cad'),relief='solid',bd=1,font=('Segoe UI',11,'bold'),padx=10,pady=3).pack(side='left',padx=3,pady=3)
   if not bar.winfo_ismapped():bar.pack(fill='x',after=self._ubar_after,pady=(4,0))
  except tk.TclError:pass
  except Exception as _se:_silent(_se)
 def _set_line_unit(self,k):
  # Miktar sayısı aynı kalır; birim ve birim fiyat değişir. Stok temel birim (adet) cinsinden tutulur.
  try:
   if self._kayitli_kilidi(False):return
   i=self._ubar_cur()
   if i is None:return
   x=self.lines[i];us=self._ubar_units(x)
   if k<0 or k>=len(us):return
   if x.get('_alfabe_special_price'):return   # elle fiyat bozulmasın
   nm,fac,upr,ubc=us[k];cur=float(x.get('_ufac',1.0) or 1.0)
   if abs(fac-cur)<1e-9:return
   r=DX.one('SELECT * FROM stock WHERE id=?',(x['stock_id'],))
   if not r:return
   n=float(x['qty'])/cur;disc=float(x.get('disc',0) or 0)
   if k==0:
    x['price']=QuickSale._tier_price(r,tier_of_customer(self.customer_id));x['note']='';x['barcode']=r['barcode'] or '';x['_ubc']=None
   else:
    _z=unit_row(x['stock_id'],nm)
    x['price']=unit_base_price(r,_z,tier_of_customer(self.customer_id)) if _z is not None else QuickSale._tier_price(r,tier_of_customer(self.customer_id))
    x['note']=f'{n:g} {nm} x {fac:g}'
    if ubc:x['barcode']=ubc;x['_ubc']=ubc
    else:x['_ubc']=None
   x['qty']=n*fac;x['_ufac']=fac;x['_uname']=nm
   x['total']=x['qty']*x['price']*(1-disc/100)
   m=next((y for j,y in enumerate(self.lines) if j!=i and y.get('stock_id')==x['stock_id'] and abs(float(y.get('_ufac',1.0) or 1.0)-fac)<1e-9 and abs(float(y.get('price',0))-x['price'])<1e-6 and abs(float(y.get('disc',0) or 0)-disc)<1e-6 and not y.get('_alfabe_special_price')),None)
   if m is not None:
    m['qty']=float(m['qty'])+x['qty'];m['total']=m['qty']*m['price']*(1-disc/100)
    if fac!=1.0:m['note']=f"{m['qty']/fac:g} {nm} x {fac:g}"
    self.lines.pop(i);i=self.lines.index(m)
   self._installment_plan=None
   self.refresh_lines()
   if self.t.exists(str(i)):self.t.selection_set(str(i))
  except Exception as ex:log_error('Cari Satış birim değiştirme',ex)
 def refresh_lines(self):
  self.after_idle(self._ubar_refresh)
  self.t.delete(*self.t.get_children()); gross=disc=vat=0
  for i,r in enumerate(self.lines):
   before=r['qty']*r['price']; d=before-r['total']; gross+=before; disc+=d; vat+=r['total']*(r['vat']/(100+r['vat'])) if r['vat'] else 0
   self.t.insert('','end',iid=str(i),values=(r['code'],r['barcode'],r['name']+(f"  [{r['note']}]" if r.get('note') else ''),f"{float(r['qty']):g}",r['unit'],money(r['price']),r['disc'],r['vat'],money(r['total']/r['qty']),money(r['total'])))
  total=gross-disc
  # v1.2.291.265: KDV dahil ara toplam - iskonto = genel toplam; genel toplamın içindeki KDV hariç tutar ve KDV ayrıca gösterilir.
  self.total_lbl.config(text=f"{len(self.lines)} kalem / {sum(float(r['qty']) for r in self.lines):g} adet\n\nARA TOPLAM (KDV dahil)\n{money(gross)}\n\nİSKONTO\n{money(disc)}\n\nKDV HARİÇ TUTAR\n{money(total-vat)}\n\nKDV TUTARI\n{money(vat)}")
  self.grand_lbl.config(text=money(total));self._sale_total_now=total
  try:self._update_projection()
  except Exception as _se:_silent(_se)
 def _edit_line_cell(self,event):
  if getattr(self,'_kaydedildi',False):return
  # Miktar, Birim ve Birim Fiyat hücrelerine tıklayınca yerinde düzenle.
  if self.t.identify_region(event.x,event.y)!='cell':return
  row=self.t.identify_row(event.y); col=self.t.identify_column(event.x)
  if not row or col not in ('#4','#5','#6'):return
  try:idx=int(row); r=self.lines[idx]
  except Exception:return
  try:
   if self._line_editor is not None and self._line_editor.winfo_exists():self._line_editor.destroy()
  except Exception as _se:_silent(_se)
  box=self.t.bbox(row,col)
  if not box:return
  x,y,w,h=box
  if col=='#4':
   var=tk.StringVar(value=f"{float(r['qty']):g}")
   ed=tk.Spinbox(self.t,textvariable=var,from_=0.001,to=999999,increment=1,justify='center',font=('Segoe UI',11))
   def save_qty(_e=None):
    q=fnum(var.get())
    if q<=0:return
    r['qty']=q; r['total']=q*float(r['price'])*(1-float(r.get('disc',0))/100); self._installment_plan=None
    try:ed.destroy()
    except Exception as _se:_silent(_se)
    self._line_editor=None; self.refresh_lines()
   ed.bind('<Return>',save_qty); ed.bind('<FocusOut>',save_qty)
  elif col=='#5':
   vals=[z['unit'] for z in DX.rows("SELECT DISTINCT unit FROM stock WHERE active=1 AND COALESCE(unit,'')<>'' ORDER BY unit")]
   for u in ('ADET','KOLİ','KUTU','PAKET','SET'):
    if u not in vals:vals.append(u)
   var=tk.StringVar(value=str(r.get('unit') or 'ADET'))
   ed=ttk.Combobox(self.t,textvariable=var,values=vals,state='readonly',font=('Segoe UI',11))
   def save_unit(_e=None):
    r['unit']=var.get() or r.get('unit') or 'ADET'
    try:ed.destroy()
    except Exception as _se:_silent(_se)
    self._line_editor=None; self.refresh_lines()
   ed.bind('<<ComboboxSelected>>',save_unit); ed.bind('<Return>',save_unit); ed.bind('<FocusOut>',save_unit)
  if col=='#6':
   var=tk.StringVar(value=f"{float(r['price']):.2f}".replace('.',','))
   ed=tk.Entry(self.t,textvariable=var,justify='right',font=('Segoe UI',11));done=[False]
   def cancel_price(_e=None):
    done[0]=True
    try:ed.destroy()
    except Exception as _se:_silent(_se)
    self._line_editor=None;return 'break'
   def save_price(_e=None):
    if done[0]:return
    done[0]=True;p=fnum(var.get());old=float(r['price'])
    try:ed.destroy()
    except Exception as _se:_silent(_se)
    self._line_editor=None
    if p>0 and abs(p-old)>=0.000001:
     cost=float(r.get('cost') or 0);vat=float(r.get('vat') or 0);disc=float(r.get('disc',0) or 0)
     if cost>0 and p*(1-disc/100)/(1+vat/100)<cost and not messagebox.askyesno(APP,'İskonto sonrası satış fiyatı KDV hariç maliyetin altında. Devam edilsin mi?',parent=self.winfo_toplevel()):p=None
     if p is not None:
      r['price']=p;r['total']=round(float(r['qty'])*p*(1-disc/100),2);r['_alfabe_special_price']=True;self._installment_plan=None
    self.refresh_lines()
    if getattr(_e,'keysym','') in ('Return','KP_Enter'):self.after_idle(self.barcode_entry.focus_set)
   ed.bind('<Return>',save_price);ed.bind('<KP_Enter>',save_price);ed.bind('<FocusOut>',save_price);ed.bind('<Escape>',cancel_price)
  self._line_editor=ed; ed.place(x=x,y=y,width=w,height=h); ed.focus_set()
  try:
   if col in ('#4','#6'):_alfabe_cursor_end(ed)
   else:ed.event_generate('<Button-1>')
  except Exception as _se:_silent(_se)

 def apply_discount(self):
  if self._kayitli_kilidi():return
  # v1.2.232 - Modern Cari Satış F8 iskonto merkezi.
  # İskontolar satırların net toplamına dağıtılır; böylece kayıt/rapor/iade motoru
  # mevcut sale_lines discount + total alanlarını kullanmaya devam eder.
  owner=self._window()
  if not self.lines:
   messagebox.showinfo(APP,'İskonto uygulamak için önce ürün ekleyin.',parent=owner); return
  w=new_toplevel(owner); w.title('İskonto Uygula'); w.geometry('1080x690'); w.minsize(980,620); w.configure(bg='#eef5fc'); w.transient(owner); w.grab_set()
  try:w.lift();w.focus_force()
  except Exception as _se:_silent(_se)
  base=[]
  for r in self.lines:
   gross=float(r['qty'])*float(r['price']); cur=float(r.get('total',gross)); base.append((r,gross,cur))
  gross0=sum(x[1] for x in base); current_total=sum(x[2] for x in base)
  tk.Label(w,text='İSKONTO UYGULA',bg='#0b3158',fg='white',font=('Segoe UI',22,'bold'),anchor='w',padx=22).pack(fill='x',ipady=14)
  main=tk.Frame(w,bg='#eef5fc'); main.pack(fill='both',expand=True,padx=18,pady=14)
  left=tk.Frame(main,bg='#eef5fc'); left.pack(side='left',fill='both',expand=True,padx=(0,10))
  right=tk.Frame(main,bg='#eef5fc',width=330); right.pack(side='right',fill='y'); right.pack_propagate(False)
  mode=tk.StringVar(value='general'); general=tk.StringVar(); amount=tk.StringVar(); target=tk.StringVar(); d1=tk.StringVar(); d2=tk.StringVar(); d3=tk.StringVar()
  def panel(title,value,bg):
   f=tk.LabelFrame(left,text=title,bg=bg,fg='#123b68',font=('Segoe UI',12,'bold'),bd=1,relief='solid'); f.pack(fill='x',pady=5,ipadx=8,ipady=5); return f
  f1=panel('1. GENEL CARİ İSKONTOSU  (Tüm Satışa)','#fff','#eaf3ff'); tk.Radiobutton(f1,text='Cari İskonto %',variable=mode,value='general',bg='#eaf3ff',font=('Segoe UI',11,'bold')).pack(side='left',padx=12,pady=12); tk.Entry(f1,textvariable=general,width=12,justify='right',font=('Segoe UI',13,'bold')).pack(side='right',padx=16)
  f2=panel('2. TUTAR İSKONTOSU  (Tüm Satışa)','#fff','#edf9ed'); tk.Radiobutton(f2,text='İskonto Tutarı',variable=mode,value='amount',bg='#edf9ed',font=('Segoe UI',11,'bold')).pack(side='left',padx=12,pady=12); tk.Entry(f2,textvariable=amount,width=12,justify='right',font=('Segoe UI',13,'bold')).pack(side='right',padx=16)
  f3=panel('3. İSKONTOLU TOPLAM TUTAR','#fff','#fff1e7'); tk.Radiobutton(f3,text='Satışın Son Toplamı',variable=mode,value='target',bg='#fff1e7',font=('Segoe UI',11,'bold')).pack(side='left',padx=12,pady=12); tk.Entry(f3,textvariable=target,width=12,justify='right',font=('Segoe UI',13,'bold')).pack(side='right',padx=16)
  f4=panel('4. SATIR / ÜRÜN İSKONTOSU  (Seçili Ürüne)','#fff','#f3edff'); tk.Radiobutton(f4,text='İskonto 1 %',variable=mode,value='line',bg='#f3edff',font=('Segoe UI',10,'bold')).pack(side='left',padx=(12,4),pady=12)
  for lab,var in [('1',d1),('2',d2),('3',d3)]: tk.Label(f4,text=lab+'. %',bg='#f3edff').pack(side='left',padx=(7,2)); tk.Entry(f4,textvariable=var,width=7,justify='right').pack(side='left',padx=2)
  summary=tk.LabelFrame(right,text='SATIŞ ÖZETİ (Güncel)',bg='white',font=('Segoe UI',12,'bold')); summary.pack(fill='x',pady=(0,10))
  sumlbl=tk.Label(summary,bg='white',fg='#102f55',font=('Segoe UI',12,'bold'),justify='left',anchor='nw'); sumlbl.pack(fill='x',padx=14,pady=14)
  quick=tk.LabelFrame(right,text='HIZLI İŞLEMLER',bg='white',font=('Segoe UI',11,'bold')); quick.pack(fill='x')
  qf=tk.Frame(quick,bg='white');qf.pack(fill='x',padx=8,pady=8)
  def qset(v):mode.set('general');general.set(str(v));preview()
  for i,v in enumerate((0,5,10,15,20,25,30)): tk.Button(qf,text=f'%{v}',command=lambda z=v:qset(z),width=7).grid(row=i//4,column=i%4,padx=3,pady=3)
  info=tk.Label(right,text='İskonto önceliği:\n1) Satır/Ürün isk.\n2) Genel cari isk.\n3) Tutar / hedef toplam\n\nTutarlar KDV dahil hesaplanır.',bg='#eaf3ff',fg='#174a7e',justify='left',anchor='w',font=('Segoe UI',10,'bold'));info.pack(fill='x',pady=10,ipadx=10,ipady=10)
  def calc():
   vals=[x[2] for x in base]
   m=mode.get()
   if m=='line':
    sel=self.t.selection()
    if not sel: raise ValueError('Satır/Ürün iskontosu için önce satış ekranından bir ürün satırı seçin.')
    idx=int(sel[0]); pcts=[max(0,min(fnum(v.get()),100)) for v in (d1,d2,d3)]; net=base[idx][1]
    for pct in pcts: net*=1-pct/100
    vals[idx]=net
   elif m=='general':
    pct=max(0,min(fnum(general.get()),100)); vals=[v*(1-pct/100) for v in vals]
   elif m=='amount':
    disc=max(0,fnum(amount.get())); tot=sum(vals)
    if disc>tot+0.0001: raise ValueError('İskonto tutarı satış toplamından büyük olamaz.')
    factor=(tot-disc)/tot if tot else 0; vals=[v*factor for v in vals]
   elif m=='target':
    tgt=max(0,fnum(target.get())); tot=sum(vals)
    if tgt>tot+0.0001: raise ValueError('İskontolu toplam mevcut satış toplamından büyük olamaz.')
    factor=tgt/tot if tot else 0; vals=[v*factor for v in vals]
   return vals
  def preview(*_):
   try: vals=calc(); net=sum(vals); disc=gross0-net; sumlbl.config(text=f'ARA TOPLAM       {money(gross0)}\n\nTOPLAM İSKONTO   {money(disc)}\n\nGENEL TOPLAM     {money(net)}')
   except Exception as e: sumlbl.config(text=f'ARA TOPLAM       {money(gross0)}\n\nMEVCUT TOPLAM    {money(current_total)}\n\n{e}')
  for v in (general,amount,target,d1,d2,d3):v.trace_add('write',preview)
  foot=tk.Frame(w,bg='#eef5fc');foot.pack(fill='x',padx=18,pady=(0,16))
  def remove_all():
   for r,g,_ in base:r['disc']=0.0;r['total']=g
   self._installment_plan=None;self.refresh_lines();w.destroy();owner.lift();owner.focus_force()
  def apply_close():
   try:vals=calc()
   except Exception as e:return messagebox.showwarning(APP,str(e),parent=self)
   for (r,g,_),net in zip(base,vals):
    net=max(0,min(float(net),g));r['total']=net;r['disc']=((g-net)*100.0/g) if g else 0.0
   self._installment_plan=None;self.refresh_lines();w.destroy();owner.lift();owner.focus_force()
  self.btn(foot,'TÜM İSKONTOLARI KALDIR',remove_all,True).pack(side='left')
  self.btn(foot,'VAZGEÇ',w.destroy,False).pack(side='right',padx=4)
  self.btn(foot,'UYGULA VE KAPAT',apply_close,True).pack(side='right',padx=4)
  preview()

 def _window(self):
  w=self.winfo_toplevel()
  return w
 def cancel_and_close(self):
  # Boş form doğrudan kapanır; kaydedilmemiş satış varsa kullanıcı onayı gerekir.
  dirty=bool(self.lines)
  if dirty:
   ok=messagebox.askyesno(APP,'CARİ SATIŞ henüz kaydedilmedi.\n\nSatışı iptal edip ekrandan çıkmak istediğinize emin misiniz?',parent=self._window())
   if not ok:return
  try:
   top=self._window()
   if hasattr(top,'show') and hasattr(top,'main'): top.show('Ana Sayfa')
   else: top.destroy()
  except Exception as _se:_silent(_se)
 def delete_line(self):
  if self._kayitli_kilidi():return
  s=self.t.selection();
  if not s:return
  del self.lines[int(s[0])]; self._installment_plan=None; self.refresh_lines()
 def preview_last_sale(self):
  if not self.last_sale_id:return messagebox.showinfo(APP,'Bu ekranda henüz kaydedilmiş bir satış bulunmuyor.',parent=self._window())
  self.preview_saved_sale(self.last_sale_id)
 def _cari_sale_print_html(self,sid):
  sale=DX.one("SELECT s.*,COALESCE(c.title,'Perakende') customer,COALESCE(c.phone,'') phone,COALESCE(c.address,'') address FROM sales s LEFT JOIN caris c ON c.id=s.customer_id WHERE s.id=?",(sid,))
  if not sale:raise RuntimeError('Satış kaydı bulunamadı.')
  lines=DX.rows('SELECT name,barcode,qty,price,discount,total FROM sale_lines WHERE sale_id=? ORDER BY id',(sid,));inst=DX.rows('SELECT due_date,amount,status FROM installments WHERE sale_id=? ORDER BY due_date',(sid,))
  e=lambda v:html.escape(str(v if v is not None else ''),quote=False)
