 def operation(self,kind):
  aa=[r['name'] for r in self.accounts()]
  if not aa:return messagebox.showwarning(APP,'Önce banka hesabı tanımlayın.',parent=self)
  w=new_toplevel(self);w.title(kind);w.geometry('590x540');w.grab_set();acc=tk.StringVar(value=aa[0]);amt=tk.StringVar();cv=tk.StringVar();note=tk.StringVar();cat=tk.StringVar();alloc=tk.BooleanVar(value=(kind=='Cari Tahsilat'));caris=[r['title'] for r in DX.rows('SELECT title FROM caris WHERE active=1 ORDER BY title')];is_money=kind in ('Para Girişi','Para Çıkışı');cat_table='income_categories' if kind=='Para Girişi' else 'expense_categories';cats=[r['name'] for r in DX.rows(f'SELECT name FROM {cat_table} WHERE active=1 ORDER BY name')] if is_money else []
