  tk.Label(pf,text='  Dönem:',bg=BG,fg=MUT,font=('Segoe UI',9,'bold')).pack(side='left',padx=(14,2))
  for _d in ('Bugün','Bu Hafta','Bu Ay','Tümü'):
   tk.Radiobutton(pf,text=_d,variable=self.date_var,value=_d,indicatoron=0,command=self.refresh,font=('Segoe UI',9,'bold'),bg='white',fg='#173b5e',selectcolor='#CFE6FB',activebackground='#E8F1FB',padx=10,pady=6,bd=1,relief='solid',cursor='hand2').pack(side='left',padx=2)
  self.info=tk.Label(fl,text='',bg='white',fg=MUT); self.info.pack(side='right',padx=12)
  self.btn(fl,'🖨 GELİR / GİDER RAPORU',self.income_expense_report).pack(side='right',padx=5,pady=5)
  base_cols=('dt','doc','account','kind','cari_code','cari','inn','out','balance','note','source');extra_cols=('source_id','finance_id','amount','direction','month','weekday','src_doc');cols=base_cols+extra_cols
  try:ttk.Style(self).configure('FinListe.Treeview',rowheight=30)
  except Exception as _se:_silent(_se)
  self.t=ttk.Treeview(self,columns=cols,displaycolumns=base_cols,show='headings',style='FinListe.Treeview');self.t._alfabe_extra_columns=set(extra_cols);self.t._alfabe_active_extra_columns=set();self.t._alfabe_extra_groups=_FIN_EXTRA_GROUPS
  for _c,_h,_w,_a in _FIN_EXTRA_HEADS:self.t.heading(_c,text=_h);self.t.column(_c,width=_w,anchor=_a)
  for _tg,_bg,_fg in (('z_even','#FFFFFF',None),('z_odd','#E6F2FA',None),('rev','#EEEEEE','#7A7A7A'),('inrow',None,'#166534'),('outrow',None,'#B00020')):self.t.tag_configure(_tg,**({'background':_bg} if _bg else {}),**({'foreground':_fg} if _fg else {}))
  self.t._alfabe_report_title='Finans Hareketleri';self.t._alfabe_report_key='Finans Merkezi / Hareketler'
  heads=('Tarih / Saat','Belge No','Hesap','İşlem','Cari Kodu','Cari','Giriş','Çıkış','İşlem Sonrası Bakiye','Açıklama','Kaynak','Kaynak ID','Finans ID')
