    cols=('barcode','name','qty','price','discount','total');t=ttk.Treeview(body,columns=cols,show='headings');t.pack(fill='both',expand=True)
    for c,h,ww in [('barcode','Barkod',130),('name','Ürün',300),('qty','Adet',90),('price','Birim Fiyat',110),('discount','İskonto',100),('total','Toplam',120)]:t.heading(c,text=h);t.column(c,width=ww,anchor='e' if c in ('qty','price','discount','total') else 'w')
    for x in DX.rows('SELECT barcode,name,qty,price,discount,total FROM sale_lines WHERE sale_id=? ORDER BY id',(sid,)):t.insert('','end',values=(x['barcode'] or '',x['name'] or '',qty_display(x['qty']),money(x['price']),money(x['discount']),money(x['total'])))
