  t=ttk.Treeview(_fr,columns=cols,show='headings',style='FinListe.Treeview')
  for c,h,wd in [('dt','Tarih / Saat',175),('account','Hesap',170),('kind','İşlem',125),('amount','Tutar',130),('note','Açıklama',350)]:
   t.heading(c,text=h);t.column(c,width=wd,anchor='e' if c=='amount' else 'w')
  _vs=ttk.Scrollbar(_fr,orient='vertical',command=t.yview);t.configure(yscrollcommand=_vs.set);t.pack(side='left',fill='both',expand=True);_vs.pack(side='right',fill='y')
  t.tag_configure('z_even',background='#FFFFFF');t.tag_configure('z_odd',background='#E6F2FA');t.tag_configure('inrow',foreground='#0b6b2e');t.tag_configure('outrow',foreground='#a01818')
  status=tk.Label(w,text='',anchor='w');status.pack(fill='x',padx=14,pady=(0,8))
  def refresh():
   d1=date_from.get().strip();d2=date_to.get().strip()
   try:
    first=_report_date_parse(d1);last=_report_date_parse(d2)
    if first>last:raise ValueError('Başlangıç tarihi bitişten sonra olamaz.')
   except ValueError as e:
    messagebox.showwarning(APP,'Tarihleri GG.AA.YYYY biçiminde giriniz. '+str(e),parent=w);return
   # Bir masraf finance kaydina bagliysa esas kaynak finance'dir.
   # Sadece baglantisiz aktif masraflar expense_records'tan tamamlanir.
   sql="""SELECT f.dt AS dt,f.account AS account,f.kind AS kind,f.amount AS amount,f.note AS note
    FROM finance f WHERE f.kind IN ('Gelir','Gider','Gider İptal') AND substr(f.dt,1,10) BETWEEN ? AND ?
    UNION ALL
    SELECT e.dt AS dt,e.account AS account,'Gider' AS kind,-ABS(e.amount) AS amount,
     COALESCE(e.category,'') || ' - ' || COALESCE(e.note,'') AS note
    FROM expense_records e WHERE e.status='Aktif' AND substr(e.dt,1,10) BETWEEN ? AND ?
     AND (e.finance_id IS NULL OR NOT EXISTS(SELECT 1 FROM finance f WHERE f.id=e.finance_id))
    ORDER BY dt DESC"""
   try:rows=DX.rows(sql,(first.isoformat(),last.isoformat(),first.isoformat(),last.isoformat()))
   except Exception as e:
    messagebox.showerror(APP,'Gelir-Gider kayıtları okunamadı:\n'+str(e),parent=w);return
   t.delete(*t.get_children());inc=0.0;exp=0.0
   for r in rows:
    amount=float(r['amount'] or 0)
    if r['kind']=='Gelir':inc+=amount
    elif r['kind']=='Gider İptal':exp-=abs(amount)
    else:exp+=abs(amount)
    t.insert('','end',values=(display_dt(r['dt']),r['account'],r['kind'],money(abs(amount)),r['note'] or ''),tags=('z_odd' if len(t.get_children())%2 else 'z_even','inrow' if r['kind']=='Gelir' else 'outrow'))
   totals['count'].config(text=str(len(rows)))
   totals['income'].config(text=money(inc));totals['expense'].config(text=money(exp))
   totals['net'].config(text=money(inc-exp))
   status.config(text=('Seçilen tarih aralığında gelir veya gider kaydı bulunamadı.' if not rows else str(len(rows))+' kayıt listelendi.'))
  def print_report():
   t._alfabe_report_title='Gelir / Gider Raporu'
   t._alfabe_report_key='Gelir / Gider Raporu'
   _open_tree_print_center(t)
  self.btn(top,'RAPORU GETİR',refresh).pack(side='left',padx=5)
