     con.execute('BEGIN IMMEDIATE');cur=con.execute('INSERT INTO finance(dt,account,kind,amount,source,note) VALUES(?,?,?,?,?,?)',(dt.get().strip() or now(),account.get(),'Gider',-a,'EXPENSE_PRO',(category.get()+' - '+note.get()).strip(' -')));fid=cur.lastrowid;con.execute('INSERT INTO expense_records(finance_id,dt,category,account,amount,payment_type,note,user,status) VALUES(?,?,?,?,?,?,?,?,?)',(fid,dt.get().strip() or now(),category.get(),account.get(),a,payment.get(),note.get(),CURRENT_USER,'Aktif'));con.commit()
