 def transfer(self):
  # v1.2.291.332: hesaplar listeden seçilir (yazım hatasıyla hayali hesap oluşmaz), anlık bakiye gösterilir,
  # bakiye yetersizse onay istenir, iki bacak tek işlemde yazılır, denetim izi tutulur.
  w=new_toplevel(self);w.title('Hesaplar Arası Transfer');w.geometry('520x420');w.grab_set()
  accounts=[r['name'] for r in DX.rows('SELECT name FROM finance_accounts WHERE active=1 ORDER BY kind,name')] or ['Ana Kasa']
  _da=getattr(self,'default_account',None);frm=tk.StringVar(value=_da if _da in accounts else accounts[0]);_rest=[x for x in accounts if x!=frm.get()];to=tk.StringVar(value=(next((x for x in _rest if 'Banka' in x),None) or (_rest[0] if _rest else accounts[0])));amt=tk.StringVar();note=tk.StringVar()
  tk.Label(w,text='HESAPLAR ARASI TRANSFER',font=('Segoe UI',16,'bold'),fg='#0b376d').pack(anchor='w',padx=18,pady=(14,4))
  def _grp(a):return 'KASA' if a in ('Nakit','Kasa','Ana Kasa') else (a or '')
  def balance(acc):
   r=DX.one("SELECT COALESCE(SUM(amount),0) b FROM finance WHERE CASE WHEN account IN ('Nakit','Kasa','Ana Kasa') THEN 'KASA' ELSE COALESCE(account,'') END=?",(_grp(acc),));return float(r['b'] or 0)
  info=tk.Label(w,text='',anchor='w',justify='left',font=('Segoe UI',10,'bold'),fg='#0b376d');
  def row(lab,fn):
   f=tk.Frame(w);f.pack(fill='x',padx=18,pady=6);tk.Label(f,text=lab,width=14,anchor='w',font=('Segoe UI',10,'bold')).pack(side='left');c=fn(f);c.pack(side='left',fill='x',expand=True);return c
  c1=row('Çıkan Hesap',lambda f:ttk.Combobox(f,textvariable=frm,values=accounts,state='readonly'))
  c2=row('Giren Hesap',lambda f:ttk.Combobox(f,textvariable=to,values=accounts,state='readonly'))
  info.pack(fill='x',padx=18)
  row('Tutar',lambda f:tk.Entry(f,textvariable=amt))
  row('Açıklama',lambda f:tk.Entry(f,textvariable=note))
  def upd(*_):
   try:info.config(text=f"{frm.get()}: {money(balance(frm.get()))}     →     {to.get()}: {money(balance(to.get()))}")
   except Exception as _se:_silent(_se)
  for c in (c1,c2):
   try:c.bind('<<ComboboxSelected>>',upd)
   except Exception as _se:_silent(_se)
  upd()
  def _v():
   try:return float(_export_numeric(amt.get())) if amt.get().strip() else 0.0
   except Exception:
    try:return float(amt.get().replace('.','').replace(',','.'))
    except Exception:return 0.0
  def save():
   v=_v()
   if v<=0:return messagebox.showwarning(APP,'Tutarı sıfırdan büyük giriniz.',parent=w)
   if _grp(frm.get())==_grp(to.get()):return messagebox.showwarning(APP,'Çıkan ve giren hesap aynı olamaz (Nakit / Kasa / Ana Kasa aynı hesap sayılır).',parent=w)
   bal=balance(frm.get())
   if bal-v<-0.005 and not messagebox.askyesno(APP,f"{frm.get()} bakiyesi {money(bal)}. Bu transfer bakiyeyi eksiye düşürür. Devam edilsin mi?",parent=w):return
   if not messagebox.askyesno(APP,f"{frm.get()} → {to.get()}\nTutar: {money(v)}\nTransfer kaydedilsin mi?",parent=w):return
   c=DX.con()
   try:
    tag='TR-'+datetime.datetime.now().strftime('%Y%m%d%H%M%S%f');stamp=now();text=tag+' '+note.get().strip()
    c.execute('INSERT INTO finance(dt,account,kind,amount,source,note) VALUES(?,?,?,?,?,?)',(stamp,frm.get(),'Transfer Çıkış',-round(v,2),'TRANSFER',text))
    c.execute('INSERT INTO finance(dt,account,kind,amount,source,note) VALUES(?,?,?,?,?,?)',(stamp,to.get(),'Transfer Giriş',round(v,2),'TRANSFER',text));c.commit()
   except Exception as e:
    c.rollback();messagebox.showerror(APP,'Transfer kaydedilemedi:\n'+str(e),parent=w);return
   finally:c.close()
   DX.audit('Finans','Transfer',0,new=f"{frm.get()}->{to.get()} {v}");w.destroy();self.refresh()
  bb=tk.Frame(w);bb.pack(fill='x',padx=18,pady=14);self.btn(bb,'TRANSFERİ KAYDET',save,True).pack(side='right');self.btn(bb,'VAZGEÇ',w.destroy).pack(side='right',padx=6)

 def installments(self):
  # v1.2.291.333: tüm cariler için taksit/senet takibi: süzgeç, arama, özet, zebra, tahsilat, ekstre, yazdırma.
  w=new_toplevel(self);w.title('Taksit / Senet Takibi');w.geometry('1180x680');w.minsize(940,560)
  head=tk.Frame(w,bg='#eaf3ff');head.pack(fill='x');tk.Label(head,text='TAKSİT / SENET TAKİBİ',bg='#eaf3ff',fg='#0b376d',font=('Segoe UI',16,'bold')).pack(side='left',padx=15,pady=12)
  mode=tk.StringVar(value='Açık');q=tk.StringVar();bar0=tk.Frame(w);bar0.pack(fill='x',padx=12,pady=(8,2))
  for k in ('Tümü','Açık','Gecikmiş','Bugün','Bu Hafta','Bu Ay','Ödenen'):
   tk.Radiobutton(bar0,text=k,value=k,variable=mode,indicatoron=0,selectcolor='#CFE6FB',padx=12,pady=5,command=lambda:load()).pack(side='left',padx=2)
  tk.Label(bar0,text='Ara:').pack(side='left',padx=(14,3));qe=tk.Entry(bar0,textvariable=q,width=28,bg='#fff59d');qe.pack(side='left')
  sumf=tk.Frame(w,bg='#e8f1fb',highlightbackground='#8aa9cf',highlightthickness=1);sumf.pack(fill='x',padx=12,pady=6);S={}
  for key,title in [('n','KAYIT'),('tot','TOPLAM TUTAR'),('paid','ÖDENEN'),('rem','KALAN'),('late','GECİKEN KALAN')]:
   bx=tk.Frame(sumf,bg='#e8f1fb');bx.pack(side='left',fill='x',expand=True,padx=7,pady=5);tk.Label(bx,text=title,bg='#e8f1fb',fg=MUT,font=('Segoe UI',8,'bold')).pack();S[key]=tk.Label(bx,text='0',bg='#e8f1fb',fg='#0b376d',font=('Segoe UI',11,'bold'));S[key].pack()
  cols=('cari','doc','due','amount','paid','remaining','days','status')
  fr=tk.Frame(w,bg='white');fr.pack(fill='both',expand=True,padx=12,pady=4)
  t=ttk.Treeview(fr,columns=cols,show='headings',selectmode='browse',style='FinListe.Treeview');vs=ttk.Scrollbar(fr,orient='vertical',command=t.yview);t.configure(yscrollcommand=vs.set)
  for c,h,wd in [('cari','Cari',230),('doc','Belge',130),('due','Vade',100),('amount','Tutar',120),('paid','Ödenen',120),('remaining','Kalan',120),('days','Gün',70),('status','Durum',120)]:t.heading(c,text=h);t.column(c,width=wd,anchor='e' if c in ('amount','paid','remaining','days') else 'w')
  t.pack(side='left',fill='both',expand=True);vs.pack(side='right',fill='y')
  for tg,bg,fg in [('z_even','#FFFFFF',None),('z_odd','#E6F2FA',None)]:t.tag_configure(tg,background=bg)
  t.tag_configure('late',background='#FFD9D9',foreground='#000000');t.tag_configure('done',foreground='#0b6b2e');t.tag_configure('part',background='#FFF3C4')
  t._alfabe_report_title='Taksit / Senet Takibi';t._alfabe_report_key='Finans Merkezi / Taksit';cache={}
  info=tk.Label(w,text='',anchor='w',fg=MUT);info.pack(fill='x',padx=14)
  def load(*_):
   t.delete(*t.get_children());cache.clear();td=datetime.date.today();needle=_tr_fold(q.get().strip());m_=mode.get()
   rows=DX.rows("SELECT i.*,COALESCE(c.title,'') title,COALESCE(s.doc_no,'') doc FROM installments i LEFT JOIN caris c ON c.id=i.cari_id LEFT JOIN sales s ON s.id=i.sale_id WHERE COALESCE(i.status,'')<>'İptal' ORDER BY i.due_date,i.id")
   n=0;tt=tp=tr=tl=0.0
   for r in rows:
    amt=float(r['amount'] or 0);paid=float(r['paid'] or 0);rem=round(amt-paid,2);st0=str(r['status'] or '')
    is_open=rem>0.005 and st0 not in ('Ödendi','İptal','İade')
    try:dd=datetime.date.fromisoformat(str(r['due_date'])[:10]);days=(td-dd).days
    except Exception:dd=None;days=0
    late=is_open and dd is not None and dd<td
    if m_=='Açık' and not is_open:continue
    if m_=='Gecikmiş' and not late:continue
    if m_=='Bugün' and not(is_open and dd==td):continue
    if m_=='Bu Hafta' and not(is_open and dd is not None and td<=dd<=td+datetime.timedelta(days=7)):continue
    if m_=='Bu Ay' and not(is_open and dd is not None and dd.year==td.year and dd.month==td.month):continue
    if m_=='Ödenen' and is_open:continue
    if needle and needle not in _tr_fold(str(r['title'])+' '+str(r['doc'])+' '+str(r['due_date'])):continue
    status='ÖDENDİ' if not is_open else ('GECİKMİŞ' if late else ('KISMİ ÖDENDİ' if paid>0.005 else 'BEKLİYOR'))
    tag=('late' if late else ('part' if is_open and paid>0.005 else ('done' if not is_open else ('z_odd' if n%2 else 'z_even'))))
    t.insert('','end',iid=str(r['id']),values=(r['title'],r['doc'],r['due_date'],money(amt),money(paid),money(max(rem,0)),(days if late else ''),status),tags=(tag,));cache[str(r['id'])]=dict(r)
    n+=1;tt+=amt;tp+=paid;tr+=max(rem,0) if is_open else 0
    if late:tl+=rem
   S['n'].config(text=str(n));S['tot'].config(text=money(tt));S['paid'].config(text=money(tp));S['rem'].config(text=money(tr));S['late'].config(text=money(tl))
   info.config(text=f'{n} kayıt listelendi. Renkler: kırmızı = gecikmiş, sarı = kısmi ödenmiş, yeşil = ödenmiş.')
  def sel():
   ss=t.selection()
   if not ss:messagebox.showwarning(APP,'Önce bir taksit seçin.',parent=w);return None
   return cache.get(ss[0])
  def collect():
   r=sel()
   if not r:return
   if not r.get('cari_id'):return messagebox.showwarning(APP,'Bu taksitin carisi yok.',parent=w)
   CariCenter.cash_transaction(self,'Tahsilat',r['cari_id']);load()
  def statement():
   r=sel()
   if not r or not r.get('cari_id'):return
   try:CariCenter.cari_output_center(self,r['cari_id'],'Cari Ekstre')
   except Exception as e:messagebox.showerror(APP,'Ekstre açılamadı:\n'+str(e),parent=w)
  b=tk.Frame(w);b.pack(fill='x',padx=12,pady=(4,12))
  self.btn(b,'TAHSİLAT AL',collect,True).pack(side='left',padx=3);self.btn(b,'CARİ EKSTRE',statement).pack(side='left',padx=3);self.btn(b,'YENİLE',load).pack(side='left',padx=3)
  self.btn(b,'🖨 MERKEZİ YAZDIRMA',lambda:_open_tree_print_center(t)).pack(side='right',padx=3);self.btn(b,'KAPAT',w.destroy).pack(side='right',padx=3)
  t.bind('<Double-1>',lambda e:collect());q.trace_add('write',load);load();qe.focus_set()

 def checks(self):
  # v1.2.229: Modern Yeni Çek/Senet kartı + eski veritabanı uyumluluğu.
  # Ekran açılmadan önce şemayı yerinde ve veri kaybetmeden tamamla.
  con=DX.con()
  try:
   cols_now={r[1] for r in con.execute('PRAGMA table_info(checks_notes)').fetchall()}
   for _name,_typ in [('cari_id','INTEGER'),('sale_id','INTEGER'),('installment_id','INTEGER'),('source','TEXT'),('doc_type','TEXT'),('issue_date','TEXT'),('currency','TEXT'),('document_name','TEXT'),('debtor','TEXT'),('debtor_address','TEXT'),('guarantor','TEXT'),('guarantor_address','TEXT'),('court','TEXT'),('bank_name','TEXT'),('bank_city','TEXT'),('bank_branch','TEXT'),('check_account_no','TEXT'),('endorser1','TEXT'),('endorser2','TEXT'),('bearer','INTEGER DEFAULT 0')]:
    if _name not in cols_now: con.execute(f'ALTER TABLE checks_notes ADD COLUMN {_name} {_typ}')
   con.execute('CREATE UNIQUE INDEX IF NOT EXISTS ux_checks_installment ON checks_notes(installment_id) WHERE installment_id IS NOT NULL')
   con.commit()
  except Exception as e:
   con.rollback();log_error('Çek/Senet eski veritabanı uyumluluk',e)
  finally: con.close()
  w=new_toplevel(self);w.title('Çek / Senet');w.geometry('1420x720');w.minsize(1050,580)
  tk.Label(w,text='ÇEK / SENET TAKİBİ',font=('Segoe UI',17,'bold'),fg='#0b376d').pack(anchor='w',padx=16,pady=(14,4))
  tk.Label(w,text='Senetli cari satışlar, tahsilatlar ve kalan bakiyeler aynı kayıt üzerinden izlenir. İşlem görmüş kayıt doğrudan değiştirilemez; güvenli iptal gerekir.',fg=MUT,font=('Segoe UI',9,'bold')).pack(anchor='w',padx=16,pady=(0,8))
  cols=('kind','no','ccode','cust','doc','due','amt','paid','remain','status','note')
  fmode=tk.StringVar(value='Tümü');fq=tk.StringVar();fb=tk.Frame(w);fb.pack(fill='x',padx=15,pady=(0,6))
  for _k in ('Tümü','Portföyde','Gecikmiş','Bu Hafta','Tahsil/Ödendi','İptal'):tk.Radiobutton(fb,text=_k,value=_k,variable=fmode,indicatoron=0,selectcolor='#CFE6FB',padx=12,pady=5,command=lambda:load()).pack(side='left',padx=2)
  tk.Label(fb,text='Ara:').pack(side='left',padx=(14,3));tk.Entry(fb,textvariable=fq,width=28,bg='#fff59d').pack(side='left')
  _fr=tk.Frame(w,bg='white');_fr.pack(fill='both',expand=True,padx=15,pady=(0,6))
  t=ttk.Treeview(_fr,columns=cols,show='headings',selectmode='browse',style='FinListe.Treeview');_vs=ttk.Scrollbar(_fr,orient='vertical',command=t.yview);t.configure(yscrollcommand=_vs.set)
  t.tag_configure('z_even',background='#FFFFFF');t.tag_configure('z_odd',background='#E6F2FA');t.tag_configure('late',background='#FFD9D9',foreground='#000000');t.tag_configure('done',foreground='#0b6b2e');t.tag_configure('part',background='#FFF3C4');t._alfabe_report_title='Çek / Senet Takibi';t._alfabe_report_key='Finans Merkezi / Çek Senet'
  specs=[('kind','Tür',105),('no','Senet No',130),('ccode','Cari Kodu',100),('cust','Cari',190),('doc','Satış / Belge No',130),('due','Vade',105),('amt','Tutar',105),('paid','Ödenen',105),('remain','Kalan',105),('status','Durum',115),('note','Açıklama',210)]
  for c,h,wd in specs:t.heading(c,text=h);t.column(c,width=wd,anchor='e' if c in ('amt','paid','remain') else 'w')
  t.pack(side='left',fill='both',expand=True);_vs.pack(side='right',fill='y');summary=tk.Label(w,text='',font=('Segoe UI',10,'bold'),anchor='e');summary.pack(fill='x',padx=16,pady=(0,6))
  def status_of(due,amt,paid):
   remain=max(float(amt or 0)-float(paid or 0),0)
   return ('ÖDENDİ' if remain<=0.005 else ('KISMİ ÖDENDİ' if float(paid or 0)>0.005 else ('GECİKMİŞ' if str(due or '')<today() else 'PORTFÖYDE')))
  def sync_links():
   con=DX.con()
   try:
    con.execute('BEGIN IMMEDIATE')
    rows=con.execute("""SELECT i.id,i.cari_id,i.sale_id,i.due_date,i.amount,i.paid,i.status,COALESCE(c.title,'') customer,COALESCE(s.payment,'') payment,COALESCE(s.doc_no,'') doc_no FROM installments i LEFT JOIN sales s ON s.id=i.sale_id LEFT JOIN caris c ON c.id=i.cari_id WHERE (LOWER(COALESCE(s.payment,'')) LIKE '%senet%' OR LOWER(COALESCE(s.payment,'')) LIKE '%taksit%' OR s.id IS NULL) ORDER BY i.id""").fetchall()
    for r in rows:
     sno=f"SNT-{r['sale_id'] or 0}-{int(r['id']):02d}";ist=status_of(r['due_date'],r['amount'],r['paid'])
     con.execute("INSERT OR IGNORE INTO checks_notes(kind,number,customer,due_date,amount,status,note,cari_id,sale_id,installment_id,source) VALUES('Alınan Senet',?,?,?,?,?,'Senetli cari satış',?,?,?,'CARI_SALE')",(sno,r['customer'],r['due_date'],r['amount'],ist,r['cari_id'],r['sale_id'],r['id']))
     con.execute("UPDATE checks_notes SET customer=?,due_date=?,amount=?,status=CASE WHEN LOWER(COALESCE(status,'')) LIKE '%iptal%' THEN status ELSE ? END,cari_id=?,sale_id=?,source='CARI_SALE' WHERE installment_id=?",(r['customer'],r['due_date'],r['amount'],ist,r['cari_id'],r['sale_id'],r['id']))
    con.commit()
   except Exception as e:con.rollback();log_error('Çek/Senet bağlantı yenileme',e)
   finally:con.close()
  def load():
   sync_links();t.delete(*t.get_children());ta=tp=0.0
   rows=DX.rows("""SELECT cn.*,COALESCE(c.title,cn.customer,'') customer_name,CASE WHEN cn.cari_id IS NULL THEN '' ELSE 'CR'||printf('%06d',cn.cari_id) END cari_code,COALESCE(s.doc_no,'') doc_no,COALESCE(i.paid,0) paid,COALESCE(i.amount,cn.amount,0) inst_amount,COALESCE(i.due_date,cn.due_date,'') inst_due FROM checks_notes cn LEFT JOIN caris c ON c.id=cn.cari_id LEFT JOIN sales s ON s.id=cn.sale_id LEFT JOIN installments i ON i.id=cn.installment_id ORDER BY COALESCE(i.due_date,cn.due_date),cn.id""")
   shown_inst=set()
   for r in rows:
    if r['installment_id']: shown_inst.add(int(r['installment_id']))
    amt=float(r['inst_amount'] or r['amount'] or 0);paid=float(r['paid'] or 0);remain=max(amt-paid,0);cancelled='iptal' in str(r['status'] or '').lower();stored=str(r['status'] or '').lower();closed=any(x in stored for x in ('tahsil','ödendi','odendi'))
    if not r['installment_id'] and closed and not cancelled:paid=amt;remain=0.0
    st='İPTAL EDİLDİ' if cancelled else ('TAHSİL/ÖDENDİ' if (not r['installment_id'] and closed) else status_of(r['inst_due'],amt,paid))
    _m=fmode.get();_late=(st=='GECİKMİŞ');_open=st in ('PORTFÖYDE','GECİKMİŞ','KISMİ ÖDENDİ')
    try:_dd=datetime.date.fromisoformat(str(r['inst_due'])[:10])
    except Exception:_dd=None
    if _m=='Portföyde' and not _open:continue
    if _m=='Gecikmiş' and not _late:continue
    if _m=='Bu Hafta' and not(_open and _dd is not None and datetime.date.today()<=_dd<=datetime.date.today()+datetime.timedelta(days=7)):continue
    if _m=='Tahsil/Ödendi' and st not in ('ÖDENDİ','TAHSİL/ÖDENDİ'):continue
    if _m=='İptal' and not cancelled:continue
    _nd=_tr_fold(fq.get().strip())
    if _nd and _nd not in _tr_fold(' '.join(str(x or '') for x in (r['kind'],r['number'],r['customer_name'],r['doc_no'],r['inst_due'],r['note']))):continue
    if not cancelled:ta+=amt;tp+=paid
    _tg='cancelled' if cancelled else ('late' if _late else ('done' if st in ('ÖDENDİ','TAHSİL/ÖDENDİ') else ('part' if st=='KISMİ ÖDENDİ' else ('z_odd' if len(t.get_children())%2 else 'z_even'))))
    t.insert('','end',iid=str(r['id']),values=(r['kind'],r['number'],r['cari_code'],r['customer_name'],r['doc_no'],r['inst_due'],money(amt),money(paid),money(remain),st,r['note'] or ''),tags=(_tg,))
   # v1.2.223'te çalışan güvenlik ağı korunur: checks_notes bağlantısı kurulmamış
   # eski senet/taksit kayıtları doğrudan installments tablosundan yine de gösterilir.
   fallback=DX.rows("""SELECT i.id,i.cari_id,i.sale_id,i.due_date,i.amount,i.paid,i.status,COALESCE(c.title,'') customer,CASE WHEN i.cari_id IS NULL THEN '' ELSE 'CR'||printf('%06d',i.cari_id) END cari_code,COALESCE(s.doc_no,'') doc_no,COALESCE(s.payment,'') payment FROM installments i LEFT JOIN sales s ON s.id=i.sale_id LEFT JOIN caris c ON c.id=i.cari_id WHERE LOWER(COALESCE(s.payment,'')) LIKE '%senet%' OR LOWER(COALESCE(s.payment,'')) LIKE '%taksit%' OR s.id IS NULL ORDER BY i.due_date,i.id""")
   for r in fallback:
    if int(r['id']) in shown_inst: continue
    if fq.get().strip() or fmode.get() in ('İptal',): continue
    amt=float(r['amount'] or 0);paid=float(r['paid'] or 0);remain=max(amt-paid,0);st=status_of(r['due_date'],amt,paid);sno=f"SNT-{r['sale_id'] or 0}-{int(r['id']):02d}"
    ta+=amt;tp+=paid
    t.insert('','end',iid='I'+str(r['id']),values=('Alınan Senet',sno,r['cari_code'],r['customer'],r['doc_no'],r['due_date'],money(amt),money(paid),money(remain),st,'Eski senet/taksit kaydı'))
   t.tag_configure('cancelled',foreground='#000000',background='#fde8e8');summary.config(text=f'Toplam Senet: {money(ta)}     Ödenen: {money(tp)}     Kalan: {money(max(ta-tp,0))}')
  def selected_row():
   ss=t.selection()
   if not ss:messagebox.showwarning(APP,'Önce bir çek/senet kaydı seçin.',parent=self);return None
   if str(ss[0]).startswith('I'):
    iid=int(str(ss[0])[1:])
    linked=DX.one('SELECT * FROM checks_notes WHERE installment_id=? ORDER BY id DESC LIMIT 1',(iid,))
    if linked:return linked
    messagebox.showinfo(APP,'Bu eski senet listede görünür durumda. YENİLE ile kalıcı bağlantı oluşturulamadı; tahsilat/düzeltme için satış bağlantısı kontrol edilmelidir.',parent=self);return None
   return DX.one('SELECT * FROM checks_notes WHERE id=?',(int(ss[0]),))
  def editable_status(status):
   st=str(status or '').strip().lower();return not any(x in st for x in ('tahsil','ödendi','odendi','ciro','banka','kapandı','kapandi','iptal'))
  def settle_standalone(r):
   # v1.2.291.334: taksite bağlı olmayan çek/senet: Alınan -> tahsil et (cari alacak, kasa/banka giriş); Verilen -> öde (cari borç, çıkış)
   recv=str(r['kind'] or '').startswith('Alınan');stored=str(r['status'] or '').lower()
   if any(x in stored for x in ('tahsil','ödendi','odendi','iptal')):return messagebox.showinfo(APP,'Bu kayıt zaten kapanmış veya iptal edilmiş.',parent=self)
   if not r['cari_id']:return messagebox.showwarning(APP,'Bu kayıt bir cariye bağlı değil. Önce cari bağlantısı olmalıdır.',parent=self)
   accounts=[x['name'] for x in DX.rows('SELECT name FROM finance_accounts WHERE active=1 ORDER BY kind,name')] or ['Ana Kasa']
   d=new_toplevel(w);d.title('Çek / Senet '+('Tahsilatı' if recv else 'Ödemesi'));d.geometry('520x340');d.grab_set()
   account=tk.StringVar(value=accounts[0]);dt=tk.StringVar(value=today());note=tk.StringVar()
   tk.Label(d,text=('TAHSİL ET' if recv else 'ÖDE'),font=('Segoe UI',16,'bold'),fg='#0b376d').pack(anchor='w',padx=20,pady=(16,2));tk.Label(d,text=f"{r['kind']} • {r['number']} • {r['customer']} • {money(r['amount'])}",font=('Segoe UI',10,'bold')).pack(anchor='w',padx=20,pady=(0,10))
   for lab_,var_,vals_ in [('Hesap',account,accounts),('Tarih',dt,None),('Açıklama',note,None)]:
    fr_=tk.Frame(d);fr_.pack(fill='x',padx=20,pady=6);tk.Label(fr_,text=lab_,width=12,anchor='w',font=('Segoe UI',10,'bold')).pack(side='left')
    (ttk.Combobox(fr_,textvariable=var_,values=vals_,state='readonly') if vals_ else tk.Entry(fr_,textvariable=var_)).pack(side='left',fill='x',expand=True)
   def go():
    try:dd=datetime.date.fromisoformat(dt.get().strip())
    except Exception:return messagebox.showwarning(APP,'Tarih YYYY-AA-GG biçiminde olmalıdır.',parent=d)
    a=round(float(r['amount'] or 0),2)
    if a<=0:return messagebox.showwarning(APP,'Kayıt tutarı geçersiz.',parent=d)
    if not messagebox.askyesno(APP,f"{money(a)} {'tahsil edilsin' if recv else 'ödensin'} mi?\nHesap: {account.get()}",parent=d):return
    stamp=dd.isoformat()+' '+datetime.datetime.now().strftime('%H:%M:%S');desc=f"Çek/Senet: {r['number']} | Hesap: {account.get()} | {note.get().strip()}";con=DX.con()
    try:
     con.execute('BEGIN IMMEDIATE');live=con.execute('SELECT status FROM checks_notes WHERE id=?',(r['id'],)).fetchone()
     if not live or any(x in str(live['status'] or '').lower() for x in ('tahsil','ödendi','odendi','iptal')):raise ValueError('Kayıt artık açık değil. Listeyi yenileyin.')
     cur=con.execute('INSERT INTO cari_moves(cari_id,dt,kind,debit,credit,source,source_id,note) VALUES(?,?,?,?,?,?,?,?)',(r['cari_id'],stamp,'Çek/Senet Tahsilatı' if recv else 'Çek/Senet Ödemesi',0 if recv else a,a if recv else 0,'CHECK_NOTE',r['id'],desc));mid=cur.lastrowid
     con.execute('INSERT INTO finance(dt,account,kind,amount,source,source_id,note) VALUES(?,?,?,?,?,?,?)',(stamp,account.get(),'Senet Tahsilatı' if recv else 'Çek/Senet Ödemesi',a if recv else -a,'CARI',mid,desc))
     con.execute("UPDATE checks_notes SET status=? WHERE id=?",('Tahsil Edildi' if recv else 'Ödendi',r['id']))
     con.execute('INSERT INTO audit(dt,user,module,action,record_id,new_value,reason) VALUES(?,?,?,?,?,?,?)',(now(),current_user(),'Çek/Senet','Tahsil' if recv else 'Ödeme',r['id'],f"{r['number']} {a}",desc));con.commit()
    except Exception as e:con.rollback();messagebox.showerror(APP,'İşlem kaydedilemedi:\n'+str(e),parent=d);return
    finally:con.close()
    d.destroy();load();self.refresh()
   bb=tk.Frame(d);bb.pack(fill='x',padx=20,pady=14);self.btn(bb,'KAYDET',go,True).pack(side='right');self.btn(bb,'VAZGEÇ',d.destroy).pack(side='right',padx=6)
  def collect_selected():
   r=selected_row()
   if not r:return
   if 'iptal' in str(r['status'] or '').lower():return messagebox.showwarning(APP,'İptal edilmiş senede tahsilat yapılamaz.',parent=self)
   if not r['installment_id']:return settle_standalone(r)
