   self.t.insert('','end',iid=str(r['id']),tags=('zero' if _zero else ('z_odd' if _n%2==0 else 'z_even'),),values=(r['name'],_var,rng,r['billing_unit'] or 'Adet',f"%{float(r['vat'] or 0):g}",money(r['price'])))
