 def restore_classic(self):
  if not _exclusive_guard(self,'Yedekten geri yükleme'):return
  f=filedialog.askopenfilename(title='ALFABE yedeği seç',filetypes=[('ALFABE Tam Yedek','*.zip'),('Eski DB Yedeği','*.db'),('Tüm dosyalar','*.*')])
  if not f:return
  fp=Path(f)
  if fp.suffix.lower()=='.db':
   verify=self.verify_dbfile(fp)
   if verify!='ok':return messagebox.showerror(APP,'Seçilen yedek doğrulanamadı:\n'+verify)
   try:
    cc=sqlite3.connect(str(fp));vals=dict(cc.execute("SELECT k,v FROM settings WHERE k IN ('company','period')").fetchall());cc.close();bco=str(vals.get('company','')).strip();bpe=str(vals.get('period','')).strip();cco=DX.get('company','').strip();cpe=DX.get('period','').strip()
    if bco and cco and bco!=cco:return messagebox.showerror(APP,f'YANLIŞ FİRMA YEDEĞİ: Yedek={bco} / Açık firma={cco}.')
    if bpe and cpe and bpe!=cpe:return messagebox.showerror(APP,f'YANLIŞ DÖNEM YEDEĞİ: Yedek={bpe} / Açık dönem={cpe}.')
   except Exception as e:return messagebox.showerror(APP,'Yedek firma/dönem kimliği okunamadı:\n'+str(e))
   mode='all';dbsource=fp;temp=None
  else:
   temp=BACK/f'_restore_{datetime.datetime.now():%Y%m%d_%H%M%S}';temp.mkdir(parents=True,exist_ok=True)
   try:
    with zipfile.ZipFile(fp,'r') as z:
     bad=z.testzip()
     if bad:raise RuntimeError('ZIP bozuk: '+bad)
     z.extractall(temp)
    dbsource=temp/'alfabe_veritabani.db'
    if not dbsource.exists():raise RuntimeError('Yedekte veritabanı bulunamadı.')
    mf=temp/'manifest.json'
    if mf.exists():
     man=json.loads(mf.read_text(encoding='utf-8'))
     for name,expected in (man.get('sha256') or {}).items():
      q=temp/name
      if not q.exists() or hashlib.sha256(q.read_bytes()).hexdigest()!=expected:raise RuntimeError('Yedek dosya doğrulaması başarısız: '+name)
     bco=str(man.get('company') or '').strip();bpe=str(man.get('period') or '').strip();cco=DX.get('company','').strip();cpe=DX.get('period','').strip()
     if bco and cco and bco!=cco:raise RuntimeError(f'YANLIŞ FİRMA YEDEĞİ: Yedek={bco} / Açık firma={cco}. Güvenlik için geri yükleme durduruldu.')
     if bpe and cpe and bpe!=cpe:raise RuntimeError(f'YANLIŞ DÖNEM YEDEĞİ: Yedek={bpe} / Açık dönem={cpe}. Güvenlik için geri yükleme durduruldu.')
    if self.verify_dbfile(dbsource)!='ok':raise RuntimeError('Yedek veritabanı doğrulanamadı.')
   except Exception as e:
    shutil.rmtree(temp,ignore_errors=True);return messagebox.showerror(APP,'Yedek açılamadı:\n'+str(e))
   w=new_toplevel(self);w.title('Geri Yükleme Seçimi');w.geometry('470x360');w.grab_set();choice=tk.StringVar(value='all')
   tk.Label(w,text='NE GERİ YÜKLENSİN?',font=('Segoe UI',15,'bold')).pack(anchor='w',padx=20,pady=(18,8))
   for val,txt in [('all','Tamamını geri yükle'),('settings','Sadece ayarları geri yükle'),('reports','Sadece rapor tasarımlarını geri yükle'),('labels','Sadece etiket tasarımlarını geri yükle')]:tk.Radiobutton(w,text=txt,variable=choice,value=val,font=('Segoe UI',10)).pack(anchor='w',padx=24,pady=5)
   done=tk.BooleanVar(value=False)
   def go():done.set(True);w.destroy()
   self.btn(w,'DEVAM',go,True).pack(pady=18);w.protocol('WM_DELETE_WINDOW',w.destroy);w.wait_window()
   if not done.get():shutil.rmtree(temp,ignore_errors=True);return
   mode=choice.get()
  if not messagebox.askyesno(APP,'Geri yüklemeden önce mevcut durumun güvenlik yedeği alınacak. Devam?'):
   if temp:shutil.rmtree(temp,ignore_errors=True)
   return
  safety=BACK/f'GERI_YUKLEME_ONCESI_{datetime.datetime.now():%Y%m%d_%H%M%S}.db'
  loadw,loadbar=_backup_loading_dialog(self)
  try:
   src=DX.con();dst=sqlite3.connect(safety);src.backup(dst);dst.close();src.close()
   if self.verify_dbfile(safety)!='ok':raise RuntimeError('Geri yükleme öncesi güvenlik yedeği doğrulanamadı.')
   if mode=='all':
    shutil.copy2(dbsource,DB)
    if self.verify_dbfile(DB)!='ok':shutil.copy2(safety,DB);raise RuntimeError('Geri yüklenen veri doğrulanamadı; güvenlik yedeğine geri dönüldü.')
   else:
    name={'settings':'ayarlar.json','reports':'rapor_tasarimlari.json','labels':'etiket_tasarimlari.json'}[mode];jf=temp/name
    if not jf.exists():raise RuntimeError('Seçilen bileşen yedekte bulunamadı: '+name)
    arr=json.loads(jf.read_text(encoding='utf-8'));self._restore_json_component(arr,mode)
   label={'all':'Tam Geri Yükleme','settings':'Ayarlar','reports':'Rapor Tasarımları','labels':'Etiket Tasarımları'}[mode]
   DX.exec("INSERT INTO backup_history(dt,path,kind,status,size,verify) VALUES(?,?,?,?,?,?)",(now(),str(fp),label+' Geri Yükleme','Başarılı',fp.stat().st_size,'OK'));self.log('Geri Yükleme','Başarılı',label+' / '+fp.name);self.refresh_health();_close_backup_loading(loadw,loadbar);messagebox.showinfo(APP,label+' geri yükleme tamamlandı.\nTam geri yüklemede programı kapatıp yeniden açın.')
  except Exception as e:_close_backup_loading(loadw,loadbar);self.log('Geri Yükleme','Hata',str(e));messagebox.showerror(APP,'Geri yükleme tamamlanamadı:\n'+str(e))
  finally:
   if temp:shutil.rmtree(temp,ignore_errors=True)
