def _main_db_file():
 try:
  reg=_bootstrap_company_registry();rec=reg.get(str(ACTIVE_COMPANY_NO)) or {}
  return Path(rec.get('base') or _DATA_BASE)/'alfabe_v1_2_31.db'
 except Exception:return None

def _company_details_json():
  """Firma bilgileri (company_details). Etkin (dönem) veritabanında logo yoksa firmanın ana veritabanındaki logo kullanılır."""
  try:d=json.loads(DX.get('company_details','{}') or '{}')
  except Exception:d={}
  if not isinstance(d,dict):d={}
  if not d.get('logo_data'):
   try:
    p=_main_db_file()
    if p and p.exists() and str(p)!=str(DB):
     c=sqlite3.connect('file:'+p.as_posix()+'?mode=ro',uri=True,timeout=3)
     try:r=c.execute("SELECT v FROM settings WHERE k='company_details'").fetchone()
     finally:c.close()
     if r and r[0]:
      m=json.loads(r[0])
      if m.get('logo_data'):d['logo_data']=m['logo_data'];d['logo_name']=m.get('logo_name','')
   except Exception as _se:_silent(_se)
  return d

def _mirror_company_logo_to_main(logo_data,logo_name=''):
  """Ayarlar'dan seçilen/kaldırılan logoyu firmanın ana veritabanına da yazar (tüm dönemler aynı logoyu görsün)."""
  try:
   p=_main_db_file()
   if not p or not p.exists() or str(p)==str(DB):return
   c=sqlite3.connect(str(p),timeout=5)
   try:
    r=c.execute("SELECT v FROM settings WHERE k='company_details'").fetchone()
    try:m=json.loads(r[0]) if r and r[0] else {}
    except Exception:m={}
    if logo_data:m['logo_data']=logo_data;m['logo_name']=logo_name
    else:m.pop('logo_data',None);m.pop('logo_name',None)
    c.execute("INSERT INTO settings(k,v) VALUES('company_details',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(json.dumps(m,ensure_ascii=False),));c.commit()
   finally:c.close()
  except Exception as e:log_error('Logo ana veritabanına yazılamadı',e)

def _logo_encode_file(path):
 """Logo dosyasını kaydedilecek biçime çevirir. Pillow varsa her resim PNG'ye çevrilir (JPG dahil) ve en çok 1200 px genişliğe küçültülür;
 yoksa dosya olduğu gibi saklanır. Dönüş: (base64, dosya_adı, not)."""
 p=Path(path);raw=p.read_bytes();name=p.name;note=''
 try:
  import io
  from PIL import Image
  im=Image.open(io.BytesIO(raw));im.load()
  if im.mode not in ('RGB','RGBA'):im=im.convert('RGBA')
  if im.width>1200:im=im.resize((1200,max(1,round(im.height*1200/im.width))),Image.LANCZOS)
  buf=io.BytesIO();im.save(buf,'PNG',optimize=True);raw=buf.getvalue();name=p.stem+'.png'
 except Exception:
  if p.suffix.lower() in ('.jpg','.jpeg'):note='JPG dosyası ekranda önizlenemiyor (raporlarda yine de kullanılır). Ekranda da görünmesi için PNG kullanmanız önerilir.'
 return base64.b64encode(raw).decode('ascii'),name,note

def _logo_photo(b64,maxw=170,maxh=110):
 """Kayıtlı logodan küçültülmüş tk.PhotoImage üretir; okunamazsa None."""
 try:
  img=tk.PhotoImage(data=b64)
  k=max(1,int(max(img.width()/float(maxw),img.height()/float(maxh))+0.999))
  return img.subsample(k,k) if k>1 else img
 except Exception:return None

