 START_CAT=None

 def __init__(self,p):
  super().__init__(p,'Ayarlar')
  self.scope=tk.StringVar(value='Firma');self.search=tk.StringVar();self.only_changed=tk.BooleanVar(value=False)
  self.cats=list(AYR.CATEGORIES);self.cur=self.cats[0]
  sc0=Settings.START_CAT;Settings.START_CAT=None
  if sc0:self.cur=next((c for c in self.cats if c.id==sc0),self.cur)
  self.vars={};self.widgets={};self.badges={};self._baseline={};self._dirty=False;self._scope_loaded='Firma'
  self.ensure_schema();self.build()
  try:self.list.selection_clear(0,'end');self.list.selection_set(self.cats.index(self.cur));self.list.see(self.cats.index(self.cur))
  except Exception as _se:_silent(_se)
