  tk.Checkbutton(bar,text='Yalnız varsayılandan farklı olanlar',variable=self.only_changed,command=self.refilter,bg='white',activebackground='white',font=('Segoe UI',9)).pack(side='right',padx=14)
  tk.Label(bar,text='Ayar ara...  (etiket, açıklama, yazıcı, iskonto, barkod, yedek)',bg='white',fg='#000000',font=('Segoe UI',9)).pack(side='right',padx=6)
  body=tk.PanedWindow(self,orient='horizontal',sashwidth=4,bg=BG,bd=0);body.pack(fill='both',expand=True,padx=20,pady=0)
