 FIRMA_ALANLARI=[('short','Kısa Ünvan *'),('full','Tam Ünvan'),('taxoffice','Vergi Dairesi'),('taxno','Vergi / TC Kimlik No'),('address','Adres'),('district','İlçe'),('city','İl'),('postal','Posta Kodu'),
  ('phone1','Telefon 1'),('phone2','Telefon 2'),('mobile','Cep Telefonu'),('fax','Faks'),('email','E-posta'),('web','Web Sitesi'),('contact','Yetkili Kişi')]
 def page_firma(self):
  host=self._scroll_host(self.right)
  self._hero(host,'Firma Bilgileri','Fatura, teklif, sipariş, ekstre, rapor ve fişlerin üst bilgisinde kullanılan firma bilgileri. Bu bilgiler yalnız etkin firmaya aittir.')
  try:d=_company_details_json()
  except Exception:d={}
  self._firma_vars={}
  card=tk.Frame(host,bg='white',highlightbackground='#dbe5ef',highlightthickness=1);card.pack(fill='x',padx=14,pady=6)
  for i,(k,lab) in enumerate(self.FIRMA_ALANLARI):
   r,c=divmod(i,2);cell=tk.Frame(card,bg='white');cell.grid(row=r,column=c,sticky='ew',padx=14,pady=6);card.columnconfigure(c,weight=1)
   tk.Label(cell,text=lab,bg='white',fg='#000000',font=('Segoe UI',9)).pack(anchor='w')
   v=tk.StringVar(value=str(d.get(k,'') or (DX.get('company','') if k=='short' else '')));self._firma_vars[k]=v
   tk.Entry(cell,textvariable=v,font=('Segoe UI',10)).pack(fill='x',ipady=3)
  b=tk.Frame(host,bg='#f8fbff');b.pack(fill='x',padx=14,pady=8)
  self.btn(b,'FİRMA BİLGİLERİNİ KAYDET',self.save_firma,True).pack(side='left')
  info=tk.Frame(host,bg='white',highlightbackground='#dbe5ef',highlightthickness=1);info.pack(fill='x',padx=14,pady=10)
  tk.Label(info,text='SİSTEM BİLGİSİ',bg='white',fg='#000000',font=('Segoe UI',9,'bold')).pack(anchor='w',padx=14,pady=(10,4))
  rows=[('Program sürümü',str(globals().get('VERSION',globals().get('APP_VERSION','')))),('Etkin firma no',str(globals().get('ACTIVE_COMPANY_NO',''))),('Etkin dönem',str(DX.get('period',''))),('Veritabanı dosyası',str(DB)),('Yedek klasörü',str(BACK)),('Bu bilgisayar',str(os.environ.get('COMPUTERNAME') or 'PC')),('Giriş yapan kullanıcı',str(current_user()))]
  for a,bv in rows:
   r=tk.Frame(info,bg='white');r.pack(fill='x',padx=14,pady=1)
   tk.Label(r,text=a,bg='white',fg='#000000',width=22,anchor='w',font=('Segoe UI',9)).pack(side='left');tk.Label(r,text=bv,bg='white',fg='#000000',anchor='w',font=('Segoe UI',9,'bold')).pack(side='left')
  tk.Frame(info,bg='white',height=8).pack()
 def save_firma(self):
  name=self._firma_vars['short'].get().strip()
  if not name:return messagebox.showwarning(APP,'Kısa Ünvan zorunludur.',parent=self)
  try:d=_company_details_json()
  except Exception:d={}
  old=dict(d)
  for k,v in self._firma_vars.items():d[k]=v.get().strip()
  em=d.get('email','')
  if em and not re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+',em):return messagebox.showwarning(APP,'E-posta adresi geçerli görünmüyor.',parent=self)
  tn=re.sub(r'\D','',d.get('taxno',''))
  if tn and len(tn) not in (10,11):return messagebox.showwarning(APP,'Vergi / TC kimlik numarası 10 veya 11 haneli olmalıdır.',parent=self)
  DX.exec("INSERT INTO settings(k,v) VALUES('company',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(name,))
  DX.exec("INSERT INTO settings(k,v) VALUES('company_details',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(json.dumps(d,ensure_ascii=False),))
  try:
   reg=_bootstrap_company_registry();rec=reg.get(str(ACTIVE_COMPANY_NO)) or reg.get(ACTIVE_COMPANY_NO)
   if rec:rec['name']=name;_company_registry_save(reg)
  except Exception as _se:_silent(_se)
  try:_mirror_company_logo_to_main(d.get('logo_data',''),d.get('logo_name',''))
  except Exception as _se:_silent(_se)
  invalidate_scoped_settings()
  for k in ('short','full','taxoffice','taxno','address','phone1','email'):
   if str(old.get(k,''))!=str(d.get(k,'')):DX.exec('INSERT INTO settings_history(dt,user,scope,category,k,old_value,new_value) VALUES(?,?,?,?,?,?,?)',(now(),current_user(),'Firma','Firma Bilgileri','firma_'+k,str(old.get(k,'')),str(d.get(k,''))))
  DX.audit('Ayarlar','Firma Bilgileri',new=name)
  messagebox.showinfo(APP,'Firma bilgileri kaydedildi.',parent=self)

