 # ------------------------------------------------------------------ özel sayfa: Yönetim
 PROFILLER={
  'Hızlı Kasa (perakende)':{'enter_nav':'Evet','barcode_auto_advance':'Evet','click_add':'Evet','sale_merge_lines':'Evet','sale_print_after':'Hayır','sale_done_message':'Hayır','search_delay':'80'},
  'Sıkı Kontrol (güvenli)':{'stock_negative':'Engelle','sale_below_cost':'Engelle','sale_zero_price':'Engelle','discount_approval':'Evet','return_approval':'Evet','cancel_approval':'Evet','critical_password':'Evet','cari_risk_action':'Engelle','session_timeout':'15'},
  'Serbest Çalışma (kontrolsüz)':{'stock_negative':'İzin Ver','sale_below_cost':'İzin Ver','sale_zero_price':'İzin Ver','cari_risk_action':'İzin Ver','campaign_loss':'İzin Ver'}}
 def page_yonetim(self):
  host=self._scroll_host(self.right)
  self._hero(host,'Ayar Yönetimi','Hazır profiller, ayar yedeği / geri yükleme, değişiklik geçmişi ve sağlık kontrolü.','Kapsam: '+self.scope.get())
  def block(title,desc,buttons):
   b=tk.Frame(host,bg='white',highlightbackground='#dbe5ef',highlightthickness=1);b.pack(fill='x',padx=14,pady=6)
   l=tk.Frame(b,bg='white');l.pack(side='left',fill='x',expand=True,padx=14,pady=10)
   tk.Label(l,text=title,bg='white',fg='#000000',font=('Segoe UI',11,'bold')).pack(anchor='w')
   tk.Label(l,text=desc,bg='white',fg='#000000',wraplength=480,justify='left',font=('Segoe UI',9)).pack(anchor='w',pady=(2,0))
   r=tk.Frame(b,bg='white');r.pack(side='right',padx=12,pady=8)
   for txt,cmd,red in buttons:self.btn(r,txt,cmd,red).pack(fill='x',pady=2)
  block('Hazır ayar profilleri','Seçilen profildeki ayarlar SEÇİLİ KAPSAMA yazılır. Diğer ayarlara dokunulmaz. İstediğiniz zaman geçmişten geri alabilirsiniz.',[(f'UYGULA: {n}',lambda n=n:self.apply_profile(n),False) for n in self.PROFILLER])
  block('Ayar yedeği','Tüm kapsamlı ayarları dosyaya kaydeder veya daha önce alınmış bir dosyadan geri yükler. Tanınmayan / geçersiz kayıtlar atlanır.',[('AYARLARI YEDEKLE',self.export_settings,False),('AYARLARI GERİ YÜKLE',self.import_settings,False)])
  block('Değişiklik geçmişi','Kim, ne zaman, hangi ayarı değiştirdi. Geçmişten bir değeri geri alabilirsiniz.',[('GEÇMİŞİ AÇ',self.history,False)])
  block('Sağlık kontrolü','Kayıtlı ayarları doğrular (geçersiz değer, bulunamayan klasör / yazıcı, tanınmayan anahtar). Hiçbir şeyi otomatik değiştirmez.',[('KONTROL ET',self.health_check,True)])
  block('Kapsamı temizle',f'“{self.scope.get()}” kapsamındaki tüm özel ayar değerlerini siler; ayarlar üst kapsamdan / varsayılandan devralınır.',[('BU KAPSAMI TEMİZLE',self.clear_scope,False)])
  try:
   rows=DX.rows('SELECT scope,count(*) n FROM scoped_settings GROUP BY scope ORDER BY scope')
   tk.Label(host,text='Kayıtlı özel ayar sayısı:  '+'   •   '.join(f"{r['scope']}: {r['n']}" for r in rows),bg='#f8fbff',fg='#000000',font=('Segoe UI',9)).pack(anchor='w',padx=16,pady=6)
  except Exception as _se:_silent(_se)
 def apply_profile(self,name):
  data=self.PROFILLER.get(name)
  if not data:return
  if self.has_unsaved_settings() and not self.confirm_leave():return
  lines=[]
  for k,v in data.items():
   s=AYR.spec(k)
   if s is None:continue
   ok,res=AYR.normalize(s,v)
   if ok and res!=self.getval(k,s.default):lines.append((k,s,res))
  if not lines:return messagebox.showinfo(APP,'Bu profildeki ayarlar zaten uygulanmış durumda.',parent=self)
  if not messagebox.askyesno(APP,f'“{name}” profili {self.scope.get()} kapsamına {len(lines)} ayar yazacak:\n\n'+'\n'.join(f'• {s.label}: {self.getval(k,s.default)} → {res}' for k,s,res in lines[:14])+('\n…' if len(lines)>14 else '')+'\n\nUygulansın mı?',parent=self):return
  for k,s,res in lines:
   c=AYR.category_of(k);ayar_yaz(k,res,self._sc_for(k),c.title if c else '');DX.audit('Ayarlar','Profil: '+name,0,'',res,k)
  invalidate_scoped_settings();messagebox.showinfo(APP,f'{len(lines)} ayar uygulandı.',parent=self)
 def clear_scope(self):
  sc=ayar_kapsam_adi(self.scope.get())
  n=DX.one('SELECT count(*) n FROM scoped_settings WHERE scope=?',(sc,))['n']
  if not n:return messagebox.showinfo(APP,'Bu kapsamda özel ayar yok.',parent=self)
  if not messagebox.askyesno(APP,f'{sc} kapsamındaki {n} ayar silinsin mi?\n\nAyarlar üst kapsamdan / varsayılandan devralınır.',parent=self):return
  for r in DX.rows('SELECT k,v,category FROM scoped_settings WHERE scope=?',(sc,)):
   DX.exec('INSERT INTO settings_history(dt,user,scope,category,k,old_value,new_value) VALUES(?,?,?,?,?,?,?)',(now(),current_user(),sc,r['category'] or '',r['k'],r['v'],'(devralınır)'))
  DX.exec('DELETE FROM scoped_settings WHERE scope=?',(sc,));invalidate_scoped_settings();DX.audit('Ayarlar','Kapsam Temizle',0,new=sc)
  messagebox.showinfo(APP,f'{n} ayar silindi.',parent=self)

 def export_settings(self):
  f=filedialog.asksaveasfilename(parent=self,defaultextension='.json',initialfile='ALFABE_AYARLAR_YEDEGI.json',filetypes=[('JSON','*.json')])
  if not f:return
  rows=DX.rows('SELECT scope,category,k,v FROM scoped_settings ORDER BY scope,category,k');data=[dict(r) for r in rows]
  Path(f).write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8');DX.audit('Ayarlar','Dışa Aktar',0,new=f'{len(data)} kayıt')
  messagebox.showinfo(APP,f'{len(data)} ayar kaydı yedeklendi.\n\n{f}',parent=self)
 def import_settings(self):
  f=filedialog.askopenfilename(parent=self,filetypes=[('JSON','*.json')])
  if not f:return
  try:
   data=json.loads(Path(f).read_text(encoding='utf-8'))
   if not isinstance(data,list):raise ValueError('Geçersiz ayar yedeği.')
   if not messagebox.askyesno(APP,f'{len(data)} ayar kaydı içe aktarılsın mı?\n\nGeçersiz veya tanınmayan kayıtlar atlanır.',parent=self):return
   ok_n=0;skipped=[]
   for r in data:
    if not isinstance(r,dict) or not all(x in r for x in ('scope','k','v')):skipped.append('biçimi bozuk kayıt');continue
    k=str(r['k']);scope=str(r['scope']);v=str(r['v']).strip();base=scope.partition(':')[0]
    if base not in self.SCOPES:skipped.append(f'{k}: geçersiz kapsam');continue
    s=AYR.spec(k)
    if s is None:skipped.append(f'{k}: bu sürümde tanınmıyor');continue
    if s.dyn:ok,res=(bool(v),v)
    else:ok,res=AYR.normalize(s,v)
    if not ok:skipped.append(str(res));continue
    c=AYR.category_of(k)
    ayar_yaz(k,res,scope if ':' not in scope else base,c.title if c else str(r.get('category','')));ok_n+=1
   invalidate_scoped_settings();DX.audit('Ayarlar','İçe Aktar',0,new=f'{ok_n} kayıt, {len(skipped)} atlandı')
   apply_table_appearance(self);self.show_category(self.cur)
   msg=f'{ok_n} ayar geri yüklendi.'
   if skipped:msg+=f'\n\n{len(skipped)} kayıt atlandı:\n'+'\n'.join(skipped[:12])+('\n…' if len(skipped)>12 else '')
   messagebox.showinfo(APP,msg,parent=self)
  except Exception as e:messagebox.showerror(APP,'Ayar yedeği okunamadı:\n'+str(e),parent=self)
 def _label_for_key(self,k):
  s=AYR.spec(k)
  if s:return s.label
  return k[6:] if k.startswith('firma_') else k
 def history(self):
  w=new_toplevel(self);w.title('Ayar Değişiklik Geçmişi');w.geometry('1100x620')
  t=ttk.Treeview(w,columns=('id','dt','user','scope','category','key','old','new'),show='headings',displaycolumns=('dt','user','scope','category','key','old','new'))
  for c,h,wd in [('dt','Tarih',145),('user','Kullanıcı',90),('scope','Kapsam',130),('category','Kategori',150),('key','Ayar',210),('old','Eski',140),('new','Yeni',140)]:t.heading(c,text=h);t.column(c,width=wd,anchor='w')
  t.pack(fill='both',expand=True,padx=12,pady=(12,4))
  for r in DX.rows('SELECT * FROM settings_history ORDER BY id DESC LIMIT 1500'):t.insert('','end',iid=str(r['id']),values=(r['id'],r['dt'],r['user'],r['scope'],r['category'],self._label_for_key(r['k']),r['old_value'],r['new_value']))
  def revert():
   sel=t.selection()
   if not sel:return messagebox.showinfo(APP,'Geri almak istediğiniz satırı seçin.',parent=w)
   r=DX.one('SELECT * FROM settings_history WHERE id=?',(int(sel[0]),))
   s=AYR.spec(r['k']) if r else None
   if not r or s is None:return messagebox.showwarning(APP,'Bu kayıt geri alınamaz (ayar bulunamadı).',parent=w)
   old=r['old_value']
   if old=='':return messagebox.showwarning(APP,'Bu değişikliğin eski değeri boş; geri alınamıyor.',parent=w)
   ok,res=(True,old) if s.dyn else AYR.normalize(s,old)
   if not ok:return messagebox.showwarning(APP,str(res),parent=w)
   if not messagebox.askyesno(APP,f'“{s.label}” ayarı {r["scope"]} kapsamında “{res}” değerine döndürülsün mü?',parent=w):return
   base=str(r['scope']).partition(':')[0]
   c=AYR.category_of(r['k']);ayar_yaz(r['k'],res,base,c.title if c else '');DX.audit('Ayarlar','Geri Al',0,r['new_value'],res,r['k'])
   messagebox.showinfo(APP,'Geri alındı.',parent=w);w.destroy()
   if self.vars:self.show_category(self.cur)
  bar=tk.Frame(w);bar.pack(fill='x',padx=12,pady=(4,12))
  self.btn(bar,'SEÇİLİ DEĞİŞİKLİĞİ GERİ AL',revert,True).pack(side='left');self.btn(bar,'KAPAT',w.destroy).pack(side='right')

 # ------------------------------------------------------------------ sağlık kontrolü
 def health_check(self):
  issues=[];seen=set();printers=self._installed_printers()
  def add(level,scope,k,msg,value=''):
   sig=(level,scope,k,msg,str(value))
   if sig in seen:return
   seen.add(sig);s=AYR.spec(k);c=AYR.category_of(k)
   issues.append((level,scope,c.title if c else '—',s.label if s else k,msg,str(value)))
  try:rows=DX.rows('SELECT scope,category,k,v FROM scoped_settings ORDER BY scope,category,k')
  except Exception as e:return messagebox.showerror(APP,'Ayar Sağlık Kontrolü başlatılamadı:\n'+str(e),parent=self)
  for r in rows:
   scope=str(r['scope'] or '');k=str(r['k'] or '');v=str(r['v'] if r['v'] is not None else '').strip();base=scope.partition(':')[0]
   if base not in self.SCOPES:add('HATA',scope,k,'Geçersiz ayar kapsamı.',v)
   s=AYR.spec(k)
   if s is None:
    if k not in _KABUL_EDILEN_ESKI_ANAHTARLAR:add('UYARI',scope,k,'Bu sürümde tanınmayan / eski ayar anahtarı (kullanılmıyor).',v)
    continue
   if s.dyn:
    if not v:add('HATA',scope,k,'Değer boş.',v)
   else:
    ok,res=AYR.normalize(s,v)
    if not ok:add('HATA',scope,k,str(res).split(': ',1)[-1],v)
   if s.kind=='dir' and v:
    try:
     if not Path(os.path.expandvars(os.path.expanduser(v))).is_dir():add('UYARI',scope,k,'Kayıtlı klasör şu anda bulunamıyor.',v)
    except Exception:add('UYARI',scope,k,'Kayıtlı yol doğrulanamadı.',v)
   if s.kind=='printer' and v and v!=YOK_PRN and printers is not None and v.casefold() not in printers:add('UYARI',scope,k,'Seçili yazıcı Windows yazıcı listesinde bulunamadı.',v)
  for k,(var,s,c) in self.vars.items():
   if not s.dyn:
    ok,res=AYR.normalize(s,var.get().strip())
    if not ok:add('HATA',self.scope.get(),k,'Ekrandaki değer geçersiz: '+str(res).split(': ',1)[-1],var.get())
  # çapraz kontroller
  try:
   if ayar_evet('login_required'):
    n=DX.one("SELECT count(*) n FROM users WHERE role='Yönetici' AND COALESCE(active,1)=1")
    if n is not None and not n['n']:add('HATA','Firma','login_required','Açılışta şifre sorulacak ama etkin Yönetici kullanıcı yok.','Evet')
  except Exception as _se:_silent(_se)
  try:
   if ayar_evet('backup_on_close') is False and not ayar_evet('backup_daily'):add('UYARI','Firma','backup_daily','Hem “kapanışta yedek” hem “günlük yedek” kapalı: otomatik yedek alınmıyor.','Hayır')
  except Exception as _se:_silent(_se)
  w=new_toplevel(self);w.title('Ayar Sağlık Kontrolü');w.geometry('1120x650')
  err=sum(1 for x in issues if x[0]=='HATA');warn=sum(1 for x in issues if x[0]=='UYARI')
  status='SAĞLAM' if not issues else ('HATA' if err else 'UYARI')
  head=tk.Frame(w,bg='white');head.pack(fill='x',padx=12,pady=(12,6))
  tk.Label(head,text='AYAR SAĞLIK KONTROLÜ',bg='white',fg='#000000',font=('Segoe UI',16,'bold')).pack(anchor='w',padx=12,pady=(10,2))
  tk.Label(head,text=f'Durum: {status}   •   Hata: {err}   •   Uyarı: {warn}   •   Denetlenen kayıt: {len(rows)}',bg='white',fg=('#15803d' if status=='SAĞLAM' else '#b45309' if status=='UYARI' else '#b91c1c'),font=('Segoe UI',11,'bold')).pack(anchor='w',padx=12,pady=(0,4))
  tk.Label(head,text='Bu kontrol hiçbir ayarı otomatik değiştirmez.',bg='white',fg='#000000').pack(anchor='w',padx=12,pady=(0,10))
  t=ttk.Treeview(w,columns=('level','scope','cat','setting','problem','value'),show='headings')
  for c,h,wd in [('level','Durum',70),('scope','Kapsam',130),('cat','Kategori',155),('setting','Ayar',200),('problem','Kontrol Sonucu',320),('value','Mevcut Değer',190)]:t.heading(c,text=h);t.column(c,width=wd,anchor='w')
  t.pack(fill='both',expand=True,padx=12,pady=6)
  if issues:
   for x in issues:t.insert('','end',values=x)
  else:t.insert('','end',values=('SAĞLAM',self.scope.get(),'Tümü','—','Kontrol edilen ayarlarda sorun bulunmadı.','—'))
  bar=tk.Frame(w);bar.pack(fill='x',padx=12,pady=(4,12));tk.Button(bar,text='KAPAT',command=w.destroy).pack(side='right',padx=4)

 def show_logo_category(self):
  # Firma logosu: tek yerden seçilir; rapor, sipariş, teklif, fatura/e-fatura önizleme, ekstre ve fişlerde kullanılır.
  self.vars={};self._input_widgets={}
  tk.Label(self.right,text='Firma Logosu',bg='white',fg='#000000',font=('Segoe UI',16,'bold')).pack(anchor='w',padx=18,pady=(14,2))
  tk.Label(self.right,text='Seçtiğiniz logo; raporlarda, sipariş / teklif / fatura çıktılarında, cari ekstrelerinde ve fişlerde üst bilgide görünür. Rapor Düzenleyici\'de "Logo göster" kapalıysa o rapor logosuz basılır.',bg='white',fg='#000000',wraplength=760,justify='left').pack(anchor='w',padx=18,pady=(0,8))
  box=tk.Frame(self.right,bg='white',highlightbackground='#dbe5ef',highlightthickness=1);box.pack(fill='x',padx=18,pady=6)
  prev=tk.Label(box,text='Logo seçilmemiş',bg='white',fg='#000000',font=('Segoe UI',11),width=40,height=9);prev.pack(side='left',padx=16,pady=16)
  info=tk.Label(box,text='',bg='white',fg='#000000',justify='left',font=('Segoe UI',10),anchor='nw');info.pack(side='left',padx=10,pady=16,fill='x',expand=True)
  def load():
   try:return json.loads(DX.get('company_details','{}') or '{}')
   except Exception:return {}
  def refresh_prev():
   d=load();data=d.get('logo_data','');nm=d.get('logo_name','')
   prev.image=None
   if not data:
    prev.config(image='',text='Logo seçilmemiş',width=40,height=9);info.config(text='Henüz logo yok.\nPNG, JPG veya GIF dosyası seçebilirsiniz.\nÖnerilen: beyaz / saydam zeminli, en az 600 piksel genişlik.');return
   img=_logo_photo(data,300,180)
   if img is not None:prev.config(image=img,text='',width=img.width(),height=img.height());prev.image=img
   else:prev.config(image='',text='(Önizleme gösterilemiyor\nama logo kayıtlı)',width=40,height=9)
   try:kb=len(base64.b64decode(data))/1024.0
   except Exception:kb=0
   info.config(text='Kayıtlı logo: %s\nBoyut: %.0f KB\n\nTüm rapor ve belge çıktılarında kullanılır.'%(nm or 'logo',kb))
  def choose():
   fn=filedialog.askopenfilename(parent=self,title='Firma logosu seç',filetypes=[('Logo resimleri','*.png *.jpg *.jpeg *.gif')])
   if not fn:return
   try:
    p=Path(fn)
    if p.stat().st_size>3*1024*1024:return messagebox.showwarning(APP,'Logo dosyası 3 MB\'tan büyük olamaz. Daha küçük bir dosya seçin.',parent=self)
    _b,_n,_note=_logo_encode_file(fn)
    d=load();d['logo_data']=_b;d['logo_name']=_n
    DX.exec("INSERT INTO settings(k,v) VALUES('company_details',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(json.dumps(d,ensure_ascii=False),))
    _mirror_company_logo_to_main(d['logo_data'],d['logo_name']);DX.audit('Ayarlar','Firma Logosu',new=p.name);refresh_prev()
    messagebox.showinfo(APP,'Logo kaydedildi. Raporlar bir sonraki açılışta / önizlemede yeni logoyu kullanır.'+(('\n\n'+_note) if _note else ''),parent=self)
   except Exception as ex:
    log_error('Firma logosu kaydı',ex);messagebox.showerror(APP,'Logo kaydedilemedi:\n'+str(ex),parent=self)
  def clear():
   d=load()
   if not d.get('logo_data'):return
   if not messagebox.askyesno(APP,'Firma logosu kaldırılsın mı? Raporlarda firma adı yazılır.',parent=self):return
   d.pop('logo_data',None);d.pop('logo_name',None)
   DX.exec("INSERT INTO settings(k,v) VALUES('company_details',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(json.dumps(d,ensure_ascii=False),))
   _mirror_company_logo_to_main('');DX.audit('Ayarlar','Firma Logosu Kaldır');refresh_prev()
  b=tk.Frame(self.right,bg='white');b.pack(fill='x',padx=18,pady=8)
  self.btn(b,'LOGO SEÇ',choose,True).pack(side='left',padx=4);self.btn(b,'LOGOYU KALDIR',clear).pack(side='left',padx=4)
  refresh_prev()
 def show_vat_rates_category(self):
  for w in self.right.winfo_children():w.destroy()
  tk.Label(self.right,text='KDV Oranları Yönetimi',bg='white',fg='#000000',font=('Segoe UI',16,'bold')).pack(anchor='w',padx=18,pady=(14,2))
  tk.Label(self.right,text='Yeni oran ekleyebilir, kullanılmayan oranı pasif yapabilir ve varsayılan oranı seçebilirsiniz. Geçmiş kayıtlar değişmez.',bg='white',fg='#000000',wraplength=760,justify='left').pack(anchor='w',padx=18,pady=(0,10))
  cols=('rate','active','default');t=ttk.Treeview(self.right,columns=cols,show='headings',height=12)
  for c,h,wid in [('rate','KDV Oranı %',180),('active','Durum',150),('default','Varsayılan',150)]:t.heading(c,text=h);t.column(c,width=wid,anchor='center')
  t.pack(fill='x',padx=18,pady=8)
  def refresh():
   t.delete(*t.get_children())
   for i,x in enumerate(vat_rate_records()):t.insert('','end',iid=str(i),values=(f"{float(x['rate']):g}",'Aktif' if x['active'] else 'Pasif','Evet' if x['default'] else ''))
  def add():
   v=simpledialog.askfloat('Yeni KDV Oranı','Yeni KDV oranı (%):',minvalue=0,maxvalue=100,parent=self)
   if v is None:return
   rows=vat_rate_records()
   if any(abs(float(x['rate'])-float(v))<0.000001 for x in rows):return messagebox.showwarning(APP,'Bu KDV oranı zaten kayıtlı.',parent=self)
   rows.append({'rate':float(v),'active':1,'default':0});rows.sort(key=lambda x:float(x['rate']));save_vat_rate_records(rows);DX.audit('Ayarlar','KDV Oranı Ekle',new=f'{v:g}%');refresh()
  def toggle():
   sel=t.selection()
   if not sel:return messagebox.showinfo(APP,'Bir KDV oranı seçin.',parent=self)
   i=int(sel[0]);rows=vat_rate_records();x=rows[i]
   if x['active'] and x['default']:return messagebox.showwarning(APP,'Varsayılan KDV oranı pasif yapılamaz. Önce başka bir oranı varsayılan seçin.',parent=self)
   x['active']=0 if x['active'] else 1;save_vat_rate_records(rows);DX.audit('Ayarlar','KDV Oranı Durum',new=f"{x['rate']:g}% {'Aktif' if x['active'] else 'Pasif'}");refresh()
  def make_default():
   sel=t.selection()
   if not sel:return messagebox.showinfo(APP,'Bir KDV oranı seçin.',parent=self)
   i=int(sel[0]);rows=vat_rate_records()
   if not rows[i]['active']:return messagebox.showwarning(APP,'Pasif oran varsayılan yapılamaz.',parent=self)
   for j,x in enumerate(rows):x['default']=1 if j==i else 0
   save_vat_rate_records(rows);DX.exec("INSERT INTO settings(k,v) VALUES('stock_vat',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(f"{float(rows[i]['rate']):g}",));DX.audit('Ayarlar','Varsayılan KDV',new=f"{rows[i]['rate']:g}%");refresh()
  b=tk.Frame(self.right,bg='white');b.pack(fill='x',padx=18,pady=8)
