  t.tag_configure('below',background='#FDE3E3',foreground='#000000')
  for x in ch[:5000]:
   cost=costs.get(x['id'],0); pp=((x['new']-cost)/x['new']*100 if x['new'] else 0); bad=x['new']>0 and cost>0 and x['new']<cost
   t.insert('', 'end',values=(x['name'],PX.PRICE_LABEL[x['key']],money(x['old']),money(x['new']),money(x['new']-x['old']),f'{pp:.1f}'),tags=(('below',) if bad else ()))
  t.pack(fill='both',expand=True,padx=12,pady=6)
  fr=tk.Frame(w); fr.pack(fill='x',padx=14); tk.Label(fr,text='Değişiklik nedeni:').pack(side='left'); why=tk.StringVar(value='Excel ile fiyat yükleme: '+os.path.basename(p)); tk.Entry(fr,textvariable=why).pack(side='left',fill='x',expand=True,padx=8,ipady=3)
