  bar=tk.Frame(w); bar.pack(fill='x',padx=14,pady=12)
  tk.Button(bar,text='ONAYLA VE UYGULA',command=apply,bg=RED,fg='white',font=('Segoe UI',10,'bold'),padx=18,pady=8).pack(side='right')
  tk.Button(bar,text='İPTAL',command=w.destroy,padx=14,pady=8).pack(side='right',padx=8)
