   bf=tk.Frame(addf); bf.pack(side='left',padx=(6,0)); tk.Button(bf,text='EKLE',command=add_def).pack(side='left',padx=2); tk.Button(bf,text='DÜZENLE',command=rename_def).pack(side='left',padx=2)
   bot=tk.Frame(d); bot.pack(side='bottom',fill='x',padx=16,pady=(4,12)); tk.Button(bot,text='SİL',command=delete_def).pack(side='left'); tk.Button(bot,text='SEÇ',command=pick,font=('Segoe UI',9,'bold')).pack(side='right'); tk.Button(bot,text='KAPAT',command=d.destroy).pack(side='right',padx=6)
