  tk.Button(head,text='← SİPARİŞ & TEKLİF MERKEZİNE DÖN',command=self.return_center,bg='white',fg='#111111',relief='solid',bd=1,font=('Segoe UI',10,'bold'),padx=10,pady=6).pack(side='left')
  tk.Label(head,text=('TEKLİF' if mode=='offer' and source else (kind.upper()+' SİPARİŞİ' if mode=='order' else 'YENİ TEKLİF')),bg=BG,fg=TXT,font=('Segoe UI',18,'bold')).pack(side='left',padx=18)
  ctype=tk.StringVar(value='Cari Müşteri' if kind!='Tedarikçi' else 'Cari Müşteri');cari=tk.StringVar();name=tk.StringVar();phone=tk.StringVar();valid=tk.StringVar(value=(datetime.date.today()+datetime.timedelta(days=7)).strftime('%Y-%m-%d'));gdisc=tk.DoubleVar(value=0);deposit=tk.DoubleVar(value=0);delivery=tk.StringVar(value=(datetime.date.today()+datetime.timedelta(days=1)).strftime('%Y-%m-%d'));note=tk.StringVar();lines=[]
