  search=tk.Frame(w);search.pack(fill='x',padx=12,pady=5);tk.Label(search,text='Barkod / Ürün Ara:',font=('Segoe UI',10,'bold')).pack(side='left');q=tk.StringVar();qe=tk.Entry(search,textvariable=q,font=('Segoe UI',12),width=30);qe.pack(side='left',padx=4)
