  def redraw():
   t.delete(*t.get_children());sub=0
   for i,x in enumerate(lines):
    net=x['price']*(1-x['discount']/100);tot=net*x['qty'];sub+=tot;t.insert('','end',iid=str(i),tags=('eksik',) if x['qty']>x['stock'] else (),values=(x['barcode'],x['name'],f"{x['stock']:g}",f"{x['qty']:g}",x.get('unit','Adet'),f"{x['price']:.2f}",f"{x.get('vat',0):g}",f"{x['discount']:g}",f"{net:.2f}",f"{tot:.2f}",x.get('note','')))
   gd=max(0,min(100,float(gdisc.get() or 0)));final=sub*(1-gd/100);totals.set(f"ARA TOPLAM: {money(sub)}     GENEL İSKONTO: %{gd:g}     GENEL TOPLAM: {money(final)}");return final
  _picked_ord={'text':None,'r':None}
  def addq(event=None):
   r=_picked_ord['r'] if _picked_ord['r'] is not None and q.get()==_picked_ord['text'] else self.stock_find(q.get())
   _picked_ord['r']=None;_picked_ord['text']=None
   if not r:return messagebox.showwarning(APP,'Ürün bulunamadı.',parent=self)
   if not r['active']:return messagebox.showwarning(APP,'Bu ürün PASİF. Teklif veya siparişe eklemeden önce Stok Merkezi üzerinden aktifleştirin.',parent=self)
   qty=max(.01,float(addqty.get() or 1));price=float(addprice.get()) if addprice.get().strip() else float(r['retail'] or 0);disc=max(0,min(100,float(adddisc.get() or 0)))
   for x in lines:
    if (x['stock_id']==r['id']
        and abs(float(x.get('price',0))-price)<0.000001
        and abs(float(x.get('discount',0))-disc)<0.000001
        and str(x.get('unit') or 'Adet')==str(r['unit'] or 'Adet')
        and not x.get('_alfabe_special_price')):
     x['qty']+=qty;break
   else:lines.append({'stock_id':r['id'],'barcode':r['barcode'] or '','name':r['name'],'stock':float(r['qty'] or 0),'qty':qty,'unit':r['unit'] or 'Adet','vat':float(r['vat'] or 0),'price':price,'discount':disc,'note':''})
   q.set('');addqty.set(1);addprice.set('');adddisc.set(0);redraw();qe.focus_set()
