  def edit_click(event):
   row,col=_alfabe_click_column(t,event)
   if row is None or col not in ('qty','price','discount'):return
   try:i=int(row);x=lines[i]
   except (ValueError,IndexError):return
   cur=float(x[col]);initial=(f"{cur:.2f}" if col=='price' else f"{cur:g}").replace('.',',')
   def commit(text):
    v=fnum(text)
    if col=='qty' and v<=0:return messagebox.showwarning(APP,'Miktar sıfırdan büyük olmalıdır.',parent=self)
    if col=='price' and v<0:return messagebox.showwarning(APP,'Birim fiyat negatif olamaz.',parent=self)
    if col=='discount':v=max(0,min(100,v))
    x[col]=v
    if col=='price':x['_alfabe_special_price']=True
