   _isexp=bool(r['end_date'] and r['end_date']<td);_issoon=bool(r['start_date'] and r['start_date']>td);_islive=bool(r['active']) and not _isexp and not _issoon
   _st='SÜRESİ DOLDU' if _isexp else ('YAKLAŞAN' if (_issoon and r['active']) else ('AKTİF' if r['active'] else 'PASİF'))
   _tag='off' if not r['active'] else ('exp' if _isexp else ('soon' if _issoon else 'live'))
