 def simulate(self):
  cid=self.selected()
  if not cid:return messagebox.showinfo(APP,'Kampanya seçin.')
  r=DX.one('SELECT * FROM campaigns WHERE id=?',(cid,));qty=simpledialog.askfloat('Kampanya Simülasyonu','Örnek ürün adedi:',initialvalue=max(1,float(r['buy_qty'] or 1)),minvalue=.01,parent=self)
  if qty is None:return
  price=simpledialog.askfloat('Kampanya Simülasyonu','Normal birim fiyat:',initialvalue=100,minvalue=0,parent=self)
  if price is None:return
  normal=qty*price;disc=0
  if r['kind'] in ('2 Al 1 Öde','3 Al 2 Öde','X Al Y Öde') and float(r['buy_qty'] or 0)>0:
   groups=int(qty//float(r['buy_qty']));free=groups*(float(r['buy_qty'])-float(r['pay_qty']));disc=free*price
  elif r['kind']=='% İndirim':disc=normal*float(r['value'] or 0)/100
  elif r['kind']=='TL İndirim':disc=min(normal,float(r['value'] or 0))
  elif r['kind']=='Sabit Fiyat' and float(r['fixed_price'] or 0)>0:disc=max(0,normal-qty*float(r['fixed_price']))
  messagebox.showinfo('Kampanya Simülasyonu',f"{r['name']}\nNormal toplam: {money(normal)}\nKampanya indirimi: {money(disc)}\nMüşteri öder: {money(max(0,normal-disc))}")
 def _stock_ids(self,r):
  """Kampanyanın kapsadığı aktif stok id'leri (çoklu seçim, marka/grup/barkod/kod/ürün/tümü)."""
  targets=DX.rows('SELECT * FROM campaign_targets WHERE campaign_id=?',(r['id'],));ids=set()
  if targets:
   for z in targets:
    if z['stock_id']:ids.add(int(z['stock_id']))
    elif z['target_type']=='Marka':ids.update(int(a['id']) for a in DX.rows('SELECT id FROM stock WHERE active=1 AND brand=?',(z['target_value'],)))
    elif z['target_type']=='Grup':ids.update(int(a['id']) for a in DX.rows('SELECT id FROM stock WHERE active=1 AND grp=?',(z['target_value'],)))
   return sorted(ids)
  st=r['scope_type'] or 'Tümü';sv=str(r['scope_value'] or '')
  if st=='Marka' and sv:rows=DX.rows('SELECT id FROM stock WHERE active=1 AND brand LIKE ?',('%'+sv+'%',))
  elif st=='Grup' and sv:rows=DX.rows('SELECT id FROM stock WHERE active=1 AND grp LIKE ?',('%'+sv+'%',))
  elif st=='Barkod' and sv:rows=DX.rows('SELECT id FROM stock WHERE active=1 AND barcode=?',(sv,))
  elif st=='Stok Kodu' and sv:rows=DX.rows('SELECT id FROM stock WHERE active=1 AND code=?',(sv,))
  elif st=='Ürün' and sv:rows=DX.rows('SELECT id FROM stock WHERE active=1 AND name LIKE ?',('%'+sv+'%',))
  elif st=='Çoklu':rows=[]
  else:rows=DX.rows('SELECT id FROM stock WHERE active=1')
  return [int(x['id']) for x in rows]
 def products(self):
  cid=self.selected()
  if not cid:return messagebox.showinfo(APP,'Kampanya seçin.')
  r=DX.one('SELECT * FROM campaigns WHERE id=?',(cid,)); targets=DX.rows('SELECT * FROM campaign_targets WHERE campaign_id=?',(cid,)); where='active=1';args=[]
  if targets:
   ids=set()
   for z in targets:
    if z['stock_id']:ids.add(int(z['stock_id']))
    elif z['target_type']=='Marka':ids.update(int(a['id']) for a in DX.rows('SELECT id FROM stock WHERE active=1 AND brand=?',(z['target_value'],)))
    elif z['target_type']=='Grup':ids.update(int(a['id']) for a in DX.rows('SELECT id FROM stock WHERE active=1 AND grp=?',(z['target_value'],)))
   if ids:where+=' AND id IN ('+','.join('?'*len(ids))+')';args=list(ids)
   else:where+=' AND 1=0'
  elif r['scope_type']=='Marka' and r['scope_value']:where+=" AND brand LIKE ?";args=['%'+r['scope_value']+'%']
  elif r['scope_type']=='Grup' and r['scope_value']:where+=" AND grp LIKE ?";args=['%'+r['scope_value']+'%']
  elif r['scope_type']=='Barkod' and r['scope_value']:where+=" AND barcode=?";args=[r['scope_value']]
  elif r['scope_type']=='Stok Kodu' and r['scope_value']:where+=" AND code=?";args=[r['scope_value']]
  elif r['scope_type']=='Ürün' and r['scope_value']:where+=" AND name LIKE ?";args=['%'+r['scope_value']+'%']
  rows=DX.rows('SELECT barcode,name,brand,grp,retail FROM stock WHERE '+where+' ORDER BY name LIMIT 1000',tuple(args));w=new_toplevel(self);w.title('Kampanyalı Ürünler');w.geometry('850x550');t=ttk.Treeview(w,columns=('barcode','name','brand','grp','price'),show='headings')
  for c,h in zip(('barcode','name','brand','grp','price'),('Barkod','Ürün','Marka','Grup','Perakende')):t.heading(c,text=h);t.column(c,width=160)
  for x in rows:t.insert('','end',values=(x['barcode'],x['name'],x['brand'],x['grp'],money(x['retail'])))
  t.pack(fill='both',expand=True,padx=15,pady=15)
 def to_labels(self):
  cid=self.selected()
  if not cid:return messagebox.showinfo(APP,'Kampanya seçin.')
  r=DX.one('SELECT * FROM campaigns WHERE id=?',(cid,));ids=self._stock_ids(r)
  if not ids:return messagebox.showinfo(APP,'Bu kampanyanın kapsadığı ürün bulunamadı.',parent=self)
  lim=1000;send=ids[:lim]
  if not messagebox.askyesno(APP,f"{len(ids)} ürün kampanya kapsamında."+(f"\nİlk {lim} ürün gönderilecek." if len(ids)>lim else '')+"\nEtiket Merkezi kuyruğuna eklensin mi?",parent=self):return
  con=DX.con();added=0
  try:
   con.execute('BEGIN')
   for sid in send:
    if con.execute("SELECT 1 FROM labels_queue WHERE stock_id=? AND template=? AND substr(dt,1,10)=? AND COALESCE(unit_name,'')=''",(sid,'20x40',today())).fetchone():continue
    con.execute('INSERT INTO labels_queue(stock_id,qty,template,dt) VALUES(?,?,?,?)',(sid,1,'20x40',now()));added+=1
   con.commit()
  except Exception as ex:
   con.rollback();return messagebox.showerror(APP,'Etiket kuyruğuna eklenemedi:\n'+str(ex),parent=self)
  finally:con.close()
  DX.audit('Kampanya','Etikete Gönder',cid,new=f'{added} ürün')
