def _lbl_svg(prims,wpx,hpx,barcode_svg,mmw,mmh):
 """Çizim ilkellerinden tek etiketlik SVG (PDF / resim dışa aktarımı)."""
 out=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{mmw:g}mm" height="{mmh:g}mm" viewBox="0 0 {wpx:.2f} {hpx:.2f}" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="#fff"/>']
 for p in prims:
  if p[0]=='rect':out.append(f'<rect x="{p[1]:.2f}" y="{p[2]:.2f}" width="{p[3]:.2f}" height="{p[4]:.2f}" fill="#000"/>')
  elif p[0]=='line':out.append(f'<line x1="{p[1]:.2f}" y1="{p[2]:.2f}" x2="{p[3]:.2f}" y2="{p[4]:.2f}" stroke="#000" stroke-width="{p[5]}"/>')
  elif p[0]=='barcode':
   s=barcode_svg(p[5])
   if s:out.append(s.replace('<svg ',f'<svg x="{p[1]:.2f}" y="{p[2]:.2f}" width="{p[3]:.2f}" height="{p[4]:.2f}" ',1))
  elif p[0]=='text':
   _,x,y,anc,txt,px,bold,color=p;ta={'nw':'start','n':'middle','ne':'end'}.get(anc,'start');base=y+px*1.08
   out.append(f'<text x="{x:.2f}" y="{base:.2f}" font-size="{px}" font-family="Segoe UI,Arial,sans-serif" font-weight="{700 if bold else 400}" text-anchor="{ta}" fill="{color}" text-rendering="geometricPrecision">{html.escape(str(txt))}</text>')
 out.append('</svg>');return ''.join(out)


