 def refresh_printers(self,silent=False,force=False):
  names=windows_printers(force=force);vals=['Windows Varsayılan Yazıcı']+names
  if hasattr(self,'printer_combo'):self.printer_combo.configure(values=vals)
  if self.printer.get() not in vals:self.printer.set('Windows Varsayılan Yazıcı')
  if not silent and not names:messagebox.showinfo(APP,'Windows üzerinde kullanılabilir yazıcı bulunamadı. Yazıcı bağlantısını ve Windows Yazıcılar ekranını kontrol edin.',parent=self)
 def bulk_qty(self):
  ids=self.t.selection()
  if not ids:return messagebox.showinfo(APP,'Adedi değiştirilecek ürünleri listeden seçin.',parent=self)
  q=simpledialog.askinteger('Toplu Etiket Adedi',f'Seçili {len(ids)} ürünün her biri için kaç etiket basılsın?',initialvalue=1,minvalue=1,maxvalue=9999,parent=self)
  if not q:return
  with DX.con() as c:
   for iid in ids:c.execute('UPDATE labels_queue SET qty=? WHERE id=?',(q,int(iid)))
  self.refresh()
 def _schedule_label_draw(self):
  try:
   if self._label_draw_after:self.after_cancel(self._label_draw_after)
  except Exception as _se:_silent(_se)
  self._label_draw_after=self.after(60,self._run_label_draw)
 def _run_label_draw(self):
  self._label_draw_after=None;self.draw_sample()
 def _schedule_preview_draw(self):
  try:
   if self._label_preview_after:self.after_cancel(self._label_preview_after)
  except Exception as _se:_silent(_se)
  self._label_preview_after=self.after(60,self._run_preview_draw)
 def _run_preview_draw(self):
  self._label_preview_after=None;self.draw_preview_strip()
 def _schedule_label_refresh(self):
  try:
   if getattr(self,'_label_filter_after',None):self.after_cancel(self._label_filter_after)
  except Exception as _se:_silent(_se)
  self._label_filter_after=self.after(120,self.refresh)
 def quick_template(self,tpl):
  self.template.set(tpl)
  # Günlük kullanımda hazır şablonlar güvenli otomatik yerleşimi kullanır.
  # Ölçü ASLA değiştirilmez: hazır şablonlar seçili etiket ölçüsüne (yatay/dikey) uyum sağlar.
  self.draw_preview_strip()
 def set_size(self,w,h):self.label_w.set(str(w));self.label_h.set(str(h));self.apply_size()
 def apply_size(self):
  try:w=float(self.label_w.get().replace(',','.'));h=float(self.label_h.get().replace(',','.'));assert w>0 and h>0
  except Exception:return messagebox.showwarning(APP,'Etiket eni ve boyu sıfırdan büyük sayı olmalı.')
  self.template.set(f'{w:g}x{h:g} - Özel');self.draw_sample();self.draw_preview_strip()
 def save_settings(self,quiet=False):
  for k,v in [('label_width',self.label_w.get()),('label_height',self.label_h.get()),('label_template',self.template.get()),('label_paper',self.paper.get()),('label_rows',self.rows.get()),('label_cols',self.cols.get()),('label_hgap',self.hgap.get()),('label_vgap',self.vgap.get())]:DX.exec('INSERT OR REPLACE INTO settings(k,v) VALUES(?,?)',(k,v))
  CZ.remember_printer('Etiket Yazıcı',self.printer.get())   # Bu bilgisayarın etiket yazıcısı + Cihazlar'daki tanım
  if not quiet:messagebox.showinfo(APP,'Etiket ölçüsü, şablon ve yazıcı ayarları kaydedildi.')
 def _job_settings(self):
  return {'label_width':self.label_w.get(),'label_height':self.label_h.get(),'label_template':self.template.get(),'label_paper':self.paper.get(),'label_printer':self.printer.get(),'label_rows':self.rows.get(),'label_cols':self.cols.get(),'label_hgap':self.hgap.get(),'label_vgap':self.vgap.get()}
 def save_job(self,name=None,overwrite=None):
  # v461.80: Etiket işini (liste + adet + şablon + ölçü + yazıcı) isimle kaydet.
  import ALFABE_ETIKET_IS as EJ
  rows=DX.rows("SELECT stock_id,qty,template,COALESCE(unit_name,'') unit_name FROM labels_queue ORDER BY id")
  if not rows:
   self.stat.config(text='Kaydedilecek etiket listesi boş.');return False
  top=self.winfo_toplevel()
  if name is None:name=simpledialog.askstring(APP,'Bu etiket işinin adı:',initialvalue='Etiket '+datetime.date.today().strftime('%d.%m.%Y'),parent=top)
  if not name or not str(name).strip():return False
  payload=EJ.build_payload([dict(r) for r in rows],self._job_settings())
  c=DX.con()
  try:
   st,msg=EJ.save(c,name,payload,bool(overwrite))
   if st=='exists':
    if not messagebox.askyesno(APP,f'“{msg}” adlı iş zaten kayıtlı. Üzerine yazılsın mı?',parent=top):return False
    st,msg=EJ.save(c,name,payload,True)
   c.commit()
  finally:c.close()
  if st!='ok':
   self.stat.config(text=str(msg));return False
  DX.audit('Etiket','İş Kaydet',0,new=f'{msg} / {len(rows)} ürün')
  messagebox.showinfo(APP,f'“{msg}” kaydedildi.\n{len(rows)} ürün, ölçü ve şablon ayarlarıyla birlikte.\nSonra KAYITLI İŞLER düğmesinden yükleyebilirsiniz.',parent=top)
  return True
 def open_jobs(self):
  import ALFABE_ETIKET_IS as EJ
  return EJ.open_jobs_dialog(self.winfo_toplevel(),DX.con,self.apply_job)
 def apply_job(self,payload,mode='replace'):
  import ALFABE_ETIKET_IS as EJ
  c=DX.con()
  try:items,missing=EJ.existing_items(c,payload)
  finally:c.close()
  s=payload.get('settings') or {}
  if mode=='replace':
   DX.exec('DELETE FROM labels_queue')
   for k,var in (('label_width',self.label_w),('label_height',self.label_h),('label_paper',self.paper),('label_rows',self.rows),('label_cols',self.cols),('label_hgap',self.hgap),('label_vgap',self.vgap)):
    if s.get(k) not in (None,''):var.set(s[k])
   if s.get('label_template'):self.template.set(s['label_template'])
   pr=s.get('label_printer')
   try:
    if pr and pr in list(self.printer_combo.cget('values')):self.printer.set(pr)
   except Exception as _pe:_silent(_pe)
  for i in items:self.enqueue(int(i['stock_id']),int(i.get('qty') or 1),'Kayıtlı İş',0,None,i.get('template') or None,i.get('unit_name') or '')
  self.refresh();self.draw_sample();self.draw_preview_strip()
  self.stat.config(text=self.stat.cget('text')+(f'    ({missing} silinmiş ürün atlandı)' if missing else ''))
  return len(items),missing
 def _measure(self,w=None):
  m=getattr(self,'_tkm',None)
  if m is None:m=self._tkm=_lbl_tk_measure(w if w is not None else self)
  return m
 def _sample_row(self):
  """Tasarım ekranı örneği: gerçek ürünün boş alanları (marka, model, üretim yeri...) örnek değerle doldurulur; böylece her nesne görünür."""
  base={'name':'SERVE DEEP VERSATİL KALEM 07','barcode':'8680869433786','code':'STK-001','retail':250.0,'new_price':250.0,'old_price':300.0,'label_new_price':250.0,'label_old_price':300.0,'brand':'SERVE','grp':'KALEM','model':'DEEP','origin':'Türkiye','price_dt':today()+' 00:00:00','created':today()}
  rows=getattr(self,'_queue_cache',None)
  if not rows:return base
  try:
   r=rows[0];d={k:r[k] for k in r.keys()} if hasattr(r,'keys') else dict(r)
  except Exception:return base
  for k,v in base.items():
   if k=='price_dt' and str(d.get('created') or '').strip():continue  # v470: gerçek baskıyla aynı kural (fiyat tarihi yoksa kart tarihi); örnek bugünü yazmasın
   if d.get(k) is None or (isinstance(d.get(k),str) and not d[k].strip()):d[k]=v
  return d
 def _design_prims(self,cv,design,r,w,h):
  lw=float(design.get('width_mm') or self._label_dims()[0]);lh=float(design.get('height_mm') or self._label_dims()[1])
  fv=lambda d:(d.get('text') if d.get('field')=='SABİT YAZI' and d.get('text') is not None else self._field_value(d.get('field',''),r))
  return _lbl_layout(design.get('fields',[]),fv,self._measure(cv),w/lw,h/lh)
 def _render_prims(self,cv,prims,ox=0,oy=0):
  for p in prims:
   k=p[0]
   if k=='rect':cv.create_rectangle(ox+p[1],oy+p[2],ox+p[1]+p[3],oy+p[2]+p[4],fill='#000000',outline='')
   elif k=='line':cv.create_line(ox+p[1],oy+p[2],ox+p[3],oy+p[4],fill='#000000',width=p[5])
   elif k=='barcode':self._draw_barcode(cv,ox+p[1],oy+p[2],p[3],p[4],p[5])
   elif k=='text':cv.create_text(ox+p[1],oy+p[2],text=p[4],anchor=p[3],font=('Segoe UI',-int(p[5]),'bold' if p[6] else 'normal'),fill=p[7],width=0)
 def draw_sample(self):
  if not hasattr(self,'design_canvas'):return
  c=self.design_canvas;c.delete('all');W=max(200,c.winfo_width());H=max(160,c.winfo_height());lw,lh=self._label_dims()
  try:self._ruler.config(text=f'{self.template.get()}   •   {lw:g} × {lh:g} mm   •   gerçek orantılı ön izleme')
  except Exception as _se:_silent(_se)
  ratio=lw/lh if lh else 1;aw=min(W-70,(H-80)*ratio);ah=aw/ratio if ratio else H-80
  if ah>H-80:ah=H-80;aw=ah*ratio
  x=(W-aw)/2;y=(H-ah)/2;r=self._sample_row();self._last_warns=[]
  self._draw_label(c,x,y,aw,ah,r,outline='#7890a8');warns=list(getattr(self,'_last_warns',[]))
  c.create_text(W/2,y+ah+12,text='Örnek ürün: '+str(r['name'])[:60],font=('Segoe UI',8),fill='#365f84')
  if warns:c.create_text(W/2,y+ah+30,text='⚠ Yazı kutuya sığmak için küçüldü: '+', '.join(f"{f.title()} %{int(q*100)}" for f,q in warns[:3])+'\n“Okunaklı Yap” düğmesi kutuları otomatik büyütür.',font=('Segoe UI',8,'bold'),fill='#a05a00',width=max(200,W-20),justify='center')
 def draw_preview_strip(self):
  if not hasattr(self,'preview_canvas'):return
  c=self.preview_canvas;c.delete('all');rows=(getattr(self,'_queue_cache',[]) or []) if hasattr(self,'t') else [];W=max(300,c.winfo_width());H=max(120,c.winfo_height())
  if not rows:c.create_text(15,45,text='Etiket kuyruğuna ürün eklediğinizde baskı ön izlemesi burada görünecek.',anchor='w',fill='#6b7d90');return
  lw,lh=self._label_dims();ratio=lw/lh if lh else 1;gap=12;ch=max(60,H-26);cw=ch*ratio
  if cw>W*.45:cw=W*.45;ch=cw/ratio
  n=max(1,int((W-gap)//(cw+gap)));self._last_warns=[]
  for i,r in enumerate(rows[:n]):self._draw_label(c,gap+i*(cw+gap),(H-ch)/2,cw,ch,r)
  tot=sum(int(r['qty'] or 1) for r in rows);more=len(rows)-n
  c.create_text(W-8,H-4,anchor='se',text=(f'+{more} ürün daha  •  ' if more>0 else '')+f'toplam {tot} etiket  •  ölçü {lw:g} × {lh:g} mm  •  F9: tam boy ön izleme',font=('Segoe UI',8),fill='#6b7d90')
 def enqueue(self,sid,qty=1,source='Manuel',old_price=0,new_price=None,template=None,unit_name=''):
  # unit_name: kutu/koli barkodu okutulduysa o birimin etiketi (birim barkodu ve birim fiyatı ile) ayrı satır olarak kuyruğa girer.
  template=template or self.template.get();st=DX.one('SELECT * FROM stock WHERE id=?',(sid,));
  if not st:return
  unit_name=str(unit_name or '').strip();_up=float(st['retail'] or 0)
  if unit_name:
   _z=DX.one('SELECT base_quantity,retail FROM stock_unit_conversions WHERE stock_id=? AND unit_name=?',(sid,unit_name))
   if not _z:unit_name=''
   else:_up=float(_z['retail'] or 0) or float(st['retail'] or 0)*float(_z['base_quantity'] or 1)
  np=float(_up if new_price is None else new_price);r=DX.one("SELECT id,qty FROM labels_queue WHERE stock_id=? AND template=? AND COALESCE(unit_name,'')=?",(sid,template,unit_name))
  if r:DX.exec('UPDATE labels_queue SET qty=qty+?,new_price=?,printer=?,source=?,dt=? WHERE id=?',(qty,np,self.printer.get(),source,now(),r['id']))
  else:DX.exec('INSERT INTO labels_queue(stock_id,qty,template,dt,old_price,new_price,printer,source,unit_name) VALUES(?,?,?,?,?,?,?,?,?)',(sid,qty,template,now(),old_price,np,self.printer.get(),source,unit_name))
 def refresh(self):
  self._label_filter_after=None;self._origin_default=None;self.t.delete(*self.t.get_children());term=self.q.get().lower().strip();total=0;shown=0
  rows=DX.rows('SELECT q.*,COALESCE(NULLIF(u.barcode,\'\'),s.barcode) AS barcode,s.code,s.name||CASE WHEN u.id IS NOT NULL THEN \' (\'||u.unit_name||\')\' ELSE \'\' END AS name,(CASE WHEN u.id IS NULL THEN s.retail WHEN u.retail>0 THEN u.retail ELSE s.retail*u.base_quantity END) AS retail,s.brand,s.grp,s.model,s.origin,s.created,(SELECT MAX(ph.dt) FROM price_history ph WHERE ph.stock_id=s.id AND ph.price_type NOT IN (\'Toptan\',\'Özel\',\'Özel Fiyat\')) AS price_dt,COALESCE(NULLIF(q.old_price,0),(CASE WHEN u.id IS NULL THEN s.retail WHEN u.retail>0 THEN u.retail ELSE s.retail*u.base_quantity END)) AS label_old_price,COALESCE(NULLIF(q.new_price,0),(CASE WHEN u.id IS NULL THEN s.retail WHEN u.retail>0 THEN u.retail ELSE s.retail*u.base_quantity END)) AS label_new_price FROM labels_queue q JOIN stock s ON s.id=q.stock_id LEFT JOIN stock_unit_conversions u ON u.stock_id=q.stock_id AND COALESCE(q.unit_name,\'\')<>\'\' AND u.unit_name=q.unit_name ORDER BY q.id DESC');self._queue_cache=rows
  for r in rows:
   if term and term not in (str(r['barcode'])+' '+str(r['code'])+' '+str(r['name'])).lower():continue
   qty=int(r['qty'] or 0);total+=qty;shown+=1;self.t.insert('','end',iid=str(r['id']),values=(r['barcode'],r['code'],r['name'],money(r['new_price'] or r['retail']),qty))
  self.stat.config(text=f'Seçili ürün: {shown}    Toplam etiket: {total}');self.draw_preview_strip()
 def _label_live_close(self):
  win=getattr(self,'_label_live_window',None)
  self._label_live_window=None;self._label_live_tree=None
  if win is not None:
   try:win.destroy()
   except tk.TclError:pass
 def _label_live_key(self,event=None):
  if event is not None and event.keysym in ('Return','Escape','Up','Down','Tab'):return
  self._schedule_label_refresh()
  job=getattr(self,'_label_live_job',None)
  if job:
   try:self.after_cancel(job)
   except tk.TclError:pass
  self._label_live_job=self.after(140,self._label_live_show)
 def _label_live_down(self,event=None):
  tree=getattr(self,'_label_live_tree',None)
  if tree is not None and tree.get_children():
   first=tree.get_children()[0];tree.selection_set(first);tree.focus(first);tree.focus_set()
   return 'break'
 def _label_live_show(self):
  self._label_live_job=None
  q=self.q.get().strip()
  if not q or not self._label_search_entry.winfo_exists():
   self._label_live_close();return
  like='%'+q+'%'
  rows=DX.rows("SELECT id,barcode,code,name,retail,active FROM stock WHERE name LIKE ? OR brand LIKE ? OR code LIKE ? OR barcode LIKE ? OR id IN (SELECT stock_id FROM stock_barcodes WHERE barcode LIKE ? AND active=1) ORDER BY CASE WHEN barcode=? OR code=? THEN 0 WHEN name LIKE ? THEN 1 ELSE 2 END,name LIMIT 40",(like,like,like,like,like,q,q,q+'%'))
  if not rows:self._label_live_close();return
  win=getattr(self,'_label_live_window',None)
