 def set_origin(self):
  ids=self.t.selection()
  rows=[r for r in (getattr(self,'_queue_cache',None) or []) if (not ids or str(r['id']) in ids)]
  if not rows:return messagebox.showinfo(APP,'Önce etiket listesine ürün ekleyin (ya da listeden ürünleri seçin).',parent=self)
  cur=str(DX.get('label_origin_default','') or '')
  v=simpledialog.askstring('Üretim Yeri',f'{len(rows)} ürün için üretim yeri (örn. TÜRKİYE):',initialvalue=cur,parent=self)
  if v is None:return
  v=_tr_upper(' '.join(v.split()))
  if not v:return messagebox.showwarning(APP,'Üretim Yeri boş olamaz.',parent=self)
  sids=sorted({int(r['stock_id']) for r in rows});filled=[r for r in rows if str(r['origin'] or '').strip() and str(r['origin']).strip()!=v]
  overwrite=True
  if filled:overwrite=messagebox.askyesno(APP,f'{len(filled)} üründe farklı bir üretim yeri kayıtlı.\n\nÜzerine yazılsın mı?\n(Hayır: yalnız üretim yeri boş olanlar doldurulur.)',parent=self)
  con=DX.con();n=0
  try:
   con.execute('BEGIN')
   for sid in sids:
    cur_o=con.execute('SELECT origin FROM stock WHERE id=?',(sid,)).fetchone()
    if cur_o and str(cur_o[0] or '').strip() and not overwrite:continue
    con.execute('UPDATE stock SET origin=?,updated=? WHERE id=?',(v,now(),sid));n+=1
   con.commit()
  except Exception as ex:
   con.rollback();return messagebox.showerror(APP,'Üretim Yeri kaydedilemedi:\n'+str(ex),parent=self)
  finally:con.close()
  DX.audit('Etiket','Üretim Yeri Ata',0,new=f'{v} / {n} ürün')
  if messagebox.askyesno(APP,f'{n} ürüne “{v}” yazıldı.\n\nÜretim Yeri kartında boş olan diğer ürünlerde de etiketlere bu değer yazılsın mı (varsayılan üretim yeri)?',parent=self):DX.exec('INSERT OR REPLACE INTO settings(k,v) VALUES(?,?)',('label_origin_default',v))
  self._origin_default=None;self.refresh()
