    src=folder/'etiket_son.html';src.write_text(page,encoding='utf-8');edge=_edge_path()
    if not edge:return messagebox.showwarning(APP,'PDF için Microsoft Edge bulunamadı. Etiketleri Baskı Ön İzleme > YAZDIR ile yazıcıya gönderebilirsiniz.',parent=self)
    dest=Path(fn).resolve();r=subprocess.run([str(edge),'--headless','--disable-gpu','--no-pdf-header-footer',f'--print-to-pdf={dest}',src.resolve().as_uri()],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=120,creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
    if r.returncode!=0 or not dest.exists() or dest.stat().st_size<100:raise RuntimeError('PDF oluşturulamadı: '+r.stderr.decode(errors='ignore')[-200:])
