 def _health_check(self):
  # Seçili raporun veri, tasarım ve ortak çıktı motoru hazırlığını yazdırmadan doğrular.
  try:
   key,heads,rows=self._report_data()
   if not heads: raise RuntimeError('Rapor alanları bulunamadı.')
   d=report_design_get(key,heads); vis=report_visible_columns(d,heads)
   if not vis: raise RuntimeError('Görünür rapor alanı bulunamadı.')
   # HTML aynı motor olduğundan önizleme/yazdırma/PDF yerleşiminin temelini doğrular.
   doc=report_html_document(key,heads,rows[:250],f'Tarih/Saat: {report_display_datetime()}',self._report_total(key,heads,rows[:250]))
   if '<table>' not in doc or '</html>' not in doc: raise RuntimeError('Rapor belgesi üretilemedi.')
   messagebox.showinfo(APP,f'Rapor sağlamlık kontrolü başarılı.\n\nRapor: {self.report.get()}\nAlan: {len(heads)}\nGörünür alan: {len(vis)}\nKayıt: {len(rows)}\nÖnizleme/PDF/Yazdır ortak belge motoru: TAMAM',parent=self)
  except Exception as e:
   log_error('Rapor sağlamlık kontrolü',e);messagebox.showerror(APP,'Rapor sağlamlık kontrolü başarısız:\n'+str(e),parent=self)
 def _open_reports(self):
  w=self
  while w is not None:
   if hasattr(w,'show'):
    try:w.show('Rapor & Analiz');return
    except Exception as _se:_silent(_se)
   w=getattr(w,'master',None)

