class PriceCheck(Base):
 _IDLE='BARKOD OKUTUN / ÜRÜN ARAYIN'
 def __init__(self,p):
  super().__init__(p,'Fiyat Gör')
  self.q=tk.StringVar();self._matches=[];self._reset_job=None
  b=self.card()
  tk.Label(b,text='BARKOD / ÜRÜN ADI / MARKA / STOK KODU',bg='white',fg=MUT,font=('Segoe UI',15,'bold')).pack(anchor='w',padx=20,pady=(12,2))
  e=tk.Entry(b,textvariable=self.q,font=('Segoe UI',28,'bold'),bg='#fff59d',insertbackground='black')
  e.pack(fill='x',padx=20,pady=(2,16),ipady=14);self.entry=e
  e.bind('<Return>',lambda ev:self.go()); e.bind('<KeyRelease>',self._typing); e.bind('<Escape>',lambda ev:self.clear());e.bind('<Down>',lambda ev:self._move(1));e.bind('<Up>',lambda ev:self._move(-1));e.focus_set()
  # Ürün adı yazılırken eşleşenler listelenir; barkod okutulunca liste açılmaz.
  self.lb=tk.Listbox(self,font=('Segoe UI',16),height=6,activestyle='dotbox',exportselection=False)
  self.lb.bind('<ButtonRelease-1>',lambda ev:self._pick_list());self.lb.bind('<Double-1>',lambda ev:self._pick_list())
  self.name=tk.Label(self,text=self._IDLE,bg=BG,fg=TXT,font=('Segoe UI',38,'bold'),wraplength=1200,justify='center')
  self.name.pack(pady=(55,8))
  self.detail=tk.Label(self,text='',bg=BG,fg=MUT,font=('Segoe UI',20,'bold'))
  self.detail.pack(pady=(0,5))
  self.stock_status=tk.Label(self,text='',bg=BG,fg=RED,font=('Segoe UI',22,'bold'))
  self.stock_status.pack(pady=(0,5))
  self.price=tk.Label(self,text='0,00 ₺',bg=BG,fg=RED,font=('Segoe UI',ayar_tam('font_pricecheck'),'bold'))
  self.price.pack(pady=(0,2))
  self.kdv=tk.Label(self,text='',bg=BG,fg=MUT,font=('Segoe UI',16,'bold'));self.kdv.pack(pady=(0,8))
  self.camp=tk.Label(self,text='',bg=BG,fg='#c2410c',font=('Segoe UI',30,'bold'),wraplength=1400,justify='center');self.camp.pack(pady=(0,4))
 def clear(self):
  self.q.set('');self._hide_list()
  self.name.config(text=self._IDLE);self.detail.config(text='');self.stock_status.config(text='');self.price.config(text='0,00 ₺');self.kdv.config(text='');self.camp.config(text='')
  try:self.entry.focus_set()
  except Exception as _se:_silent(_se)
 def _hide_list(self):
  self._matches=[]
  try:self.lb.pack_forget()
  except Exception as _se:_silent(_se)
 def _search(self,q,limit=8):
  f=_tr_fold(q)
  if len(f)<1:return []
  terms=f.split();res=[]
  for r in DX.rows('SELECT * FROM stock ORDER BY active DESC,name COLLATE NOCASE'):
   nm=_tr_fold(str(r['name'] or ''))
   hay=nm+' '+_tr_fold(' '.join(str(r[k] or '') for k in ('brand','model','code','barcode','special')))
   if all(t in hay for t in terms):
    # Sıralama: aktif ürün, adı yazılanla başlayan, sonra alfabetik.
    res.append((0 if r['active'] else 1,0 if nm.startswith(terms[0]) else 1,nm,r))
  res.sort(key=lambda x:x[:3])
  return [x[3] for x in res[:limit]]
 def _typing(self,ev=None):
  if ev is not None and ev.keysym in ('Return','Up','Down','Escape','Tab','Shift_L','Shift_R','Control_L','Control_R'):return
  q=self.q.get().strip()
  # Yalnız rakamlardan oluşan uzun girdi barkod kabul edilir: öneri listesi açılmaz.
  if not q or (q.isdigit() and len(q)>=6):self._hide_list();return
  self._matches=self._search(q)
  if not self._matches:self._hide_list();return
  self.lb.delete(0,'end')
  for r in self._matches:self.lb.insert('end',('' if r['active'] else '[PASİF] ')+str(r['name'])+('   •   '+str(r['brand']) if r['brand'] else '')+'   •   '+money(r['retail']))
  self.lb.config(height=min(6,len(self._matches)));self.lb.selection_clear(0,'end');self.lb.selection_set(0)
  self.lb.pack(fill='x',padx=24,pady=(4,0),before=self.name)
 def _move(self,d):
  if not self._matches:return
  sl=self.lb.curselection();k=(sl[0] if sl else 0)+d;k=max(0,min(len(self._matches)-1,k))
  self.lb.selection_clear(0,'end');self.lb.selection_set(k);self.lb.see(k);return 'break'
 def _pick_list(self):
  sl=self.lb.curselection()
  if not sl or sl[0]>=len(self._matches):return
  r=self._matches[sl[0]];self.q.set('');self._hide_list();self.show(r);self.entry.focus_set()
 def go(self):
  q=self.q.get().strip()
  if not q:return
  if self._matches and not (q.isdigit() and len(q)>=6):
   return self._pick_list()
  r=DX.one('SELECT * FROM stock WHERE (barcode=? OR code=? OR id IN (SELECT stock_id FROM stock_barcodes WHERE barcode=? AND active=1)) ORDER BY active DESC,CASE WHEN barcode=? THEN 0 WHEN code=? THEN 1 ELSE 2 END LIMIT 1',(q,q,q,q,q))
  if not r:
   m=self._search(q,1);r=m[0] if m else None
  self.q.set('');self._hide_list()
  if not r:
   self.name.config(text='ÜRÜN BULUNAMADI');self.detail.config(text='Aranan: '+q);self.stock_status.config(text='');self.price.config(text='');self.kdv.config(text='');self.camp.config(text='');self._arm_reset();return
  self.show(r)
 def show(self,r):
  self.name.config(text=str(r['name']).upper())
  self.detail.config(text='  •  '.join(x for x in [str(r['brand'] or ''),str(r['code'] or ''),str(r['barcode'] or '')] if x))
  act=bool(r['active']);qty=float(r['qty'] or 0)
  self.stock_status.config(text=('PASİF ÜRÜN' if not act else 'STOKTA YOK' if qty<=0 else 'STOKTA VAR  •  '+qty_display(r['qty'])),fg=(RED if not act or qty<=0 else '#13834b'))
  pr=float(r['retail'] or 0)
  if pr<=0:self.price.config(text='FİYAT YOK');self.kdv.config(text='Bu ürünün satış fiyatı tanımlı değil')
  else:self.price.config(text=money(pr));self.kdv.config(text='KDV DAHİL SATIŞ FİYATI')
  try:self.camp.config(text=self._campaign_text(r,pr))
  except Exception:self.camp.config(text='')
  self._arm_reset()
 def _campaign_text(self,r,pr):
  """Ürüne şu an uygulanan kampanya (satıştaki eşleştirme ile aynı kurallar). Yoksa boş döner."""
  if not r['active']:return ''
  td=today()
  camps=DX.rows("SELECT * FROM campaigns WHERE active=1 AND (start_date IS NULL OR start_date='' OR start_date<=?) AND (end_date IS NULL OR end_date='' OR end_date>=?) ORDER BY priority,id",(td,td))
  for c in camps:
   kind=str(c['kind'] or '')
   if kind not in ('2 Al 1 Öde','3 Al 2 Öde','X Al Y Öde','% İndirim','TL İndirim','Sabit Fiyat'):continue
   targets=DX.rows('SELECT target_type,target_value,stock_id FROM campaign_targets WHERE campaign_id=?',(c['id'],))
   typ=c['scope_type'] or 'Tümü';sv=str(c['scope_value'] or '').lower();ok=(typ=='Tümü')
   if targets:
    ok=False
    for t in targets:
     tt=str(t['target_type'] or '');tv=str(t['target_value'] or '').lower()
     if t['stock_id'] and int(t['stock_id'])==int(r['id']):ok=True;break
     if tt=='Marka' and tv==str(r['brand'] or '').lower():ok=True;break
     if tt=='Grup' and tv==str(r['grp'] or '').lower():ok=True;break
   elif typ=='Barkod':ok=str(r['barcode'] or '')==str(c['scope_value'] or '')
   elif typ=='Stok Kodu':ok=str(r['code'] or '')==str(c['scope_value'] or '')
   elif typ=='Ürün':ok=sv in str(r['name'] or '').lower()
   elif typ=='Marka':ok=sv in str(r['brand'] or '').lower()
   elif typ=='Grup':ok=sv in str(r['grp'] or '').lower()
   if not ok:continue
   val=float(c['value'] or 0);txt=''
   if kind in ('2 Al 1 Öde','3 Al 2 Öde','X Al Y Öde'):
    buy=int(float(c['buy_qty'] or 0));pay=int(float(c['pay_qty'] or 0))
    if buy<=0:continue
    txt=f'{buy} AL {pay} ÖDE'
   elif kind=='% İndirim' and val>0:
    txt=f'%{val:g} İNDİRİM'+(f'  •  KAMPANYALI FİYAT: {money(max(0,pr*(1-val/100)))}' if pr>0 else '')
   elif kind=='TL İndirim' and val>0:
    txt=f'{money(val)} İNDİRİM'+(f'  •  KAMPANYALI FİYAT: {money(max(0,pr-val))}' if pr>0 else '')
   elif kind=='Sabit Fiyat' and float(c['fixed_price'] or 0)>0:
    txt=f'KAMPANYALI FİYAT: {money(float(c["fixed_price"]))}'
   else:continue
   end=str(c['end_date'] or '').strip()
   return 'KAMPANYALI  •  '+txt+(f'  (BİTİŞ {_date_display(end[:10])})' if end else '')
  return ''
 def _arm_reset(self):
  # Müşteriye eski ürünün fiyatı bırakılmasın: 60 sn sonra ekran temizlenir.
  try:
   if self._reset_job:self.after_cancel(self._reset_job)
   self._reset_job=self.after(60000,self.clear)
  except Exception as _se:_silent(_se)

