  tk.Label(bar,text='Başlangıç:',bg='white').pack(side='left',padx=(12,3));date_entry(bar,start,width=11).pack(side='left');tk.Label(bar,text='Bitiş:',bg='white').pack(side='left',padx=(8,3));date_entry(bar,end,width=11).pack(side='left')
  cards=tk.Frame(w,bg=BG);cards.pack(fill='x',padx=20,pady=4);cardvars={}
  for key,title in [('net','NET SATIŞ'),('count','İŞLEM'),('items','ÜRÜN ADEDİ'),('avg','ORT. SEPET'),('profit','BRÜT KÂR'),('returns','İADE')]:
   f=tk.Frame(cards,bg='white',bd=1,relief='solid');f.pack(side='left',fill='x',expand=True,padx=3);tk.Label(f,text=title,bg='white',fg=MUT,font=('Segoe UI',9,'bold')).pack(anchor='w',padx=11,pady=(7,0));v=tk.StringVar(value='0');cardvars[key]=v;tk.Label(f,textvariable=v,bg='white',fg=RED if key in ('net','returns') else TXT,font=('Segoe UI',16,'bold')).pack(anchor='w',padx=11,pady=(0,8))
  grid=tk.Frame(w,bg=BG);grid.pack(fill='both',expand=True,padx=20,pady=(8,3));tree=ttk.Treeview(grid,show='headings');ys=ttk.Scrollbar(grid,orient='vertical',command=tree.yview);xs=ttk.Scrollbar(grid,orient='horizontal',command=tree.xview);tree.configure(yscrollcommand=ys.set,xscrollcommand=xs.set);ys.pack(side='right',fill='y');xs.pack(side='bottom',fill='x');tree.pack(side='left',fill='both',expand=True);last={'heads':[],'rows':[],'total':[]}
  total_var=tk.StringVar(value='GENEL TOPLAM')
  totalbar=tk.Frame(w,bg='#e8f1fb',highlightthickness=1,highlightbackground='#9db8d6');totalbar.pack(fill='x',padx=20,pady=(0,6));tk.Label(totalbar,textvariable=total_var,bg='#e8f1fb',fg='#0b376d',font=('Segoe UI',10,'bold'),anchor='w',justify='left',wraplength=1320).pack(fill='x',padx=12,pady=9)
  def query_data(k,a,b):
   p=(a,b+' 23:59:59')
   if k=='Satış Özeti':return ['Belge','Tarih','Müşteri','Ödeme','Brüt','İskonto','Net','Kâr','Durum','Kullanıcı'],DX.rows("SELECT s.doc_no,s.dt,COALESCE(c.title,'Perakende'),s.payment,s.gross,s.discount,s.total,COALESCE(SUM(sl.total-sl.qty*CASE WHEN COALESCE(sl.cost_snapshot,0)>0 THEN sl.cost_snapshot ELSE COALESCE(NULLIF(st.avg_cost,0),st.last_cost,0) END),0),s.status,s.user FROM sales s LEFT JOIN caris c ON c.id=s.customer_id LEFT JOIN sale_lines sl ON sl.sale_id=s.id LEFT JOIN stock st ON st.id=sl.stock_id WHERE s.status='FINAL' AND s.dt BETWEEN ? AND ? GROUP BY s.id ORDER BY s.dt DESC",p)
   if k=='Dönem Karşılaştırması':
    try:da=datetime.date.fromisoformat(a);db=datetime.date.fromisoformat(b)
    except Exception:da=db=datetime.date.today()
    span=max(1,(db-da).days+1);pa=da-datetime.timedelta(days=span);pb=da-datetime.timedelta(days=1)
    def totals(x,y):return DX.one("SELECT COUNT(*) c,COALESCE(SUM(total),0) n,COALESCE(AVG(total),0) av,COALESCE(SUM(discount),0) d FROM sales WHERE status='FINAL' AND dt BETWEEN ? AND ?",(x.isoformat(),y.isoformat()+' 23:59:59'))
    cur=totals(da,db);old=totals(pa,pb)
    def ch(n,o):return ((float(n)-float(o))*100.0/float(o)) if float(o) else (100.0 if float(n) else 0.0)
    return ['Dönem','Tarih Aralığı','İşlem','Net Satış','Ort. Sepet','İskonto','Satış Değişim %'],[('Seçili Dönem',f'{da} / {db}',cur['c'],cur['n'],cur['av'],cur['d'],ch(cur['n'],old['n'])),('Önceki Eş Dönem',f'{pa} / {pb}',old['c'],old['n'],old['av'],old['d'],0)]
   if k=='Günlük Satış Trendi':return ['Gün','İşlem','Ürün Adedi','Net Satış','İskonto','Brüt Kâr'],DX.rows("WITH la AS (SELECT sl.sale_id,SUM(sl.qty) items,SUM(sl.total-sl.qty*CASE WHEN COALESCE(sl.cost_snapshot,0)>0 THEN sl.cost_snapshot ELSE COALESCE(NULLIF(st.avg_cost,0),st.last_cost,0) END) profit FROM sale_lines sl LEFT JOIN stock st ON st.id=sl.stock_id GROUP BY sl.sale_id) SELECT substr(s.dt,1,10),COUNT(*),COALESCE(SUM(la.items),0),SUM(s.total),SUM(s.discount),COALESCE(SUM(la.profit),0) FROM sales s LEFT JOIN la ON la.sale_id=s.id WHERE s.status='FINAL' AND s.dt BETWEEN ? AND ? GROUP BY substr(s.dt,1,10) ORDER BY 1",p)
   if k=='Aylık Satış Trendi':return ['Ay','İşlem','Net Satış','İskonto','Brüt Kâr'],DX.rows("WITH la AS (SELECT sl.sale_id,SUM(sl.total-sl.qty*CASE WHEN COALESCE(sl.cost_snapshot,0)>0 THEN sl.cost_snapshot ELSE COALESCE(NULLIF(st.avg_cost,0),st.last_cost,0) END) profit FROM sale_lines sl LEFT JOIN stock st ON st.id=sl.stock_id GROUP BY sl.sale_id) SELECT substr(s.dt,1,7),COUNT(*),SUM(s.total),SUM(s.discount),COALESCE(SUM(la.profit),0) FROM sales s LEFT JOIN la ON la.sale_id=s.id WHERE s.status='FINAL' AND s.dt BETWEEN ? AND ? GROUP BY substr(s.dt,1,7) ORDER BY 1",p)
   if k=='Saatlik Yoğunluk':return ['Saat','İşlem','Net Satış','Ortalama Sepet'],DX.rows("SELECT CASE WHEN length(dt)>=13 AND substr(dt,12,2) GLOB '[0-2][0-9]' THEN substr(dt,12,2)||':00' ELSE 'Saat Bilgisi Yok' END,COUNT(*),SUM(total),AVG(total) FROM sales WHERE status='FINAL' AND dt BETWEEN ? AND ? GROUP BY 1 ORDER BY CASE WHEN 1='Saat Bilgisi Yok' THEN 1 ELSE 0 END,1",p)
   if k=='Haftanın Günleri':return ['Gün','İşlem','Net Satış','Ortalama Sepet'],DX.rows("SELECT CASE strftime('%w',dt) WHEN '0' THEN 'Pazar' WHEN '1' THEN 'Pazartesi' WHEN '2' THEN 'Salı' WHEN '3' THEN 'Çarşamba' WHEN '4' THEN 'Perşembe' WHEN '5' THEN 'Cuma' WHEN '6' THEN 'Cumartesi' ELSE 'Bilinmiyor' END,COUNT(*),SUM(total),AVG(total) FROM sales WHERE status='FINAL' AND dt BETWEEN ? AND ? GROUP BY strftime('%w',dt) ORDER BY strftime('%w',dt)",p)
   if k in ('Ürün Performansı','Marka Performansı','Grup Performansı'):
    fld={'Ürün Performansı':'COALESCE(st.name,sl.name)','Marka Performansı':"COALESCE(st.brand,'(Boş)')",'Grup Performansı':"COALESCE(st.grp,'(Boş)')"}[k];cost="sl.qty*CASE WHEN COALESCE(sl.cost_snapshot,0)>0 THEN sl.cost_snapshot ELSE COALESCE(NULLIF(st.avg_cost,0),st.last_cost,0) END";return ['Kırılım','Adet','Ciro','Maliyet','Brüt Kâr','Kâr %'],DX.rows(f"SELECT {fld},SUM(sl.qty),SUM(sl.total),SUM({cost}),SUM(sl.total-{cost}),CASE WHEN SUM(sl.total)>0 THEN SUM(sl.total-{cost})*100.0/SUM(sl.total) ELSE 0 END FROM sale_lines sl JOIN sales s ON s.id=sl.sale_id LEFT JOIN stock st ON st.id=sl.stock_id WHERE s.status='FINAL' AND s.dt BETWEEN ? AND ? GROUP BY {fld} ORDER BY SUM(sl.total) DESC",p)
   if k=='Birlikte Satılan Ürünler':return ['1. Ürün','2. Ürün','Birlikte Satış Sayısı'],DX.rows("SELECT a.name,b.name,COUNT(DISTINCT a.sale_id) FROM sale_lines a JOIN sale_lines b ON b.sale_id=a.sale_id AND b.id>a.id JOIN sales s ON s.id=a.sale_id WHERE s.status='FINAL' AND s.dt BETWEEN ? AND ? GROUP BY a.name,b.name ORDER BY 3 DESC LIMIT 250",p)
   if k=='Ödeme Türü Analizi':return ['Ödeme Türü','İşlem','Tutar','Pay %'],DX.rows("SELECT COALESCE(sp.kind,s.payment),COUNT(DISTINCT s.id),SUM(COALESCE(sp.amount,s.total)),100.0*SUM(COALESCE(sp.amount,s.total))/NULLIF((SELECT SUM(total) FROM sales WHERE status='FINAL' AND dt BETWEEN ? AND ?),0) FROM sales s LEFT JOIN sale_payments sp ON sp.sale_id=s.id WHERE s.status='FINAL' AND s.dt BETWEEN ? AND ? GROUP BY COALESCE(sp.kind,s.payment) ORDER BY 3 DESC",p+p)
   if k=='Kullanıcı / Kasiyer Performansı':return ['Kullanıcı','İşlem','Net Satış','İskonto','Ortalama Sepet'],DX.rows("SELECT COALESCE(user,'(Boş)'),COUNT(*),SUM(total),SUM(discount),AVG(total) FROM sales WHERE status='FINAL' AND dt BETWEEN ? AND ? GROUP BY user ORDER BY 3 DESC",p)
   if k=='Müşteri Satış Analizi':return ['Müşteri','İşlem','Net Satış','Ortalama Sepet','Son Satış'],DX.rows("SELECT COALESCE(c.title,'Perakende'),COUNT(*),SUM(s.total),AVG(s.total),MAX(s.dt) FROM sales s LEFT JOIN caris c ON c.id=s.customer_id WHERE s.status='FINAL' AND s.dt BETWEEN ? AND ? GROUP BY s.customer_id ORDER BY 3 DESC",p)
   if k=='İskonto Analizi':return ['Belge','Tarih','Brüt','İskonto','İskonto %','Net','Kullanıcı'],DX.rows("SELECT doc_no,dt,gross,discount,CASE WHEN gross>0 THEN discount*100.0/gross ELSE 0 END,total,user FROM sales WHERE status='FINAL' AND dt BETWEEN ? AND ? AND discount>0 ORDER BY discount DESC",p)
   if k=='İade Analizi':return ['Belge','Tarih','Tutar','Neden','Kullanıcı','Orijinal Satış'],DX.rows("SELECT r.doc_no,r.dt,ABS(r.total),r.return_note,r.user,o.doc_no FROM sales r LEFT JOIN sales o ON o.id=r.original_sale_id WHERE r.status='RETURN' AND r.dt BETWEEN ? AND ? ORDER BY r.dt DESC",p)
   if k=='Satış / İade Karşılaştırması':return ['Gün','Satış İşlemi','Brüt Satış','İade İşlemi','İade Tutarı','Net Sonuç'],DX.rows("SELECT substr(dt,1,10),SUM(CASE WHEN status='FINAL' THEN 1 ELSE 0 END),SUM(CASE WHEN status='FINAL' THEN total ELSE 0 END),SUM(CASE WHEN status='RETURN' THEN 1 ELSE 0 END),ABS(SUM(CASE WHEN status='RETURN' THEN total ELSE 0 END)),SUM(total) FROM sales WHERE status IN ('FINAL','RETURN') AND dt BETWEEN ? AND ? GROUP BY substr(dt,1,10) ORDER BY 1",p)
   if k=='Kârlılık Analizi':return ['Belge','Tarih','Net Satış','Maliyet','Brüt Kâr','Kâr %'],DX.rows("SELECT s.doc_no,s.dt,s.total,SUM(sl.qty*CASE WHEN COALESCE(sl.cost_snapshot,0)>0 THEN sl.cost_snapshot ELSE COALESCE(NULLIF(st.avg_cost,0),st.last_cost,0) END),SUM(sl.total-sl.qty*CASE WHEN COALESCE(sl.cost_snapshot,0)>0 THEN sl.cost_snapshot ELSE COALESCE(NULLIF(st.avg_cost,0),st.last_cost,0) END),CASE WHEN SUM(sl.total)>0 THEN SUM(sl.total-sl.qty*CASE WHEN COALESCE(sl.cost_snapshot,0)>0 THEN sl.cost_snapshot ELSE COALESCE(NULLIF(st.avg_cost,0),st.last_cost,0) END)*100.0/SUM(sl.total) ELSE 0 END FROM sales s JOIN sale_lines sl ON sl.sale_id=s.id LEFT JOIN stock st ON st.id=sl.stock_id WHERE s.status='FINAL' AND s.dt BETWEEN ? AND ? GROUP BY s.id ORDER BY 5 DESC",p)
   return ['Sepet Aralığı','İşlem','Toplam Satış'],DX.rows("SELECT CASE WHEN total<100 THEN '0-99' WHEN total<250 THEN '100-249' WHEN total<500 THEN '250-499' WHEN total<1000 THEN '500-999' ELSE '1000+' END,COUNT(*),SUM(total) FROM sales WHERE status='FINAL' AND dt BETWEEN ? AND ? GROUP BY 1 ORDER BY MIN(total)",p)
  def run():
   a=start.get() or today();b=end.get() or today()
   try:
    da=datetime.date.fromisoformat(a);db=datetime.date.fromisoformat(b)
    if da>db:raise ValueError('Başlangıç tarihi bitiş tarihinden sonra olamaz.')
    heads,rows=query_data(report.get(),a,b)
   except Exception as e:
    return messagebox.showerror(APP,'Gelişmiş rapor hazırlanamadı:\n'+str(e),parent=self)
   def shown(h,v):
    if isinstance(v,tk.Variable):
     try:v=v.get()
     except Exception:return ''
    if v is None:return ''
    return report_value_text(h,v)
   def numeric(value):
    if isinstance(value,tk.Variable):
     try:value=value.get()
     except Exception:return None
    try:return float(value)
    except (TypeError,ValueError):return None
   def total_row():
    vals=[None]*len(heads);parts=[]
    if vals:vals[0]='GENEL TOPLAM'
    if not rows:return vals,'GENEL TOPLAM  |  Kayıt bulunamadı'
    def idx(names):
     for n in names:
      for j,h in enumerate(heads):
       if n in h.lower():return j
     return None
    skip=('tarih','gün','ay','saat','belge','dönem','aralığı','müşteri','kullanıcı','ödeme türü','kırılım','ürün','neden','durum','son satış','orijinal')
    for j,h in enumerate(heads):
     hl=h.lower()
     if j==0 or any(x in hl for x in skip) or '%' in h or 'ortalama' in hl or 'ort.' in hl:continue
     nums=[numeric(r[j]) for r in rows];nums=[x for x in nums if x is not None]
     if nums:
      vals[j]=sum(nums);parts.append(f'{h}: {shown(h,vals[j])}')
    trans=idx(['işlem']);amount=idx(['net satış','toplam satış','tutar','ciro']);avg=idx(['ortalama sepet','ort. sepet'])
    if avg is not None and trans is not None and amount is not None:
     tc=sum(numeric(r[trans]) or 0 for r in rows);ta=sum(numeric(r[amount]) or 0 for r in rows);vals[avg]=ta/tc if tc else 0;parts.append(f'{heads[avg]}: {shown(heads[avg],vals[avg])}')
    for j,h in enumerate(heads):
     if '%' not in h:continue
     hl=h.lower();v=None
     if 'pay' in hl:v=100.0 if rows else 0
     elif 'kâr' in hl:
      pi=idx(['brüt kâr']);bi=idx(['ciro','net satış'])
      if pi is not None and bi is not None:
       pv=sum(numeric(r[pi]) or 0 for r in rows);bv=sum(numeric(r[bi]) or 0 for r in rows);v=pv*100.0/bv if bv else 0
     elif 'iskonto' in hl:
      di=idx(['iskonto']);gi=idx(['brüt'])
      if di is not None and gi is not None:
       dv=sum(numeric(r[di]) or 0 for r in rows);gv=sum(numeric(r[gi]) or 0 for r in rows);v=dv*100.0/gv if gv else 0
     if v is not None:vals[j]=v;parts.append(f'{h}: {shown(h,v)}')
    return vals,'GENEL TOPLAM  |  '+('   •   '.join(parts) if parts else f'{len(rows)} kayıt')
   totals,total_text=total_row()
   display_rows=[tuple(shown(heads[i],v) for i,v in enumerate(row)) for row in rows]
   display_total=tuple(shown(heads[i],v) for i,v in enumerate(totals));last['heads']=heads;last['rows']=display_rows;last['total']=display_total;total_var.set(total_text);tree.delete(*tree.get_children());tree._alfabe_report_title=report.get();tree._alfabe_report_key='Gelişmiş Satış / '+report.get();tree['displaycolumns']=();tree['columns']=[str(i) for i in range(len(heads))];tree['displaycolumns']='#all'
   for i,h in enumerate(heads):tree.heading(str(i),text=h);tree.column(str(i),width=150,anchor='w')
   try:design=apply_report_design(tree,'Gelişmiş Satış / '+report.get(),heads)
   except Exception:tree['displaycolumns']='#all';design={'show_totals':1,'font_size':9}
   totalbar.pack_forget()
   if design.get('show_totals',1):totalbar.pack(fill='x',padx=20,pady=(0,6),before=grid)
