  self.t.delete(*self.t.get_children());q='%'+self.q.get().strip()+'%'
  for r in DX.rows("SELECT id,title,description,start_date,end_date,alert_time,priority,is_read,created_by FROM announcements WHERE title LIKE ? OR description LIKE ? ORDER BY is_read,CASE priority WHEN 'Acil' THEN 0 WHEN 'Önemli' THEN 1 ELSE 2 END,id DESC",(q,q)):
   self.t.insert('','end',iid='A:'+str(r['id']),values=('Duyuru',r['priority'] or 'Normal',r['title'],r['start_date'] or '',r['alert_time'] or '','Okundu' if r['is_read'] else 'Aktif',r['created_by'] or ''))
  for r in DX.rows("SELECT id,title,detail,due,level,status,completed,assigned_to FROM reminders WHERE title LIKE ? OR detail LIKE ? ORDER BY COALESCE(completed,0),id DESC",(q,q)):
   due=str(r['due'] or '');self.t.insert('','end',iid='R:'+str(r['id']),values=('Hatırlatma',r['level'] or 'NORMAL',r['title'],due[:10],due[11:16] if len(due)>10 else '', 'Tamamlandı' if r['completed'] else (r['status'] or 'Yeni'),r['assigned_to'] or ''))
