 def stock_alert_rule(self,title):
  pct=self.rule('profit_pct',20)
  return {
   'Negatif stok':('qty<0',()),'Kritik stok':('min_qty>0 AND qty>=0 AND qty<=min_qty',()),'Sıfır stok':('qty=0',()),
   'Fazla stok':('max_qty>0 AND qty>max_qty',()),
   'Stok bitişi yaklaşıyor':("id IN(SELECT st.id FROM stock st JOIN sale_lines sl ON sl.stock_id=st.id JOIN sales sa ON sa.id=sl.sale_id WHERE st.active=1 AND st.qty>0 AND substr(sa.dt,1,10)>=date('now','-7 day') GROUP BY st.id HAVING SUM(sl.qty)>0 AND st.qty/(SUM(sl.qty)/7.0)<="+str(int(self.rule('stockout_days',7)))+")",()),
   'Ölü stok / bağlı sermaye':("qty>0 AND id NOT IN(SELECT DISTINCT sl.stock_id FROM sale_lines sl JOIN sales sa ON sa.id=sl.sale_id WHERE sl.stock_id IS NOT NULL AND substr(sa.dt,1,10)>=date('now','-"+str(int(self.rule('no_sale_days',90)))+" day'))",()),
   'Raf bilgisi eksik':("COALESCE(section,'')='' OR COALESCE(shelf,'')=''",()),
   'Satış fiyatı eksik':('retail<=0',()),'Maliyet eksik':('avg_cost<=0',()),
   'Zararına satış riski':('avg_cost>0 AND retail<avg_cost',()),
   'Düşük kâr oranı':('retail>0 AND avg_cost>0 AND ((retail-avg_cost)*100.0/retail)<?',(pct,)),
   'Maliyet arttı / fiyat riski':("id IN(SELECT DISTINCT ph.stock_id FROM price_history ph WHERE ph.price_type IN ('Alış','Maliyet','Son Alış') AND ph.new_price>ph.old_price) AND retail<=avg_cost",()),
   'Barkodsuz stok kartı':("COALESCE(barcode,'')=''",()),
   'Sipariş verilmesi gereken ürün':('qty<=min_qty',()),
   'Kampanyada stoku biten ürün':("qty<=0 AND id IN(SELECT stock_id FROM campaign_targets WHERE stock_id IS NOT NULL)",()),
   'Etiketi yenilenmesi gereken ürün':("id IN(SELECT DISTINCT stock_id FROM price_history WHERE substr(dt,1,10)=date('now'))",()),
   'Eksik ürün kartları':("COALESCE(name,'')='' OR COALESCE(code,'')='' OR COALESCE(unit,'')=''",()),
   'Bugün fiyatı değişen ürün':("id IN(SELECT DISTINCT stock_id FROM price_history WHERE substr(dt,1,10)=date('now'))",())}.get(title)
