 def sales_alert_rule(self,title):
  disc=self.rule('discount_pct',25);amount=self.rule('high_sale_amount',5000);qty=self.rule('high_item_qty',20)
  return {
   'Yüksek iskonto':("s.status IN ('FINAL','PARTIAL_RETURN') AND substr(s.dt,1,10)=date('now') AND s.gross>0 AND s.discount*100.0/s.gross>=?",(disc,)),
   'Maliyet altında satış':("s.status IN ('FINAL','PARTIAL_RETURN') AND substr(s.dt,1,10)=date('now') AND EXISTS(SELECT 1 FROM sale_lines x LEFT JOIN stock stx ON stx.id=x.stock_id WHERE x.sale_id=s.id AND x.qty>0 AND x.total<(x.qty*CASE WHEN COALESCE(x.cost_snapshot,0)>0 THEN x.cost_snapshot ELSE COALESCE(stx.avg_cost,0) END))",()),
   'Olağan dışı yüksek satış':("s.status IN ('FINAL','PARTIAL_RETURN') AND substr(s.dt,1,10)=date('now') AND s.total>=?",(amount,)),
   'Aynı üründe olağan dışı satış':("s.status IN ('FINAL','PARTIAL_RETURN') AND substr(s.dt,1,10)=date('now') AND EXISTS(SELECT 1 FROM sale_lines x WHERE x.sale_id=s.id AND x.stock_id IN(SELECT sl2.stock_id FROM sale_lines sl2 JOIN sales s2 ON s2.id=sl2.sale_id WHERE s2.status IN ('FINAL','PARTIAL_RETURN') AND substr(s2.dt,1,10)=date('now') AND sl2.stock_id IS NOT NULL GROUP BY sl2.stock_id HAVING SUM(sl2.qty)>=?))",(qty,)),
   'İade yoğunluğu':("s.status='RETURN' AND substr(s.dt,1,10)=date('now')",()),
   'Satış iptali yoğunluğu':("s.status='CANCEL' AND substr(s.dt,1,10)=date('now')",()),
   'Satış düşüşü':("s.status IN ('FINAL','PARTIAL_RETURN') AND substr(s.dt,1,10)=date('now')",()),
   'Satış artışı':("s.status IN ('FINAL','PARTIAL_RETURN') AND substr(s.dt,1,10)=date('now')",())}.get(title)
