def _login_on():
 try:
  r=DX.one("SELECT v FROM scoped_settings WHERE scope='Firma' AND k='login_required' ORDER BY id DESC LIMIT 1")
  v=str(r['v'] if r else DX.get('login_required','Hayır'))
 except Exception:v=str(DX.get('login_required','Hayır'))
 return v.strip().lower() in ('evet','yes','1','true','açık','acik')

def _sec_opt_raw(k):
 """Ayar kaydı yoksa None (kayıt defteri varsayılanı uygulanmaz)."""
 try:
  v=_scoped_setting_lookup(k)
  if v in (None,''):v=DX.get(k,None)
  return None if v in (None,'') else v
 except Exception:return None
def _sec_opt(k,default=''):
 v=_sec_opt_raw(k)
 if v is not None:return v
 try:
  s=AYR.spec(k)
  return s.default if s is not None else default
 except Exception:return default

def _ayar_ac(kategori=None):
 """Başka modüllerden Ayarlar Merkezi'ni (isteğe bağlı kategoriyle) açar."""
 try:
  Settings.START_CAT=kategori
  root=tk._default_root
  if root is not None and hasattr(root,'show'):root.show('Ayarlar')
 except Exception as e:log_error('Ayarlar aç',e)

def _sec_save_opt(k,v):
 c=AYR.category_of(k)
 ayar_yaz(k,str(v),'Firma',c.title if c else 'Kullanıcı & Güvenlik');return
 DX.exec("INSERT INTO settings(k,v) VALUES(?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",(k,str(v)))
 DX.exec("INSERT INTO scoped_settings(scope,category,k,v,updated,user) VALUES(?,?,?,?,?,?) ON CONFLICT(scope,k) DO UPDATE SET category=excluded.category,v=excluded.v,updated=excluded.updated,user=excluded.user",('Firma','Kullanıcı & Güvenlik',k,str(v),now(),current_user()))
 try:invalidate_scoped_settings()
 except Exception as _se:_silent(_se)

def _period_role_rows():
 try:return ([tuple(r) for r in DX.rows('SELECT name,description,active FROM roles')],[tuple(r) for r in DX.rows('SELECT role,module,view,add_rec,edit,passive,print,critical FROM role_permissions')])
 except Exception:return ([],[])

def _sync_perms_to_period():
 """Firma yetkilerini açık dönem DB'sine aynalar (AI Asistan / Günlük gibi eski okuyucular aynı yetkiyi görsün)."""
 try:
  G=_gv();c=G._con()
  try:
   roles=[tuple(r) for r in c.execute('SELECT name,description,active FROM sec_roles')]
   perms=[tuple(r) for r in c.execute('SELECT role,module,view,add_rec,edit,passive,print,critical FROM sec_role_permissions')]
  finally:c.close()
  con=DX.con()
  try:
   con.execute("CREATE TABLE IF NOT EXISTS roles(name TEXT PRIMARY KEY,description TEXT,active INTEGER DEFAULT 1)")
   con.execute("CREATE TABLE IF NOT EXISTS role_permissions(role TEXT,module TEXT,view INTEGER DEFAULT 0,add_rec INTEGER DEFAULT 0,edit INTEGER DEFAULT 0,passive INTEGER DEFAULT 0,print INTEGER DEFAULT 0,critical INTEGER DEFAULT 0,PRIMARY KEY(role,module))")
   con.execute('DELETE FROM role_permissions');con.executemany('INSERT INTO role_permissions(role,module,view,add_rec,edit,passive,print,critical) VALUES(?,?,?,?,?,?,?,?)',perms)
   con.executemany('INSERT OR REPLACE INTO roles(name,description,active) VALUES(?,?,?)',roles);con.commit()
  finally:con.close()
 except Exception as e:log_error('Yetki aynalama',e)


def _sale_cancel_log(kind,items,approver='',note=''):
 """v448: Kaydedilmeden iptal edilen satış satırları / fişler kayıt altına alınır (rapor: İptal Edilen Fişler / Ürünler)."""
 try:
  con=DX.con()
  try:
   con.execute("CREATE TABLE IF NOT EXISTS sale_cancels(id INTEGER PRIMARY KEY,dt TEXT,user TEXT,kind TEXT,item_count INTEGER,total REAL,approver TEXT,note TEXT)")
   con.execute("CREATE TABLE IF NOT EXISTS sale_cancel_lines(id INTEGER PRIMARY KEY,cancel_id INTEGER,stock_id INTEGER,barcode TEXT,name TEXT,qty REAL,price REAL,total REAL)")
   tot=0.0;rows=[]
   for x in items:
    q=float(x.get('qty') or 0);pr=float(x.get('price') or 0);t=max(0.0,q*pr-float(x.get('disc',0) or 0)-float(x.get('camp_disc',0) or 0));tot+=t
    rows.append((x.get('id'),str(x.get('barcode') or ''),str(x.get('name') or ''),q,pr,round(t,2)))
   cid=con.execute('INSERT INTO sale_cancels(dt,user,kind,item_count,total,approver,note) VALUES(?,?,?,?,?,?,?)',(now(),current_user(),kind,len(rows),round(tot,2),approver,note)).lastrowid
   con.executemany('INSERT INTO sale_cancel_lines(cancel_id,stock_id,barcode,name,qty,price,total) VALUES(?,?,?,?,?,?,?)',[(cid,)+r for r in rows]);con.commit()
  finally:con.close()
 except Exception as e:log_error('Satış iptal kaydı',e)

def _cancel_ok(parent,what):
 """Satış İptal Onayı ayarı: yetkisi olmayan kullanıcı satır / fiş iptalinde yetkili onayı alır. (izin, onaylayan) döner."""
 try:
  G=_gv()
  if not G._yes(_sec_opt('cancel_approval','Evet')) or G.can('Hızlı Satış','critical'):return True,''
  who=G.approve_dialog(parent,f'"{what}" için yetkiniz yok ({current_user()} / {CURRENT_ROLE}).\nKaydedilmemiş satışı iptal etmek için yetkili onayı gerekiyor.','Hızlı Satış','critical')
  return (who is not None),(who or '')
 except Exception as e:
  log_error('Satış iptal onayı',e);return True,''

