  for v in (self.f_status,self.f_type,self.q):v.trace_add('write',lambda *_:self.refresh())
  self.summary=tk.Label(f,text='',bg='white',fg=TXT,font=('Segoe UI',9,'bold')); self.summary.pack(side='right')
  cols=('date','no','type','kind','buyer','vkn','net','vat','total','status','sale')
  heads={'date':('Tarih',90),'no':('Fatura No',150),'type':('Belge',100),'kind':('Tip',60),'buyer':('Alıcı',260),'vkn':('VKN / TCKN',100),'net':('Matrah',90),'vat':('KDV (+ÖTV)',90),'total':('Toplam',100),'status':('Durum',120),'sale':('Satış No',120)}
