  for key in ['Toplam','Aktif','Varsayılan','Sorunlu','Doğrulanamadı']:
   f=tk.Frame(cards,bg='white',highlightthickness=1,highlightbackground=BORDER);f.pack(side='left',fill='x',expand=True,padx=4);tk.Label(f,text=key,bg='white',fg='#c00000',font=('Segoe UI',9,'bold')).pack(anchor='w',padx=12,pady=(8,0));v=tk.Label(f,text='0',bg='white',fg='#000000',font=('Segoe UI',18,'bold'));v.pack(anchor='w',padx=12,pady=(0,8));self.card_labels[key]=v
  self.detail=tk.Label(self,text='',bg='#eef6ff',fg='#000000',anchor='w',justify='left',wraplength=1500,font=('Segoe UI',10),padx=12,pady=8);self.detail.pack(side='bottom',fill='x',padx=24,pady=(0,12))
  wrap=tk.Frame(self,bg=BG);wrap.pack(fill='both',expand=True,padx=24,pady=10)
