   for r in reversed(hist):ph.insert('','end',values=(r['stock'] or '-',r['supplier'] or '-',r['dt'],money(r['cost']),money(r['_old']) if r['_old'] is not None else '-',f"{r['_chg']:+.1f}%" if r['_old'] else '-'))
