  # Alış satırlarını ayrı pencere açmadan doğrudan tablo üzerinde düzenle.
  # Temel stok miktarı ve birim maliyet, gösterim biriminden ayrı tutulur.
  def edit_line(event=None):
   selected=tree.selection()
   if not selected:return
   iid=selected[0]
   if iid=='pending':return
   column=tree.identify_column(event.x) if event is not None and hasattr(event,'x') else '#4'
   # Görünür sütun sırası değişirse de doğru alanı düzenle.
   try:
    display_cols=tree['displaycolumns']
    visible=list(columns) if display_cols=='#all' else list(display_cols)
    index=int(column[1:])-1
    actual=visible[index] if 0<=index<len(visible) else ''
   except (ValueError,IndexError,TypeError):actual=''
   field=actual if actual in ('qty','unit','currency','vat','included','cdisc','disc','cost') else None
   if not field:return
   bbox=tree.bbox(iid,column)
   if not bbox:return
   x=cart[int(iid)];left,top,width,height=bbox
   current={'qty':x.get('display_qty',x['qty']),'unit':x.get('display_unit',x['unit']),'currency':x.get('currency','TL'),'vat':x.get('vat',20),'included':'EVET' if x.get('included') else 'HAYIR','cdisc':x.get('cdisc',0),'disc':x.get('disc',0),'cost':x.get('display_cost',x['cost'])}[field]
   var=tk.StringVar(value=str(current))
   choices={'unit':['ADET','KOLİ','PAKET','KUTU'],'currency':['TL'],'included':['EVET','HAYIR']}
   if field in choices:editor=ttk.Combobox(tree,textvariable=var,values=choices[field],state='readonly')
   else:editor=tk.Entry(tree,textvariable=var,justify='right')
   editor.place(x=left,y=top,width=width,height=height);editor.focus_set()
   if field not in choices:_alfabe_cursor_end(editor)
   done=[False]
   def finish(commit=True):
    if done[0]:return
    if commit:
     try:
      value=var.get().strip();candidate=x.copy()
      if field=='unit':
       if not value:raise ValueError('Birim boş olamaz.')
       factor=float(candidate.get('unit_factor',1))
       if value.upper() in ('KOLİ','PAKET','KUTU') and factor==1:
        raw=__import__('tkinter.simpledialog',fromlist=['askfloat']).askfloat('Birim Çarpanı','Bir '+value.lower()+' kaç stok adedi içeriyor?',parent=w,minvalue=0.001)
        if raw is None:return
        factor=raw
       elif value.upper()=='ADET':factor=1
       candidate['unit_factor']=factor;candidate['display_unit']=value
       candidate['qty']=float(candidate.get('display_qty',candidate['qty']))*factor
       candidate['cost']=float(candidate.get('display_cost',candidate['cost']))/factor
      elif field=='currency':candidate['currency']=value
      elif field=='included':candidate['included']=value=='EVET'
      else:
       number=float(value.replace(',','.'))
       if field=='qty':candidate['display_qty']=number;candidate['qty']=number*float(candidate.get('unit_factor',1))
       elif field=='cost':candidate['display_cost']=number;candidate['cost']=number/float(candidate.get('unit_factor',1))
       else:candidate[field]=number
      calc_line(candidate);x.update(candidate)
     except (ValueError,OverflowError) as err:
      messagebox.showwarning(APP,str(err),parent=w);editor.focus_set();return
    done[0]=True;editor.destroy();redraw();tree.selection_set(iid)
   editor.bind('<Return>',lambda e:finish(True));editor.bind('<Escape>',lambda e:finish(False));editor.bind('<FocusOut>',lambda e:finish(True))
   if field in choices:editor.bind('<<ComboboxSelected>>',lambda e:finish(True))
  tree.bind('<Double-Button-1>',edit_line)
  def click_edit(event):
   row,field=_alfabe_click_column(tree,event)
   if row is None or field not in ('qty','cost'):return
   return edit_line(event)
  tree.bind('<ButtonRelease-1>',click_edit,add='+')
  def change_purchase_price(event=None):
   sel=tree.selection()
   if not sel or sel[0]=='pending':return messagebox.showwarning(APP,'Önce eklenmiş bir alış satırı seçiniz.',parent=w)
   try:i=int(sel[0]);x=cart[i]
   except (ValueError,IndexError):return
   old=float(x.get('display_cost',x['cost']))
   def validate_purchase_price(price):
    if price>0:return True
    messagebox.showwarning(APP,'Alış birim fiyatı sıfır olamaz.',parent=w)
    return False
   new=_alfabe_document_unit_price(w,x['name'],old,'Alış',validate_purchase_price,line=x)
   if new is None:return
   candidate=x.copy();candidate['display_cost']=new
   candidate['cost']=new/float(candidate.get('unit_factor',1))
   try:calc_line(candidate)
   except ValueError as err:return messagebox.showwarning(APP,str(err),parent=w)
   x.update(candidate);x['_alfabe_special_price']=True;redraw()
   if tree.exists(str(i)):tree.selection_set(str(i))
  w.bind('<Control-F6>',change_purchase_price)
  w.bind('<F7>',change_purchase_price)
