  def excel_lines(terminal=False):
   import ALFABE_STOK_EXCEL as _X
   path=filedialog.askopenfilename(parent=w,title=('El terminali mal kabul dosyası' if terminal else 'Alış faturası Excel / CSV dosyası'),filetypes=[('Excel / CSV / TXT','*.xlsx *.csv *.txt'),('Tüm dosyalar','*.*')])
   if not path:return
   try:
    heads,rws=_X.read_table(path)
    cc=DX.con()
    try:items,errs=(_X.parse_terminal_rows if terminal else _X.parse_purchase_rows)(cc,heads,rws)
    finally:cc.close()
   except Exception as ex:
    return messagebox.showerror(APP,'Dosya okunamadı:\n'+str(ex),parent=w)
   if not items:
    return messagebox.showwarning(APP,'Eklenebilecek satır bulunamadı.'+('\n\n'+'\n'.join(f'Satır {a}: {b}' for a,b in errs[:15]) if errs else ''),parent=w)
   if not messagebox.askyesno(APP,f'{len(items)} satır alış belgesine eklenecek.'+(f'\n{len(errs)} satır atlanacak:\n'+'\n'.join(f'  Satır {a}: {b}' for a,b in errs[:10])+('\n  ...' if len(errs)>10 else '') if errs else '')+'\n\nDevam edilsin mi?',parent=w):return
   for it in items:
    st=DX.one('SELECT * FROM stock WHERE id=?',(it['stock_id'],))
    cart.append({'id':st['id'],'barcode':st['barcode'] or '','code':st['code'] or '','name':st['name'],'unit':st['unit'] or 'Adet','qty':float(it['qty']),'cost':float(it['cost']),'avg_cost':float(st['avg_cost'] or 0),'vat':float(it['vat'] if it['vat'] is not None else (st['vat'] or 0)),'included':bool(it['included']),'cdisc':supplier_discount(),'disc':0.0,'currency':'TL'})
   redraw()
