  def xml_lines():
   import ALFABE_EFATURA as _E
   path=filedialog.askopenfilename(parent=w,title='Gelen e-fatura XML dosyası',filetypes=[('XML','*.xml'),('Tüm dosyalar','*.*')])
   if not path:return
   try:xd=_E.parse_incoming_xml(path)
   except Exception as ex:return messagebox.showerror(APP,'Fatura okunamadı:\n'+str(ex),parent=w)
   cc=DX.con();found=[];miss=[]
   try:
    for ln in xd['lines']:
     r=None
     for code in ln['codes']:
      r=cc.execute("SELECT * FROM stock WHERE active=1 AND (trim(COALESCE(barcode,''))=? OR trim(COALESCE(code,''))=?) LIMIT 1",(code,code)).fetchone()
      if r is None:
       r=cc.execute("SELECT s.* FROM stock_barcodes b JOIN stock s ON s.id=b.stock_id WHERE s.active=1 AND b.active=1 AND trim(COALESCE(b.barcode,''))=? LIMIT 1",(code,)).fetchone()
      if r is not None:break
     if r is None and ln['name']:
      r=cc.execute('SELECT * FROM stock WHERE active=1 AND lower(name)=lower(?) LIMIT 1',(ln['name'],)).fetchone()
     if r is None or ln['qty']<=0 or ln['price']<=0:miss.append(ln['name'] or '(adsız)')
     else:found.append((r,ln))
   finally:cc.close()
   if not found:return messagebox.showwarning(APP,'Faturadaki kalemlerden hiçbiri stokta eşleşmedi.\nÖnce ürünleri stok kartı olarak açın (barkod/stok kodu veya birebir ürün adı eşleşmeli).',parent=w)
   if not messagebox.askyesno(APP,f"Fatura: {xd['number']}  {xd['date']}\nTedarikçi: {xd['supplier']}\n\n{len(found)} kalem eklenecek."+(f"\nEşleşmeyen {len(miss)} kalem atlanacak:\n  "+'\n  '.join(miss[:10])+('\n  ...' if len(miss)>10 else '') if miss else '')+'\n\nDevam edilsin mi?',parent=w):return
   try:
    if xd['supplier'] and not supplier.get().strip():supplier.set(xd['supplier'])
    if xd['number']:inv.set(xd['number'])
   except Exception as ex:log_error('E-fatura XML alanları',ex)
   for st,ln in found:
    cart.append({'id':st['id'],'barcode':st['barcode'] or '','code':st['code'] or '','name':st['name'],'unit':st['unit'] or 'Adet','qty':float(ln['qty']),'cost':float(ln['price']),'avg_cost':float(st['avg_cost'] or 0),'vat':float(ln['vat'] if ln['vat'] else (st['vat'] or 0)),'included':False,'cdisc':supplier_discount(),'disc':0.0,'currency':'TL'})
   redraw()
  self.btn(add2,"E-FATURA XML AL",xml_lines).pack(side='left',padx=(0,10),pady=8)
