  def reverse():
   if not ht.selection():return messagebox.showwarning(APP,'İptal edilecek mal kabulü seçin.',parent=self)
   rid=int(ht.selection()[0]);gr=DX.one('SELECT * FROM goods_receipts WHERE id=?',(rid,))
   if gr['status']=='İptal':return messagebox.showinfo(APP,'Bu mal kabul zaten iptal edilmiş.',parent=self)
   # Mal kabulden doğan alış, Alış İadesi ile geri gönderildiyse stok ikinci kez düşülmesin.
   try:_pr=DX.one('SELECT status FROM purchases WHERE id=?',(gr['purchase_id'],))
   except Exception:_pr=None
   try:_rr=DX.one('SELECT 1 x FROM purchase_return_lines WHERE purchase_id=? LIMIT 1',(gr['purchase_id'],))
   except Exception:_rr=None
   if _rr or (_pr and _pr['status']!='Kesinleşti'):return messagebox.showerror(APP,'Bu mal kabulden doğan alış belgesi için alış iadesi yapılmış (veya belge artık kesinleşmiş durumda değil).\nStok ve cari ters kayıtları zaten oluştuğu için mal kabul iptal edilemez.',parent=self)
   try:_iv=DX.one("SELECT invoice_no FROM supplier_invoices WHERE receipt_id=? AND status!='İptal' LIMIT 1",(rid,))
   except Exception:_iv=None
   if _iv:return messagebox.showerror(APP,f"Bu mal kabule bağlı tedarikçi faturası var ({_iv['invoice_no']}).\nÖnce Tedarikçi Faturası > FATURAYI SİLMEDEN İPTAL ile faturayı iptal edin.",parent=self)
   rows=receipt_rows(rid)
   for x in rows:
    if float(x['accepted_qty'] or 0)>float(x['current_stock'] or 0)+1e-9:return messagebox.showerror(APP,f"{x['name']} mevcut stoku iptal için yetersiz.\nMevcut: {float(x['current_stock'] or 0):g}  Geri alınacak: {float(x['accepted_qty'] or 0):g}",parent=self)
   reason=simpledialog.askstring('Mal Kabul İptali','Zorunlu iptal gerekçesi:',parent=self)
   if not reason or not reason.strip():return
   if not messagebox.askyesno(APP,'Kayıt silinmeyecek; stok, maliyet, cari borç ve sipariş miktarı ters hareketlerle geri alınacak. Devam edilsin mi?',parent=self):return
   con=DX.con()
   try:
    con.execute('BEGIN')
    for x in rows:
     acc=float(x['accepted_qty'] or 0);cost=float(x['unit_cost'] or 0)
     if acc<=0:continue
     live=con.execute('SELECT qty,avg_cost FROM stock WHERE id=?',(x['stock_id'],)).fetchone();oldq=float(live['qty'] or 0);oldavg=float(live['avg_cost'] or 0);newq=oldq-acc;book=(oldq*oldavg)-(acc*cost);newavg=max(0,book/newq) if newq>1e-9 else 0;prev=con.execute("SELECT sph.cost FROM supplier_price_history sph JOIN purchases p ON p.id=sph.purchase_id WHERE sph.stock_id=? AND p.id<>? AND p.status='Kesinleşti' ORDER BY sph.dt DESC,sph.id DESC LIMIT 1",(x['stock_id'],gr['purchase_id'])).fetchone();last=float(prev['cost'] or 0) if prev else 0;con.execute('UPDATE stock SET qty=?,avg_cost=?,last_cost=?,updated=? WHERE id=?',(newq,newavg,last,now(),x['stock_id']));con.execute('INSERT INTO stock_moves(stock_id,dt,kind,qty,unit_cost,source,source_id,note) VALUES(?,?,?,?,?,?,?,?)',(x['stock_id'],now(),'Mal Kabul İptali',-acc,cost,'GOODS_RECEIPT_REVERSAL',rid,reason.strip()));con.execute('UPDATE order_lines SET delivered=MAX(0,delivered-?) WHERE id=?',(acc,x['order_line_id']))
    if float(gr['total'] or 0)>0:con.execute('INSERT INTO cari_moves(cari_id,dt,kind,debit,source,source_id,note) VALUES(?,?,?,?,?,?,?)',(gr['supplier_id'],now(),'Mal Kabul İptali',float(gr['total'] or 0),'GOODS_RECEIPT_REVERSAL',rid,reason.strip()))
    # Alış kaydı silinmez; mevcut maliyet/tedarikçi raporlarının iptal edilen fiyatı dışlaması için İade durumuna alınır.
    con.execute("UPDATE purchases SET status='İade' WHERE id=?",(gr['purchase_id'],));con.execute("UPDATE goods_receipts SET status='İptal',reversed_at=?,reverse_reason=? WHERE id=?",(now(),reason.strip(),rid));oq,od=con.execute('SELECT COALESCE(SUM(qty),0),COALESCE(SUM(delivered),0) FROM order_lines WHERE order_id=?',(gr['order_id'],)).fetchone();status='Tamamlandı' if od>=oq and oq>0 else ('Kısmi Teslim' if od>0 else 'Açık');con.execute('UPDATE orders SET status=? WHERE id=?',(status,gr['order_id']));con.execute('INSERT INTO audit(dt,user,module,action,record_id,old_value,new_value,reason) VALUES(?,?,?,?,?,?,?,?)',(now(),current_user(),'Mal Kabul','Ters Kayıtla İptal',rid,'Kesinleşti','İptal',reason.strip()));con.commit()
   except Exception as e:con.rollback();messagebox.showerror(APP,'İptal kaydedilemedi:\n'+str(e),parent=self);return
   finally:con.close()
   refresh_orders();refresh_history();self.refresh();messagebox.showinfo(APP,'Mal kabul silinmeden ters kayıtla iptal edildi.',parent=self)
  def report_text(rid):
   gr=DX.one('SELECT gr.*,o.doc_no order_doc,c.title supplier FROM goods_receipts gr LEFT JOIN orders o ON o.id=gr.order_id LEFT JOIN caris c ON c.id=gr.supplier_id WHERE gr.id=?',(rid,));out=[APP,'MAL KABUL RAPORU','='*125,f"Belge: {gr['doc_no']}   Tarih: {gr['dt']}   Sipariş: {gr['order_doc'] or '-'}   Tedarikçi: {gr['supplier'] or '-'}   Durum: {gr['status']}",'-'*125,f"{'BARKOD':14} {'ÜRÜN':34} {'KABUL':>8} {'HASARLI':>8} {'FAZLA':>8} {'SİP.F.':>11} {'GELEN F.':>11} {'FARK%':>8} {'TOPLAM':>12}",'--'*62]
   for x in receipt_rows(rid):out.append(f"{str(x['barcode'] or '')[:14]:14} {str(x['name'])[:34]:34} {float(x['accepted_qty'] or 0):>8g} {float(x['damaged_qty'] or 0):>8g} {float(x['extra_qty'] or 0):>8g} {float(x['ordered_price'] or 0):>11.2f} {float(x['unit_cost'] or 0):>11.2f} {float(x['price_diff_pct'] or 0):>8.1f} {float(x['line_total'] or 0):>12.2f}")
   out+=['-'*125,'GENEL TOPLAM: '+money(gr['total'])];return '\n'.join(out)
