  for c,h,wd in [('receipt','Mal Kabul',150),('dt','Tarih',145),('order','Sipariş',145),('supplier','Tedarikçi',260),('items','Kalem',70),('receipt_total','Mal Kabul Tutarı',130),('status','Durum',110)]:pt.heading(c,text=h);pt.column(c,width=wd,anchor='e' if c in ('items','receipt_total') else 'w')
  _tr_norm=lambda x:_tr_fold(x)
  try:ttk.Style(w).configure('AlisListe.Treeview',rowheight=32);pt.configure(style='AlisListe.Treeview')
  except Exception as _se:_silent(_se)
