  pt.pack(fill='both',expand=True);pt.tag_configure('wait',background='#fff7cc')
  def _pend_filter(rows):
   tm=_tr_norm(pq.get().strip()).split()
   return [r for r in rows if not tm or all(t in _tr_norm(' '.join(str(r[k] or '') for k in ('doc_no','order_doc','supplier'))) for t in tm)]
  ft=ttk.Treeview(history,columns=('invoice','dt','due','supplier','receipt','subtotal','vat','total','declared','diff','paid','remaining','status'),show='headings')
  for c,h,wd in [('invoice','Fatura No',140),('dt','Tarih',95),('due','Vade',95),('supplier','Tedarikçi',210),('receipt','Mal Kabul',125),('subtotal','Matrah',100),('vat','KDV',90),('total','Hesaplanan',105),('declared','Fatura Toplamı',110),('diff','Fark',90),('paid','Ödenen',90),('remaining','Kalan',90),('status','Durum',105)]:ft.heading(c,text=h);ft.column(c,width=wd,anchor='e' if c in ('subtotal','vat','total','declared','diff','paid','remaining') else 'w')
  try:ft.configure(style='AlisListe.Treeview')
  except Exception as _se:_silent(_se)
  iq=tk.StringVar();ist=tk.StringVar(value='Tümü');hf=tk.Frame(history);hf.pack(fill='x',pady=7)
  tk.Label(hf,text='Fatura / tedarikçi / mal kabul ara:').pack(side='left');ie=tk.Entry(hf,textvariable=iq,bg='#fff7a8');ie.pack(side='left',fill='x',expand=True,padx=6)
  hf2=tk.Frame(history);hf2.pack(fill='x',pady=(0,6))
  for _x in ('Tümü','Açık','Kısmi Ödendi','Ödendi','Vadesi Geçmiş','Fark Var','İptal'):tk.Radiobutton(hf2,text=_x,variable=ist,value=_x,indicatoron=0,bg='white',selectcolor='#CFE6FB',relief='solid',bd=1,font=('Segoe UI',9,'bold'),padx=12,pady=5,cursor='hand2').pack(side='left',padx=(0,4))
  isum=tk.Label(history,text='',anchor='w',bg='#E8F1FB',fg=TXT,font=('Segoe UI',10,'bold'),padx=12,pady=5);isum.pack(side='bottom',fill='x',pady=(4,0))
  ft.pack(fill='both',expand=True);ft.tag_configure('bad',background='#fee2e2');ft.tag_configure('cancel',foreground='#991b1b');ft.tag_configure('paid',background='#dcfce7');ft.tag_configure('late',background='#FFE0C2',foreground='#9A3412')
  agg=[0,0.0,0.0]
  def _inv_ok(r,status,rem,overdue):
   f=ist.get()
   if f=='Açık' and not (r['status']!='İptal' and rem>.005 and status=='Onaylandı'):return False
   if f=='Kısmi Ödendi' and status!='Kısmi Ödendi':return False
   if f=='Ödendi' and status!='Ödendi':return False
   if f=='Vadesi Geçmiş' and not overdue:return False
   if f=='Fark Var' and not (r['status']!='İptal' and abs(float(r['difference'] or 0))>.01):return False
   if f=='İptal' and r['status']!='İptal':return False
   tm=_tr_norm(iq.get().strip()).split()
   if tm and not all(t in _tr_norm(' '.join(str(r[k] or '') for k in ('invoice_no','supplier','receipt_doc','note'))) for t in tm):return False
   return True
  def refresh_pending():
   pt.delete(*pt.get_children())
   for r in _pend_filter(DX.rows("""SELECT gr.*,o.doc_no order_doc,c.title supplier,COUNT(gl.id) items FROM goods_receipts gr LEFT JOIN orders o ON o.id=gr.order_id LEFT JOIN caris c ON c.id=gr.supplier_id LEFT JOIN goods_receipt_lines gl ON gl.receipt_id=gr.id WHERE gr.status='Kesinleşti' AND NOT EXISTS(SELECT 1 FROM supplier_invoices si WHERE si.receipt_id=gr.id AND si.status!='İptal') GROUP BY gr.id ORDER BY gr.id DESC""")):
    pt.insert('','end',iid=str(r['id']),values=(r['doc_no'],r['dt'],r['order_doc'] or '-',r['supplier'] or '-',r['items'],money(r['total']),r['status']),tags=('wait',))
  def refresh_invoices():
   ft.delete(*ft.get_children());agg[0]=0;agg[1]=0.0;agg[2]=0.0;isum.config(text='0 fatura')
   for r in DX.rows("""SELECT si.*,c.title supplier,gr.doc_no receipt_doc,COALESCE((SELECT SUM(amount) FROM supplier_invoice_payments p WHERE p.invoice_id=si.id AND p.status='Aktif'),0) paid FROM supplier_invoices si LEFT JOIN caris c ON c.id=si.supplier_id LEFT JOIN goods_receipts gr ON gr.id=si.receipt_id ORDER BY si.id DESC"""):
    paid=float(r['paid'] or 0);rem=max(0,float(r['declared_total'] or r['total'] or 0)-paid);status=r['status'];status='Ödendi' if status!='İptal' and rem<=.005 else ('Kısmi Ödendi' if status!='İptal' and paid>0 else status);overdue=bool(r['status']!='İptal' and rem>.005 and (r['due_date'] or '')[:10] and (r['due_date'] or '')[:10]<today())
    if not _inv_ok(r,status,rem,overdue):continue
    agg[0]+=1
    if r['status']!='İptal':agg[1]+=rem;agg[2]+=(rem if overdue else 0.0)
    isum.config(text=f'{agg[0]} fatura  •  Ödenecek kalan: {money(agg[1])}  •  Vadesi geçmiş: {money(agg[2])}')
    tag='cancel' if r['status']=='İptal' else 'late' if overdue else 'bad' if abs(float(r['difference'] or 0))>.01 else 'paid' if rem<=.005 else '';ft.insert('','end',iid=str(r['id']),values=(r['invoice_no'],r['dt'],r['due_date'] or '',r['supplier'] or '-',r['receipt_doc'] or '-',money(r['subtotal']),money(r['vat']),money(r['total']),money(r['declared_total']),money(r['difference']),money(paid),money(rem),status),tags=(tag,) if tag else ())
  def create_invoice():
   if not pt.selection():return messagebox.showwarning(APP,'Faturası kaydedilecek mal kabulü seçin.',parent=self)
