  def report_text(iid):
   si=DX.one('SELECT si.*,c.title supplier,gr.doc_no receipt_doc,o.doc_no order_doc FROM supplier_invoices si LEFT JOIN caris c ON c.id=si.supplier_id LEFT JOIN goods_receipts gr ON gr.id=si.receipt_id LEFT JOIN orders o ON o.id=si.order_id WHERE si.id=?',(iid,));out=[APP,'TEDARİKÇİ FATURASI ÜÇLÜ KONTROL RAPORU','='*130,f"Fatura: {si['invoice_no']}  Tarih: {si['dt']}  Vade: {si['due_date']}  Tedarikçi: {si['supplier']}  Sipariş: {si['order_doc']}  Mal Kabul: {si['receipt_doc']}",'-'*130,f"{'ÜRÜN':32} {'SİPARİŞ':>8} {'KABUL':>8} {'FATURA':>8} {'SİP.F.':>10} {'KABUL F.':>10} {'FATURA F.':>10} {'KDV':>6} {'TOPLAM':>12}",'--'*65]
