        tk.Label(w,text='⇄  AĞ / VERİ KLASÖRÜ AYARI',bg=BG,fg=TXT,font=(F,16,'bold')).pack(anchor='w',padx=22,pady=(18,6))
        cur=tk.Frame(w,bg=PANEL,highlightthickness=1,highlightbackground=LINE);cur.pack(fill='x',padx=22,pady=(0,10))
