_REPORT_DESIGN_PREVIEW_OVERRIDE={}
_RE_THEMES=[('Lacivert (varsayılan)','#143d68'),('Mavi','#1d6fb8'),('Koyu yeşil','#1f6b4a'),('Bordo','#8a1c2b'),('Turuncu','#b9540b'),('Mor','#5b3a99'),('Antrasit','#2f3a45'),('Siyah','#111111')]
_RE_ALIGNS=[('Otomatik','auto'),('Sola','force_left'),('Ortaya','center'),('Sağa','right')]
