def _re_sample_rows(heads):
    """Gerçek veri yokken önizleme için başlık türüne uygun örnek satırlar."""
    out=[]
    for i in range(12):
        row=[]
        for h in heads:
            t=_alfabe_report_field_type(h)
            row.append({'identifier':f'86900000{i:05d}','money':round(125.5+i*37.25,2),'quantity':float(5+i),'date':f'2026-10-{10+i%9:02d} 10:{i:02d}:00','ratio':float(10+i)}.get(t,f'Örnek metin {i+1}'))
        out.append(tuple(row))
    return out

def _re_preview_commands(L):
    """Motorun yerleşim kararlarını (mm cinsinden) çizim komutlarına çevirir. rect: (x,y,w,h,dolgu,çerçeve,kesik) text: (x,y,metin,pt,kalın,renk,çapa,kırpma_mm)
    Bölüm (band) konumları L['_geo'] içine yazılır: title/chips/thead/detail/total/footer = (y0,y1); xs = [(x,w)]; rows = [(tür,y0,y1)]"""
    c=[];m=L.get('ml',L['margin']);mT=L.get('mt',m);mB=L.get('mb',mT);W=L['pw'];H=L['ph'];pw=L['page_w'];th=L['theme'];fp=L['font_pt'];hh=L['head_h'];geo={}
    c.append(('rect',0,0,W,H,'#ffffff','#c9d3de',False));c.append(('rect',m,mT,pw,H-mT-mB,'','#e6ecf3',True))
    hx=m
    if L.get('has_logo'):
        c.append(('rect',m,mT+hh-2-15,26,15,'#f1f5f9','#cbd5e1',False));c.append(('text',m+13,mT+hh-2-7.5,'LOGO',fp-1,False,'#94a3b8','c',26));hx=m+30
    y=mT+hh-2.0;lines=[]
    if L.get('note'):lines.append((L['note'],fp-0.5,False,'#5b6b7b'))
    if L.get('subtitle'):lines.append((L['subtitle'],fp-0.5,False,'#5b6b7b'))
    lines.append((L['title'],L['title_pt'],True,th['title']));lines.append((str(L['company']).upper(),fp+1,True,th['company']))
    for t,sz,b,col in lines:
        y-=sz*0.3528*1.25;c.append(('text',hx,y,t,sz,b,col,'nw',pw*0.62))
    y=mT+hh-2.0
    for t in reversed(L.get('meta',[])):
        y-=(fp-1)*0.3528*1.55;c.append(('text',m+pw,y,t,fp-1,False,'#44566a','ne',pw*0.4))
    c.append(('rect',m,mT+hh-0.35,pw,0.7,th['accent'],'',False))
    geo['title']=(mT,mT+hh);ty=mT+hh
    if L['chips']:
        n=len(L['chips']);cw=(pw-3*(n-1))/n;cy=ty+3;ch=L['chips_h']-3
        for k,(lab,val) in enumerate(L['chips']):
            x=m+k*(cw+3)
            c.append(('rect',x,cy,cw,ch,th['chip'],th['chip_line'],False));c.append(('rect',x,cy,1.2,ch,th['accent'],'',False))
            c.append(('text',x+3.5,cy+1.5,str(lab).upper(),fp-1.5,False,'#5b6b7b','nw',cw-5));c.append(('text',x+3.5,cy+1.5+(fp-1.5)*0.3528*1.45,str(val),fp+3,True,th['title'],'nw',cw-5))
        geo['chips']=(ty,ty+L['chips_h']);ty+=L['chips_h']
    ty+=L['gap']-1+float(L.get('top_space',0) or 0)
    xs=[];acc=m
    for w_ in L['widths']:xs.append((acc,pw*w_/100.0));acc+=pw*w_/100.0
    geo['xs']=xs
    def put(x,w_,yc,text,align,pt,bold,col):
        if align=='right':c.append(('text',x+w_-1.3,yc,text,pt,bold,col,'e',w_-2.6))
        elif align=='center':c.append(('text',x+w_/2,yc,text,pt,bold,col,'c',w_-2.6))
        else:c.append(('text',x+1.3,yc,text,pt,bold,col,'w',w_-2.6))
    c.append(('rect',m,ty,pw,L['thead_h'],th['accent'],'',False))
    for (x,w_),h,a in zip(xs,L['headings'],L['aligns']):put(x,w_,ty+L['thead_h']/2,h,a,fp-0.5,True,'#ffffff')
    geo['thead']=(ty,ty+L['thead_h'])
    ry=ty+L['thead_h'];rh=L['rh'];d0=ry;rowinfo=[]
    ents=L.get('first_entries') or [('r',r) for r in L['rows']]
    k=0
    for e in ents:
        kind=e[0]
        if kind=='t':continue
        if kind=='r':
            if L['zebra'] and k%2==1:c.append(('rect',m,ry,pw,rh,th['zebra'],'',False))
            c.append(('rect',m,ry+rh-0.2,pw,0.2,th['row_line'],'',False))
            for (x,w_),t,a in zip(xs,e[1],L['aligns']):put(x,w_,ry+rh/2,t,a,fp,False,'#1b2733')
            k+=1
        elif kind=='gh':
            c.append(('rect',m,ry,pw,rh,th['chip'],'',False));c.append(('rect',m,ry,1.2,rh,th['accent'],'',False));c.append(('text',m+3,ry+rh/2,e[1],fp,True,th['title'],'w',pw-6));k=0
        else:
            c.append(('rect',m,ry,pw,rh,th['total'],'',False));c.append(('rect',m,ry+rh-0.3,pw,0.3,th['accent'],'',False))
            span=max(1,int(e[3]));lab_w=sum(w_ for _,w_ in xs[:span]);c.append(('text',m+1.3,ry+rh/2,e[2],fp-0.5,True,th['title'],'w',lab_w-2.6))
            for j,((x,w_),t,a) in enumerate(zip(xs,e[1],L['aligns'])):
                if j>=span and str(t).strip():put(x,w_,ry+rh/2,t,a,fp,True,th['title'])
        rowinfo.append((kind,ry,ry+rh));ry+=rh
    geo['detail']=(d0,ry);geo['rows']=rowinfo
    if L.get('total'):
        span=max(1,int(L.get('total_span',1)));c.append(('rect',m,ry,pw,rh,th['total'],'',False));c.append(('rect',m,ry,pw,0.5,th['accent'],'',False));c.append(('rect',m,ry+rh-0.5,pw,0.5,th['accent'],'',False))
        lab_w=sum(w_ for _,w_ in xs[:span]);c.append(('text',m+1.3,ry+rh/2,'GENEL TOPLAM' if span>=2 else 'TOPLAM',fp,True,th['title'],'w',lab_w-2.6))
        for k,((x,w_),t,a) in enumerate(zip(xs,L['total'],L['aligns'])):
            if k>=span and str(t).strip():put(x,w_,ry+rh/2,t,a,fp,True,th['title'])
        geo['total']=(ry,ry+rh)
    fy=mT+L['page_h']-L['foot_h']
    c.append(('rect',m,fy,pw,0.2,'#b8c6d6','',False));yc=fy+L['foot_h']/2
    c.append(('text',m,yc,L.get('footer_left') or f"{L['company']} · ALFABE SATIŞ PRO",fp-1.5,False,'#5b6b7b','w',pw*0.35));c.append(('text',m+pw/2,yc,L['footer'],fp-1.5,False,'#5b6b7b','c',pw*0.3))
    fr=L.get('footer_right')
    if fr is None and L.get('show_page_no'):fr=f"Sayfa 1 / {L['n_pages']}"
    if fr:c.append(('text',m+pw,yc,fr,fp-1.5,True,th['title'],'e',pw*0.2))
    geo['footer']=(fy,fy+L['foot_h']);L['_geo']=geo
    return c

