_RE_EXTRA_KEYS=('objects','group_by','group_sort','group_subtotals','margin_top','margin_right','margin_bottom','margin_left','font_family','borders','head_style','cell_pad','row_scale',
                'top_space','bottom_space','wm_text','wm_size','wm_angle','wm_opacity','wm_color','signatures','footer_left','footer_center','footer_right','meta_text')

def _re_edge_png(html_path,png_path,w,h):
    """Gerçek raporu (yazdırılan HTML'nin kendisini) Edge ile görüntüye çevirir. Edge yoksa/başarısızsa None döner."""
    edge=_edge_path()
    if not edge:return None
    try:
        prof=Path(tempfile.gettempdir())/'alfabe_edge_onizleme';prof.mkdir(exist_ok=True)
        Path(png_path).unlink(missing_ok=True)
        cmd=[str(edge),'--headless','--disable-gpu','--hide-scrollbars','--force-device-scale-factor=1','--no-first-run',f'--user-data-dir={prof}',f'--window-size={int(w)},{int(h)}',f'--screenshot={png_path}',Path(html_path).resolve().as_uri()]
        subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=30,creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
        return str(png_path) if Path(png_path).exists() and Path(png_path).stat().st_size>500 else None
    except Exception as e:
        log_error('Rapor gerçek önizleme',e);return None

def _re_preview_page_html(key,heads,rows,design,page_no,zoom,total):
    """Tek sayfayı, yazdırılan HTML'nin birebir aynısıyla üretir (yalnız ekran ölçeği farklı)."""
    _REPORT_DESIGN_PREVIEW_OVERRIDE[key]=design
    try:doc=report_html_document(key,heads,rows,'Tarih/Saat: '+report_display_datetime(),total)
    finally:_REPORT_DESIGN_PREVIEW_OVERRIDE.pop(key,None)
    css=(f'<style>body{{background:#8b97a6!important;padding:0!important}}.report-page{{display:none!important}}section.report-page:nth-of-type({int(page_no)}){{display:block!important;margin:0!important;box-shadow:none!important;zoom:{zoom:.4f}}}</style>')
    return doc.replace('</head>',css+'</head>',1)

