        hd=tk.Frame(w,bg=PANEL2,highlightthickness=1,highlightbackground=LINE);hd.pack(fill='x',padx=14,pady=(12,8))
        tk.Label(hd,text='▤  RAPOR DÜZENLEYİCİ',bg=PANEL2,fg=TXT,font=(FONT,15,'bold')).pack(side='left',padx=16,pady=10)
        tk.Label(hd,text=report_key+('    |    önizleme: gerçek rapor verisi' if self.real else '    |    önizleme: örnek veri'),bg=PANEL2,fg=CY,font=(FONT,10,'bold')).pack(side='left',padx=8)
        self.nb=ttk.Notebook(w);self.nb.pack(fill='both',expand=True,padx=14)
        body=self._body=tk.Frame(self.nb,bg=BG);body.grid_columnconfigure(1,weight=1);body.grid_rowconfigure(0,weight=1)
