        # ---------- sol: sütunlar ----------
        left=box(body,'SÜTUNLAR',0,width=370);left.grid_propagate(False)
        tb=tk.Frame(left,bg=PANEL);tb.pack(fill='x',padx=8,pady=(8,4))
        def mk(par,text,cmd,col,fg='#04121f',px=10):
            return tk.Button(par,text=text,command=cmd,bg=col,fg=fg,activebackground=_alfabe_lighten(col),relief='flat',bd=0,font=(FONT,9,'bold'),cursor='hand2',padx=px,pady=6)
