        mk(tb,'Göster / Gizle',self._toggle_sel,'#10b981').pack(side='left',padx=(0,4));mk(tb,'Tümünü Göster',lambda:self._show_all(1),'#dbe4ef',fg='#12263f').pack(side='left',padx=(0,4));mk(tb,'Tümünü Gizle',lambda:self._show_all(0),'#dbe4ef',fg='#12263f').pack(side='left')
        lw=tk.Frame(left,bg=PANEL);lw.pack(fill='both',expand=True,padx=8,pady=(0,6))
        self.lb=tk.Listbox(lw,bg='#ffffff',fg=TXT,selectbackground='#cfe6fb',selectforeground='#0b376d',font=(FONT,11),activestyle='none',exportselection=False,bd=0,highlightthickness=1,highlightbackground=LINE)
        sb=tk.Scrollbar(lw,orient='vertical',command=self.lb.yview);self.lb.configure(yscrollcommand=sb.set);self.lb.pack(side='left',fill='both',expand=True);sb.pack(side='right',fill='y')
