        pf=tk.Frame(left,bg=PANEL);pf.pack(fill='x',padx=8,pady=(0,8))
        tk.Label(pf,text='SEÇİLİ SÜTUN',bg=PANEL,fg=MUT,font=(FONT,9,'bold')).grid(row=0,column=0,columnspan=2,sticky='w',pady=(0,4))
        self.v_head=tk.StringVar();self.v_align=tk.StringVar();self.v_fmt=tk.StringVar();self.v_width=tk.StringVar()
