    def _vis_cols(self):
        return [c for c in self.ed.cols if c['visible']]
    def _draw_obj(self,o,c,L,fam):
        cv=self.cv;sc=self.sc;X0=self.PX0;Y0=self.PY0
        x,y,w,h=self._obj_geom(o,L);px=X0+x*sc;py=Y0+y*sc;pw_=w*sc;ph_=h*sc;t=c['type']
        self._ohits.append((c['id'],(x,y,w,h),c['layer']))
        ang=c['angle']
        def poly(pts,**kw):
            return cv.create_polygon(pts,**kw)
        def rot(pts):
            import math
            cx=px+pw_/2;cy=py+ph_/2;a=math.radians(ang);ca=math.cos(a);sa=math.sin(a);out=[]
            for i in range(0,len(pts),2):
                dx=pts[i]-cx;dy=pts[i+1]-cy;out+= [cx+dx*ca-dy*sa,cy+dx*sa+dy*ca]
            return out
        if t=='line':
            lw=max(1,int(round(max(c['bw'],0.1)*sc)));col=c['border'] or c['color']
            if ang:
                p=rot([px,py,px+pw_,py]);cv.create_line(*p,fill=col,width=lw)
            else:cv.create_line(px,py,px+pw_,py,fill=col,width=lw)
            return
        if t in ('rect','ellipse','text'):
            fill=c['fill'];out=c['border'] if (c['border'] and c['bw']>0) else '';lw=max(1,int(round(c['bw']*sc))) if out else 1
            if t=='ellipse':
                if ang:
                    import math
                    pts=[];cx=px+pw_/2;cy=py+ph_/2
                    for k in range(48):
                        a=2*math.pi*k/48;pts+= [cx+pw_/2*math.cos(a),cy+ph_/2*math.sin(a)]
                    cv.create_polygon(*rot(pts),fill=fill,outline=out,width=lw)
                else:cv.create_oval(px,py,px+pw_,py+ph_,fill=fill,outline=out,width=lw)
            elif fill or out:
                if ang:cv.create_polygon(*rot([px,py,px+pw_,py,px+pw_,py+ph_,px,py+ph_]),fill=fill,outline=out,width=lw)
                else:cv.create_rectangle(px,py,px+pw_,py+ph_,fill=fill,outline=out,width=lw)
        if t=='text':
            fpx=max(5,int(round(c['size']*0.3528*sc)));font=self._ofont(fam,fpx,c['bold'],c['italic'],c['underline'])
            pad=1.2*sc;txt=self._tok(c['text'],L)
            if ang:
                cv.create_text(px+pw_/2,py+ph_/2,text=txt.split('\n')[0],fill=c['color'],font=font,angle=-ang);return
            lines=[self.ed._fit(font,ln,pw_-2*pad) for ln in self._wrap(font,txt,pw_-2*pad)]
            lh=fpx*1.25
            if c['h']>0:lines=lines[:max(1,int((ph_-1.6*sc)/lh))]
            bh=len(lines)*lh;vo={'top':0.8*sc,'middle':(ph_-bh)/2,'bottom':ph_-bh-0.8*sc}[c['valign']]
            ax={'left':(px+pad,'nw','left'),'center':(px+pw_/2,'n','center'),'right':(px+pw_-pad,'ne','right'),'justify':(px+pad,'nw','left')}[c['align']]
            cv.create_text(ax[0],py+max(0,vo),text='\n'.join(lines),anchor=ax[1],justify=ax[2],fill=c['color'],font=font)
        elif t=='image':
            drawn=False
            if c['img'] and c['mime'] in ('image/png','image/gif'):
                try:
                    key=(c['id'],len(c['img']),int(pw_),int(ph_))
                    if key not in self._imgs:
                        if len(self._imgs)>30:self._imgs.clear()
                        im=tk.PhotoImage(data=c['img']);f=max(1,int(max(im.width()/max(pw_,1),im.height()/max(ph_,1))));self._imgs[key]=im.subsample(f,f) if f>1 else im
                    im=self._imgs[key];cv.create_image(px+pw_/2,py+ph_/2,image=im);drawn=True
                except Exception as ex:log_error('Stüdyo resim',ex)
            if not drawn:
                cv.create_rectangle(px,py,px+pw_,py+ph_,fill='#eef3f9',outline='#9db4cf',dash=(3,3));cv.create_text(px+pw_/2,py+ph_/2,text='RESİM',fill='#526782',font=(self.ed.FONT,max(7,int(8*sc/3)),'bold'))
    def _handles(self,o,L=None):
        c=_rp_obj_clean(o) or {}
        x,y,w,h=self._obj_geom(o,L or self._Lcur)
        if c.get('angle'):return {}
        if c.get('type')=='line':return {'w':(x,y),'e':(x+w,y)}
        return {'nw':(x,y),'n':(x+w/2,y),'ne':(x+w,y),'e':(x+w,y+h/2),'se':(x+w,y+h),'s':(x+w/2,y+h),'sw':(x,y+h),'w':(x,y+h/2)}
    def _draw_selection(self,L):
        cv=self.cv;sc=self.sc;X0=self.PX0;Y0=self.PY0;BL='#0b5cad';geo=self._geo
        for it in self.sel:
            if it[0]=='obj':
                o=self._obj(it[1])
                if o is None:continue
                x,y,w,h=self._obj_geom(o,L);pad=1.0 if h<1.5 else 0
                cv.create_rectangle(X0+x*sc-1,Y0+(y-pad)*sc-1,X0+(x+w)*sc+1,Y0+(y+h+pad)*sc+1,outline=BL,width=1,dash=(4,2))
                if len(self.sel)==1:
                    for nm,(hx,hy) in self._handles(o,L).items():
                        cv.create_rectangle(X0+hx*sc-3,Y0+hy*sc-3,X0+hx*sc+3,Y0+hy*sc+3,fill='#ffffff',outline=BL)
            elif it[0]=='col':
                vis=self._vis_cols();k=next((i for i,c in enumerate(vis) if c['name']==it[1]),None)
                if k is not None and k<len(geo.get('xs',[])) and 'thead' in geo:
                    x,w_=geo['xs'][k];ya=geo['thead'][0];yb=geo.get('total',geo.get('detail',geo['thead']))[1]
                    cv.create_rectangle(X0+x*sc,Y0+ya*sc,X0+(x+w_)*sc,Y0+yb*sc,fill=BL,stipple='gray12',outline=BL,width=2)
            elif it[0]=='part':
                for z in self._zones:
                    if z[3]==it and z[1]=='part':
                        x,y,w,h=z[2];cv.create_rectangle(X0+x*sc,Y0+y*sc,X0+(x+w)*sc,Y0+(y+h)*sc,outline=BL,width=2)
                        if it[1] not in ('footer_l','footer_c','footer_r','meta','group'):break
            elif it[0]=='band':
                for z in self._zones:
                    if z[1]=='band' and z[3]==it:
                        key=it[1];rg=geo.get(key)
                        if rg:cv.create_rectangle(X0+self._Lcur['ml']*sc,Y0+rg[0]*sc,X0+(self._Lcur['ml']+self._Lcur['page_w'])*sc,Y0+rg[1]*sc,outline=BL,width=2)
        d=self._drag
        if d and d.get('kind')=='rubber':
            cv.create_rectangle(d['px0'],d['py0'],d['px1'],d['py1'],outline=BL,dash=(3,3))
        if d and d.get('kind')=='create':
            x0,y0,x1,y1=d['rect'];cv.create_rectangle(X0+x0*sc,Y0+y0*sc,X0+x1*sc,Y0+y1*sc,outline=BL,dash=(3,3))
        if d and d.get('kind')=='colmove' and d.get('moved') and d.get('target_x') is not None:
            cv.create_line(X0+d['target_x']*sc,Y0+geo['thead'][0]*sc,X0+d['target_x']*sc,Y0+geo.get('total',geo.get('detail'))[1]*sc,fill='#dc2626',width=3)
    def _fill_fields(self):
        ed=self.ed;want=[('☑ ' if c['visible'] else '☐ ')+c['heading'] for c in ed.cols]
        if list(self.flb.get(0,'end'))!=want:
            cur=self.flb.curselection();self.flb.delete(0,'end')
            for t in want:self.flb.insert('end',t)
            if cur and cur[0]<len(want):self.flb.selection_set(cur[0])
    def _field_pick(self):
        s=self.flb.curselection()
        if s and s[0]<len(self.ed.cols):
            c=self.ed.cols[s[0]]
            if c['visible']:self.select([('col',c['name'])])
            else:self.select([('col',c['name'])])
    def _field_toggle(self):
        s=self.flb.curselection()
        if not s or s[0]>=len(self.ed.cols):return
        c=self.ed.cols[s[0]];c['visible']=0 if c['visible'] else 1
        if not any(x['visible'] for x in self.ed.cols):c['visible']=1;return
        self.ed._refresh_list(s[0]);self.commit(True);self.show_props()
    def _update_status(self,L):
        n=len(self.sel);vis=len(self._vis_cols());it=self.sel[0] if self.sel else None
        parts={'title':'Rapor başlığı','meta':'Sağ üst bilgi','chips':'Özet kutuları','total':'Genel toplam','group':'Grup','footer_l':'Alt bilgi (sol)','footer_c':'Alt bilgi (orta)','footer_r':'Alt bilgi (sağ)'}
        if it is None:what='Seçim yok'
        elif it[0]=='obj':what=f'{n} nesne seçili'
        elif it[0]=='col':what='Sütun: '+str(it[1])
        elif it[0]=='part':what='Bölüm: '+('Sayfa' if len(it)<2 else parts.get(it[1],''))
        elif it[0]=='band':what='Bölüm: '+_RS_BAND_NAMES.get(it[1],'').replace('\n',' ')
        else:what='Sayfa'
        x,y=self._cur;veri=f'{len(self.ed.rows)} kayıt (gerçek veri)' if self.ed.real else 'örnek veri'
        self.status.config(text=f"  {what}  ·  İmleç {x:.1f} mm × {y:.1f} mm  ·  Izgara {self.v_step.get()} mm{' (yapışma açık)' if self.v_snap.get() else ''}  ·  {vis}/{len(self.ed.cols)} sütun  ·  {len(self.objs())} nesne  ·  {self.ed.paper_text()}  ·  {veri}")
    # ------------------------------------------------------------------ fare
    def _pick(self,mx,my):
        sc=self.sc;tol=5.0/sc
        if len(self.sel)==1 and self.sel[0][0]=='obj':
            o=self._obj(self.sel[0][1])
            if o is not None:
                for nm,(hx,hy) in self._handles(o).items():
                    if abs(mx-hx)<=tol and abs(my-hy)<=tol:return ('handle',nm,o)
        def inside(r,pad=0.0):return r[0]-pad<=mx<=r[0]+r[2]+pad and r[1]-pad<=my<=r[1]+r[3]+pad
        for oid,r,ly in reversed(self._ohits):
            if ly!='back' and inside(r,max(0.0,(2.5-r[3])/2)+0.2):return ('obj',oid)
        geo=self._geo;xs=geo.get('xs',[])
        for kk in range(len(xs)-1):
            bx=xs[kk][0]+xs[kk][1]
            if abs(mx-bx)<=tol*0.8:
                for key in ('thead','detail'):
                    if key in geo and geo[key][0]<=my<=geo[key][1]:return ('resize',kk)
        for pr,kind,r,item in self._zones:
            if pr<=2 and inside(r):return ('zone',item)
        for oid,r,ly in reversed(self._ohits):
            if ly=='back' and inside(r,max(0.0,(2.5-r[3])/2)+0.2):
                if not any(inside(z[2]) for z in self._zones if z[1]=='col'):return ('obj',oid)
        for pr,kind,r,item in self._zones:
            if inside(r):return ('zone',item)
        return ('none',)
    def _on_motion(self,e):
        mx,my=self._mm(e);self._cur=(mx,my)
        if self._drag:self._drag_move(e,mx,my);return
        try:
            h=self._pick(mx,my);cur=''
            if self.tool!='select':cur='crosshair'
            elif h[0]=='handle':cur={'nw':'size_nw_se','se':'size_nw_se','ne':'size_ne_sw','sw':'size_ne_sw','n':'sb_v_double_arrow','s':'sb_v_double_arrow','e':'sb_h_double_arrow','w':'sb_h_double_arrow'}.get(h[1],'')
            elif h[0]=='resize':cur='sb_h_double_arrow'
            elif h[0]=='obj':cur='fleur'
            elif h[0]=='zone' and h[1][0]=='col':cur='hand2'
            self.cv.config(cursor=cur)
        except tk.TclError:pass
        if self._Lcur:self._update_status(self._Lcur)
    def _on_press(self,e):
        cv=self.cv;cv.focus_set();self._close_edit(True)
        if self._Lcur is None:return
        mx,my=self._mm(e);shift=bool(e.state&0x1);ctrl=bool(e.state&0x4);px,py=cv.canvasx(e.x),cv.canvasy(e.y)
        if self.tool!='select':
            sx,sy=self._sn(mx),self._sn(my);self._drag={'kind':'create','sx':sx,'sy':sy,'rect':(sx,sy,sx,sy),'moved':False};return
        h=self._pick(mx,my);k=h[0]
        if k=='handle':
            o=h[2];self._drag={'kind':'handle','h':h[1],'o':o,'o0':dict(_rp_obj_clean(o)),'g0':self._obj_geom(o,self._Lcur),'moved':False,'step':True};return
        if k=='obj':
            oid=h[1]
            if shift or ctrl:
                it=('obj',oid)
                if it in self.sel:self.sel.remove(it)
                else:self.sel=[s for s in self.sel if s[0]=='obj']+[it]
            elif ('obj',oid) not in self.sel:self.sel=[('obj',oid)]
            self._sync_list();self.show_props()
            objs=self.sel_objs();self._drag={'kind':'move','sx':mx,'sy':my,'orig':[(o,float(_rp_float(o.get('x'),0)),float(_rp_float(o.get('y'),0))) for o in objs],'moved':False};self.redraw(0);return
        if k=='resize':
            kk=h[1];L=self._Lcur;pwid=L['page_w'];mm=[wd*pwid/100.0 for wd in L['widths']]
