    def select_all(self):
        self.select([('obj',o.get('id')) for o in self.objs()])
    def copy(self):
        import copy as _c
        objs=self.sel_objs()
        if objs:self.clip=[_c.deepcopy(o) for o in objs];self._pasten=0
