        import copy as _c;new=[]
        for o in objs:
            n=_c.deepcopy(o);n['id']=self._newid();n['x']=round(_rp_float(n.get('x'),0)+5,2);n['y']=round(_rp_float(n.get('y'),0)+5,2);self.objs().append(n);new.append(('obj',n['id']))
        self.sel=new;self.show_props();self.commit(True)
