        objs=self.sel_objs()
        if objs:
            ids={o.get('id') for o in objs};self.ed.extra['objects']=[o for o in self.objs() if o.get('id') not in ids];self.sel=[];self.show_props();self.commit(True);return
        if self.sel and self.sel[0][0]=='col':self.hide_col(self.sel[0][1])
