        L=self._layout();G=[(o,)+self._obj_geom(o,L) for o in objs]
        if len(objs)>=2:bx0=min(g[1] for g in G);by0=min(g[2] for g in G);bx1=max(g[1]+g[3] for g in G);by1=max(g[2]+g[4] for g in G)
        else:bx0=L['ml'];bx1=L['ml']+L['page_w'];by0=L['mt'];by1=L['mt']+L['page_h']
        for o,x,y,w,h in G:
            if mode=='l':o['x']=round(bx0,2)
            elif mode=='r':o['x']=round(bx1-w,2)
            elif mode=='c':o['x']=round((bx0+bx1)/2-w/2,2)
            elif mode=='t':o['y']=round(by0,2)
            elif mode=='b':o['y']=round(by1-h,2)
            elif mode=='m':o['y']=round((by0+by1)/2-h/2,2)
