 def build(self):
  # v1.2.291.232: Teknolojik yeni açılış ekranı. Yalnız görünüm katmanıdır; bütün düğmeler
  # mevcut callback'lere (login, maintenance, new_period, backup, restore ...) bağlıdır.
  # Hata olursa eski ekrana otomatik dönülür.
  if USE_CLASSIC_LOGIN:
   return self.build_classic()
  try:
   self._build_tech()
  except Exception as e:
   log_error('Yeni açılış ekranı',e)
   try:
    self.stop_tick()
    for w in list(self.winfo_children()):w.destroy()
    self.configure(bg='#f7fafc')
   except Exception as _se:_silent(_se)
   self.build_classic()
 def _build_tech(self):
  BG='#071320';PANEL='#0e1e34';PANEL2='#0a1627';LINE='#1f4a6b';TXT='#e6f4ff';MUT='#8fb4d3';CY='#22d3ee';FONT='Segoe UI'
  self.configure(bg=BG)
  # ---------- Üst başlık ----------
  hcv=tk.Canvas(self,bg=BG,height=150,highlightthickness=0);hcv.pack(fill='x');self._hdr=hcv
  def _mix(c1,c2,t):
   a=[int(c1[i:i+2],16) for i in (1,3,5)];b2=[int(c2[i:i+2],16) for i in (1,3,5)]
   return '#%02x%02x%02x'%tuple(int(a[i]+(b2[i]-a[i])*t) for i in range(3))
  def draw_header(event=None):
   hcv.delete('all');w=max(hcv.winfo_width(),1100);h=150
   # Zemin: yukarıdan aşağıya yumuşak renk geçişi + çok hafif ızgara
   for y in range(h):hcv.create_line(0,y,w,y,fill=_mix('#0d2740','#071320',y/float(h)))
   for x in range(0,w,44):hcv.create_line(x,0,x,h,fill='#0b2034')
   for y in range(0,h,44):hcv.create_line(0,y,w,y,fill='#0b2034')
   # Alt vurgu çizgisi: kenarlarda sönük, ortada parlak
   for x in range(0,w,4):
    t=1-abs((x-w/2)/(w/2));hcv.create_line(x,h-3,x+4,h-3,fill=_mix(LINE,CY,max(0,t)**1.6),width=3)
   # Logo: yalnız seçili firmanın kendi logosu varsa gösterilir (beyaz yuvarlak plaka üzerinde); yoksa sol taraf boş kalır.
   lg=getattr(self,'_hdr_logo_img',None)
   if lg is not None:
    lw,lh=lg.width(),lg.height();px0,py0=28,max(8,(h-(lh+16))//2)
    _alfabe_round_rect(hcv,px0,py0,px0+lw+24,py0+lh+16,16,fill='#ffffff',outline='#2b86b8',width=2)
    hcv.create_image(px0+12,py0+8,image=lg,anchor='nw')
   import tkinter.font as tkfont
   tf=tkfont.Font(family=FONT,size=32,weight='bold');t1='ALFABE SATIŞ ';t2='PRO'
   x0=w/2-(tf.measure(t1)+tf.measure(t2))/2
   hcv.create_text(x0,62,text=t1,anchor='w',fill='#ffffff',font=(FONT,32,'bold'))
   hcv.create_text(x0+tf.measure(t1),62,text=t2,anchor='w',fill=CY,font=(FONT,32,'bold'))
   # Slogan: iki yanında ince çizgi
   sf=tkfont.Font(family=FONT,size=10,weight='bold');st='KIRTASİYEDE  GÜVENİLİR  ADRES';sw=sf.measure(st)
   hcv.create_text(w/2,106,text=st,fill=MUT,font=(FONT,10,'bold'))
   hcv.create_line(w/2-sw/2-70,106,w/2-sw/2-14,106,fill=LINE);hcv.create_line(w/2+sw/2+14,106,w/2+sw/2+70,106,fill=LINE)
   # Saat paneli
   _alfabe_round_rect(hcv,w-300,36,w-36,112,14,fill=PANEL,outline=LINE)
   hcv.create_line(w-282,40,w-54,40,fill=CY,width=2)
   hcv.create_text(w-168,66,text='',fill=CY,font=(FONT,24,'bold'),tags='clk_time')
   hcv.create_text(w-168,97,text='',fill=MUT,font=(FONT,10),tags='clk_date')
   self._hdr_tick(once=True)
  self._draw_header=draw_header
  hcv.bind('<Configure>',draw_header);self.after_idle(draw_header);self._hdr_tick();self.after_idle(self._refresh_header_logo)
  # ---------- Gövde ----------
  main=tk.Frame(self,bg=BG);main.pack(fill='both',expand=True,padx=36,pady=(20,12))
