  tk.Label(ph,text='▦  ÇALIŞMA DÖNEMİ',bg=PANEL2,fg=TXT,font=(FONT,15,'bold')).pack(side='left',padx=20)
  self.period_list=tk.Listbox(right,font=(FONT,15,'bold'),bg=PANEL,fg='#cfe8fb',selectbackground='#1565c0',selectforeground='#ffffff',activestyle='none',exportselection=False,bd=0,highlightthickness=1,highlightbackground=LINE,highlightcolor=CY)
  self.period_list.pack(fill='both',expand=True,padx=20,pady=16);self.period_list.bind('<<ListboxSelect>>',self.select_period)
  fb=tk.Frame(right,bg=PANEL);fb.pack(fill='x',padx=20,pady=(0,20))
  # v1.2.291.469: Kullanıcı Girişi paneli. Yalnız "açılışta kullanıcı girişi" açıksa görünür (_update_login_panel).
  self._lp_on=False;self._lp_fb=fb
