  try:row,err=G.authenticate(c,u,p,_verify_company_user_password,hash_password)
  finally:c.close()
  if not row:
   self.password.set('');self._lp_msg.config(text=str(err or 'Giriş başarısız.'));self._lp_pass.focus_set();return None
  c=G._con()
  try:need=bool(row['must_change_pw']) or G.password_expired(c,row)
  finally:c.close()
  if need and not G.change_password_dialog(self,row,'Yöneticiniz ilk girişte şifrenizi değiştirmenizi istedi ya da şifrenizin süresi doldu. Devam etmek için yeni şifrenizi belirleyin.'):self.password.set('');return None
