 def refresh(self):
  reg=_bootstrap_company_registry();companies=[(str(k),str(v.get('name') or f'Firma {k}')) for k,v in sorted(reg.items(),key=lambda x:int(x[0]) if str(x[0]).isdigit() else 999999)]
