 def refresh_periods(self):
  _cleanup_pending_period_deletes()
  vals=[]
  reg=_period_registry_load()
  if reg: vals=sorted([k for k,v in reg.items() if Path(v.get('path','')).exists()],reverse=True)
  # v1.2.207: Dönem listesinde TEK gerçek kaynak donem_kayitlari.json'dur.
  # settings.period hiçbir firmada dönem listesi üretmez; böylece başka/default yıl sızamaz.
  self.period_list.delete(0,'end')
  for v in vals:self.period_list.insert('end',v)
  if not vals:self.period.set('')
  elif self.period.get() not in vals:self.period.set(vals[0]);self.period_list.selection_set(0);_switch_period_db(vals[0])
  self._update_login_panel()
