 def _login_required(self):
  # Firma/dönem veritabanındaki firma kapsamlı ayarı esas al; eski genel ayarla da uyumlu kal.
  try:
   r=DX.one("SELECT v FROM scoped_settings WHERE scope='Firma' AND k='login_required' ORDER BY id DESC LIMIT 1")
   v=str(r['v'] if r else DX.get('login_required','Hayır')).strip().lower()
  except Exception:v=str(DX.get('login_required','Hayır')).strip().lower()
  return v in ('evet','yes','1','true','açık','acik')
 def _recover_login_users(self):
  # v1.2.291.35: kullanıcı/şifre artık firma bazında tek merkezî DB'dedir.
  try:
   _ensure_company_users();return bool(_cu_one('SELECT id FROM users WHERE active=1 LIMIT 1'))
  except Exception as e:
   log_error('Merkezi kullanıcı kaynağı hazırlama',e);return False
 def _ask_user_login(self):
  self._recover_login_users()
  users=_cu_rows('SELECT username,full_name,role,password_hash FROM users WHERE active=1 ORDER BY username')
  if not users:
   messagebox.showwarning(APP,'Açılışta kullanıcı girişi açık ancak seçili firma/dönemde aktif kullanıcı bulunamadı. Kullanıcı & Yetki Yönetimi bölümünde en az bir aktif kullanıcı tanımlayın.',parent=self);return None
  w=new_toplevel(self);w.title('Kullanıcı Girişi');w.geometry('470x300');w.resizable(False,False);w.grab_set()
  tk.Label(w,text='KULLANICI GİRİŞİ',font=('Segoe UI',16,'bold'),fg='#0b376d').pack(pady=(22,16))
  form=tk.Frame(w);form.pack(fill='x',padx=28)
