# Düğme, klavye kısayolu (F4, F9...) ve çift tıklama aynı işleve gider; yetki kontrolü işlevin kendisine konur.
def _gate_method(cls,name,module,kind,label):
 f=getattr(cls,name,None)
 if f is None or getattr(f,'_alf_gate',None):return
 def w(self,*a,**k):
  kd=kind(a,k) if callable(kind) else kind
  if CURRENT_ROLE!='Yönetici':
   try:
    G=_gv()
    if not G.can(module,kd) and not G.require(self.winfo_toplevel(),module,label(a,k) if callable(label) else label,kind=kd,setting_key=None,cache_minutes=5):return None
   except Exception as e:log_error('İşlem yetkisi: '+name,e)
  return f(self,*a,**k)
 w._alf_gate=(module,kind);w.__name__=f.__name__;w.__doc__=f.__doc__
 setattr(cls,name,w)

